INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('8', '姚瑶', '文学与传媒学院', '副教授', NULL, '', '基本情况 姓名 姚瑶 性别 女 职称 副教授 所属系 网络与新媒体 是否硕导 否 最高学历 硕士研究生 Email 286483628@qq.com yy2017@czu.edu.cn 详细情况 所在学科专业 新闻传播学 研究方向 理论传播学；应用传播学；网络与新媒体方向；非遗文化传播方向 讲授课程 《媒体市场调查与分析》《新媒体用户分析》《新媒体视听节目制作》《大众传播学》《网络营销》《网络与新媒体技术》《影视写作》等。 教育经历 安徽师范大学新闻传播学专业研究生毕业 工作经历 池州学院文学与传媒学院专任教师 科研项目 近年来主持安徽省高等学校科学研究项目人文社会科学重点项目、安徽省社科界青年学人成长计划、企业横向科研项目等各级各类科研项目6项。 学术论文 近年来在各类各级刊物 发表学术论文19篇，以独撰或第一作者身份发表14篇。 《池州傩文化的场域生发与流动转向研究》《新质生产力背景下微短剧赋能文旅的三重勾连》等。 获奖情况 活动竞赛方面： 2024年第四届全国高校教学创新大赛安徽省赛三等奖；2024年第四届全国高校教学创新大赛校赛二等奖；2024年池州学院优秀课程思政典型教学案例二等奖2024年池州学院“坚定不移跟党走，歌唱新时代双拥”大合唱总决赛三等奖；2019年池州学院第六届就业指导课程教学大赛优秀奖；池州学院2018年教师技能大赛一等奖；2018年10月代表池州学院在“新时代 新担当 新作为”安徽省教科文卫体系统职工纪念改革开放四十周年演讲比赛中荣获三等奖；池州学院2017年度新进教师教学技能大赛“优秀教学新手”；池州学院2018年度教师技能大赛一等奖；安徽省教科文卫体系统职工纪念改革开放四十周年演讲比赛三等奖。 考核评优方面： 池州学院教学成果奖二等奖； 池州学院2024-2025学年度教师教学工作年度考核优秀；池州学院2023-2024学年度教师教学工作年度考核优秀；池州学院2023年度师德考核优秀；池州学院2023年度考核优秀；池州学院2022-2023学年辅导员考核优秀；池州学院2020-2021、2021-2022两学年度优秀教学质量奖；池州学院2018-2019、2019-2020两学年度优秀教学质量奖。 指导学生方面： 安徽省大学生微电影大赛优秀指导教师、全国大学生广告艺术大赛安徽赛区优秀指导老师； 指导学生国家级、省级等各级各类奖项获奖30余项。 社会兼职 中国编剧网特约编剧； 安徽同梦文化传媒有限公司媒体总监； 池州市影视家协会会员。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '硕士研究生', NULL, '《媒体市场调查与分析》《新媒体用户分析》《新媒体视听节目制作》《大众传播学》《网络营销》《网络与新媒体技术》《影视写作》等', NULL, '硕士研究生 ；大学新闻传播学专业研究生毕业 工作经历 池州学院文学与传媒学院专任教师 科研项目 近年来主持安徽省高等学校科学研究项目人文社会科学重点项目、安徽省社科界青年学人成长计划、企业横向科研项目等各级各类科研项目；大学生微电影大赛优秀指导教师、全国大学生广告艺术大赛安徽赛区优秀指导老师； 指导学生国家级、省级等各级各类奖项获奖', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('9', '岑霞', '文学与传媒学院', '博士', NULL, '', '基本情况 姓名 岑霞 性别 女 职称 教员 所属系 中文系 是否硕导 否 最高学历 博士研究生 Email 824326109@qq.com 详细情况 所在学科专业 中国语言文学 研究方向 西方文论 讲授课程 外国文学等 教育经历 学士（ 2014-2018 ）、硕士（ 2018-2021 ）、博士（ 2021-2024 ） 工作经历 无 科研项目 暂无 学术论文 在《中外文化与文论》《兰州文理学院学报（社会科学版）》等发表文章 著作教材 无 获奖情况 无 社会兼职', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '博士研究生', NULL, '外国文学等', NULL, '博士研究生 ；学士；硕士', NULL, NULL);
