INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('13', '刘玉艳', '大数据与人工智能学院', '副教授', NULL, '', '刘玉艳，女，1995年7月毕业于安徽财经大学计算机应用技术专业，1996年7月进入原池州工业技工学校任教，1999年9月进入池州师范专科学校计算机中心。1998年、2004年先后在安徽大学、合肥工业大学进修，2007年获得合肥工业大学硕士学位，2011年获评副教授职称。 主要研究领域与方向： 数据分析与可视化、信息化建设、信息化教学、网络管理与技术', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '获得合肥工业大学', NULL, NULL, NULL, '大学计算机应用技术专业，；大学、合肥工业大学进修，；大学硕士学位，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('14', '王贞', '大数据与人工智能学院', '王  贞-大数据与人工智能学院', '代数编码，图论 教科研项目： ', '', '王贞，男，1987年11月生，安徽东至人，硕士研究生，2011年7月就职于池州学院，2015年12月被评为讲师。 主讲课程： 高等代数，线性代数，概率论与数理统计，图论，近世代数 研究方向： 代数编码，图论 教科研项目： 1、安徽省教育厅教研重点项目：以本为本背景下的地方本科院校公共数学基础课程建设研究(2018jyxm0579)，参与', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, '高等代数，线性代数，概率论与数理统计，图论，近世代数 研究方向： 代数编码，图论 教科研项目： ', NULL, '硕士研究生，；本科院校公共数学基础课程建设研究', NULL, NULL);
