INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('16', '吴青青', '大数据与人工智能学院', '吴青青-大数据与人工智能学院', '经济系统预测与决策 主持的教科研项目： ', '', NULL, '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, '线性代数，概率论与数理统计，回归分析，时间序列分析，统计学 研究方向： 经济系统预测与决策 主持的教科研项目： ', NULL, '大学数学与应用数学专业，获理学学士学位，；大学数量经济学专业，获经济学硕士学位。 主讲课程： 线性代数，概率论与数理统计，回归分析，时间序列分析，统计学 研究方向： 经济系统预测与决策 主持的教科研项目： ；本科院校统计学教学中存在的问题与对策.现代商贸工业,', NULL, NULL);
