INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('19', '许奇', '大数据与人工智能学院', '讲师/博士', '图像处理、模式识别、计算机视觉 教科研论文：以第一作者', '', '许奇，男，汉族，1991年11月生，安徽庐江人。2015年毕业于蚌埠医科大学，获学士学；2019年毕业于安徽大学计算机科学与技术学院，获硕士学位；2025年毕业于河海大学计算机与软件学院，获博士学位。 办公地点：博奕北103 电子邮箱：qixu@hhu.edu.cn 研究方向：图像处理、模式识别、计算机视觉 教科研论文：以第一作者(Qi Xu/许奇)发表论文如下： [1]Qi Xu, Zhuoming Xu, Huabin Wang, et al.Online learning discriminative sparse convolution networks for robust UAV object tracking[J].Knowledge-Based Systems(KBS),2025,308:112742(SCI 1区 top) [2]Qi Xu, Zhuoming Xu, Zhe Chen, et al.Learning sparse filters-based convolutional networks without offline training for robust visual tracking[J].Applied Intelligence(APIN),2025,55(6):459(SCI 2区) [3]Qi Xu, Zhuoming Xu, Yan Tang, et al.Effective sparse tracking with convolution-based discriminative sparse appearance model[J].Journalof Visual Communicationand Image Representation(JVCIR),2025,11:104547(SCI 4区) [4]Qi Xu, Huabin Wang, Qilin Wu, et al.Robust online tracking via sparse gradient convolution networks[J]. Signal Processing-Image Communication (SPIC),2021,90:116056(SCI 2区) [5] 许奇,韩俊波,黎海霞.基于卷积的稀疏跟踪算法[J].激光与光电子学进展,2021,58(16):431-440.(CSCD核心) [6]许奇,王华彬,周健,等.用于目标跟踪的智能群体优化滤波算法[J].智能系统学报,2019,14(04):697-707.(CSCD核心) [7]QiXu, Huabin Wang, Jian Zhou, et al.Real-Time Online Tracking via a Convolution-Based Complementary Model[J]. IEEE Access,2018,6:30073-30085(SCI 3区) [8]Qi Xu,Huabin Wang, Jian Zhou, et al.Robust Visual Tracking Using Oriented Gradient Convolution Networks[C]. CCCV,2017,1:320-330', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '蚌埠医科大学', NULL, NULL, NULL, '大学，获学士学；；大学计算机科学与技术学院，获硕士学位；；大学计算机与软件学院，获博士学位。 办公地点：博奕北', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('20', '胡欢欢', '大数据与人工智能学院', '胡欢欢-大数据与人工智能学院', NULL, '', '胡欢欢，女，1991.11-，安徽安庆人，讲师，硕士，池州学院教师。 E-mail: 研究领域和方向： 深度学习 主讲课程： 《数据结构》、《面向对象程序设计》、《人工智能程序设计》 获奖情况： 1、2023年获校级智慧教学大赛一等奖1 项。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, '《数据结构》、《面向对象程序设计》、《人工智能程序设计》 获奖情况： ', NULL, '硕士，池州学院教师。 ', NULL, NULL);
