INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('26', '孙薇', '外国语学院', '副教授', NULL, '', '基本情况 姓名 孙薇 性别 女 职称 副教授 所属系部 英语系 最高学历 本科 Email 619338316@qq.com 详细情况 所在学科专业 英语语言文学 研究方向 英美文学，翻译 讲授课程 高级英语，口译，中国文化概论 教育经历 2004.09-2005.06 安徽大学 进修硕士学位 2014.09-2015.06 上海外国语学院大学访学 工作经历 2000.09---2002.06 池州师范学校 2002.07—至今 池州学院外国语学院 科研项目 1. 主持2025年校级质量工程项目《课程思政示范课程“中国文化概论”》 2. 主持2017年省厅重点教研项目《译介学视角下池州傩文化的对外传播创新与实践》，项目号：SK2017A0649 3. 主持安徽省质量工程重点项目《 翻译理论与实践本科教学团队》，项目号： 2015jxtd043 4. 主持2010年安徽省高等学校优秀青年人才基金项目《约克纳帕塔法神话王国中女性众生相》 ，项目号： 2010SQRW096 5. 主持2007年校级科研课题威廉.《福克纳的女性情结》，项目号：XK0710 6. 主持2012年校级教研课题《英语本科专业“旅游英语”课程实践教学体系研究》 ，项目号： 2012jyxm028 学术论文 1. 试论地方特色文化引入旅游英语教学的意义,《巢湖学院学报》,2015年第4期； 2. 《押沙龙，押沙龙》中罗莎小姐的形象的解读,《宿州学院学报》,2012年第12期； 3. 《喧嚣与骚动》中康普生夫人形象的解读，《课程教育研究》,2013年第4期； 4. 美丽的沉沦---从《喧哗与骚动》中的凯蒂形象的塑造上看福克纳的女性情结,《池州学院学报》,2009年第5期； 5. 旅游英语地方特色探讨；《山东文学 》 ,2008 年第 9 期； 6. 试论《圣经》）对西方文学的影响 , 《池州 学院学报》 ,2006 年第 6 期； 7. 文化因素对英语教学的影响与作用,《池州学院学报》,2006年第1期； 8. 试论文化对颜色词象征意义的影响,《科技信息》,2006年第4期； 9. 英汉委婉语比较,《大学时代》,2006年第4期 著作教材 获奖情况 1.2008-2009、2009-2010两学年度优秀教学质量奖 2. 2010-2011、2011-2012两学年度优秀教学质量奖 3.2010“基础英语”优秀试卷奖 4.2014年“高级英语”优秀试卷奖 5.2018年“二等奖英语专业口译课程校内实践应用”教学成果二等奖 6. 2024年十三届全国口译大赛安徽赛区优秀口译指导教师奖 6. 2024年十三届全国口译大赛优秀口译指导教师奖 7.2025年校课程思政案例三等奖 社会兼职', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '本科 ；大学 进修硕士学位 ；大学访学 工作经历 ', NULL, NULL);
