INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('30', '鲍红信', '马克思主义学院', '鲍红信-池州学院马克思主义学院', NULL, '', '池州学院马克思主义学院副院长（主持 工作 ）、皖南民俗文化与旅游发展研究院副院长、家风文化研究中心主任，博士，副教授，全国教学技能比赛优秀指导教师。 近年来先后主持安徽省社科规划、社科创新项目、人文社科重点项目教研重点项目等 8项。参与国家社科基金重点、一般项目多项。先后在《上海师大学报》、《史林》、《都市文化研究》《文汇报》《中国纪检监察报》等期刊、报纸上发表论文40余篇。编写或编撰翻译了《崇德尚文 家囯天下》《剑桥世界古代史》《池州傩舞》《以文化人》《中华优秀家风经典选读》等书籍6本。获得省级教学成果特等奖1项。为池州市、安庆市等地开展各类文化宣讲50多场。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '博士，副教授，全国教学技能比赛优秀指导教师。 近年来先后主持安徽省社科规划、社科创新项目、人文社科重点项目教研重点项目等 ；大学报', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('31', '周佩东', '马克思主义学院', '周佩东-池州学院马克思主义学院', NULL, '', NULL, '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '博士名录 习近平新时代中国特色社会主义思想概论系 毛泽东思想和中国特色社会主义理论体系概论系 马克思主义基本原理系 中国近现代史纲要系 思想道德与法治系 形势与政策系 思想政治教育系 党建工作 组织建设 ；本科招生 就业指导 下载专区 登录管理 师资队伍 教授、博士名录 习近平新时代中国特色社会主义思想概论系 毛泽东思想和中国特色社会主义理论体系概论系 马克思主义基本原理系 中国近现代史纲要系 思想道德与法', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('32', '章清', '马克思主义学院', '章清-池州学院马克思主义学院', NULL, '', '章清，女，中共党员，讲师，硕士研究生。 2010年12月毕业于安徽师范大学马克思主义学院思想政治教育专业，获硕士学位。现为池州学院马克思主义学院习近平新时代中国特色社会主义思想概论系主任，2023年任池州市第一中学模拟政协社团指导教师。 一、项目情况 1、安徽省思想政治理论课教研项目（2021szjyxm077）以微视频为载体的思想政治理论课实践教学模式研究 ——以池州学院为例 2、党的二十大精神理论研究专项（重点项目）（CZ2022ESDZ01）党的二十大对人民至上原则的新贡献研究 二、著作情况 1、章清.以微视频为载体的思政课实践教学问题剖析及路径优化[J]池州学院学报.2024（8） 三、获奖情况 1、2022年12月被共青团池州市委授予志愿服务项目“优秀指导老师”称号', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '安徽师范大学', NULL, NULL, NULL, '硕士研究生。 ；大学马克思主义学院思想政治教育专业，获硕士学位。现为池州学院马克思主义学院习近平新时代中国特色社会主义思想概论系主任，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('33', '李燕', '马克思主义学院', '李燕-池州学院马克思主义学院', '马克思主义基本原理教学与研究、主讲课程有《马克思主义哲学原理》《马克思主义基本原理概论》《马克思主义经典著作选读》等', '', '李燕，女， 1979年7月出生于内蒙古自治区。2004毕业于吉林延边大学师范学院外国哲学专业，获哲学硕士学位，现任池州学院马克思主义学院讲师。主要从事马克思主义基本原理教学与研究，主讲课程有《马克思主义哲学原理》《马克思主义基本原理概论》《马克思主义经典著作选读》等。主持校级课题2项，参与国家级项目1项，发表论文多篇，参编校本教材《形势与政策》，多次获得院级教学成果奖。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '吉林延边大学师范学院', NULL, NULL, NULL, '大学师范学院外国哲学专业，获哲学硕士学位，现任池州学院马克思主义学院讲师。主要从事马克思主义基本原理教学与研究，主讲课程有', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('34', '程凯', '马克思主义学院', '程凯-池州学院马克思主义学院', NULL, '', '程凯，男，中共党员，副教授，大学本科，硕士。 2009年12月毕业于河海大学公共管理学院社会学专业，获法学硕士学位。现为池州学院马克思主义学院思想道德与法治系主任、教工三支部书记。 一、项目情况 安徽省教育厅人文社科重点项目《国家级非遗 “东至花灯”口述资料整理及保护传承研究》（SK2019A0409）等。 二、论文情况 1、《乡土社会中的文化坚守——东至花灯舞的文化社会学阐释》《池州学院学报》2023年第5期， 2、《花灯何以可能？——“五马跑朝”灯种间断与接续》，《池州学院学报》2024年第5期。 获奖情况 1、2016年获团中央、全国学联颁发的全国暑期“三下乡”社会实践活动“优秀个人”荣誉称号； 2、2016年获池州学院优秀党员荣誉称号。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '员，副教授，大学', NULL, NULL, NULL, '大学本科，硕士。 ；大学公共管理学院社会学专业，获法学硕士学位。现为池州学院马克思主义学院思想道德与法治系主任、教工三支部书记。 一、项目情况 安徽省教育厅人文社科重点项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('35', '胡孔发', '马克思主义学院', '胡孔发-池州学院马克思主义学院', NULL, '', '胡孔发，男， 1978年6月生，安徽枞阳人，1999年7月参加工作。2007年6月于云南师范大学历史与行政学院中国近现代史专业毕业，获历史学硕士学位；2010年6月于南京农业大学人文学院毕业，获理学博士学位。现为马克思主义学院副教授。 一、研究领域和方向 生态环境史；地方文化史 二、主讲课程 中国近现代史纲要；世界古代史；世界近代史；国际关系史 三、代表性论文、论著 1、民众的心理需求与太平天国的衰亡，中国高等教育研究论丛，2006年第4期 2、中国共产党领导的多党合作制度的历史考察，中国学术研究，2006年第7期 3、鸦片战争后中国家庭手工艺与城乡经济的二元性，中国学术研究，2007年第1期 4、民国时期植树造林研究，农业考古，2010年第1期 5、民国时期林业教育研究，教育评论，2010年第2期 6、民国时期苏南水灾研究，农业考古，2010年第3期 7、民国时期苏南自然灾害述论，池州学院学报，2013年第4期 8、近十年来“红军长征”研究综述，池州学院学报，2016年第6期； 9、在“纲要”课教学中融入安徽红色文化资源，池州学院学报，2017年第3期； 10、论新四军与根据地的医疗卫生事业，池州学院学报，2017年第5期； 11、参与撰写《池州傩舞》，江苏凤凰美术出版社，2016年版。 12、参与撰写《近代淮河流域自然灾害与乡村社会研究》，安徽大学出版社2018年版。 四、主持或参与的科研、教研项目 1、教育部人文社科基金项目：中国传统农业的生态学内涵及意义研究，编号：05JA770013，（参与先秦部分的编撰工作，时间为2007至2009年）；主持； 2、校级科研项目：民国时期苏南工业发展与生态环境变迁研究（2011RC023），主持； 3、校级科研中心项目：明清民国时期皖南地区农业开发与生态环境变迁研（XKY201315），主持； 4、省级重点学科专门史项目：明清以来安徽地区疫病与卫生防疫体系研究（2015ZMS003），主持； 4、国家社科项目：明清民国时期皖南生态环境变迁与地方社会，（12CZS047），参与； 5、国家社科项目：中国历代帝王神话研究（19BZS150)，参与。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '农业大学人文学院', NULL, NULL, NULL, '大学历史与行政学院中国近现代史专业毕业，获历史学硕士学位；；大学人文学院毕业，获理学博士学位。现为马克思主义学院副教授。 一、研究领域和方向 生态环境史；地方文化史 二、主讲课程 中国近现代史纲要；世界古代史；世界近代史；国际关系史 三、代表性论文、论著 ；大学出版社', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('36', '谢建军', '马克思主义学院', '谢建军-池州学院马克思主义学院', NULL, '', '谢建军，男， 1997年生，安徽省黄山人，中共党员，历史学硕士；主要研究方向为中国近现代史，思想政治教育；主要教授《中国近现代史纲要》《马克思主义基本原理》和《形势与政策》课程。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '硕士；主要研究方向为中国近现代史，思想政治教育；主要教授', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('37', '孙琪', '马克思主义学院', '孙琪-池州学院马克思主义学院', NULL, '', '孙琪 ， 女 ， 中共党员 ， 副教授 ， 硕士研究生 。 2014 年 6 月毕业于 安徽 大学 历史 学院。现为池州学院马克思主义学院 专职思政课教师，是池州市第四届青年联合会委员、池州市新四军历史研究会会员、池州学院家风文化研究中心专职研究员、池州市青年讲师团成员 。 一、项目情况 1、主持安徽省教育厅高校思想政治工作能力提升暨“三全育人”试点省建设项目—高校思想政治理论课教学重点难点热点研究项目（sztsjh2019-4-35），立项年月：2020年3月，优秀结项。 2、主持安徽省教育厅质量工程—思想政治理论课教研项目（2020szjyxm097），立项年月：2020年12月，优秀结项。 3、主持池州学院校级质量工程项目大规模在线开放课程（2019XMOOC10），立项年月：2019年11月，优秀结项。 4、主持安徽省教育厅高校优秀拔尖人才培育资助项目-高校优秀青年骨干教师国内访学研修项目（gxgnfx2022081），立项年月：2022年7月。 4、主持池州学院与池州市中小学及幼儿园校地合作重点项目（JK2023027），立项年月：2023年5月，优秀结项（J2024001）。 5、主持安徽省教育厅人文社会科学重点研究项目（2024AH052898），立项年月：2024年9月，在研（有阶段性成果）。 6、主持安徽省哲学社会科学规划项目（AHSKQ2023D071），立项年月：2024年6月，在研（有阶段性成果）。 7、主持安徽省教育厅质量工程—线上线下混合式课程项目（2024xsxx084），立项年月：2025年6月，二类，在研（有阶段性成果）。 8、主持安徽省教育厅质量工程—思想政治理论课教研重点项目（2024sxzz083），立项年月：2025年6月，二类，在研（有阶段性成果）。 二、著作情况 1、晚清桐城派作家与东至周氏家族关系考论[J].合肥大学学报,2025(04):14-20. 2、中华优秀家风融入大中小学思政课一体化建设的路径探究[J].大理大学学报,2025(09):69-77. 3、三全育人视角下家风在思政教育中的应用[J].成都中医药大学学报（教育科学版）,2021（04）:110-113. 4、中国共产党百年红色家风：阶段特征、价值意蕴与践行理路[J].皖西学院学报,2025(03):24-31+35. 5、新时代红色资源融入高校思想政治教育的赓续路径[J].宿州学院学报,2024(02):5-8. 6、基于接受者主体视角的思想政治理论教育路径分析[J].池州学院学报,2018(4):138-140. 7、东至周氏家风家训与社会主义核心价值观的耦合性研究[J].池州学院学报,2019(4):6-9. 8、安徽东至周氏优良家风文化的源起及当代价值研究[J].池州学院学报,2020(5):38-40. 9、总体国家安全观的十年回眸与时代意义[N].池州日报,2024-04-15(005). 10、《周馥<负暄闲语>注译》（合肥工业大学出版社）第三作者，国际标准书号（ISBN 978-7-5650-5134-0） 11、《地方应用型大学文化建设的探索与实践——池州学院校园文化建设研究》（合肥工业大学出版社）参编，国际标准书号（ISBN 978-7-5650-5338-2） 三、获奖情况 1、获安徽省“教坛新秀”荣誉称号 2、获安徽省教科文卫体系统女职工“书润匠心”读书征文活动一等奖 3、获安徽省本科师范院校教师智慧教学大赛人文社科组二等奖 4、获第四届全国高校教师教学创新大赛安徽省赛基础课程副高组三等奖 5、获安徽省教学成果特等奖（2021jxcgj394-9） 6、获全省大中专学生志愿者暑期“三下乡”社会实践活动“优秀个人奖” 7、获安徽省社会科学界第十八届学术年会论文二等奖 8、获第十一届皖江地区历史文化研讨会优秀论文二等奖 9、获安徽省高校思政课一体化学科二等奖 10、获安徽省社科联“三项课题”研究成果优秀奖 11、荣获池州青年五四奖章 12、获池州市“三八红旗手”荣誉称号 13、获池州学院“微宣讲”竞赛一等奖 14、获池州学院课程思政典型教学案例一等奖 15、获池州学院质量工程思想政治教育教学成果一等奖（2021XSZCG02-1） 16、获池州学院第四届教师教学创新大赛暨首届“课程思政”说课比赛一等奖 17、获池州学院“教书育人楷模”荣誉称号 18、获池州学院教师教学竞赛先进个人 19、被聘为池州市“青年讲师团”成员 20、被评为池州学院“双能型”教师 21、获池州学院优秀教学质量奖 22、获池州学院“优秀共产党员”荣誉称号 23、获池州学院“标兵团总支”荣誉称号 24、指导学生获安徽省“新时代·新思想·新青年”安徽省大学生学习马克思主义理论成果大赛一等奖 25、指导学生获安徽省首届大学生红', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '硕士研究生 。 ；大学 历史 学院。现为池州学院马克思主义学院 专职思政课教师，是池州市第四届青年联合会委员、池州市新四军历史研究会会员、池州学院家风文化研究中心专职研究员、池州市青年讲师团成员 。 一、项目情况 ；大学学报,', NULL, NULL);
