INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('39', '程福根', '马克思主义学院', '程福根-池州学院马克思主义学院', NULL, '', '程福根，男，汉族， 1990年 7月 生，安徽潜山人，中共党员， 现任池州学院马克思主义学院讲师 。毕业于福建师范大学中国近现代史基本问题研究专业，获法学博士学位，主要从事中共党史研究，发表学术论文多篇，荣获 “学习宣传贯彻党的二十届三中全会精神理论研讨会暨安徽省科学社会主义学会2024年年会”的论文优秀奖、第三届红色文化论坛的论文三等奖等荣誉称号。主讲课程《毛泽东思想和中国特色社会主义理论体系概论》《中国共产党思想政治教育史》《形势与政策》等课程。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '福建师范大学', NULL, NULL, NULL, '大学中国近现代史基本问题研究专业，获法学博士学位，主要从事中共党史研究，发表学术论文多篇，荣获 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('40', '阳光宁', '旅游与历史文化学院', '教授', NULL, '', '年起在安徽师范大学社会学院在职攻读硕士。主讲课程：历史教育学、社会科教育学、中国历史与文化、文书学、中国近现代史、中国教育学刊、社会科教育学概论。省级教学成果', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '年起在安徽师范大学社会学院（硕士）', NULL, '历史教育学、社会科教育学、中国历史与文化、文书学、中国近现代史、中国教育学刊、社会科教育学概论', NULL, '在职攻读硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('41', '陈健', '旅游与历史文化学院', '副教授', '学生思想政治教育、劳动教育', '', '教授。年硕士毕业于安徽师范大学有机化学专业，获理学硕士。研究方向：学生思想政治教育、劳动教育。主讲课程：《大学生职业生涯规划与就业指导》、《大学生劳动教育》', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '安徽师范大学有机化学（硕士）', NULL, '《大学生职业生涯规划与就业指导》、《大学生劳动教育》', NULL, '安徽师范大学有机化学专业，理学硕士', NULL, NULL);
