INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('57', '王长春', '机电工程学院', '教授', NULL, '', '理学硕士。主讲课程：理论力学、热力学与统计物理、大学物理学、物理教学论、中国物理快报、大学物理、电子技术。主持企业横向项目1项。省模范教师。社会兼职：现为安徽省物理学会理事；池州市电机工程学会副理事', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '硕士', NULL, '理论力学、热力学与统计物理、大学物理学、物理教学论、中国物理快报、大学物理、电子技术', NULL, '理学硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('58', '汪贤才', '机电工程学院', '半导体学院', '光电子技术专业课程的教学及相关方面的研究', '', '汪贤才，男， 1968 年 9 月生，池州学院副校长、教授， 1989 年毕业于华东师范大学物理系，并获安徽大学物理与材料科学学院硕士学位。 多年来主要从事光电子技术专业课程的教学及相关方面的研究。教学上 , 注重教学内容与贾学方法，教学效果得到师生的认可，被评为安徽省优秀教师、学校教学名师、学校教学质量优秀奖。科研上，主持安徽省科技厅立项的安徽省年度重点课题《新型透明氧化物半导体异质结的制备与光伏效应研究》（项目编号 11070203010 ）的研究，安徽省教育厅立项的安徽省高校省级自然科学项目《相干态在量子信息处理中的应用研究》（项目编号 KJ2011Z268 ）的研究，池州学院自然科学重点项目《运动三能级原子与光场作用系统的系列量子性质研究》（项目编号 2006xk07 ）的研究；以排名第二的身份参与了安徽省科技计划项目《多原子与腔场作用体系的量子特性及量子信息处理》、安徽省教育厅青年基金《基于腔 QED 的纠缠与信息熵特性》、《腔 QED 中的量子纠缠若干问题研究》。先后在《 International Journal of Theoretical Physics 》（ SCIE 收录）、《原子与分子物理学报》、《吉林大学学报》（理学版）、《量子电子学报》、《合肥师范学院学报》、《黄山学院学报》、《池州学院学报》发表论文九篇。近来逐步将自己的研究方向调整到半导体材料方向，同时也以此为契机，建立本方向的科研团队。 一、相关论文 1 、关于量子非逻辑局域门的研究 《量子电子学报》第 22 卷， 2005 年 6 月第 3 期 2 、二项式光场与运动二能级原子相互作用系统的光场压缩效应 《原子与分子物理学报》第 23 卷， 2006 年第 5 期 3 、二项式光场与运动三能级原子相互作用系统的光场压缩效应 《吉林大学学报》（理学版）第 44 卷， 2006 年第 3 期 4 、双模纠缠光场与运动三能级原子相互作用系统的反聚束效应 《原子与分子物理学报》第 24 卷， 2007 年第 3 期 5 、汪贤才，杨名 . 基于腔 QED 的任意相干叠加态远程制备 . 合肥师范学院学报， 2009,27(6):24-26. 6 、汪贤才，一种类型的薛定谔方程的求解 . 《黄山学院学报》， 2010 ， 12(6):18-20. 7 、 Xian-Cai Wang,Ming Yang, Concentration of Non-maximally Entangled States via Entanglement Swapping in Cavity QED. Int J Theor Phys (2011) 50: 1479 – 1485 8 、 Xian-Cai Wang ， Density matrix of the harmonic oscillator in thermostat based on coordinate momentum intermediate representation 《量子电子学报》第 29 卷， 2012 年第 3 期 9 、 Xian-Cai Wang ， Squeezing mechanism and squeezed state in mesoscopic LCR electric circuit obtained by quantum Fresnel transformation. 《量子电子学报》第 30 卷， 2013 年第 4 期 10 、汪贤才， n-ZnO/p-CuI 异质结的制备及光电特性 . 《池州学院学报》， 2012 ， 12(26):15-17.', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '理与材料科学学院', NULL, NULL, NULL, '大学物理系，并获安徽大学物理与材料科学学院硕士学位。 多年来主要从事光电子技术专业课程的教学及相关方面的研究。教学上 , 注重教学内容与贾学方法，教学效果得到师生的认可，被评为安徽省优秀教师、学校教学名师；大学学报；大学学报', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('59', '张玉峰', '机电工程学院', '半导体学院', NULL, '', NULL, '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '硕士研究生，高级实验师。 上一篇： 查超飞 下一篇： 师道田 版权所有: ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('60', '刘茹茹', '机电工程学院', '半导体学院', NULL, '', NULL, '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '硕士', NULL, '数字电子技术、模拟电子技术、微电子工艺、集成电路设计、SOC设计技术', NULL, '硕士。主要从事', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('61', '姚大杰', '机电工程学院', '半导体学院', NULL, '', '姚大杰，男， 1986 年 2 月，安徽枞阳人，博士，副教授。 2013 年 7 月入职池州学院，获得池州学院 2013 年度新进教师教学展示“优秀教学能手”，池州学院 2015 年青年教师教学技能大赛一等奖，安徽省第二届普通本科院校青年教师教学竞赛三等奖、池州学院第四届就业创业指导课程教学大赛三等奖，池州学院 2016 年青年教师教学技能大赛一等奖。主讲课程《电路分析》、《自动控制原理》、《计算机控制技术》等，研究方向为自适应控制，多智能体协同控制。主持校级和省部级科研项目多项，先后在 IEEE Transactions on Systems, Man, and Cybernetics: Systems 、 IEEE Transactions on Fuzzy Systems 、 Neurocomputing 、 Nonlinear Dynamics 等国际期刊发表 SCI 文章 9 篇，并担任 Journal of the Franklin Institute ， IEEE Transactions on Fuzzy Systems ， Transactions of the Institute of Measurement and Control 等期刊审稿人。 近三年发表文章罗列如下： [1] Dajie Yao, et al. Adaptive Tracking Consensus Control of Nonlinear Multiagent Systems With Predefined Accuracy Under Disturbance Observer[J]. IEEE Transactions on Systems, Man, and Cybernetics: Systems, doi: 10.1109/TSMC.2023.3245299. （ SCI 一区， IF:11.471 ） [2] Dajie Yao, et al. Event Triggered Practical Fixed-time Fuzzy Containment Control for Stochastic Multi-agent Systems.IEEE Transactions on Fuzzy Systems, 2022, 30(8): 3052-3062. （ SCI 一区， IF:12.253 ） [3] Dajie Yao, et al. Containment control of non-affine multi-agent systems based on given precision. Applied Mathematics and Computation. 2022, 412: 126579. （ SCI 二区） [4] Dajie Yao, et al. Adaptive Neural Network Consensus Tracking Control for Uncertain Multi-agent Systems With Predefined Accuracy. Nonlinear Dynamics, 2020, 101(4): 2249-2262. （ SCI 二区） [5] Dajie Yao, et al. Event-triggered Adaptive Consensus Tracking Control for Nonlinear Switching Multi-agent Systems. Neurocomputing, 2020, 415: 157-164. （ SCI 二区） [6] Dajie Yao, et al. Finite-time consensus control for a class of multi-agent systems with dead-zone input. Journal of the Franklin Institute, 2021, 358 (7):3512-3529. （ SCI 二区） [7] Dajie Yao, et al. Practical fixed-time adaptive consensus control for a class of multi-agent systems with full state constraints and input delay. Neurocomputing,2021, 46:156-164. （ SCI 二区）', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '博士，副教授。 ；本科院校青年教师教学竞赛三等奖、池州学院第四届就业创业指导课程教学大赛三等奖，池州学院 ', NULL, NULL);
