INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('65', '杨荣', '艺术与教育学院', '副教授', '教育与发展心理、心理咨询', '', '讲 师。大学本科。研究方向：教育与发展心理、心理咨询。主讲课程：“教育学”、“心理学”、“大学生心理学健康教育”、“西方心理学史”、“人格心理学”、“情绪心理学”、“变态心理学”、“家庭治疗”。邮箱：379476791@qq.com', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '师。大学', NULL, '“教育学”、“心理学”、“大学生心理学健康教育”、“西方心理学史”、“人格心理学”、“情绪心理学”、“变态心理学”、“家庭治疗”', NULL, '师。大学本科', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('66', '王俊华', '艺术与教育学院', '讲师', '大学生思想政治教育、大学生创新创业教育、大学生劳动教育', '', '助教。月就读于沈阳大学经济学专业，获学士。研究方向：大学生思想政治教育、大学生创新创业教育、大学生劳动教育。邮箱：215691362@qq.com', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '沈阳大学', NULL, NULL, NULL, '专业，获学士、沈阳大学', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('67', '吴诗琪', '艺术与教育学院', '讲师', '建筑遗产保护及非遗文化活态研究、高校美育理论研究', '', '讲 师。硕士。研究方向：建筑遗产保护及非遗文化活态研究、高校美育理论研究。主讲课程：中国建筑史、设计透视学、AI智能与设计表现技法、计算机辅助制图（Photoshop）、展示设计、办公空间设计等。邮箱：568644719@qq.com', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '硕士', NULL, '中国建筑史、设计透视学、AI智能与设计表现技法、计算机辅助制图（Photoshop）、展示设计、办公空间设计等', NULL, '师。硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('68', '沈丽丽', '艺术与教育学院', '讲师', '发展与教育心理学', '', '副教授。硕士。研究方向：发展与教育心理学；劳动心理学。主讲课程：心理统计学；心理学；大学生心理健康教育；大学生劳动教育。邮箱：287746639@qq.com', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '硕士', NULL, '心理统计学；心理学；大学生心理健康教育；大学生劳动教育', NULL, '副教授。硕士', NULL, NULL);
