INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('72', '顾彦力', '艺术与教育学院', '顾彦力-艺术与教育学院', '工业设计及理论、文化产品创意设计、社会创新设计', '', '硕士研究生。研究方向：工业设计及理论，文化产品创意设计，社会创新设计。主讲课程：UI设计，包装设计，文创产品开发设计。邮箱：475112182@qq.com', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '硕士研究生', NULL, 'UI设计，包装设计，文创产品开发设计', NULL, '硕士研究生', NULL, NULL);
