INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('77', '王瑞侠', '材料与环境工程学院', '副教授', '无机纳米材料、电化学', '', '教授。年硕士毕业于华中师范大学分析化学专业，获理学硕士。研究方向：无机纳米材料、电化学。主讲课程：分析化学。主持1项。安徽省优秀学术论文三等奖，2010.2；', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '华中师范大学分析化学（硕士）', NULL, '分析化学', NULL, '华中师范大学分析化学专业，理学硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('78', '陈大勇', '材料与环境工程学院', '副教授', NULL, '', '教授。月在北京化工大学获得化学工程专业工学硕士', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '北京化工大学（硕士）', NULL, '', NULL, '', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('79', '彭艳芬', '材料与环境工程学院', '讲师', '配位聚合物的合成及性质研究', '', '教授。月硕士毕业于苏州大学无机化学专业，获理学硕士。研究方向：配位聚合物的合成及性质研究。主讲课程：无机化学、大学化学、无机化学实验、分析化学实验、应用化学综合实验、材料综合与设计实验', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '硕士', NULL, '无机化学、大学化学、无机化学实验、分析化学实验、应用化学综合实验、材料综合与设计实验', NULL, '苏州大学无机化学专业，理学硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('80', '刘天宝', '材料与环境工程学院', '副教授', '杂环化合物合成及性能研究', '', '教授。年本科毕业于曲阜师范大学化学专业，获理学学士。研究方向：杂环化合物合成及性能研究。主讲课程：有机化学、基础化学实验3A(有机)、应用化学设计性实验、应用化学综合实验等。池州学院“教学名师”，2023年1月；', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '曲阜师范大学', NULL, '有机化学、基础化学实验3A(有机)、应用化学设计性实验、应用化学综合实验等', NULL, '曲阜师范大学化学专业，理学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('81', '贾莉', '材料与环境工程学院', '讲师', '水污染防治、废水处理', '', '教授。获工学学士学位。研究方向：水污染防治、废水处理。主讲课程：环境工程CAD、水污染控制工程、工业废水处理技术。获教学质量优秀奖4项（2010-2012，2012-2014，2018-2020，2020-2022）；', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, '环境工程CAD、水污染控制工程、工业废水处理技术', NULL, '。获工学学士、工学学士学位', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('82', '盛敏刚', '材料与环境工程学院', '教授', '主要从事环保技术、化工分离及生产安全等研究与教学工作', '', '副教授。月毕业于合肥工业大学化工学院，获工学硕士。研究方向：主要从事环保技术、化工分离及生产安全等研究与教学工作。主讲课程：化工原理、化工实训、化工原理实验、化工原理课程设计等。池州学院2006-2007、2007-2008两学年度优秀教学质量奖，2009年1月；', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, '硕士', NULL, '化工原理、化工实训、化工原理实验、化工原理课程设计等', NULL, '合肥工业大学化工学院，工学硕士', NULL, NULL);
