INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('84', '高三双', '材料与环境工程学院', '博士', '主要从事原子功能材料设计及其能源器件应用研究、包括纳米材料合成、新能源电催化材料与器件、电催化性能与功能材料的设计研究', '', '副教授。本科。研究方向：主要从事原子功能材料设计及其能源器件应用研究，包括纳米材料合成、新能源电催化材料与器件，电催化性能与功能材料的设计研究。主讲课程：无', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, '无', NULL, '副教授。本科', NULL, NULL);
