INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('91', '吴自爱', '商学院', '教授', NULL, '', '吴自爱，教授，信息技术博士，池州学院商学院（法学院）院长，国家标准化良好行为评价专家，中国国际大学生创新创业大赛国赛、省赛评委，高级电子商务师（一级国家职业资格证书），加拿大里加贾纳大学访问学者，安徽省教坛新秀，安徽省线上教学名师，安徽省金牌职工，安徽省商务厅电子商务专家顾问，安徽省人力资源与社会保障厅电子商务技能鉴定专家委员、安徽省农业农村厅新型职业农民培训名师、安徽省经信厅中小企业志愿服务专家，池州市贵池区科技特派员。国内外公开刊物发表成果22篇，主持国家级一流本科课程1项，主持编写国家级规划教材1部，安徽省规划教材3部，荣获商务部商务研究成果奖1次，安徽省教学成果奖4次。主持起草国家标准1项，安徽省地方标准1项，团体标准18项。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '博士，池州学院商学院；大学生创新创业大赛国赛、省赛评委，高级电子商务师；大学访问学者，安徽省教坛新秀，安徽省线上教学名师，安徽省金牌职工，安徽省商务厅电子商务专家顾问，安徽省人力资源与社会保障厅电子商务技能鉴定专家委员、安徽省农业农村厅新型职业农民培训名师、安徽省经信厅中小企', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('92', '吴义根', '商学院', '教授', NULL, '', '吴义根，中国农业大学管理学博士，教授，硕士生导师，池州学院最美教师。 多年来，主要从事农业经济理论与政策、金融市场运行与管理、空间经济学等方面的教学和研究工作，先后主持教育部人社会科学等省部级项目以及企业委托项目等20多项课题的研究工作，发表学术论文50余篇，其中CSSCI、CSCD论文20余篇，出版专著1部。获得池州市社科奖一等奖1项、二等奖2项；获省级教学成果奖二等奖2项。主持建设省级精品资源共享课1门、省级示范课程1门。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '大学管理学博士，教授，硕士生导师，池州学院最美教师。 多年来，主要从事农业经济理论与政策、金融市场运行与管理、空间经济学等方面的教学和研究工作，先后主持教育部人社会科学等省部级项目以及企业委托项目等', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('93', '吴铖铖', '商学院', '副教授', NULL, '', '吴铖铖，南京财经大学管理学硕士，副教授，审计学系主任，兼任《安徽内审》杂志编委会委员。先后获得安徽省教坛新秀、池州学院“优秀教师”、池州学院“优秀共产党员”。 近年来，主要从事供应链管理、数字化转型、数据资产、公司治理以及智能审计等方面的教学与研究工作，先后主持安徽省高等学校哲学社会科学研究重点项目、安徽省社会科学创新发展研究课题、安徽省社科界青年学人成长计划、池州学院人文社会科学研究重点项目、池州市社科联课题重点项目、池州学院人文社会科学研究一般项目等多项课题的研究工作，参与安徽省社会科学创新发展研究课题重大研究项目，在CSSCI等期刊发表学术论文60余篇。研究成果获安徽省社科界第二十届（2025）学术年会征文获奖成果一等奖，安徽省社科联“三项课题”研究活动获奖成果二等奖、安徽会计学者研讨会优秀论文二等奖、安徽省管理学学会年会优秀论文二等奖、安徽省经济文化研究会年会优秀论文一等奖。主讲中级财务会计学、财务管理学、新商科跨专业综合实训等课程，主持建设教育部产学合作协同育人项目1项、省级线下一流课程1门、省级教学示范课1门、省级教学研究一般项目1项、校级线下一流课程2门、校级课程思政示范课程1门、校级教学研究重点项目1项，获得第五届全国高校教师教学创新大赛安徽省新文科中级及以下组二等奖（团队）、池州学院课程思政典型教学案例一等奖、池州学院课程思政教学比赛一等奖，连续多年教学质量考核获评“优秀”等级。学科竞赛方面，指导学生获得第十届全国大学生电子商务“三创赛”安徽省选拔赛、安徽省大学生创新创业ERP管理大赛、安徽省大学生财税技能大赛等学科竞赛一等奖20余项、二等奖30余项。服务社会方面，主笔撰写“池州市非矿产业转型升级之路研究报告”获池州市委书记肯定性签批，参与池州市财政局“十四五”规划编制工作。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '大学管理学硕士，副教授，审计学系主任，兼任；大学生电子商务；大学生创新创业', NULL, NULL);
