INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('95', '章麓', '商学院', '章麓-商学院', '证券投资学、企业运营管理和SIYB课程教学工作', '', '章麓，池州学院商学院教师，池州学院教坛新秀，池州学院双型教师，安徽省创业培训讲师，主要从事证券投资学、企业运营管理和SIYB课程教学工作。主持或参与安徽省质量工程项目多项，主持安徽省人才项目1项，指导学生参加学科竞赛获省级以上奖多项。指导学生完成国家级、省级创新创业训练计划多项。主要研究方向为企业财务绩效和创新创业研究。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
