INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('97', '翟荣兵', '商学院', '教授', NULL, '', '翟荣兵，管理学教授，博士，受聘于中国数量经济学会长三角洲经济研究会任第一届常务理事、安徽城市经济学会任理事、合肥市商务局任商务领域评审专家。近年来，积极开展乡村公共文化服务方面的研究，积累了系统的研究成果与教学资源，在相关领域展现出突出的学术研究与实践融合能力；发表三类及以上论文20余篇，其中二类及以上8篇。主持或参与各类科研项目10余项，其中主持三类纵向项目2项，作为主要成员参与二类项目1项。主持或参与质量工程项目10余项，其中主持二类及以上4项。获得厅级及以上荣誉5项，其中指导学生获B类比赛全国三等奖2次，厅级荣誉2次。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '博士，受聘于中国数量经济学会长三角洲经济研究会任第一届常务理事、安徽城市经济学会任理事、合肥市商务局任商务领域评审专家。近年来，积极开展乡村公共文化服务方面的研究，积累了系统的研究成果与教学资源，在相关领', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('98', '李春顶', '商学院', '教授', NULL, '', NULL, '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('99', '周天宇', '体育学院', '周天宇-体育学院', NULL, '', '周天宇，男，1987年3月出生，安徽池州人，南通大学教育学硕士，讲师，校双能型教师。主要承担《运动解剖学》、《游泳》、《体育舞蹈》等课程的教学任务。 主要教学效果： 2019年9月指导学生参加安徽省大、中学生体育联赛游泳比赛获一等奖7项，二等奖10余项；高校丙组团体冠军； 2022年7月指导学生参加安徽省第十五届运动会高校部游泳比赛获一等奖2项，二等奖10余项； 指导学生立项大学生创新创业大赛国家级2项，省级1项。 教科研情况： 主持校级科研项目《以绿运会为契机的池州休闲体育产业经营方式的研究》（项目编号：2016RW018）已结项 高校体育专业术科课程教学现状与发展研究，《榆林学院学报》，2017年3月第2期 新时代背景下中小学校园足球教学理念及方法的思考，《韶关学院学报》，2017年5月第5期 2021年主持校级教研一般项目《大学生游泳课程思政的探索与实践》（项目号：2021XKSXM08）已结项 2022年主持校级线上线下混合式课程《运动解剖学》（项目号：2022XHHKC07） 2023年《基于“赛教融合，学用互联”双驱动下高校体育育人模式的探索与实践》（项目号：2023XJXCG11）获校级教学成果三等奖 2024年主持校级科研重点项目《“大黄山”建设背景下安徽体育康养产业的发展模式与路径研究》（项目号：CZ2024RWZ13） 个人参赛和专业实践情况： 体育舞蹈国家级社会体育指导员、游泳一级裁判员、游泳中级社会体育指导员、中级救生员。 2015年获池州学院优秀教学新手 2017年获安徽省第三届普通高等学校体育教师技能比赛丙组三等奖 2021年获安徽省本科师范院校教师智慧教学大赛三等奖 2024年担任池州市青少年U系列游泳锦标赛裁判长 2024年参加安徽省第五届职工运动会游泳比赛获第六名2项', '1', '2', '5', '2026-06-05 15:20:27', '2026-06-06 19:15:30', NULL, NULL, NULL, NULL, NULL, '大学教育学硕士，讲师，校双能型教师。主要承担；大学生创新创业大赛国家级；大学生游泳课程思政的探索与实践', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('100', '陈忠菊', '体育学院', '陈忠菊-体育学院', NULL, '', '陈忠菊，安徽霍邱人，1982年11月出生，中共党员，硕士学位，副教授职称，双能型教师，气排球国家级裁判员、乒乓球国家一级裁判员，主要担任排球、乒乓球、毽球及大学生排球体育俱乐部教学工作。 主要教学效果： 1、2017年11月在安徽省大学生排球联赛中指导学生在男子丙组二等奖； 2、2018年在4月在安徽省第十四届运动会高校组排球比赛中指导学生获男子丙组二等奖； 主要教科研情况： 一、课题 （1）生态文明视域下皖南国际文化旅游示范区生态体育旅游可持续发展研究（CZ2018RW10），池州学院校级人文一般研究项目，2018年12月 二、论文 （1）安徽省高师院校体教专业排球专修课程设置调查研究，搏击.武术科学,2012.5 （2）基于SWOT分析池州市体育旅游的可行性，通化师范学院学报，2013.6 （3）全域旅游下池州市体育旅游发展策略研究，赤峰学院学报，2017.10 （4）九华山体育旅游经济圈建设可行性研究，牡丹江师范学院学报，2019.1', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '硕士学位，副教授职称，双能型教师，气排球国家级裁判员、乒乓球国家一级裁判员，主要担任排球、乒乓球、毽球及大学生排球体育俱乐部教学工作。 主要教学效果： ；大学生排球联赛中指导学生在男子丙组二等奖； ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('101', '焦瑞胜', '体育学院', '焦瑞胜-体育学院', NULL, '', NULL, '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '硕士研究生，副教授，池州学院大学体育教学部主任，池州学院；大学体育高质量发展的路径研究、校级教研重点 ；大学生体育舞蹈比赛优秀裁判员 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('102', '戴园园', '体育学院', '戴园园-体育学院', NULL, '', '戴园园，女，出生于1989年，安徽怀宁人，中共党员，硕士研究生，双能型教师，副教授职称。 2016--2017、2017--2018学年度，获池州学院优秀教学质量奖； 2017年荣获池州学院“最美教师”称号； 2017年抽调参加安徽省大学生运动会羽毛球比赛临场裁判； 2017年参加池州市羽毛球比赛，荣获女子双打冠军； 2018年指导学生参加安徽省第十四届运动会高校部羽毛球比赛，获得一等奖2项、二等奖3项、三等奖3项； 2018年参加安徽省第十四届运动会群众部羽毛球比赛荣获女子双打二等奖； 2015年于沈阳医学院学报发表论文1篇（不同强度运动结合CLA对青春期肥胖大鼠Vaspin的影响）； 2016年于安徽师范大学学报发表论文1篇（不同强度运动队青春期肥胖大鼠Vaspin的影响）； 2018年于池州学院学报发表论文1篇（非体育专业学生肥胖率与体质健康指标的相关分析——以池州学院为例）； 2016年申报池州学院自然科学项目，获得立项。', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '硕士研究生，双能型教师，副教授职称。 ；大学生运动会羽毛球比赛临场裁判； ；大学学报发表论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('103', '朱珠', '体育学院', '朱珠-体育学院', NULL, '', '朱珠，安徽无为人，1988年4月，中共党员，研究生，硕士学位，讲师。 国家级社会体育指导员；安徽省健美操高级教练员；航空模型裁判员；跳绳裁判员、教练员；执裁二届全国青少年航空模型锦标赛（安徽赛区）裁判工作。 教学成果方面： 1、指导学生获安徽省十四届运动会高校部田径比赛四个二等奖，三个三等奖； 2、指导学生获全国航空模型公开赛（南京站）无线电遥控纸飞机竞时赛第一名； 3、指导学生获全国航空模型公开赛（江西站）无线电遥控固定翼模型空战(P3Z)第一名； 科研方面： 1、主持校级人文一般课题一项、参与校级人文一般课题二项、参与校级重点项目二项； 2、发表论文四篇，参编高等教育“十三五”规划教材一本；', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '硕士学位，讲师。 国家级社会体育指导员；安徽省健美操高级教练员；航空模型裁判员；跳绳裁判员、教练员；执裁二届全国青少年航空模型锦标赛', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('104', '侍玉杰', '体育学院', '侍玉杰-体育学院', NULL, '', '籍贯：安徽泗县 出生日期：1992.2.15 学历：研究生 学位：硕士 职称：讲师 获奖情况： 1、2024年安徽省第六届全民健身运动会羽毛球A组女子单打第一名 2、2024年安徽省第五届职工运动会羽毛球比赛甲组青年女子第二名 3、2023年安徽省羽毛球业余联赛总决赛获B组女子单打第二名，女子双打第三名 4、2023年获得羽毛球一级裁判员证书 5、2020年第五届全民健身运动会羽毛球比赛甲组女子单打第二名 6、获2017年中华人民共和国第十三届学生运动会“体育道德风尚奖”运动员称号、高校组羽毛球女子团体第七名 7、获2017年安徽省大学生羽毛球锦标赛丙组女子团体第一名、双打第二名', '0', '0', '0', '2026-06-05 15:20:27', '2026-06-05 15:20:27', NULL, NULL, NULL, NULL, NULL, '硕士 职称：讲师 获奖情况： ；大学生羽毛球锦标赛丙组女子团体第一名、双打第二名', NULL, NULL);
