INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('108', '汪江节', '材料与环境工程学院', '汪江节-池州学院材料与环境工程学院', '现主要从事生态环境分析及生物无机复合功能材料研究', '', '高级实验师。月毕业于安庆师范大学化学专业，获理学学士。研究方向：现主要从事生态环境分析及生物无机复合功能材料研究。主讲课程：《仪器分析实验》、《材料测试技术实验》', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '安庆师范大学', NULL, '《仪器分析实验》、《材料测试技术实验》', NULL, '安庆师范大学化学专业，理学学士', NULL, NULL);
