INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('122', '蒋志华', '外国语学院', '讲师', NULL, '', '基本情况 姓名 蒋志华 性别 女 职称 讲师 所属教研室 大学英语 最高学历 本科 Email jennyjiang1977@qq.com 详细情况 所在学科专业 英语语言文学 研究方向 应用语言学 讲授课程 大学英语 教育经历 1995.9-1999.7 阜阳师范学院外语系 2004.9-2005.7 安徽大学外国语学院 工作经历 1999.7- 至今 池州学院外国语学院 科研项目 学术论文 著作教材 获奖情况 社会兼职', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, NULL, NULL, NULL, NULL, '大学英语 最高学历 本科 ；大学英语 教育经历 ；大学外国语学院 工作经历 ', NULL, NULL);
