INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('124', '张永', '大数据与人工智能学院', '教授/博士', NULL, '', '张永，男，汉族，1980年9月生，河南长垣人，2008年7月参加工作，2004年12月加入中国共产党，兰州大学基础数学专业毕业，研究生学历，理学博士学位。现任大数据与人工智能学院教授，副院长，安徽工业大学兼职硕士研究生导师，省教坛新秀，安徽赛区数学建模竞赛评委和优秀指导老师，校教学名师，校教学科研型导师，校双能型教师，省数学建模与数学实验教学创新团队和校“黄大年”教学团队负责人。 办公地点 ：博奕南106 E-mail: yongzhang@czu.edu.cn 研究领域和方向： 非线性分析、微分方程数值解、数学模型 主讲课程： 高等数学、高等数学选讲、计算方法引论、概率论与数理统计、线性代数、数学建模与数学实验 科研论文： [1]High-order finite element method on a Vulanovi´c-Bakhvalov mesh for a singularly perturbed convection-diffusion problem, Applied Mathematics Letters,2023, https://doi.org/10.1016/j.aml.2022.108457.(SCI). [2]A second-order adaptive grid method for a singularly perturbed Volterra integro-differential equation, Fractal and Fractional, 2022, 6(636),1-13.(SCI) [3] Probabilistic Calibration and Genetic Algorithm-based Bank Credit Strategies for MSMEs and Enlightenment to Tobacco Enterprise Management，Tobacco Regulatory Science,2021, 7(6): 5726~5740. [4] Parameter uniform numerical method for a system of two coupled singularly perturbed parabolic convection-diffusion equations，Advances in Difference Equations（2018）450,1-19.(SCI) [5] The (n-1)-radial symmetric positive classical solution for elliptic equations with gradient, Electron.J. Diff. Equ., Vol. 2013 (2013), No. 204, pp. 1-9.(SCI) [6] Parametric Cubic Spline Methods for Solving Hyperbolic Equations，The 2nd International Conference on Information Engineering and Computer Science，2010.(EI) [7] Existence of positive solutions for semilinearelliptic equations with supercritical growth，Journal of Mathematical Analysis and Applications，381（2011）215-228.(SCI) [8] Compact Sobolev embedding theorems involving symmetry and its application，Nonlinear Differential Equations and Applications, 2010,Volume 17, Number 2, Pages 161-180.(SCI) [9]一类拟线性椭圆方程整体解的不存在性，纯粹数学与应用数学，2009，第25卷第1期，14-18.（国内核心CSCD） [10] The existence and asymptotic behavior of entire blow-up solutions for quasilinear elliptic equations, Applicable Analysis, Vol 86,1455-1461.（SCIE） 主持的教科研项目： 1.数学建模与数学实验教学创新团队，项目编号：2022XJXTD02. 2.奇异摄动积分微分方程的高阶数值方法，项目编号', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, NULL, NULL, '高等数学、高等数学选讲、计算方法引论、概率论与数理统计、线性代数、数学建模与数学实验 科研论文： ', NULL, '大学基础数学专业毕业，研究生学历，理学博士学位。现任大数据与人工智能学院教授，副院长，安徽工业大学兼职硕士研究生导师，省教坛新秀，安徽赛区数学建模竞赛评委和优秀指导老师，校教学名师，校教学科研型导师，校双；大学生公共课线上教学的探讨与实践，项目编号：；大学公共数学省级教学团队，项目编号：', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('125', '魏继成', '大数据与人工智能学院', '魏继成-大数据与人工智能学院', '非线性泛函分析。主持完成了池州学院一般项目', '', '魏继成，男，汉族，1979年2月出生，安徽池州人，2002年毕业于安徽师范大学数学教育专业，获理学学士学位。同年进入池州学院（原池州师范专科学校）任教。2006年在东南大学数学系攻读在职研究生，获硕士学位。 主讲课程： 高等数学、复变函数与积分变换、常微分方程。 主要研究方向： 非线性泛函分析。主持完成了池州学院一般项目1项，论文数篇。', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '安徽师范大学', NULL, '高等数学、复变函数与积分变换、常微分方程。 主要研究方向： 非线性泛函分析。主持完成了池州学院一般项目', NULL, '大学数学教育专业，获理学学士学位。同年进入池州学院；大学数学系攻读在职研究生，获硕士学位。 主讲课程： 高等数学、复变函数与积分变换、常微分方程。 主要研究方向： 非线性泛函分析。主持完成了池州学院一般项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('126', '洪牡丹', '外国语学院', '副教授', NULL, '', '基本情况 姓 名 洪牡丹 性 别 女 职 称 副教授 所属 系 商务英语教研室 最高学历 硕士 Email 552390165@qq.com 详细情况 学科专业 英语语言文学 研究方向 语用学；跨文化交际 讲授课程 口语、语法、语音、 基础英语、 综合英语、语言与文化、 高级英语、 英语演讲、 综合商务英语、跨文化交际、英语国家社会与文化 教育经历 1994.09-1998.07 安徽师范大学外语系 2002.09-200 6 .0 1 华东师范大学英语系 2015.09-2016.07 南京大学外国语学院 工作经历 1998.07-2002.07 池州师范专科学校 2003.09-至今 池州学院 科研项目 1. 安徽省教育厅人文社科课题：隐喻视角下的语篇连贯研究（ 2010sk508） ； 2.校级重点科研课题;英汉广告语篇中的人称指代对比研究（XK0801） 学术论文 1.军队语境中不礼貌话语的身份建构机制，《天津外国语大学学报》，2018年第1期； 2.公示语中的地名译写研究—以南京市地名译写为例，《池州学院学报》，2016年第2期； 3.隐喻的语篇建构功能探究，《巢湖学院学报》，2014年第4期； 4.隐喻的语篇功能和语篇构建，《池州学院学报》，2010年第5期； 5.浅议第一人称指示语非常规用法及其语用功能，《滁州学院学报》，2008年第4期； 6.英语广告语篇中人称系统和语气系统的人际意义，《阜阳师范学院学报》，2008年第3期； 7.高师英语专业学生英语口语学习策略，《池州学院学报》，2008年第1期； 8.《雨中的猫》的功能语法分析，《池州师专学报》，2007年第2期。 著作教材 省级规划教材《实用大学英语口语教程（上）》，副主编 获奖情况 1.2025年获得优秀课程思政典型教学案例三等奖 2.2024年获得“外研社.国才杯”“理解当代中国”全国大学生外语能力大赛（安徽赛区）指导教师二等奖； 3.2024年获得“外研社.国才杯”“理解当代中国”全国大学生外语能力大赛国赛 英语组 国际传播综合能力赛项 指导教师铜奖； 4.2024年获得安徽省大学生跨文化能力大赛指导教师一等奖； 5.2023年获得2020-2021/2021-2022两学年度优秀教学质量奖； 6.2023年获得“外研社.国才杯”“理解当代中国”全国大学生外语能力大赛（安徽赛区）指导教师一等奖； 7.2023年获得安徽省大学生跨文化能力大赛指导教师三等奖； 8.2023年获得首届“中语智汇杯”全国高校商务谈判大赛指导教师二等奖； 9.2021年、2022年“外研社杯”全国大学生英语阅读大赛（安徽赛区）指导教师二等奖； 10.2020年、2021年“外研社杯”全国大学生英语阅读大赛（安 徽赛区）指导教师三等奖； 11.2019年获得2016-2017、2017-2018两学年优秀教学质量奖； 12.2018年“外研社杯”全国大学生英语阅读大赛（安徽赛区）指导教师三等奖； 13.2010-2011、2011-2012两学年优秀教学质量奖； 14.2010年、2012年获得安徽省教学成果三等奖； 15.2004-2005、2005-2006两学年度优秀教学质量奖； 16.2005年获得教师教学技能比赛二等奖； 17.2004年被评为校级优秀教师。 社会兼职 无', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '硕士', NULL, '雨中的猫、实用大学英语口语教程（上）', NULL, '硕士 ；大学外语系 ；大学英语系 ', NULL, NULL);
