INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('131', '刘孝光', '机电工程学院', '半导体学院', '过程装备控制的研究工作', '', '刘孝光，男，硕士，副教授。承担《机械原理》、《机械设计》、《理论力学》、《材料力学》等课程的教学工作，多次获池州学院教学质量优秀奖。主要从事过程装备控制的研究工作。主持省厅级项目 2 项，省高校学科人才资助项目 1 项，参与安徽省科技攻关计划项目 1 项。以第一作者发表论文 8 篇，获池州市科技进步二等奖 1 项，实用新型专利 7 项。 一、主要期刊论文 1 、刘孝光 , 徐健 , 冯进 . 钻井液重力式气液分离器的分离机理 [J], 机械工程师 ,2006,11:67-68. 2 、刘孝光 , 高莉 , 潘培道 .CFD 技术在涡轮钻具机械性能预测分析中的的应用 [J]. 机械工程师 ,2006,12:89-91. 3 、刘孝光 , 冯进 , 潘培道 . 高密度钻井液一级气液分离器的仿真和优化技术研究 [J]. 矿山机械 ,2007,35(10);98-103. 4 、刘孝光 , 潘培道 , 胡昌军 . 涡轮叶栅水力性能仿真优化技术研究 [J]. 冶金设备 ,2007,161(1):21-24,28. 5 、刘孝光 , 潘培道 , 徐健 . 基于 CFD 技术的机械搅拌通风发酵罐溶氧性能预测 [J]. 轻工机械 ,2008,26(2):21-24.', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, NULL, NULL, NULL, NULL, '硕士，副教授。承担', NULL, NULL);
