INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('151', '杨修菊', '旅游与历史文化学院', '教师', '文化创意学', '', '教授。年毕业于江南大学法政学院，获法学学士。研究方向：文化创意学。主讲课程：管理学原理；创意思维训练；创意文案写作；大学生传统文化素养。安徽省教坛新秀', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '江南大学法政学院', NULL, '管理学原理；创意思维训练；创意文案写作；大学生传统文化素养', NULL, '江南大学法政学院，法学学士', NULL, NULL);
