INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('153', '朱坤', '文学与传媒学院', '副教授', NULL, '', '基本情况 姓名 朱坤 性别 男 职称 副教授 所属系 中文系 是否硕导 否 最高学历 本科 Email Shichuan502@163.com 详细情况 所在学科专业 汉语言文学 研究方向 文艺学 讲授课程 文学理论、文学批评原理 教育经历 1999 年，湘潭大学汉语言文学专业毕业（本科）； 2008 年，山东大学古代史专业毕业（硕士）。 工作经历 1999 年至今，池州学院中文系 科研项目 1. 地藏信仰与九华山民俗研究， 2011 年省教育厅一般人文社科项目； 2. 杜荀鹤诗歌的语言艺术研究， 2005 学校一般人文社科项目。 学术论文 1. 论现代文学图书版本变迁及影响，《出版发行研究》， 2013 （ 11 ） . 2. 论新文学研究中的善本问题，《黄山学院学报》， 2014 （ 4 ） . 3. 从教学主体看文学理论教学问题，《池州学院学报》， 2014 （ 4 ） . 4. 九华山金地藏考略，《铜陵职业技术学院学报》， 2013 （ 6 ） . 5. 民俗视野下的目连戏，《戏剧之家》， 2014 （ 1 ） . 著作教材 1. 参编《马克思主义文艺论著选读》； 2. 参编池州历史文化资源总成《漫步秋浦》。 获奖情况 1.2013 年 8 月，获池州学院教学成果奖二等奖，排名第 4 ； 2.2013 年 12 月，获安徽省教学成果奖三等奖，排名第 4 。 社会兼职 安徽省文艺评论家协会会员 池州市文艺评论家协会秘书长', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, NULL, NULL, '文学理论、文学批评原理', NULL, '本科 ；大学汉语言文学专业毕业；本科', NULL, NULL);
