INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('156', '单振生', '艺术与教育学院', '教师', '教师教育、高等教育', '', '大学本科/硕士。研究方向：教师教育、高等教育。主讲课程：教育学、心理学、教师职业道德素养、班级管理理论与实务。邮箱：964166193@qq.com', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '硕士', NULL, '教育学、心理学、教师职业道德素养、班级管理理论与实务', NULL, '大学本科', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('157', '林国霞', '艺术与教育学院', '副教授', '油画实践与创作', '', '副教授。硕士。研究方向：油画实践与创作。主讲课程：油画风景，油画头像，油画、色粉画（基础）人物，素描石膏像，水粉、水彩人物，素描（静物）人物。邮箱：854370880@qq.com', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '硕士', NULL, '油画风景，油画头像，油画、色粉画（基础）人物，素描石膏像，水粉、水彩人物，素描（静物）人物', NULL, '副教授。硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('158', '冯鹤', '艺术与教育学院', '教师', '视觉传达设计及其理论研究', '', '硕士研究生。研究方向：视觉传达设计及其理论研究。主讲课程：字体设计、版式设计、书籍装帧设计、标志设计。邮箱：56258458@qq.com', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '硕士研究生', NULL, '字体设计、版式设计、书籍装帧设计、标志设计', NULL, '硕士研究生', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('159', '刘光明', '文学与传媒学院', '教授', NULL, '', '基本情况 姓名 刘光明 性别 男 职称 教授 所属 系 中文系 是否硕导 否 最高学历 本科 Email czliugm@163.com 详细情况 所在学科专业 汉语言文字学 研究方向 汉语史 讲授课程 汉语史、古代汉语、现代汉语、学术论文写作 教育经历 1.1984.9 — 1988.7 ，在安徽师范大学中文系学习，获文学学士学位 ; 2.2000.10-2003.7 ，在安徽师大汉语言文字学专业“以研究生毕业同等学力申请硕士学位教师进修班”学习、结业； 3.2004.9 — 2005.7 ，在华中师范大学文学院做高级访问学者。 工作经历 1988 年 7 月至今，池州学院中文系 科研项目 1. 安徽省教育厅人文社科研究项目：《 < 颜氏家训 > 语法研究》（ 2006SK314 ） 2. 安徽省教育厅人文社科研究重点项目：《中古汉语方位词研究——以中古诗歌为例》（ 2011SK494ZD ） 3. 安徽省教育厅教研重点项目：《师范院校中文专业语言类课程内容体系改革与师范生语言能力培养研究》（ 2007jyxm122 ） 4. 安徽省教育厅教研重点项目：《应用型本科院校人文类专业实践教学体系与运行机制研究》（ 2012JYXM564 ） 5. 安徽省精品资源共享课程《古代汉语》（ 2013 ） 6.安徽省汉语言文字学教学团队（2016） 学术论文 在《古汉语研究》、《语言研究》、《中国现当代文学研究丛刊》、《中国戏剧》、《中文自学指导》、《安徽师范大学学报》、《浙江师范大学学报》、《广东海洋大学学报》等刊物发表论文 40 余篇。 著作教材 著作：《 < 颜氏家训 > 语法研究》，合肥工业大学出版社， 2006. 教材：编著《马克思主义文艺论著选读》，中国戏剧出版社， 2008. 主编《普通话与安徽方言辨正教程》，合肥工业大学出版社， 2010. 主编《高等语文》，合肥工业大学出版社， 2011. 主编《大学生文学素养》，江苏凤凰教育出版社， 2014 . 获奖情况 1. 池州学院首届教学名师， 2006. 2. 安徽省教学成果三等奖， 2010. 3. 安徽省教学成果二等奖， 2013. 4. 安徽省教学成果三等奖， 2015. 5. 安徽省教学名师， 2015. 社会兼职 安徽省语言学会理事、华东修辞学会会员', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, NULL, NULL, NULL, NULL, '本科 ；大学中文系学习，获文学学士学位 ; ；硕士学位教师进修班', NULL, NULL);
