INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('169', '陈精兵', '大数据与人工智能学院', '副教授', '数学专业的教学与研究工作', '', '陈精兵，女，汉族，1968年12月出生，安徽枞阳人，1992年7月毕业于安庆师范学院数学教育专业，获理学学士学位，同年分配到池州工业学校任教，1999年进入池州学院（原池州师范专科学校）任教。先后在南京大学、华东师范大学进修学习，2002年—2006年在南京大学数学系攻读基础数学专业在职研究生，获理学硕士学位。现为池州学院大数据与人工智能学院副教授、应用数学教研室主任。 主要从事数学专业的教学与研究工作。专业研究方向是动力系统，主持了省教育厅自然科学研究项目：具有时滞的捕食者—食饵系统的周期解的存在性与解的性质研究，在Annals of Differential Equations等刊物上发表了学术论文。先后承担了《复变函数》《初等数论》《常微分方程》《高等数学》《高等数学选讲》等课程的教学。', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '安庆师范学院', NULL, NULL, NULL, '学士学位，同年分配到池州工业学校任教，；大学、华东师范大学进修学习，；大学数学系攻读基础数学专业在职研究生，获理学硕士学位。现为池州学院大数据与人工智能学院副教授、应用数学教研室主任。 主要从事数学专业的教学与研究工作。专业研究方向是动力系统，主持了省教育厅自然科学研究项目', NULL, NULL);
