INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('174', '彭秀芬', '大数据与人工智能学院', '彭秀芬-大数据与人工智能学院', '计算机应用、生物信息学 主要研究课题： ', '', '彭秀芬，女，1979年11月生，安徽池州人，池州学院大数据与人工智能学院讲师。2002年毕业于安徽师范大学计算机科学教育专业，获工学学士学位。2009年7月获南京航空航天大学计算机应用技术专业硕士学位。 主讲课程： 面向对象程序设计、网页服务开发与网站建设、企业网络应用程序开发 研究方向： 计算机应用、生物信息学 主要研究课题： 1.教育厅重点项目：生物网络的随机Petri网模型构建与分析（2013SQRL096ZD），主持。 2.校级自然重点：生物网络关键节点的识别方法研究（2013ZRZ003），主持。 3.省教育厅重点项目：希瓦氏菌细胞色素c网络的构建、分析及其在胞外电子转移中的作用机制研究（KJ2015A264），参与。 4.省教育厅一般研究项目：面向细胞功能的代谢网络模块化分解研究（KJ2013B167）参与。 5.校级应用型课程建设项目：WEB 服务与开发（2017XYYKC01），参与。 6.安徽省高等教育振兴计划项目：网络工程新专业建设项目（2015zytz070），参与。 7.全国高等院校计算机基础教育教学研究项目：《大数据导论》实验课程开发与实践（2018-AFCEC-198），参与。 主要期刊论文： 1.基于Petri网方法的红血球代谢系统研究，计算机与应用化学，2014年（第一作者）。 2.生物网络关键节点识别方法研究进展，生物学杂志，2017年（第一作者）。 获得主要奖励情况： 1.2011年，获池州学院青年教师教学技能比赛三等奖。 2.2012年，指导学生参加“安徽省第四届机器人大赛暨全国机器人邀请赛”，获得田径赛（轮式组）二等奖和三等奖，仿真机器人舞蹈组二等奖和三等奖。 3.2013年，指导学生参加“安徽省第五届机器人大赛暨全国机器人邀请赛”，获得田径赛（轮式组）二等奖，仿真机器人舞蹈组两个三等奖。 4.2016年，获校级优秀课内实践教学教案奖。 5.2016年，获优秀试卷奖。 6.多次获校级优秀多媒体教学课件奖。 7.2012年度、2018年度考核优秀。', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '安徽师范大学', NULL, '面向对象程序设计、网页服务开发与网站建设、企业网络应用程序开发 研究方向： 计算机应用、生物信息学 主要研究课题： ', NULL, '大学计算机科学教育专业，获工学学士学位。；大学计算机应用技术专业硕士学位。 主讲课程： 面向对象程序设计、网页服务开发与网站建设、企业网络应用程序开发 研究方向： 计算机应用、生物信息学 主要研究课题： ', NULL, NULL);
