INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('178', '殷丽霞', '大数据与人工智能学院', '副教授', '数学教育 教学工作： 从事', '', '殷丽霞，女，1964年9月生，副教授，毕业于安庆师范学院，现从事数学教育教学，校工会副主席。先后被派往北京师范大学、华东师范大学、浙江师范大学进修学习，主持和参加校级以上教科研课题研究4项，撰写论文数十篇，编著教材1部，参编教材1部。 研究方向： 数学教育 教学工作： 从事《数学教育学》、《初等代数研究》、《初等几何研究》、《微格教学》等课程的教学 获奖情况： 获中共池州地区直属机关委员会1995～1996两个年度“优秀共产党员”称号；获池州学院2004～2006两个学年度校级“优秀教学质量奖”；2006年，获省教育系统“先进女教职工”称号；2012年9月获校创先争优“优秀共产党员”称号；2012～2014两个学年度校级“优秀教学质量奖”；2017年3月获省总工会授予的“安徽省五一巾帼标兵”称号；2016～2018两个学年度校级“优秀教学质量奖”。', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '安庆师范学院', NULL, NULL, NULL, '大学、华东师范大学、浙江师范大学进修学习，主持和参加校级以上教科研课题研究', NULL, NULL);
