INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('183', '谢家顺', '文学与传媒学院', '教授', NULL, '', '基本情况 姓 名 谢家顺 性 别 男 职 称 教授 所属系 中文系 是否硕导 硕士生导师 最高学历 本科 Email Chuanbei63@163.com 详细情况 所在学科专业 中国语言文学 研究方向 中国现当代文学 讲授课程 中国现代文学，张恨水小说研究（专业选修课） 教育经历 1.1985年毕业于安庆师范学院中文系，获文学学士学位； 2.2000年10月至2003年7月在安徽师大中国现当代文学专业“以研究生毕业同等学力申请硕士学位教师进修班”学习、毕业； 3.2004—2005学年做北京大学中文系高级访问学者。 工作经历 1.1985-1990，安徽池州殷汇中学任教； 2.1990-1995，安徽池州工业技工学校任教； 3.1995-1999，池州工业学校任教； 4.1999-至今，池州学院任教。 科研项目 1.安徽省教育厅2001年人文社科项目“张恨水对联艺术研究”（2001JW002ZC）； 2.安徽省教育厅2003年人文社科项目“张恨水小说民俗学研究”（2003JW201）； 3.安徽省社科规划项目《张恨水年谱长编》研究（AHSK07-08D117）； 4.国家社科基金项目《张恨水年谱》研究（10BZW091）； 5.安徽省社科规划项目《张恨水佚文搜集与整理》（AHSKYG2017D160）。 学术论文 1.关于《张恨水年谱》编纂的若干问题，《池州学院学报》，2011（1）； 2.“新时期张恨水研究”国际学术研讨会综述，《文学评论》，2011（5）； 3.《前线日报》张恨水一组佚文述考，《新文学史料》，2011（4）； 4. 审美叙事感事：论张恨水小说中对联的功能 ，《 廊坊师院学报 》，2012（4）； 5.张恨水研究三十年，《中国现代文学研究丛刊》，2012（6）； 6.张恨水《写作生涯回忆》补遗，《新文学史料》，2013（1）； 7.冒名张恨水的小说伪作考略，《中国现代文学研究丛刊》，2013（3）； 8.张恨水两封佚信辑注，《新文学史料》，2016（2）； 9.从山野到歌坛——著名民歌手姜秀珍学术访谈，《池州学院学报》，2017（2）； 10.国际化：张恨水作品海外传播及其路径探究，《新文学史料》，2018（3）。 著作教材 1 .著作： ① 《张恨水对联艺术论稿》（合著，第一作者），香港新闻出版社，2001. ② 《张恨水年谱》，安徽文艺出版社，2014. ③ 《此山 此水 此人——张恨水生活足迹寻踪（皖江篇）》，广陵书社，2019. 2. 教材： 《张恨水小说教程》（主编），合肥工业大学出版社，2011. 3. 主编： 丛书《回望张恨水》（五本七卷）、《张恨水纪念文集》，2019。 获奖情况 1.在中国职业教育学会97教研重点课题结题评选活动中，“中专语文学法指导基本理论”荣获壹等奖； 2.论文《中专作文教学误区与对策》，1999年被中国职业技术教育学会期刊编辑委员会评为“中国优秀职教论文”壹等奖； 3.论文《张恨水小说民俗学阐释》2003年获安徽省社会科学界联合会优秀成果奖； 4.论文《研究性语文学习若干理论问题的思考》，被评为2005年度全国教师教育学会地方院校协作会教师教育研究优秀成果贰等奖； 5.2004年12月，荣获安徽省社会科学界联合会2001—2003年度“省社科联学会先进工作者”称号； 6.2005年6月被评为池州师专1995—2004年度“科研先进个人”； 《张恨水对联艺术论稿》、《张恨水小说教程》分别获池州学院2007年度、2012年度优秀科研、教学成果奖； 《张恨水年谱》获池州市2013-2014社会科学优秀成果三等奖。 社会兼职 1.安徽省政府参事室（文史研究馆）特约研究员； 2.安徽师范大学兼职教授、硕士生导师，安徽省张恨水研究会副会长； 3.江西农业大学兼职教授； 4.张恨水纪念馆名誉馆长，江西黎川张恨水旧居文化顾问。', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '安庆师范学院', NULL, NULL, NULL, '硕士生导师 最高学历 本科 ；学士学位； ；硕士学位教师进修班', NULL, NULL);
