INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('193', '章建文', '文学与传媒学院', '教授', NULL, '', '基本情况 姓名 章建文 性别 男 职称 教授 所属系 中文系 是否硕导 是 最高学历 本科 Email 1452930023@qq.com 详细情况 所在学科专业 汉语言文学 研究方向 明清诗文与文论 讲授课程 中国文学批评史、文学批评方法论 教育经历 1987.9—1991.6安徽师范大学中文系，本科毕业；2005.2—2007.12安徽师范大学文学院，在职攻读硕士学位，获文学硕士学位；2009.9—2010.9中国社会科学院文学所访学。 工作经历 1991.7—2002.8安徽省经贸学校；2002.8至今，池州学院 科研项目 吴应箕文学思想研究 （安徽省教育厅一般项目，主持，已结项）；《楼山堂集》整理与研究（安徽省教育厅重点项目，主持，已结项）明末清初皖江作家群研究（安徽省社科规划办，主持，已结项）；桐城派视域下张英父子研究（国家社科基金，主持，在研） 学术论文 1. 从性情之正到性情之美——吴应箕的性情诗论 （文学评论丛刊第10卷，2008年4月，CSSCI集刊） 2. 古典文论范畴“洁”的文化考察 （江淮论坛 2009 . 3,CSSCI扩展） 3. 汉代骚体咏史诗的类型及其审美特征 （ 社会科学辑刊2009 . 3 , CSSCI） 4. 明末清初皖江作家群论略 （ 中国文化研究2010 . 2 ， CSSCI） 5. 明末清初贵池的史学传统 （ 安徽史学2010 . 3 , CSSCI） 6. 明末清初尚朴的文学思潮 （ 文学评论2010 . 4 , CSSCI） 7. 论明末崇祯年间皖江散文思想的转变与影响 （江海学刊 2010 . 4 , CSSCI） 8. 学问与性情：“颐情志于典坟”的内涵与意义 （社会科学辑刊 2010 . 4 , CSSCI） 9. 家训语境下张英的文学观——论《聪训斋语》的文学思想 （ 宁夏社会科学201 2.2, CSSCI） 10. 施闰章佚文佚诗新辑 （古籍研究第 59卷2013年6月 ,CSSCI集刊） 11. 张英以“裕”论文的内涵与意义 （古代文学理论研究第40辑 2015年6月 ,CSSCI集刊） 12. 清初文学批评语境下张英的文学观——以《御选古文渊鉴》为中心 （社会科学辑刊 201 6.6 , CSSCI） 13. 论张英对桐城派的贡献 （北京社会科学 201 6.8 , CSSCI） 著作教材 1. 吴应箕研究 ，安徽大学出版社， 2009年； 2. 吴应箕文集（校点） ，黄山书社， 2017年。 获奖情况 2009-2010年度 安徽省社会科学文学艺术出版奖（社科类） 三等奖；市社科奖二等奖一次，三等奖二次。 社会兼职', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '硕士', NULL, NULL, NULL, '本科 ；大学中文系，本科毕业；；大学文学院，在职攻读硕士学位，获文学硕士学位；', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('194', '赵娣', '商学院', '副教授', '物流管理和市场营销方面的教学和研究工作、主讲《管理学》、《物流管理》、《新商科跨专业综合实训》、《市场营销综合实训》、《网络营销》和《企业运营管理》等课程', '', '赵娣，管理学硕士，副教授。主要从事物流管理和市场营销方面的教学和研究工作，主讲《管理学》、《物流管理》、《新商科跨专业综合实训》、《市场营销综合实训》、《网络营销》和《企业运营管理》等课程。主持省厅级科研项目1项、省级质量工程项目2项，池州市社科联、企业单位以及校级各类项目等7项，发表教科研论文10余篇，参编教材7部。', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, NULL, NULL, NULL, NULL, '硕士，副教授。主要从事物流管理和市场营销方面的教学和研究工作，主讲', NULL, NULL);
