INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('199', '徐华结', '机电工程学院', '半导体学院', NULL, '', '徐华结，男，安徽望江人，池州学院机电工程学院博士、教授，微电子科学与工程教研室主任。主要研究方向为：传感网络，数据采集，智能信息处理与工程应用，人工智能及自动控制，物联网技术。 一、主持参与研究的科研项目 1 、主持安徽省高等学校自然科学重点研究项目：《多参数异构传感器网络数据表示方法的研究》项目编号： KJ2012A207 2 、主持安徽省高等学校优秀青年人才基金项目：《基于语音信息隐秘传输的 FPGA 与 DSP 实现的研究》项目编号： 2009SQRZ138 3 、参与科技部 2011 年国家重大专项《新一代宽带无线移动通信网》子课题《信息汇聚传感器网络综合测试与验证评估环境》 4 、参与国家传感器网络标准工作组—— PG7 接口项目组，制订传感器信号接口标准草案 5 、主持池州学院教学研究项目：《面向本科专业建设的微机原理与单片机实验项目的研究与开发》项目编号： 2007XJ016 6 、主持安徽省高等学校自然科学基金项目：《杜比数字 AC-3 （ Dolby Surround Audio Coding-3 ）音频解码电路的研究与实现》项目编号： 2006KJ084B 7 、参与省教育厅研究项目两项，参与安徽省自然科学基金项目一项。 二、近几年发表的学术论文 [1] Huajie Xu, Yunfei Li, Lei Zheng, Hao Fang, Zhongcheng Wu.Smart Sensor and Sensor Node Design Based on WGSN Data Interface Standard. Sensors & Transducers Journal,Vol. 153, No. 6, June 2013,pp.141-147.(EI Compendex) [2] Huajie Xu, Lei Zheng, Yunfei Li and Zhongcheng Wu.Interface Middleware Design and Implementation Based on Sensor Data Interface Standard.Journal of Applied Sciences,Volume 13, Number 14,2013 2725-2729. (EI Compendex) [3] 徐华结 , 郑磊 , 吴仲城 . 基于嵌入式智能传感节点设计与实现 [J]. 微型机与应用 , 2014,04:63-65+70. [4] 徐华结 , 吴仲城 . 基于 Web 服务实现的环境监测数据采集平台 [J]. 计算机技术与发展 ,2013,06:237-240. [5] 徐华结 , 陈林 . 基于虚拟仪器和仿真技术的实验室建设探讨 [J]. 池州学院学报 ,2009,03:115-118. [6] 徐华结 , 郭立 . 数字音频 AC-3 比特流分析处理器的 FPGA 实现 [J]. 电子测量技术 ,2008,01:142-144. [7] 徐华结 . 基于心理声学模型的杜比数字音频 AC-3[J]. 电声技术 ,2007,10:55-58. [8] 徐华结 , 郭立 , 李琳 , 吴思 . 基于 AC-3 数字音频解码的递归 IMDCT 的 FPGA 实现 [J]. 微电子学与计算机 ,2007,12:167-170. [9] 徐华结 . 一种用于 IMDCT 的对称共用递归结构 [J]. 计算机工程与应用 ,2007,19:83-84+88.', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '学院机电工程学院', NULL, NULL, NULL, '博士、教授，微电子科学与工程教研室主任。主要研究方向为：传感网络，数据采集，智能信息处理与工程应用，人工智能及自动控制，物联网技术。 一、主持参与研究的科研项目 ；本科专业建设的微机原理与单片机实验项目的研究与开发', NULL, NULL);
