INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('223', '韩旭东', '艺术与教育学院', '韩旭东-艺术与教育学院', '油画。主讲课程：油画材料与技法、油画半身像、油画风景、油画创作与实践', '', '讲 师。硕士研究生。研究方向：油画。主讲课程：油画材料与技法、油画半身像、油画风景、油画创作与实践。邮箱：578566682@qq.com', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '硕士研究生', NULL, '油画材料与技法、油画半身像、油画风景、油画创作与实践', NULL, '师。硕士研究生', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('224', '胡惠芳', '旅游与历史文化学院', '教师', NULL, '', '获历史学硕士。主讲课程：历史档案。主持完成省厅人文社科项目3项。发表论文30余篇。省级教学成果。社会兼职：全国历史教师教育专业委员会常务理事', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '硕士', NULL, '历史档案', NULL, '获历史学硕士', NULL, NULL);
