INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('228', '夏启寿', '大数据与人工智能学院', '教授', NULL, '', '夏启寿，男，1975年8月生，安徽庐江人，教授，硕导。2000年7月毕业于安徽理工大学计算机应用专业，获工学学士学位；2007年7月毕业于西北大学计算机软件与理论专业，获工学硕士学位。安徽省教育厅优秀指导教师，池州学院优秀教师，池州学院教坛新秀。 E-mail:xqs@czu.edu.cn 研究领域和方向： 云计算、信息安全、机器学习机 科研论文： 1、殷晓玲,陈晓江,夏启寿,何娟,张鹏艳,陈峰.基于智能手机内置传感器的人体运动状态识别[J].通信学报,2019,40(3):157-169.(EI). 2、殷晓玲,夏启寿,陈晓江,何娟,陈峰.基于智能手机感知的人体运动状态深度识别[J].北京邮电大学学报,2019,42(3):43-50.(EI). 3、Qishou Xia, Xiaoling Yin,*, Juan He, and Feng Chen.Real-time Recognition of Human Daily Motion with Smart Phone Sensor[J].International Journal of Performability Engineering,2018,14(4):593-602.(EI) 4、夏启寿,殷晓玲.云计算服务中安全动态访问控制在电子健康档案系统中的应用[J].安庆师范大学学报(自然科学版),2017,23(4):62-67. 5、丁德武,夏启寿,殷小玲.蛋白质螺线管域检测的序列和结构方法综述[J].生物学杂志, 2017,34(195):85-88. 6、夏启寿,殷晓玲,王汝传. RBAC中基于信任的细粒度访问控制研究[J].计算机工程与应用,2012,48(21):75-78. 7、殷晓玲,夏启寿,王汝传.Web Services中基于信任的动态访问控制[J].计算机应用研究.2011,28(11):4331-4334. 8、丁德武,谢杨梅,夏启寿.The centers of kinas and phosphates interaction network[J].计算机与应用化学.2011.28(6):783-786. 9、夏启寿,殷晓玲.周期时间特性的角色访问控制[J].计算机应用研究, 2009,26(12):4730-4734. 10、方元康,胡学钢,夏启寿等.改进的Web日志数据预处理技术[J].计算机工程,2009,35(10):73-74. 11、方元康,胡学钢,夏启寿.Web日志预处理中优化的会话识别方法[J].计算机工程,2009,35(7):49-51 12、方元康,胡学钢,夏启寿等.基于框架网页与页面阈值的会话识别算法[J].计算机应用与软件2009,26(1):18-19. 13、夏启寿,殷晓玲.基于时间角色访问控制授权模型的研究[J].计算机技术与发展2008,18(11).138-141. 14、夏启寿,殷晓玲.基于时间的RBAC转授权模型[J].西北大学学报(自然科学版), 2008,38(6):932-936. 15、方元康,胡学钢,夏启寿.一种改进的Web日志会话识别方法[J].计算机技术与发展(原微机发展).2008.18(11):214-216. 教研论文： 1、殷晓玲,夏启寿,黄孝,章哲庆.新工科背景下的C语言程序设计MOOC建设——以池州学院为例[J].池州学院学报,2019,33(3):121-123. 2、王文广,夏启寿.基于B-Learning的《C程序设计》课程教学过程模式设计[J].电脑知识与技术,2019,15(12):157-158+161. 3、夏启寿,殷晓玲.应用型本科院校计算机专业毕业设计(论文)改革探析[J].池州学院学报,2018,32(03):142-144. 4、殷晓玲,夏启寿.应用型本科院校“数据结构”课程教学研究[J].池州学院学报, 2016(6).131-134 5、王文广,夏启寿.以用为先的精品课程网站建设探究[J].河北广播电视大学学报,2013,(3).78-80 教科研项目： 1、安徽省教育厅教研重点项目：精品资源共享课程-C程序设计(2016gxx097)，主持 2、全国高等院校计算机基础教育研究会项目：以“人工智能”为背景、以“计算思维”为导向的“大学计算机基础”课程内容的建设研究(2018-AFCEC-197)，主持 3、池州学院教学研究项目：以专业应用为导向的大学计算机基础教学改革措施探究(2012jyxm042)，主持 4、安徽高校自然科学研究项目：基于云模型的自适应访问控制在云计算中的应用研究(KJ2015A290)，主持 5、池州学院自然科学研究项目：普适环境中基于模糊理论的细粒度访问控制研究(2013ZRZ008)，主持 6、安徽高校自然科学研究项目：基于分组、', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '安徽理工大学', NULL, NULL, NULL, '大学计算机应用专业，获工学学士学位；；大学计算机软件与理论专业，获工学硕士学位。安徽省教育厅优秀指导教师，池州学院优秀教师，池州学院教坛新秀。 ；大学学报,', NULL, NULL);
