INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('238', '陈念', '大数据与人工智能学院', '教授', NULL, '', '陈念，男，1978.02-，安徽池州人，教授，硕士，池州学院教学名师，双能型教师。2012.09~2013.07在南京理工大学访学。 E-mail: 研究领域和方向： 主讲课程： 《计算机组成原理》、《计算机科学导论》、《计算机图形学》 科研论文： 1.专著《网络文本分类与应用》，中国水利水电出版社，2020.08； 2.A Search Method for Optimal Band Combination of Hyperspectral Imagery Based on Two Layers Selection Strategy，2021.06,SCI； 3.SICEM: A Generation Approach of Band Combination for Hyperspectral Imagery Reconstitution Based on Space and Information Analyses，2021.09,SCI； 教科研项目 ： 1.支持：面向形态多样性数据的密度模型增量聚类算法研究(2020A0767)，教育厅自然重点项目，2021.01~2022.12； 2.主持：网络工程基层示范教研室项目(2018jyssf072)，省级质量工程项目，2019.01~2022.04； 3.主持：MOOC 课程《计算机图形学》 (2016mooc262)，省级质量工程项目，2017.01~2020.04； 4.主持：“计算机网络”教学团队 (2020XSZTD04)，校级质量工程项目，2020.10~2023.04。 获奖情况： 1、2017 年、2019 年获评省级优秀学科竞赛指导教师2 次； 2、2015~2017 年连续获校级教学成果三等奖3 项； 3、2021 年获校级优秀课堂教学质量奖1 项； 4、2022 年获校级教学创新设计大赛二等奖1 项。', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, NULL, NULL, '《计算机组成原理》、《计算机科学导论》、《计算机图形学》 科研论文： ', NULL, '硕士，池州学院教学名师，双能型教师。；大学访学。 ', NULL, NULL);
