INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('251', '李海燕', '大数据与人工智能学院', '李海燕-大数据与人工智能学院', '微分方程与动力系统的研究', '', '李海燕，女，1980年生，安徽桐城人，池州学院大数据与人工智能学院讲师。2002年7月本科毕业于安徽师范大学数学教育专业，2002~2004年在池州师专任助教。2007年7月获安徽大学数学与应用数学硕士学位。2007至今就职于池州学院大数据与人工智能学院。2008年7月被评为讲师。 主要从事微分方程与动力系统的研究。教学上主要从事《数学分析》、《高等数学》的课程教学。 主要研究课题 2009.1主持池州学院校级科研一般项目“脉冲微分方程组解的存在性研究”（校级一般XK0910）。 主要期刊论文 1、李海燕，魏章志，王良龙.抽象空间中一类二阶奇异脉冲微分方程的正解[J]. 安徽大学学报（增刊），2006，4-7 2、一阶脉冲泛函微分方程的边值问题. 合肥学院学报（自然科学版）.2007.vol.17 NO.1 (第一作者) 3、一类二阶奇异脉冲微分方程的正解. 池州学院学报（自然科学版）. 2008.vol.22 NO.3 (第一作者) 4、抽象空间中二阶奇异脉冲微分方程边值问题的多个正解. 安庆师范学院学报（自然科学版）.2009.Vol.15 NO.1（第一作者） 5、二阶非线性微分方程组三点边值问题的多个正解(英文).大学数学.2011.vol.27 NO.6(第一作者) 6、风险价值VaR及实证研究 .安庆师范学院学报（自然科学版）.2015.vol.21 NO.1（第一作者）. 获奖情况 1、获2011年度池州学院青年教师教学技能大赛一等奖； 2、2013-2014年度第一学期“数学分析1”试卷被评为校级优秀试卷； 3、获2014-2015、2015-2016、2016-2017、2017-2018学年校优秀教学质量奖', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '安徽师范大学', NULL, NULL, NULL, '本科毕业于安徽师范大学数学教育专业，；大学数学与应用数学硕士学位。；大学学报', NULL, NULL);
