INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('253', '时国平', '机电工程学院', '半导体学院', NULL, '', '时国平，女，教授，硕士，硕士生导师。近年来，先后主持安徽省质量工程项目项目2项，安徽省教育厅科研自然重点项目2项；指导国家级大学生创新创业训练项目7项；获得省级、校级教学成果二等奖2项；指导学生在“恩智浦”全国智能汽车竞赛中获得二等奖。发表科研论文10余篇，授权发明专利3项，实用新型专利11项。', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, NULL, NULL, NULL, NULL, '硕士，硕士生导师。近年来，先后主持安徽省质量工程项目项目；大学生创新创业训练项目', NULL, NULL);
