INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('256', '吴璞', '大数据与人工智能学院', '副教授', '复杂网络，智能计算 主持的教科研项目： ', '', '吴璞，副教授，男，1968年2月生，安徽池州人。1992年毕业于安徽师范大学计算机教育专业，获理学学士学位，2009年毕业于南京邮电大学软件工程专业，获硕士学位。主要获得的奖励： 主讲课程： 程序设计基础，数据结构，计算机网络，数据库原理及应用等 研究方向： 复杂网络，智能计算 主持的教科研项目： 1、省级一般，基于智能代理的无线传感器网络协议和算法研究(KJ2009B233Z)，主持 2、校级自然重点，生物网络关键节点的识别方法研究（2013ZRZ003）,参与 3、校级自然一般，基于马尔科夫模型方法的蛋白质残基预测（2013ZR017）,参与 4、校级专业质量标准建设，地方应用型本科院校计算机科学与技术专业质量标准建设，2015，主持 5、校级特色品牌专业建设，计算机科学与技术(2018XTSPP01)，主持 研究成果： 一种无线传感器网络节点带宽分配策略,池州学院学报, 2007,10 层次式无线传感器网络中的协商机制研究，计算机技术与发展2008,3 网格下基于并行混合GA的复杂函数优化算法,安庆师范学院学报(自然科学版),2008,5', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '安徽师范大学', NULL, '程序设计基础，数据结构，计算机网络，数据库原理及应用等 研究方向： 复杂网络，智能计算 主持的教科研项目： ', NULL, '大学计算机教育专业，获理学学士学位，；大学软件工程专业，获硕士学位。主要获得的奖励： 主讲课程： 程序设计基础，数据结构，计算机网络，数据库原理及应用等 研究方向： 复杂网络，智能计算 主持的教科研项目： ；本科院校计算机科学与技术专业质量标准建设，', NULL, NULL);
