INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('271', '李小新', '大数据与人工智能学院', '教授', '代数图论、化学图论 学术兼职： 美国', '', '李小新，教授，男，1976年12月生，安徽怀宁人。1999年毕业于安徽大学应用数学专业，获理学学士学位，2005年于安徽大学获应用数学专业硕士学位。 获得的主要奖励： 教学上： 1. 2020年获“安徽省教学名师”称号； 2. 2020年获“池州学院最美教师”称号； 3. 2022年获安徽省高校教师教学创新大赛省级三等奖； 4. 2016年获安徽省教学成果一等奖； 5. 2015年获全国高校数学微课程教学设计竞赛华东赛区二等奖； 6. 2006年获得“池州学院教师课堂教学技能比赛一等奖”； 7. 2006年获得“安徽省第二届数学教案说课比赛一等奖”； 8. 2008年获得“池州学院教坛新秀”称号； 9. 自参加工作以来，连续获池州学院“优秀教学质量奖”。 科研上： 1. 2015年11月获安徽省第八届自然科学优秀学术论文三等奖。 指导学生比赛： 1. 2015年9月，在全国大学生数学建模竞赛中，指导学生卜子健、刘翠萍、胡倩倩获安徽省赛区本科组二等奖； 2. 2018年11月，在第九届安徽省高等学校师范生教学技能竞赛上，指导学生林家慧获得一等奖，连倪鸿获得二等奖； 3. 2021年11月，在第十三届全国大学生数学竞赛中，指导叶徐坤获得数学B类省级二等奖。 主讲课程： 数学分析、高等代数、抽象代数、图论、点集拓扑学、高等数学、线性代数等 研究方向： 代数图论、化学图论 学术兼职： 美国《数学评论》评论员（编号：108966） 校内兼职： 青年教师教学型导师、科研型导师，校级教学督导员，校学术委员会成员。 服务社会： 作为B站up主“秋浦新哥”，推广大学数学的教学成果。 主持的教科研项目： 1、安徽省高校青年人才支持计划项目(重点)：分子图的拓扑指标及其逆问题研究(gxyqZD2016367)； 2、安徽省高校自然科学研究项目(重点)：图的基于距离的拓扑指标的研究( KJ2013A196)； 3、安徽省高校省级自然科学研究项目：图的谱研究（KJ2010B136）； 4、安徽省高校青年教师科研资助项目：协正矩阵的判定及谱理论研究（2007jql188）； 5、池州学院教学团队（代数类课程群教学团队）项目（2016XJXTD02）； 6、安徽省精品线下开放课程（线性代数）建设项目（2018kfk051）； 7、安徽省高校示范课程（线性代数）建设项目（2020SJJXSFK1789）。 研究成果： 1. On the reciprocal degree distance of graphs with cut vertices or cut edges.Ars Combinatoria，2017，SCI.（第一作者） 2. The Laplacian-energy-like invariants of three types of Lattices.Journal of Analytical Methods in Chemistry,2016,SCI.(通讯作者) 3. The connectivity and the Harary index of a graph.Discrete Applied Mathematics，2014，SCI. （第一作者） 4. A lower bound for the distance signless Laplacian spectral radius of graphs in terms of chromatic number.数学研究及应用，2014，CSCD核心. （第一作者） 5. Minimum distance spectral radius of graphs with given edge connectivity.数学杂志，2014，CSCD核心.（第一作者） 6. 连通图的Harary指数上界及其极图.中国科学技术大学学报，2014，CSCD核心. （第一作者） 7. 含割点的连通图的最小距离无符号Laplace谱半径.中国科学技术大学学报，2014，CSCD核心. （第一作者） 8. A unified approach to maximizing the spectral radii of the complements of graphs with small dimension.应用数学，2013，CSCD核心.（第一作者） 9. 偕正矩阵的判定.高等学校计算数学学报,2010，CSCD核心. （第一作者） 10. The least eigenvalue of graphs with domination number 1.第九届中国矩阵理论及其应用国际会议，2010，ISTP. （第一作者） 11. On positive eigenvectors of coposit', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '安徽大学', NULL, '数学分析、高等代数、抽象代数、图论、点集拓扑学、高等数学、线性代数等 研究方向： 代数图论、化学图论 学术兼职： 美国《数学评论》评论员', NULL, '大学应用数学专业，获理学学士学位，；大学获应用数学专业硕士学位。 获得的主要奖励： 教学上： ；大学生数学建模竞赛中，指导学生卜子健、刘翠萍、胡倩倩获安徽省赛区本科组二等奖； ', NULL, NULL);
