INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('320', '李九云', '文学与传媒学院', '李九云-文学与传媒学院', NULL, '', '基本情况 姓名 李九云 性别 女 职称 讲师 所属 系 是否硕导 否 最高学历 本科 Email 1294944709qq.com 详细情况 所在学科专业 汉语言文学 研究方向 秘书学 讲授课程 应用文写作、大学语文 教育经历 1.1998—2002 ，安庆师范学院中文系 2.2011—2014 ，中国人民大学教育学院 工作经历 1.2002 年 7 月 —2004 年 7 月淮南四中任教 2.2004 年 7 月至今，池州学院 科研项目 学术论文 1.浅谈信息时代的高校学生思想政治教育工作，时代报告.2013（2） 2.重视标签理论 创新工作思路，科教文汇.2013（7） 著作教材 获奖情况 1.2010 年池州学院优秀辅导员 2.2008 年中文系度考核为优 社会兼职', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, NULL, NULL, NULL, NULL, '本科 ；大学语文 教育经历 ；大学教育学院 工作经历 ', NULL, NULL);
