INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('323', '宋桂娥', '商学院', '副教授', NULL, '', '宋桂娥，天津财经大学管理学硕士、副教授、中级会计师、注册会计师。主要研究领域为财务会计、政府预算会计等。先后发表了《对我国预算会计改革的若干思考》、《论会计诚信及其倡导与规制》、《会计信息披露为效率和公平“说话”》等多篇论文，荣获安徽省会计诚信有奖征文比赛鼓励奖、国家财政部会计信息检查征文比赛三等奖。从事会计学教育三十多年，在年度考核中，多次被评为优秀等级，并多次荣获学校两学年度教学质量优秀奖。', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, NULL, NULL, NULL, NULL, '大学管理学硕士、副教授、中级会计师、注册会计师。主要研究领域为财务会计、政府预算会计等。先后发表了', NULL, NULL);
