INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('351', '钱叶旺', '机电工程学院', '教师', NULL, '', '教授。工学硕士。主讲课程：模拟电子技术基础及实验、数字电子技术基础及实验、电路分析及实验、信号与系统、数字信号处理、通信原理、高频电子线路。主持池州学院院级自然科研项目2项。发表科研论文20余篇。省级教学成果', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '硕士', NULL, '模拟电子技术基础及实验、数字电子技术基础及实验、电路分析及实验、信号与系统、数字信号处理、通信原理、高频电子线路', NULL, '授。工学硕士', NULL, NULL);
