INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('357', '包健', '大数据与人工智能学院', '副教授', '一线基础课程教学工作、曾在安庆师范学院学报、高等数学研究、大学数学、池州学院学报等期刊发表论文、并获得过优秀试卷、年度考核优秀、优秀教学质量奖等荣誉称号', '', '包健，男，1990年7月毕业于淮北煤炭师范学院数学系基础数学专业，进入池州工业技工学校任教，1999年9月进入池州师范专科学校数学系任教，2000年在安徽师范大学数学系以研究生毕业同等学力申请硕士学位教师进修班进修，2006年评为副教授。主要从事一线基础课程教学工作，曾在安庆师范学院学报、高等数学研究、大学数学、池州学院学报等期刊发表论文，并获得过优秀试卷、年度考核优秀、优秀教学质量奖等荣誉称号。', '0', '0', '0', '2026-06-05 16:04:28', '2026-06-05 16:04:28', NULL, '淮北煤炭师范学院', NULL, NULL, NULL, '大学数学系以研究生毕业同等学力申请硕士学位教师进修班进修，；大学数学、池州学院学报等期刊发表论文，并获得过优秀试卷、年度考核优秀、优秀教学质量奖等荣誉称号。', NULL, NULL);
