INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('372', '殷贵林', '商学院', '副教授', '国际经济与贸易、区域经济等方面的研究工作、先后主持并参与省级教科研项目10多项、校级教科研项目多项、公开发表学术论文10余篇、主编教材1部、参编教材2部', '', '殷贵林，中国人民大学经济学硕士，副教授。池州学院商学院（法学院）国际经济与贸易专业教师，主讲国际结算、报关实务、国际货物运输与保险、外贸单证实务等国际经济与贸易专业课程。 多年来主要从事国际经济与贸易、区域经济等方面的研究工作，先后主持并参与省级教科研项目10多项，校级教科研项目多项，公开发表学术论文10余篇，主编教材1部，参编教材2部。', '0', '0', '0', '2026-06-05 16:04:51', '2026-06-05 16:04:51', NULL, NULL, NULL, NULL, NULL, '大学经济学硕士，副教授。池州学院商学院', NULL, NULL);
