INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('425', '杨雄', '地理与规划学院', '杨雄-地理与规划学院', NULL, '', '杨雄 ，男，未定级，中国科学院南京土壤研究所农学博士。近年来，主持省级教科研项目1项，承担横向项目1项，在国内外期刊发表论文8篇。 教授课程 ：安徽地理、中国地理、大学生职业生涯规划与就业素养 研究领域 ：土壤重金属污染修复、粮食安全 联系方式 ：2313164381@qq.com', '0', '0', '0', '2026-06-05 16:52:43', '2026-06-05 16:52:43', NULL, NULL, NULL, NULL, NULL, '博士。近年来，主持省级教科研项目；大学生职业生涯规划与就业素养 研究领域 ：土壤重金属污染修复、粮食安全 联系方式 ：', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('426', '刘小媛', '地理与规划学院', '刘小媛-地理与规划学院', '土壤碳氮循环 联系方式： liuxy@czu.edu.cn', '', '刘小媛， 女，讲师，农学博士，池州学院青年教师，近年来，在国内外期刊发表论文30余篇。 教授课程： 土地生态学、土地整治与生态修复 研究领域： 土壤碳氮循环 联系方式： liuxy@czu.edu.cn', '0', '0', '0', '2026-06-05 16:52:43', '2026-06-05 16:52:43', NULL, NULL, NULL, '土地生态学、土地整治与生态修复 研究领域： 土壤碳氮循环 联系方式： liuxy@czu.edu.cn', NULL, '博士，池州学院青年教师，近年来，在国内外期刊发表论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('427', '胡刘胤', '地理与规划学院', '胡刘胤-地理与规划学院', '环境监测、污染控制与修复、电化学/荧光传感 联系方式： liuyinhu@sjtu.edu.cn', '', '胡刘胤 ，男，未定级，环境科学与工程博士，池州学院青年教师。近年来，在国内外期刊发表论文10余篇。 教授课程： 中外城市建设史、经济地理学（双语） 研究领域： 环境监测、污染控制与修复、电化学/荧光传感 联系方式： liuyinhu@sjtu.edu.cn', '0', '0', '0', '2026-06-05 16:52:43', '2026-06-05 16:52:43', NULL, NULL, NULL, '中外城市建设史、经济地理学（双语） 研究领域： 环境监测、污染控制与修复、电化学/荧光传感 联系方式： liuyinhu@sjtu.edu.cn', NULL, '博士，池州学院青年教师。近年来，在国内外期刊发表论文', NULL, NULL);
