INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('429', '荣慧芳', '地理与规划学院', '副教授', '城市与区域规划；旅游地理', 't_429_avatar.jpg', '荣慧芳 ，女，1984年9月生，河南永城人。2005年6月获郑州大学地理信息系统专业理学学士学位，2008年6月获兰州大学城市与区域规划理学硕士学位， 2021年6月获南京师范大学人文地理学博士学位 。2008年7月进入池州学院工作，现为池州学院地理与规划学院专业教师， 2018年被评为池州学院“双师型”教师， 2021年12月晋升为副教授，。 教授课程： 城市规划原理、图像处理技术、计算机辅助规划设计 研究领域： 城市与区域规划，旅游地理 一、主持项目 1．基于遥感和GIS的城市宜居性评价研究——以池州市为例，安徽省教育厅人文项目，2012年，结项良好； 2.生态文明视阈下安徽省城镇化与资源环境互耦特征及协调发展对策研究，安徽省社科规划项目，2015年，结项良好； 3．应用型本科院校人文地理与城乡规划专业实践教学体系构建、安徽省质量工程项目，2015年，结项良好。 二、近五年学术成果 1 基于熵权物元模型的皖江城市带土地生态安全评价 水土保持研究，2015 第一作者 2 甘肃省农业经济效益的地区差异及成因分析 安徽农业大学学报，2016 第一作者 3 基于重心模型的安徽省城镇化与生态环境匹配度分析 中国土地科学，2017 第一作者 4 地方本科院校人文地理与城乡规划专业实践教学体系构建 池州学院学院，2018 第一作者 5 安徽省城镇化-生态环境-旅游产业 水土保持研究，2019 第一作者 6 基于网络数据的乡村旅游热点识别及成因分析 自然资源学报，2020 第一作者 三 、 获奖情况 2008-2010年，池州学院，优秀教学质量奖； 2009年，安徽省第一届GIS大赛二等奖； 2010年，第四届挑战杯安徽省大学生课外学术科技作品竞赛优秀指导教师奖； 2010-2012年，优秀教学质量奖； 2011年，池州学院，优秀辅导员奖； 2011年，2012年，2015年，池州学院年度考核优秀奖； 2014年，安徽省第五届GIS大赛三等奖，优秀指导教师奖； 2015年，池州市第四届社科成果奖； 2016年，池州学院优秀共产党员，教坛新秀； 2018年，池州学院“双师型”教师。', '3', '0', '0', '2026-06-05 16:54:37', '2026-06-16 17:42:07', NULL, NULL, NULL, '城市规划原理；图像处理技术；计算机辅助规划设计', NULL, '郑州大学地理信息系统专业理学学士；兰州大学城市与区域规划理学硕士；南京师范大学人文地理学博士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('430', '赵冰雪', '地理与规划学院', '副教授', '海岸带遥感、湿地生态遥感（1988年生，安徽淮北人）', 't_430_avatar.jpg', '女，池州学院地理与规划学院副教授，南京大学地理学专业博士，池州学院青年教师教学型、科研型导师，池州学院教坛新秀，安徽工业大学、安徽建筑大学兼职硕士生导师，中国地理学会会员。主持省部级教科研项目6项，在国内外期刊发表论文十余篇，主编学术专著1部，获安徽省教学成果一等奖等各类教学奖项多项，指导省级大学生创新创业训练项目多项。', '5', '1', '5', '2026-06-05 16:54:37', '2026-06-16 22:40:49', NULL, '南京大学（博士）', '主持省部级教科研项目6项、横向项目4项；第一作者发表中英文学术论文10余篇；出版学术专著3部；获安徽省教学成果一等奖1项、全国第十三届青年教师GIS教学研修班微课比赛二等奖1项、池州学院智慧教学大赛二等奖1项、教学创新大赛三等奖1项；指导学生获国家级、省级学科竞赛获奖十余项。', '遥感概论、遥感图像解译、遥感专业英语', NULL, '南京大学地理学专业博士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('431', '章勇', '地理与规划学院', '副教授', '热红外遥感', 't_431_avatar.jpg', '章勇，男，1988年10月生，安徽铜陵人。副教授，测绘科学与技术专业博士。主要研究方向为热红外遥感。', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, '主持省级教科研项目2项，承担横向项目1项；以第一作者发表SCI论文2篇（中科院一区TOP和二区各1篇）；获安徽省大学生GIS技能大赛暨长三角空间信息技术大赛"优秀指导教师"2项；指导省级、校级大学生创新创业训练项目2项；指导学生国家级、省级学科竞赛获奖10余项', '遥感原理与应用；摄影测量学', NULL, '河北工程大学测绘工程专业学士（2012）；河海大学摄影测量与遥感专业硕士（2015）；河海大学测绘科学与技术专业博士（2025）', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('432', '王雷', '地理与规划学院', '副教授', '大气环境遥感；大气污染时空分异及其成因；PM2.5与O3时空耦合关系；地质灾害易发性评价；生境质量与开发强度协调演化', 't_432_avatar.jpg', '王雷，男，1988年10月生，安徽池州人，副教授。2013年7月入职池州学院地理与规划学院，测绘与遥感科学技术系专任教师，中国矿业大学摄影测量与遥感博士在读。', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '硕士', '【省级科研项目】
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('433', '吴海中', '地理与规划学院', '副教授', '自然地理学 遥感地学分析 联系方式： hzwu2014@163.com', '', '吴海中 ，男，1985.10出生，安庆人，2005年9月-2009年7月就读于安徽师范大学地理科学专业，获理学学士学位；2009年9-2010年11月就读于安徽师范大学国土资源与旅游学院自然地理学专业，2010年11月-2012年6月就读于中国科学院对地观测与数字地球科学中心，获理学硕士学位。2012年7月-2014年8月，注册成立安庆法思特教育咨询有限公司。2014年8月在池州学院资源环境与旅游系工作，现为池州学院地理与规划学院专业教师。 教授课程： 自然地理学 普通地质学 研究领域： 自然地理学 遥感地学分析 联系方式： hzwu2014@163.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '安徽师范大学', NULL, '自然地理学 普通地质学 研究领域： 自然地理学 遥感地学分析 联系方式： hzwu2014@163.com', NULL, '大学地理科学专业，获理学学士学位；；大学国土资源与旅游学院自然地理学专业，；硕士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('434', '徐成林', '地理与规划学院', '副教授', '土地政策及土地经济、不动产价格 联系方式： xucl2024@163.com', '', '徐成林， 男，副教授，管理学硕士，池州学院青年教师教学型导师，池州学院“双能型”教师，池州学院教学名师，安徽建筑大学大学兼职硕士生导师，安徽省土地估价师与不动产登记代理人协会理事，安徽省自然资源厅、农业农村厅、住房和城乡建设厅专家。近年来，主持省级教科研项目6项，承担横向项目2项，在国内外期刊发表论文10余篇，获教学成果省级一等奖1项、三等奖1项，校级二等奖2项。 教授课程： 《不动产估价》、《房地产估价实务》 研究领域： 土地政策及土地经济、不动产价格 联系方式： xucl2024@163.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '安徽建筑大学大学（硕士）', NULL, '《不动产估价》、《房地产估价实务》 研究领域： 土地政策及土地经济、不动产价格 联系方式： xucl2024@163.com', NULL, '硕士，池州学院青年教师教学型导师，池州学院；大学大学兼职硕士生导师，安徽省土地估价师与不动产登记代理人协会理事，安徽省自然资源厅、农业农村厅、住房和城乡建设厅专家。近年来，主持省级教科研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('435', '孙建平', '地理与规划学院', '副教授', '时空数据挖掘 联系方式： 267187655@qq.com', '', '孙建平 ，女，副教授，地图制图学与地理信息工程工学硕士，注册测绘师，安徽省线上教学新秀，池州学院青年教师教学型导师，池州学院“双能型”教师，池州学院教学督导员，安徽建筑大学、安徽工业大学兼职硕士生导师，安徽省招投标专家库专家、安徽省乡村建设专家库专家。近年来，主持省级教科研项目9项，承担横向项目3项，在国内外期刊发表论文10余篇，获教学成果省级一等奖1项、校级一等奖1项、校级二等奖2项，指导国家级、省级大学生创新创业训练项目5项，指导学生国家级、省级学科竞赛获奖20余项。 教授课程： 地理信息系统原理、地图学 研究领域： 时空数据挖掘 联系方式： 267187655@qq.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, NULL, '地理信息系统原理、地图学 研究领域： 时空数据挖掘 联系方式： 267187655@qq.com', NULL, '硕士，注册测绘师，安徽省线上教学新秀，池州学院青年教师教学型导师，池州学院；大学、安徽工业大学兼职硕士生导师，安徽省招投标专家库专家、安徽省乡村建设专家库专家。近年来，主持省级教科研项目；大学生创新创业训练项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('436', '纪凯婷', '地理与规划学院', '副教授', NULL, '', '纪凯婷 ，女，1990年4月生，安徽池州人。2007年9月至2011年7月就读于安徽农业大学园林专业；2014年7月毕业于南京林业大学。池州学院副教授、双能型教师。 教授课程： 设计初步、计算机辅助规划设计、村庄规划实践、城市园林绿地规划、园林植物学、园林植物配置等。 研究领域： 乡村绿色发展、村庄规划、详细设计 一、承担的主要教科研 项目 1.安徽省哲学社科规划青年项目《安徽省乡村绿色发展驱动机制及实现路径研究》（AHSKQ2020D70）； 2.安徽省教育厅人文社科重点项目《皖南国际文化旅游示范区乡村旅游与绿色发展协同耦合机制及演进对策研究》（SK2020A0561）； 3.安徽省自然资源厅科技项目《村庄规划中韧性评价与提升策略研究》（2024-k-6）； 4.池州学院自然科学研究项目《池州市海绵城市建设中雨水花园景观设计研究》（2017ZR006）； 5.《齐山公园植被与地质研究》，2022年； 6.安徽省教学示范课《设计初步》（2020SJJXSFK1771）； 7.安徽省教学改革项目《“双一流”背景下基于OBE理念的城乡规划专业实践教学改革创新模式研究》（2021jyxm1017）； 8.池州学院虚拟教研室项目《城乡规划虚拟教研室》（2023XXJYS01）； 9.池州学院校本一流教材《人文地理与城乡规划专业实践教学指导书》（2023XYLJC06）； 10.池州学院教学改革项目《基于翻转课堂的手绘教学改革实践与路径——以人文地理与城乡规划专业为例》（2017XJYXM21）。 二、 近5年主要成果 [1] 纪凯婷.安徽省农业生产减污降碳协同性驱动因子识别及响应[J].地理与地理信息科学,2025,41(2):105-110. [2]纪凯婷,张乐勤,王雷.安徽省乡村绿色发展水平测度及时空演变分析[J].贵州师范大学学报(自然科学版),2023,41(2):33-40. [3]纪凯婷,王文琴,李琼,等.基于PCA-PLS的池州市乡村旅游驱动因子的识别及响应[J].安徽师范大学学报(自然科学版),2022,45(6):567-574+583. [4]纪凯婷,张乐勤.安徽省乡村绿色发展的驱动因子及其影响[J].水土保持通报,2023,43(2):389-396. [5]纪凯婷.皖南国际文化旅游示范区核心区旅游-生态-文化耦合协调研究[J].黄山学院学报,2023,25(4):36-42. [6]纪凯婷,荣慧芳,韩雪,等.城乡规划专业实践教学改革创新模式研究[J].池州学院学报,2023,37(3):132-135. [7]纪凯婷,李琼,王雷,等.基于OBE理念的城市园林绿地规划课程教学创新设计[J].高师理科学刊,2023,43(7):97-101. 三、学生指导与获奖情况 2024-2025年，全国高等院校大学生乡村规划方案竞赛一等奖1项、一等奖1项、三等奖2项，安徽省高等院校大学生乡村规划建设方案竞赛一等奖2项、二等奖2项、三等奖3项； 2022年，安徽省高等院校大学生乡村规划建设方案竞赛二等奖1项； 2022-2023年，安徽省乡村振兴创新创业大赛三等奖、优秀奖； 2023-2024年，池州市“和美乡村•转角遇到美”青年创意设计PK赛，二等奖2项，三等奖1项，优秀奖3项； 2023年，国家级大创项目《兰亭茗序—“智慧茶乡，科技振兴，迈向可持续发展”》（202311306045X）； 2023年，省级大创项目《云上田园——互联网赋能乡村振兴平台》（S202311306203X）、《安徽省土地利用碳排放时空演变规律及低碳优化路径研究》（S202311306123）、《后疫情时代新型特色民宿的旅游设计与推广》（S202311306143X）； 2020年，省级大创项目《“博文”大学生花卉种植俱乐部》（202011306087）、《留住感恩情—共植毕业花》（202011306018）； 2019年，省级大创项目《池州市海绵城市建设评价》（201911306055）； 2024年，池州市第七届社会科学成果奖； 2021年，池州市第六届社会科学成果奖。 联系方式：jkt00168@163.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '安徽农业大学', NULL, '设计初步、计算机辅助规划设计、村庄规划实践、城市园林绿地规划、园林植物学、园林植物配置等', NULL, '大学园林专业；；大学。池州学院副教授、双能型教师。 教授课程： 设计初步、计算机辅助规划设计、村庄规划实践、城市园林绿地规划、园林植物学、园林植物配置等。 研究领域： 乡村绿色发展、村庄规划、详细设计 一、承担的主要教科；大学学报', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('437', '贾丽', '地理与规划学院', '副教授', NULL, '', '贾丽 ，女，1984年10月生，副教授。2003年9月至2007年7月就读于安徽农业大学土地资源管理专业，获管理学学士学位；2007年9月至2009年7月就读于武汉大学土地资源管理专业，获管理学硕士学位。2009年7月至今在池州学院工作，现为池州学院地理与规划学院专业教师，校级双能型教师，房地产估价师，土地估价师，房地产经纪人。 教授课程 ：土地管理学、房地产开发与经营、房地产市场营销、房地产经济学、社交礼仪。 研究领域 ：三生空间、农村人居环境治理、农村三产融合发展 主要代表性科研项目： [1]主持安徽省哲学社科规划项目《协同视角的安徽省乡村振兴三生融合发展研究》（AHSKQ2018D19） [2]主持安徽省教育厅哲学社会科学重点研究项目《乡村全面振兴背景下安徽省“三生”空间功能测度及耦合协调研究》（2023AH052339） [3]主持校级重点项目《农村宅基地退出问题的研究》（2015RWZ005） [4]主持池州社科联重点课题《“双碳”目标下池州市乡村振兴绿色低碳发展路径研究》（2022ZD11） [5]主持池州社科联一般课题《乡村振兴背景下的池州市乡村人居环境治理模式创新研究》（A201910） [6]主持校级项目《土地整理中的生态伦理道德》（2012RW010） [7]主持校级项目《地价动态监测中数字地价模型建立方法研究》（2009RC033） 主要代表性教研项目： [1]主持省级教学示范课《房地产开发与经营》（2020SJJXSFK1765） [2]主持省级一般教研项目《房地产开发与经营课程建设中创客元素的嵌入研究》（2017jyxm0582） [3]主持校级重点课程思政示范课程《房地产开发与经营》（2019XKCSZ10） 发表论文： [1]农村闲置宅基地退出过程中农民权益保障研究，池州学院学报，2020（1）：46-50. [2]合肥市桃花工业园区土地集约利用评价研究.山西能源学院学报，2019（1）：81-84. [3]农村闲置宅基地再利用方式探索.山东农业工程学院学报，2019（7）：21-25. [4]土地整理中的生态伦理道德建设.中国集体经济，2013（07）：7-9 [5]优化农村人居环境的策略研究_基于美好乡村建设背景.当代经济，2015（36）：25-27 [6]合理构建土地资源管理专业实践教学体系.考试周刊，2013（69）：169-170 [7]创客教育理念下的《房地产开发与经营》课程教学改革研究.创新创业理论研究与实践，2018（14）：88-90 联系方式： 邮箱： limen457@126.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '安徽农业大学', NULL, NULL, NULL, '大学土地资源管理专业，获管理学学士学位；；大学土地资源管理专业，获管理学硕士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('438', '王丽英', '地理与规划学院', '副教授', '土地利用与保护、土地制度 联系方式： 34300658@qq.com', '', '王丽英， 女，副教授，南京农业大学公共管理硕士，池州学院“双能型”教师，池州学院教坛新秀，乡村建设专家库专家。近年来，主持省级教科研项目3项，承担横向项目1项，在国内外期刊发表论文5篇，指导国家级、省级大学生创新创业训练项目2项，指导学生国家级、省级学科竞赛获奖2项。 教授课程： 土地资源调查与评价、城市规划原理、住宅小区规划 研究领域： 土地利用与保护、土地制度 联系方式： 34300658@qq.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, NULL, '土地资源调查与评价、城市规划原理、住宅小区规划 研究领域： 土地利用与保护、土地制度 联系方式： 34300658@qq.com', NULL, '大学公共管理硕士，池州学院；大学生创新创业训练项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('439', '王文琴', '地理与规划学院', '副教授', NULL, '', '王文琴 ，女，1984年11月，安徽铜陵人，副教授。2003—2007年就读于长沙理工大学资源环境与城乡规划专业，获得理学学士学位；2007—2010年就读于安徽师范大学土地资源管理专业，获得管理学硕士学位。2010年7月至今在池州学院工作，现任地理与规划学院教师，校级双能型教师，二级建造师。 讲授课程 ：土地经济学、房地产经济学、房地产制度与政策。 研究领域 ：土地制度与政策 主持代表性的科研项目 ： （1）主持江南产业集中区土地整治模式研究(B2012008)，2012年池州市社科联项目，已经结题 （2）主持土地信息系统实践教学改革研究（池州学院校级质量工程项目2014JYXM39）（已经结题） （3）主持统筹城乡发展的视角下安徽省农村土地流转模式选择研究（池州学院校级重点项目2016RWZ001）（在研） 发表论文 （1）王文琴，鲁成树.土地资源生态安全分析—以黄山市为例[J].中国集体经济，2012（27）：38-39. （2）王文琴，尹文汉等.土地信息系统实践教学改革研究[J].池州学院学报，2017（4）:147-149. （3）参加编写《房地产营销》教材（江苏教育出版社），撰写字数3万，编写教材的第八章房地产营销促销策略。 联系方式： 1006180040@qq.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '长沙理工大学', NULL, NULL, NULL, '大学资源环境与城乡规划专业，获得理学学士学位；；大学土地资源管理专业，获得管理学硕士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('440', '李琼', '地理与规划学院', '副教授', NULL, '', '副教授。发表论文10余篇。邮箱：1029949655@qq.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '', NULL, '', NULL, '', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('441', '陈永卓', '地理与规划学院', '讲师', NULL, '', '陈永卓 ，男，1993年10月生，山东潍坊人。2016年6月获济宁医学院生物技术专业理学学士学位，2019年6月获曲阜师范大学动物生态学专业理学硕士学位，2022年9月获安徽师范大学生态学专业博士学位。2022年7月进入池州学院工作，现为地理与规划学院专业教师。 教授课程 ：自然地理学、自然资源学原理 研究领域 ：生态经济，铃木氏果蝇病虫害防治 一、近五年学术成果 Chen YZ , Pan H, Li J, Pan D, Liu PC, Hu HY*. Effects of Irradiated Sterile Male and Mating Sequence on the Fertility of Drosophila suzukii (Diptera: Drosophilidae). Journal of Insect Science, 2022, 22(1): 22; 1–5. Chen YZ , Li Q, Li J, Pan D, Hu W, Liu PC, Hu HY *. Seasonal monitoring of Drosophila suzukii and its non-crop hosts in Wuhu, Eastern China. Journal of Applied Entomology, 2021, 145: 1-9. DOI: 10.1111/jen.12835.', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '月获曲阜师范大学（硕士）', NULL, NULL, NULL, '学士学位，；大学动物生态学专业理学硕士学位，；大学生态学专业博士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('442', '曹明达', '地理与规划学院', '讲师', '岩溶动力系统、水文地球化学、地下水与地表水相互作用 联系方式： cmd965621@sina.com', '', '曹明达， 男，讲师，中国地质大学（武汉）地质学博士。近年来，主持省级教科研项目2项，在国内外期刊发表论文20余篇，授权实用新型专利1项，获教学成果校级二等奖1项，指导国家级、省级大学生创新创业训练项目2项，指导学生国家级、省级学科竞赛获奖3项。 教授课程： 地貌学、植物地理学、地质地貌野外实习 研究领域： 岩溶动力系统、水文地球化学、地下水与地表水相互作用 联系方式： cmd965621@sina.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, NULL, '地貌学、植物地理学、地质地貌野外实习 研究领域： 岩溶动力系统、水文地球化学、地下水与地表水相互作用 联系方式： cmd965621@sina.com', NULL, '大学；博士。近年来，主持省级教科研项目；大学生创新创业训练项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('443', '张杰', '地理与规划学院', '讲师', '水文地质与环境地质 联系方式： zhangjie45678@163.com', '', '张杰 ，男，讲师，地质学理学博士，安徽工业大学兼职硕士生导师。近年来，主持省级教科研项目3项，承担横向项目1项，在国内外期刊发表论文10余篇，授权发明专利1项，获教学成果校级二等奖1项，指导国家级、省级大学生创新创业训练项目多项，指导学生省级学科竞赛获奖1项。 教授课程： 地质学、环境地理学 研究领域： 水文地质与环境地质 联系方式： zhangjie45678@163.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, NULL, '地质学、环境地理学 研究领域： 水文地质与环境地质 联系方式： zhangjie45678@163.com', NULL, '博士，安徽工业大学兼职硕士生导师。近年来，主持省级教科研项目；大学生创新创业训练项目多项，指导学生省级学科竞赛获奖', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('444', '焦文军', '地理与规划学院', '讲师', '古地磁、岩石磁学、海洋磁学 联系方式： wjjiao@czu.edu.cn', '', '焦文军， 男，讲师，地质学博士。近年来，主持国家级科研项目两项，参与国家级项目4项，主持省级科研项目1项，承担横向项目1项，在国内外期刊发表高水平论文十余篇，其中以一作身份在国际自然指数（Nature-Index）期刊GRL、JGR-SE发表论文3篇，获教学成果校级二等奖1项。 教授课程： 土壤地理学、地图学、自然地理学 研究领域： 古地磁、岩石磁学、海洋磁学 联系方式： wjjiao@czu.edu.cn', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, NULL, '土壤地理学、地图学、自然地理学 研究领域： 古地磁、岩石磁学、海洋磁学 联系方式： wjjiao@czu.edu.cn', NULL, '博士。近年来，主持国家级科研项目两项，参与国家级项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('445', '范聪慧', '地理与规划学院', '讲师', '气候变化影响评价 联系方式： fanch@czu.edu.cn', '', '范聪慧 ，女，讲师，北京师范大学理学博士，中国地理学会会员，中国农业绿色发展研究会会员。近年来，主持教科研项目2项，在国内外期刊发表论文7篇，授权软件著作权1项，获教学成果校级二等奖1项，获第五届、第六届全国高校教师教学创新大赛安徽赛区比赛池州学院校赛二等奖；第七届全国高校混合式教学设计创新大赛国家级优胜奖、校级二等奖，指导学生省级学科竞赛获奖2项。 教授课程： 世界地理、气象与气候学、区域地理野外实习 研究领域： 气候变化影响评价 联系方式： fanch@czu.edu.cn', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '北京师范大学（博士）', NULL, '世界地理、气象与气候学、区域地理野外实习 研究领域： 气候变化影响评价 联系方式： fanch@czu.edu.cn', NULL, '大学理学博士，中国地理学会会员，中国农业绿色发展研究会会员。近年来，主持教科研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('446', '杨美玉', '地理与规划学院', '讲师', NULL, '', '杨美玉 ，女，讲师，福建师范大学理学博士，池州市补充耕地质量鉴定专家库专家。近年来，主持省级科研项目1项，承担横向项目1项，在国内外期刊发表论文7篇. 教授课程 ：《水文学》、《生态学》和《中学地理教学设计》等 研究领域 ：土壤环境化学 联系方式 ：yangmy@czu.edu.cn', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '福建师范大学（博士）', NULL, NULL, NULL, '大学理学博士，池州市补充耕地质量鉴定专家库专家。近年来，主持省级科研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('447', '赵思腾', '地理与规划学院', '讲师', '碳氮循环 联系方式： zhaost@czu.edu.cn', '', '赵思腾， 男，讲师，理学博士，安徽省地理学会会员。近年来，主持省级教科研项目1项，承担横向项目1项，在国内外期刊发表论文10余篇，授权实用新型专利1项。 教授课程： 地理信息系统 研究领域： 碳氮循环 联系方式： zhaost@czu.edu.cn', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, NULL, '地理信息系统 研究领域： 碳氮循环 联系方式： zhaost@czu.edu.cn', NULL, '博士，安徽省地理学会会员。近年来，主持省级教科研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('448', '周梦佳', '地理与规划学院', '讲师', NULL, '', '周梦佳 ，女，1995年生，江苏无锡人。2017年获盐城师范学院海洋资源开发技术专业工学学士学位，2020年获南京农业大学海洋科学理学硕士学位，2024年获南京农业大学农业资源与环境专业农学博士学位。2024年6月进入池州学院工作，现为地理与规划学院专业教师。 未来主要研究方向 ：农业资源与环境、微生物调控土地生态系统 教授课程： 土地经济学 代表性论文： 1. Mengjia Zhou, Yiyang Wei, Ji Wang, Mingxiang Liang, Gengmao Zhao. Salinity-induced alterations in physiological and biochemical processes of blessed thistle and peppermint, Journal of Soil Science and Plant Nutrition, 2021, 21(4):2857-2870. (SCI收录；IF=3.9) 2. Mengjia Zhou, Ji Wang, Jing Zhou, Lin Liu, Ruixuan Yang, Jingjing Xu, Mingxiang Liang, Li Xu. Exogenous IAA application affects the specific characteristics of fluoranthene distribution in Arabidopsis . Ecotoxicology and Environmental Safety, 2023, 263:115306. (SCI收录；IF=6.9) 3.Ji Wang, Zeyang Jin, Mengjia Zhou , Yongjian Yu, Mingxiang Liang. Characterization of NF-Y transcription factor families in industrial rapeseed ( Brassica napus L.) and identification of BnNF-YA3, which functions in the abiotic stress response. Industrial Crops & Products, 2020, 148:112253. 4.Wang Ji, Jin Zeyang, Zhou Mengjia , Yu Yongjian, Liang Mingxiang. Characterization of NF-Y transcription factor families in industrial rapeseed ( Brassica napus L.) and identification of BnNF-YA3, which functions in the abiotic stress response. Industrial Crops and Products, 2020. 5.Wang Ji, Jiao Jiao, Zhou Mengjia , Jin Zeyang, Yu Yongjian, Liang Mingxiang. Physiological and transcriptional responses of industrial rapeseed ( Brassica napus ) seedlings to drought and salinity stress. International Journal of Molecular Sciences, 2019. 6.Jiao Jiao, Ji Wang, Mengjia Zhou , Xuyang Ren, Wenyue Zhan, Zongjiu Sun, Haiyan Zhao, Yao Yang, Mingxiang Liang, Wim Van den Ende. Characterization of fructan metabolism during Jerusalem artichoke ( Helianthus tuberosus L.) germination. Frontiers in Plant Science. 2018. 科研项目： 1.科技部重点研发计划：“黄渤海滩涂生态农牧化与三产融合模式示范”子课题（2020YFD0900704）；参与 2.科技部外国专家项目（个人类）：新型绿色植物免疫激活剂-果聚糖的作用机理及其应用(G2022145002L)；参与 3.三亚南京农业大学研究院引导资金项目：利云型低聚果糖诱导反季节蔬菜抗病的机制及其合成研究（NAUSY-', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '年获南京农业大学（硕士）', NULL, NULL, NULL, '学士学位，；大学海洋科学理学硕士学位，；大学农业资源与环境专业农学博士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('449', '刘怀庆', '地理与规划学院', '讲师', '水环境遥感；定量遥感', 't_449_avatar.jpg', '刘怀庆，男，1997年4月生，安徽蚌埠人。2018年获安徽农业大学测绘工程专业学士学位，2019-2024年于南京师范大学硕博连读，获地理环境遥感专业博士学位。2024年6月进入池州学院工作，现为地理与规划学院专业教师。主要研究方向为水环境遥感、定量遥感，发表SCI论文十余篇。', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, 'SCI论文4篇：Optics Express(IF=3.8)、ESPR(IF=5.8)、Water Research(IF=13.3)、环境科学；参与国家自然科学基金项目3项（面上项目2项+联合基金1项）', '航空与航天数据获取；生态环境信息图谱生成与应用', NULL, '安徽农业大学 测绘工程专业 学士（2018）；南京师范大学 地理环境遥感专业 博士（2024）', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('450', '刘梦洋', '地理与规划学院', '讲师', NULL, '', '刘梦洋 ，女，1993年10月生，天津人。2012年9月至2016年6月就读于南京信息工程大学，专业：大气科学（水文气象方向），获理学学士学位。2016年9月至2019年6月就读于南京信息工程大学，专业：应用气象学，获理学硕士学位。2019年9月至2024年6月就读于南京信息工程大学，专业：气象学，获理学博士学位。2022年4月至2023年4月，法国国家科研中心动力气象实验室，联合培养博士。2024年6月进入池州学院工作，现为地理与规划学院专业教师。 主要研究方向 ：水文气象，极端事件机理 教授课程 ：世界地理 论文情况： [1] Liu, M. , Yin, Y., Wang, X., Ma, X., Chen, Y., & Chen, W. (2022). More frequent, long-lasting, extreme and postponed compound drought and hot events in eastern China. Journal of Hydrology, 614, 128499.（SCI收录，IF=6.4） [2] Liu, M. , Ma, X., Yin, Y., Zhang, Z., Yin, J., Ullah, I., & Arshad, M. (2021). Non-stationary frequency analysis of extreme streamflow disturbance in a typical ecological function reserve of China under a changing climate. Ecohydrology, e2323.（SCI收录，IF=2.6） [3] Liu, M. , Yin, Y., Ma, X., Zhang, Z., Wang, G., & Wang, S. (2020). Encounter Probability and Risk of Flood and Drought under Future Climate Change in the Two Tributaries of the Rao River Basin, China. Water, 12(1), 104.（SCI收录，IF=3.4） [4] 刘梦洋 ,王小军,柯杭,罗志文,尹义星.甘肃省陇东地区夏季极端降水及典型年环流特征分析[J].干旱区研究, 2021, 38(03):775-784. [5] 刘梦洋 ,尹义星,韩翠,黄伊涵.基于地区线性矩法的江西省极值降水频率分析[J].水电能源科学, 2018, 36(09):1-5. [6] Zou, R., Yin, Y., Wang, X., Zhang, Z., Ma, X., Liu, M. , & Ullah. I. (2023). Characteristics and propagation of meteorological and hydrological droughts in eastern Gansu, a typical semi-arid region, China. International Journal of Climatology, 43(12), 5327-5347.（SCI收录，IF=3.9） [7] Ullah, I., Ma, X., Yin, J., Omer, A., Habtemicheal, A., Saleem, F., Iyakaremye, V., Syed, S., Arshad, M. & Liu, M. (2022). Spatiotemporal characteristics of meteorological drought variability and trends (1981-2020) over South Asia and the associated large-scale circulation patterns. Climate Dynamics, 60, 2261-2284.（SCI收录，IF=4.6） [8] Ullah, I., Ma, X., Yin, J., Asfaw, T., Azam, K., Syed, S., Liu, M. , Arshad, M., & Shahzaman, M. (2021a). Evaluating the meteorological drought characteristics over Pakistan using in situ observations and reanalysis products. International Journ', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '南京信息工程大学', NULL, NULL, NULL, '大学，专业：大气科学；学士学位。；大学，专业：应用气象学，获理学硕士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('451', '王吉', '地理与规划学院', '讲师', '盐碱地土地资源管理与植物抗逆性改良 联系方式 ：wj_czu@yeah.net', '', '王吉， 女，讲师，南京农业大学农学博士。近年来，主持省级教科研项目1项，承担横向项目1项，在国外期刊发表论文6篇。 教授课程： 经济学原理、管理学原理、经济地理学 研究领域： 盐碱地土地资源管理与植物抗逆性改良 联系方式 ：wj_czu@yeah.net', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '南京农业大学（博士）', NULL, '经济学原理、管理学原理、经济地理学 研究领域： 盐碱地土地资源管理与植物抗逆性改良 联系方式 ：wj_czu@yeah.net', NULL, '大学农学博士。近年来，主持省级教科研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('452', '范宇宾', '地理与规划学院', '讲师', '冰雪水文遥感；测高卫星应用；冰川质量平衡；格陵兰冰面湖', 't_452_avatar.jpg', '范宇宾，男，1996年11月生，江苏盐城人。2018年获南京邮电大学地理信息科学理学学士学位，2024年获南京大学地理学专业理学博士学位。2024年6月进入池州学院工作，现为地理与规划学院专业教师。', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, '发表SCI论文5篇（Q1三篇：Journal of Glaciology、The Cryosphere、Earth System Science Data），主持国家自然科学基金青年项目（42501167）。代表性成果：格陵兰冰面湖扩张研究(J Glaciology 2024)、ICESat-2全球冰川质量损失研究(IEEE JSTARS 2025)、格陵兰数字高程模型(ESSD 2022, IF=11.8)。', '遥感地学应用', NULL, '南京邮电大学 学士（地理信息科学，2018）；南京大学 博士（地理学，2024）', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('453', '任芳', '地理与规划学院', '讲师', NULL, '', '任芳 ， 女，1989年生，河南鹤壁人。2015年获南昌大学文学学士学位，2025年获南京林业大学农学博士学位。2025年6月进入池州学院工作，现为地理与规划学院专业教师。 未来主要研究方向 ：城市森林可持续经营规划与资源管理、景观生态学 代表性论文： (1) Ren F , Xu J, Wu Y, et al. Analysis of eco-environmental quality of an urban forest park using LTSS and modified RSEI from 1990 to 2020—A case study of Zijin mountain national forest Park, Nanjing, China[J]. Forests, 2023, 14(12): 2458.（SCI二区一作，IF=2.4） (2) Ren F , Chen L, Li T, et al. Spatial Changes of Suburban Forest Ecological Functions and Their Impact on Ecological Equity in the Process of Urbanization—A Case Study of Jiangning District, Nanjing, China[J]. Forests, 2023, 14(7): 1308.（SCI二区一作，IF=2.4） (3) Li T, Wu Y, Ren F , et al. Estimation of unrealized forest carbon potential in China using time-varying Boruta-SHAP-random forest model and climate vegetation productivity index[J]. Journal of Environmental Management, 2025, 377: 124649. (4) Yang C, Li M Y, Li T, et al. Scenic beauty evaluation of forests with autumn-colored leaves from aerial and ground perspectives: a case study in qixia mountain in nanjing, China[J]. Forests, 2023, 14(3): 542. (5) Li T, Li M, Ren F , et al. Estimation and spatio-temporal change analysis of NPP in subtropical forests: a case study of Shaoguan, Guangdong, China[J]. Remote Sensing, 2022, 14(11): 2541. 科研项目： 1.基于情景分析与多目标决策的南方集体林长期经营规划方法研究。项目编号31770697/执行日期：2018.01-2021.12/负责人：李明阳/本人承担职责：负责城市森林生态功能监测及空间优化。 2.苏南丘陵地区退化林修复关键技术示范推广。项目编号：LYKJ[2024]21/执行期限：2024.07-2027.12/负责人:吴文浩/技术负责人：李明阳/本人承担职责：负责退化林美学价值提升经营措施设计。 3. “十三五”江苏省高等学校重点教材。教材名称：森林经营规划/主编：李明阳/出版社：北京中国林业出版社/时间：2022年6月/本人负责部分：第十二章“3S技术在森林经营规划中的应用”。 4.喀斯特地区森林潜在生产力估测方法研究—以贵州为例。执行日期：2024.11-2026.11/。 5.高分辨率遥感图像处理。执行日期：2020.11-2021.11/。 联系方式： renfanghk17@126.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, NULL, NULL, NULL, '大学文学学士学位，；大学农学博士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('454', '胡刚', '地理与规划学院', '讲师', '人文地理、区域资源开发与环境评价', '', '胡刚 ，男，1973年3月生。1992年至1994年在池州师范专科学校地理系学习，毕业后到安徽省贵池市棠溪中学从事教育教学工作，2001年取得理学学士学位，2003年至2006年在安徽师范大学国土资源与旅游学院攻读硕士学位并在2006年取得理学硕士学位，2006年至2015年在池州学院资源环境与旅游系工作，2015年至今在池州学院地理与规划学院工作。 研究领域： 人文地理、区域资源开发与环境评价。 主讲课程： 人文地理学、世界地理、客源国概论、遥感概论、国际贸易地理等。 参与的科研项目和学术交流： 安徽省教育厅自然科学基金(2003kj085)芜湖市城市扩展与城郊生态环境演变研究，安徽省环境保护局(2004-2005)安徽省芜湖县生态示范区建设规划，安徽省教育厅（KJ2012B120）池州市环境质量对快速城市化的响应，中国环境科学学会2004年度年会（2004.9沈阳），城市化与环境质量变化耦合关系研究——以皖南部分城市为例（XYK200603）等。研究成果曾在《国土与自然资源研究》、《池州学院学报》、《资源开发与市场》、《合肥学院学报》等刊物发表，其中《生态示范区建设中的循环经济实例研究》在中国环境科学学会2004年度年会大会上进行报告及交流。 发表的教科研论文有： 快速城市化背景下城市边缘区大气环境质量变化研究——以芜湖市为例，池州师专学报2007年第3期 芜湖市城市边缘区环境质量分析及其评价，资源开发与市场，2009年第10期 安徽省黄山市1998—2004年大气中SO2浓度变化分析，合肥学院学报(自然科学版)，2011年第2期 综合文科教育专业《世界地理》教学改革，池州学院学报，2011年第6期', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '安徽师范大学国土资源与旅游学院攻读硕士学位并在2006年（硕士）', NULL, '人文地理学、世界地理、客源国概论、遥感概论、国际贸易地理等。 参与的科研项目和学术交流： 安徽省教育厅自然科学基金', NULL, '学士学位，；大学国土资源与旅游学院攻读硕士学位并在；硕士学位，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('455', '孙满英', '地理与规划学院', '讲师', '中学地理教育、乡土资源调查与利用 联系方式： 1173857865@qq.com', '', '孙满英， 女，讲师，自然地理学硕士。近年来，主持校级教科研项目6余项，承担横向项目2余项。获校级教学成果二等奖1项，指导省级大学生创新创业训练项目4项，指导学生省级学科竞赛获奖10余项。 教授课程： 地理课程与教学论、地理课标解读与教材分析 研究领域： 中学地理教育，乡土资源调查与利用 联系方式： 1173857865@qq.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, NULL, '地理课程与教学论、地理课标解读与教材分析 研究领域： 中学地理教育、乡土资源调查与利用 联系方式： 1173857865@qq.com', NULL, '硕士。近年来，主持校级教科研项目；大学生创新创业训练项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('456', '韩雪', '地理与规划学院', '讲师', NULL, '', '韩雪，女， 1985.11 出生，硕士研究生，讲师。 2003.9—2007.6 就读于安徽农业大学观赏园艺专业，获得学士学位， 2007.9—2010.6 就读于安徽大学生态学专业，获得理学硕士学位。 2011.4-2012.4 工作于池州市环境科学研究院。 2012 年 5 月在池州学院资源环境与旅游系工作，现为池州学院 地理与规划 学院专任教师。 教授课程 ：旅游资源开发与规划、园林规划、生态学、城市规划三维制图技术、图形图像处理技术、园林艺术原理等。 研究领域 ：景观生态学；景观规划与设计 主持的代表性科研项目 ： （ 1 ） 池州市综合类公园植物配置结构与景观评价研究（院级科研项目： 2013ZR022 ） （ 2 ）杏花村文化旅游区植物景观规划设计研究（ 池州生态经济与旅游发展研究中心项目： XKY201513 ） 主持的代表性教研项目 ： （ 1 ）基于项目驱动的应用型本科院校 《园林植物配置》教学与实践研究（池州学院质量工程项目 (2015jyxm18) 代表性科研成果： [1] 醉翁榆（ Ulmus gaussenii Cheng ）的濒危特征与机制 . 安徽大学学报 ( 自然科学版 ),2008(6). [2] 西鄂尔多斯六种强旱生植物的花粉形态及其生态因子, 微体古生物学报 ,2009,26(1). [3] 我国两种特有濒危榆树的花粉形态及其地史意义，微体古生物学报 ,2010,27(1). [4] 基于 ITS 、 atpB-rbcL 序列的醉翁榆 (Ulmus gaussenii) 与相近榆属植物的亲缘关系 , 安徽大学学报 ( 自然科学版 ),2011,35(6). [5] 基于 AHP 法的三台山公园植物景观多样性评价 , 池州学院学报， 2014,28(6). [6] 安徽池州地区居住小区园林小品景观特征评价 , 武汉轻工大学， 2016,35(1). 曾参与完成的规划设计项目： （ 1 ）安徽省池州市杏花村水利风景区规划 （ 2 ）池州五连塘农庄旅游总体规划 （ 3 ）池州市村庄规划导则 （ 4 ）池州解放农场旅游开发规划 （ 5 ）石台旅游扶贫及摄影基地规划 联系方式 : E-mail ： soulmate985@qq.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '硕士', NULL, NULL, NULL, '硕士研究生，讲师。 ；大学观赏园艺专业，获得学士学位， ；大学生态学专业，获得理学硕士学位。 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('457', '甘梦仙', '地理与规划学院', '讲师', NULL, '', '甘梦仙 ，女，1986年12月生，中国矿业大学硕士研究生学历；池州学院地理与规划学院专任教师；主要研究方向为生态环境遥感、激光雷达应用研究，在国内期刊发表论文2篇，参编教材2部。 主要教授课程 ：大地测量学，测绘CAD等 主要研究领域 ：地表地物分类、生态环境遥感反演 代表性研究项目： [1]安徽省地表覆盖热环境垂直变化特征分布及趋势研究（2024AH051378），省级自然，在研中； [2]大地测量实验与实训（2021XYLJC04）,校级质量工程，已结项； [3]大地测量学（双语）（2020SJJXSFK1813）,省级质量工程，已结项； [4]控制测量学（2018XJPKC14），校级质量工程，已结项； [5]基于贝叶斯模型的激光强度距离效应参数估计（CZ2018ZRZ09），校级自然，已结项； [6]构建地方高校新工科教师良性发展评价激励机制（2017xgkxm66）,省级质量工程，已结项； [7]测绘工程专业综合改革试点（2015zy071），安徽省高等学校教学质量与教学改革工程项目,参与者 联系方式：0120120596@qq.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '硕士研究生', NULL, NULL, NULL, '大学硕士研究生学历；池州学院地理与规划学院专任教师；主要研究方向为生态环境遥感、激光雷达应用研究，在国内期刊发表论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('458', '刘俊超', '地理与规划学院', '讲师', NULL, '', '刘俊超 ，男，1987年12月生。2005年9月至2009年7月就读于河南理工大学土木工程专业，并获得土木工程学士学位。2009年9月至2012年7月就读于河南理工大学结构工程专业，并获得结构工程硕士学位。2012年7月进入池州学院工作至今，现为池州学院地理与规划学院专职教师。 主要教授课程： 测量学，工程力学，CAD制图，建筑施工，建筑识图与制图 主要研究领域： 地下工程结构的选型与设计，桥梁工程，民用建筑施工 代表性研究项目： [1]“互联网+”与实践混合教学方式在《测量学》课程中的应用研究(2017XJYXM25)，校级教学研究项目，2018年1月立项；主持人 [2]深部巷道锚杆增阻让压装置结构形式方案数值模拟分析（2017ZR002），校级自然科学项目，2018年1月立项；主持人 代表性研究成果： [1]深部巷道锚杆增阻让压装置结构形式分析[J].池州学院学报（ISSN：1674-1102），2018年第3期； [2]建筑工程基础工程施工质量的控制与管理[J].山东工业技术（ISSN：1006-7523），2017年第16期； [3]“互联网+”与实践混合教学方式在测量学课程中的应用研究[J].知识文库（ISSN 1002-2708），2019年第14期。 联系方式： 2121308884@qq.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '河南理工大学', NULL, NULL, NULL, '大学土木工程专业，并获得土木工程学士学位。；大学结构工程专业，并获得结构工程硕士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('459', '汪颂晖', '地理与规划学院', '讲师', NULL, '', '汪颂晖， 男，安徽石台人，讲师。2012年6月毕业于西安工业大学岩土工程专业，获工学硕士学位。注册建造师，池州市发展改革委市级投资项目评估专家库专家，池州市重大决策社会稳定风险评估专家库专家，校级双能型教师。主持省级、校级教科研项目10项，国内期刊发表论文8篇，指导学生省级以上学科竞赛获奖10余项。 主讲课程： 测量学、房屋建筑学、工程项目管理 联系方式： 348364568@qq.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '西安工业大学', NULL, '测量学、房屋建筑学、工程项目管理 联系方式： ', NULL, '大学岩土工程专业，获工学硕士学位。注册建造师，池州市发展改革委市级投资项目评估专家库专家，池州市重大决策社会稳定风险评估专家库专家，校级双能型教师。主持省级、校级教科研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('460', '仵振东', '地理与规划学院', '讲师', '卫星导航与卫星重力 联系方式： 0120140666@czu.edu.cn', '', '仵振东 ， 男，讲师，工学硕士。近年来，主持省级教科研项目2项，发表论文10余篇。 教授课程： GNSS原理及应用、测绘专业英语、工程测量学 研究领域： 卫星导航与卫星重力 联系方式： 0120140666@czu.edu.cn', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, NULL, 'GNSS原理及应用、测绘专业英语、工程测量学 研究领域： 卫星导航与卫星重力 联系方式： 0120140666@czu.edu.cn', NULL, '硕士。近年来，主持省级教科研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('461', '张璐', '地理与规划学院', '讲师', NULL, '', NULL, '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '', NULL, '', NULL, '大学行政管理专业，获学士学位； ；大学教育经济与管理专业，获硕士学位。 ；大学生职业生涯规划与就业素养，毛泽东思想和中国特色社会主义理论体系概论 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('462', '张姣姣', '地理与规划学院', '讲师', '变形监测与数据处理 联系方式： jjz0801@126.com', '', '张姣姣 ，女， 1988 年 6 月生。 2007 年 9 月至 2011 年 7 月就读于长春工程学院测绘工程专业，本科学士学位； 2011 年 9 月至 2014 年 7 月就读于安徽理工大学大地测量学与测量工程专业，研究生硕士学位。 2014 年 8 月至 2018 年 6 月在江西科技学院从事教学工作， 2018 年 2 月晋升讲师职称。 2018 年 7 月至今在池州学院资源环境学院工作，现为池州学院 地理与规划 学院专业教师。 教授课程： 计算机地图制图、数字高程模型、工程测量 研究领域： 变形监测与数据处理 联系方式： jjz0801@126.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '硕士', NULL, '计算机地图制图、数字高程模型、工程测量 研究领域： 变形监测与数据处理 联系方式： jjz0801@126.com', NULL, '本科学士学位； ；大学大地测量学与测量工程专业，研究生硕士学位。 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('463', '贺香', '地理与规划学院', '讲师', NULL, '', '贺香，女，1992年3月生，安徽安庆人，2015年7月获安徽建筑大学景观学学士学位，2018年6月获天津城建大学风景园林硕士学位，2018年7月入职池州学院，现为池州学院地理与规划学院专任教师，“双能型”教师，入选2024年度省社科界青年学人成长计划，中国农业绿色发展研究会会员、安徽省土地学会会员、安徽省国土空间规划学会会员。 教授课程：《园林史》《建筑设计》《城市规划原理》等。 研究领域：景观生态学、环境与健康 代表性成果： [1]贺香,纪凯婷,等.城市绿地与绿化投入的居民健康效应研究[J].生态学报,2024,(24):1-11[2024-11-09].（CSCD，一作） [2]贺香,吴疆.基于心理学的校园疗愈景观设计策略研究[J].安徽建筑,2021(03)2306. [3]贺香,刘雪梅.现代庭院设计中建筑与景观的融合[J].山东林业科技,2018,48(01):67-70. [4]贺香,刘雪梅,位晓.探讨现代景观设计中意境的体现[J].山东林业科技,2017,47(01):113-117 主持项目： (1)主持池州学院校级科研项目《高校校园景观对大学生健康的影响效应、机制及响应研究》（CZ2018ZR06），2019年1月 (2)主持池州学院校级质量工程项目《基于OBE理念的《建筑设计》课程实践教学模式创新研究》（2020XJYXM32），2020年12月 (3)主持池州学院校级科研项目《池州市绿地健康效益、群体差异及实现路径研究》（CZ2022ZR01），2022/12-2024/12 (4)主持自然资源部江淮耕地资源保护与生态修复重点实验室开放课题《江淮地区农业空间半自然生境特征、识别与营造研究》（ARPE-2024-KF08）,2024/10-2026/10 联系方式：he327@foxmail.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, NULL, '《园林史》《建筑设计》《城市规划原理》等', NULL, '大学景观学学士学位，；大学风景园林硕士学位，；大学生健康的影响效应、机制及响应研究', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('464', '马举', '地理与规划学院', '讲师', NULL, '', '马举， 男，1991年11月生，2011-2015年就读于青岛理工大学国际工程项目管理专业，获管理学学士学位；2016-2019就读于青岛理工大学管理科学与工程专业，获管理学硕士学位；2019年毕业至今，在池州学院地理与规划学院房地产开发与管理教研室任专业课教师。 教授课程： 建筑装饰设计、工程量清单计价 研究领域： 工程项目管理、工程造价 代表性成果： [1]基于主成分分析法的山东省房地产周期波动研究[J].工程经济,2018,28(09):46-49. [2]基于博弈论的装配式建筑优惠补贴政策的稳定性和收益最大化研究[J].工程经济,2018,28(06):57-59. 联系方式： QQ邮箱：1398165746@qq.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '硕士', NULL, NULL, NULL, '大学国际工程项目管理专业，获管理学学士学位；；大学管理科学与工程专业，获管理学硕士学位；', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('465', '黄银兰', '地理与规划学院', '讲师', NULL, '', '黄银兰，女，安徽安庆人，硕士，讲师，2015年1月毕业于浙江师范大学，获得人文地理学硕士学位。主持省级、校级教科研项目5项，承担横向项目5项，在国内外期刊发表论文20余篇，指导学生竞赛获奖10余项。 讲授课程 ：人文地理学、地图学、土地利用规划等。 联系方式： hyl@czu.edu.cn', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '浙江师范大学', NULL, NULL, NULL, '硕士，讲师，；大学，获得人文地理学硕士学位。主持省级、校级教科研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('466', '周素芬', '地理与规划学院', '讲师', NULL, '', '周素芬 ， 女，1992年出生。2012年9月至2016年7月就读于南京林业大学化学工程与工艺专业，获学士学位；2016年8月至2017年7月于云南省昆明市东川区拖布卡中心学校支教，担任美术老师；2017年9月至2020年7月就读于南京林业大学农林经济管理专业，获硕士学位。2020年9月起入职为池州学院地理与规划学院专职辅导员。', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '南京林业大学', NULL, NULL, NULL, '大学化学工程与工艺专业，获学士学位；；大学农林经济管理专业，获硕士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('467', '李娟', '地理与规划学院', '助教', '中国近现代史 联系方式： 569974107@qq.com', '', '李娟， 女，助教，历史学硕士，池州学院专职辅导员，发表论文1篇。 教授课程： 《劳动教育》 研究领域： 中国近现代史 联系方式： 569974107@qq.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, NULL, NULL, '《劳动教育》 研究领域： 中国近现代史 联系方式： 569974107@qq.com', NULL, '硕士，池州学院专职辅导员，发表论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('468', '花颖', '地理与规划学院', '助教', '：土地利用与管理、土地资源调查与评价', '', '助教。年毕业于安徽师范大学地理与旅游学院土地资源管理专业，获得管理学学士。研究方向：：土地利用与管理，土地资源调查与评价。邮箱：1614677518@qq.com', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '安徽师范大学', NULL, NULL, NULL, '安徽师范大学地理与旅游学院土地资源管理专业，得管理学学士', NULL, NULL);
