INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('470', '刘畅', '地理与规划学院', '助教', NULL, '', '助教。年毕业于安徽理工大学土木建筑学院风景园林专业，获得风景园林学学士。研究方向：：文化景观', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '', NULL, '', NULL, '安徽理工大学土木建筑学院风景园林专业，得风景园林学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('471', '谭啸', '地理与规划学院', '助教', NULL, '', '助教。年获哈尔滨师范大学人文地理学专业理学硕士。研究方向：人文地理学', '0', '0', '0', '2026-06-05 16:54:37', '2026-06-05 16:54:37', NULL, '年获哈尔滨师范大学（硕士）', NULL, '', NULL, '哈尔滨师范大学人文地理学专业理学硕士', NULL, NULL);
