INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('475', '王丹', '商学院', '教授', '营销理论与实务、消费者行为、电子商务等方面的教学、研究和实践', '', '王丹，博士，教授，硕士生导师，安徽省教坛新秀，池州学院“双能型”教师。中国通信工业协会高级网络营销师、高级电子商务师，中国电子商务协会电子商务创业导师。 主要从事营销理论与实务、消费者行为、电子商务等方面的教学、研究和实践。主持省级教学示范课1门、校级一流课程2门。荣获安徽省教学成果一等奖1次、二等奖1次、三等奖1次。多次荣获池州学院“优秀教学质量奖”。先后主持安徽省哲学社会科学规划项目、安徽省社会科学创新发展研究项目、安徽省人文社科重点项目、企业委托项目等10余项课题的研究工作，发表论文20余篇。主持编写、参编安徽省规划教材3部。荣获中华人民共和国文化和旅游部研究成果推广1项，省级科研奖励2项。指导学生团队在国家级A类赛事中荣获二等奖1项，省级B类赛事中荣获一等奖2项、二等奖4项、三等奖7项，荣获全国大学生电子商务“创新、创意及创业”挑战赛优秀指导老师、全国第一届高校数智化商业决策创新大赛优秀指导教师等荣誉称号。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '博士，教授，硕士生导师，安徽省教坛新秀，池州学院；大学生电子商务', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('477', '林葆青', '商学院', '教授', NULL, '', '林葆青，台湾省人，管理科学博士，教授，市场营销专业教师。从事国际市场营销学、客户关系管理、商务谈判、跨境电商营销、市场营销实训、新商科跨专业实训等管理相关专业课程，主要研究方向为消费者行为、决策分析、科技教育管理研究。 曾任职德明财经科技大学专任教师,获评2017年度优良导师,国际营销/管理学/消费者行为学/观光休闲概论等课程评选为优良课程,历任八届中小企业协会跨业交流十二会财务长。 以第一作者发表国际学术期刊20余篇，其中SCI期刊3篇、EI期刊2篇。2026年取得实用新型专利权一项。 取得多项国际及国内专业资格证照: A.国际 1.FLMI (Fellow，Life Management Institute)2.ACS (Associate, Customer Service) 3.ALHC (Associate, Life and Health Claims)4.UND (Underwriting Life and Health Insurane) 5.AIAA (Associate, Insurane Agency Administration) 6. SMM服务业营销管理甲级证照7.SQM服务业质量管理师甲级证照8.IBSE国际商业社交礼仪乙级证照等。 B.国内 1.高级电子商务师2.就业服务乙级技术士3保户服务认证等。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '博士，教授，市场营销专业教师。从事国际市场营销学、客户关系管理、商务谈判、跨境电商营销、市场营销实训、新商科跨专业实训等管理相关专业课程，主要研究方向为消费者行为、决策分析、科技教育管理研究。 曾任职德明；大学专任教师,获评', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('478', '杜宝印', '商学院', '教授', NULL, '', '杜宝印，管理学博士、教授，兼任洛阳科技职业学院特聘教授、广东财经大学新发展研究院特约研究员、安徽九华山文旅康养集团有限公司独立董事、辽宁省沈阳市科技评审专家。曾从事人民警察、政府官员、企业高管等工作，历任国家级经济技术开发区招商局局长、企业服务中心主任、科研成果创新转化服务中心（大连理工大学军民融合研究院）党组书记兼主任、金地集团城市公司高管等职务。主要研究方向包括可持续发展、创新创业、产业经济学。在特色小镇、文旅项目、科技园区、房地产等产业开发运营方面积累了丰富的咨询服务经验和人脉资源，对相关产业的政策法规、规划、开发、招商、运营有深度研究，擅于推动区域的科技发展规划和创新体系建设，具有丰富的企业管理实践经验和战略规划能力。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '博士、教授，兼任洛阳科技职业学院特聘教授、广东财经大学新发展研究院特约研究员、安徽九华山文旅康养集团有限公司独立董事、辽宁省沈阳市科技评审专家。曾从事人民警察、政府官员、企业高管等工作，历任国家级经济技术；大学军民融合研究院', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('479', '王文广', '商学院', '副教授', '网络思政教育，数字化学习。主持省教育厅重点项目', '', '王文广，副教授，研究方向：网络思政教育，数字化学习。主持省教育厅重点项目2项，主持校级教科研项目5项，参与省厅级重大项目重点项目10余项，发表教科研论文20余篇。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('480', '王剑程', '商学院', '副教授', NULL, '', '王剑程，男，1987年7月生，中共党员，安徽池州人，池州学院商学院电子商务专业副教授。省级“教坛新秀”、校级“教学名师”、及“双能型教师”。主讲《电子商务概论》《创业策划与实战》等课程，主持省级一流专业建设点及多项省级质量工程项目，荣获省级教学成果一等奖1项、二等奖2项，并主编省级规划教材《电子商务实用教程（第4版）》。曾担任安徽国润茶业有限公司营销顾问，指导学生团队成功创办实体企业十余家。依托池州本地旅游与农村电商产业特色，长期致力于农村电商、旅游电商及新媒体营销等领域的研究工作。主持省哲学社会科学规划项目1项、省教育厅哲学社科重点项目2项，参与国家级、省级科研课题10余项，在学术期刊公开发表论文30余篇。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('481', '洪为宝', '商学院', '副教授', NULL, '', '洪为宝，男，硕士，副教授。1970年11月出生，安徽芜湖人。1989年7月参加工作至今，现任池州学院党委学工部部长、学生处处长、就业指导中心主任、武装部部长。工作期间历任池州学院经贸系副主任、副书记，校评建办常务副主任，校教学质量管理与评估处副处长（主持工作），教务处副处长、继续教育学院（乡村振兴学院）院长，后勤管理与基建处处长等职务。 多年来，主持安徽省重大教学改革研究项目等各类教科研项目10余项，参与各级各类研究项目20余项，主持校地企横向合作项目10余项，发表学术论文20余篇，主编《大学生职业规划与就业指导素养》《大学生创新创业素养教程》等教材4部。曾获评2008年安徽省高校学生就业工作先进个人；指导学生参加2017年安徽省第五届大学生艺术展演获一等奖，并获优秀指导老师；指导学生参加2009年安徽省“挑战杯”技能大赛获得一等奖；指导学生获得2012年度国家级大学生创新创业训练计划项目。曾获多次教学成果奖和教学质量优秀奖，其中获2024年安徽省教学成果一等奖等一项，获2025年池州学院教学成果特等奖一项，获2025年池州学院教学成果一等奖一项。撰写《校地合作“六个人”—池州学院地方性、应用型优秀实践案例》获优秀案例，入选教育部《新型大学新成就》一书；本人代表学校驻安庆望江县土永村扶贫期间，扶贫工作典型案例获评教育部优秀案例，并在中国教育报刊登。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '硕士，副教授。；大学生职业规划与就业指导素养；大学生创新创业素养教程', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('482', '刘为国', '商学院', '副教授', NULL, '', '刘为国，法学硕士，副教授，北京大学访问学者，兼职律师、仲裁员、安庆师大硕士生导师。安徽省法学法律专家库成员，安徽省知识产权专家库专家，池州市人大常委会、市政府立法咨询专家，池州市检察局、司法局、市监局等多部门法律咨询专家。 长期从事思想政治和法学课程教学与研究，系统讲授过《宪法学》、《刑法学》、《知识产权法学总论》和《习近平法治思想概论》等多门课程。编写出版了《新编物业管理法规实务教程》（副主编，中国科技大学出版社，2010年8月）、《经济法》（副主编，外语教学与研究出版社，2011年8月）和《物业管理概论》（编委，凤凰出版集团，2012年8月）等教材。 主持和参加《信息社会下犯罪发生机理研究》等省厅级课题十余项；在《苏州大学学报》、《佳木斯大学学报》等报刊上发表二、三类学术论文二十多篇；获得过池州市第二、四届社会科学优秀科研成果奖、2017年甘肃省高级人民法院优秀论文奖等。2022年获安徽省教学成果奖特等奖。 2011年，被学校授予“优秀党务工作者”荣誉称号，2018年和2019年，连续两年被学校授予“优秀共产党员”荣誉称号。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '硕士，副教授，北京大学访问学者，兼职律师、仲裁员、安庆师大硕士生导师。安徽省法学法律专家库成员，安徽省知识产权专家库专家，池州市人大常委会、市政府立法咨询专家，池州市检察局、司法局、市监局等多部门法律咨询；大学出版社，；大学学报', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('483', '谭庆', '商学院', '副教授', '公司治理、技术创新、财务绩效、智能财务、创新创业等方面的教学与研究', '', '谭庆，安徽财经大学管理学硕士，副教授，财务管理系主任。兼任安徽工业大学硕士生导师、公司独立董事、中国商业会计协会理事、池州市人大常委会预算审查监督顾问、池州市涉税服务协会监事。先后获安徽省教学成果二等奖、安徽省教坛新秀、安徽省大学生创新创业大赛优秀工作者、池州学院优秀共产党员、教书育人楷模、校级教学名师等荣誉称号。 主要从事公司治理、技术创新、财务绩效、智能财务、创新创业等方面的教学与研究。主持省部级以上教学科研项目10余项，发表论文30余篇，出版专著1部；指导学生团队立项国家级大学生创新创业训练项目10余项、指导学生团队获大学生学科与技能竞赛省级以上奖励100余项，获评优秀指导教师10余次；主讲高级财务会计学、会计综合模拟实训、新商科跨专业综合实训、创新创业实战等课程。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, '兼任安徽工业大学', NULL, NULL, NULL, '大学管理学硕士，副教授，财务管理系主任。兼任安徽工业大学硕士生导师、公司独立董事、中国商业会计协会理事、池州市人大常委会预算审查监督顾问、池州市涉税服务协会监事。先后获安徽省教学成果二等奖、安徽省教坛新秀；大学生创新创业大赛优秀工作者、池州学院优秀共产党员、教书育人楷模、校级教学名师等荣誉称号。 主要从事公司治理、技术创新、财务绩效、智能财务、创新创业等方面的教学与研究。主持省部级以上教学科研项目；大学生创新创业训练项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('484', '胡鹏', '商学院', '副教授', '产业经济、区域经济。主讲政治经济学、宏观经济学、微观经济学等课程。 获得省级教学成果奖二等奖一项，校级教学成果奖二等奖一项。主持省级MOOC课程', '', '胡鹏，男（1981-），安徽广德人，副教授，经济学硕士，研究方向：产业经济、区域经济。主讲政治经济学、宏观经济学、微观经济学等课程。 获得省级教学成果奖二等奖一项，校级教学成果奖二等奖一项。主持省级MOOC课程“西方经济学”；主持省厅级科研项目2项、省级质量工程项目1项。指导学生参加学科技能竞赛，获得全国竞赛三等奖一项、省级竞赛二等奖三项、三等奖五项。池州学院首届暨第二届“最美教师。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '硕士，研究方向：产业经济、区域经济。主讲政治经济学、宏观经济学、微观经济学等课程。 获得省级教学成果奖二等奖一项，校级教学成果奖二等奖一项。主持省级', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('485', '苏飞', '商学院', '副教授', '大学生创新创业教育及电子商务物流方面的研究', '', '苏飞，男，1979年7月生，中共党员，安徽宿州人，商学院电子商务专业教师，副教授。主要从事大学生创新创业教育及电子商务物流方面的研究；主持省级质量工程项目5项、安徽省人文社科重点项目2项、第1作者发表教科研论文10篇，主编安徽省“十四五”规划教材1本。 从教以来，承担《大学生职业生涯规划》《供应链管理》《电子商务概论》《电子商务物流》等课程的理论和实践教学，在教书育人岗位上发挥党员先锋模范作用，获校“优秀教师”“教书育人楷模”“最美教师”“优秀共产党员”“优秀辅导员”等荣誉称号，多次获“优秀教学质量奖”。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '大学生创新创业教育及电子商务物流方面的研究；主持省级质量工程项目；大学生职业生涯规划', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('486', '张璐', '商学院', '副教授', NULL, '', '张璐，1987年2月出生，中央财经大学财政学专业毕业，池州学院副教授。主要研究方向为产业经济、财务与审计。主持省部级以上教科研项目3项，发表论文10余篇；长期指导学生参与各类学科竞赛，获省级以上奖项20余项，获评优秀指导教师。曾获校级教坛新秀、优秀共产党员等荣誉。主要承担政府与非营利组织会计、税法、金融学、计算机审计等课程教学工作。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '大学财政学专业毕业，池州学院副教授。主要研究方向为产业经济、财务与审计。主持省部级以上教科研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('487', '李迎春', '商学院', '副教授', NULL, '', '李迎春，中南财经政法大学硕士，副教授，现为池州学院商学院（法学院）财务管理专业专任教师，主讲课程为《会计学原理》、《管理会计学》等，主要研究方向为管理会计、环境会计。曾主持省教育厅人文社科、省级教研项目、校级人文社科、校级网络课程、校级课程思政示范课程等多个项目，指导“互联网+”大赛和国家级大学生创新创业训练多项，公开发表学术论文数篇，主编《会计学原理与实务》《管理会计》两门教材。 在职期间，积极参加社会实践，为“双师型”教师。课程教学中，多次获“优秀试卷”“优秀课内实践教学教案”“优秀多媒体课件奖”“优秀教学质量奖”等荣誉称号。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, '中南财经政法大学', NULL, NULL, NULL, '大学硕士，副教授，现为池州学院商学院；大学生创新创业训练多项，公开发表学术论文数篇，主编', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('488', '雷红霞', '商学院', '副教授', NULL, '', '雷红霞，河海大学管理学博士，副教授，硕士生导师，池州学院市场营销系主任。多年来，主要从事服务营销、技术创新与知识管理、旅游管理等方面的教学和研究工作，先后主持安徽省质量工程研究项目、安徽省教育厅人文重点研究项目、安徽省社科联创新发展研究课题、安徽省哲学社会科学规划办项目等近十项课题的研究工作，发表学术论文近30篇，其中CSSCI、EI论文5篇。带领学生团队参加省级及国家级比赛获奖近十项，荣获“优秀指导老师”称号。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '大学管理学博士，副教授，硕士生导师，池州学院市场营销系主任。多年来，主要从事服务营销、技术创新与知识管理、旅游管理等方面的教学和研究工作，先后主持安徽省质量工程研究项目、安徽省教育厅人文重点研究项目、安徽', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('490', '邹津', '商学院', '副教授', '《会计学原理》、《成本会计学》等课程的教学工作、其中《成本会计学》课程荣获省级示范课程', '', '邹津，湖南大学管理学硕士，副教授。主要研究方向为：财务会计理论与实务。 多年来，主要从事《会计学原理》、《成本会计学》等课程的教学工作，其中《成本会计学》课程荣获省级示范课程。先后主持池州学院、池州市及安徽省教育厅等多项课题的研究工作，公开发表学术论文十余篇。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '大学管理学硕士，副教授。主要研究方向为：财务会计理论与实务。 多年来，主要从事', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('492', '陶耘', '商学院', '副教授', NULL, '', '陶耘，副教授，硕士研究生，池州学院商学院电子商务专业教师，担任电子商务专业的主要技术课程。主要在电子商务整合建设和商务数据分析等方向取得一定的研究成果。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '硕士研究生，池州学院商学院电子商务专业教师，担任电子商务专业的主要技术课程。主要在电子商务整合建设和商务数据分析等方向取得一定的研究成果。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('493', '曾珍', '商学院', '副教授', NULL, '', '曾珍，南京农业大学经济学博士，副教授，硕士生导师，安徽省教坛新秀，池州学院“双能型”教师、教书育人楷模。曾担任池州学院商学院经济学系主任，现任教务处副处长，并兼任安徽省城市经济学会理事、安徽欧美同学会理事。 多年来，专注于国际贸易学与农业经济学的教学与研究工作。先后主持多项省部级课题，包括安徽省哲学规划办青年项目、安徽省创新发展攻关课题、安徽省教育厅人文社科重大项目、高校优秀青年人才支持计划重点项目以及安徽省教育厅人文社科重点项目等。在学术成果方面，已发表SSCI、CSSCI及CSCD等核心期刊论文二十余篇。 在科研与教学方面屡获殊荣，曾获安徽省“三项课题”二等奖、池州市第七届社会科学奖一等奖、池州学院教学成果奖二等奖；在第四届全国高校教师教学创新大赛池州学院选拔赛暨首届“课程思政说课比赛”中获基础课程组一等奖，并荣获智慧教学大赛二等奖等多项奖项。此外，还主持建设了安徽省国际经济与贸易专业新文科研究与改革项目，以及安徽省国际经济与贸易专业实践类课程教学研究项目。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '大学经济学博士，副教授，硕士生导师，安徽省教坛新秀，池州学院', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('495', '李荣富', '商学院', '副教授', '国际贸易、经济增长和计量经济研究、主持市级、校级和省级课题5项、公开发表论文30余篇', '', '李荣富，男，1966年2月生，副教授，硕士毕业于安徽财经大学国际经济与贸易学专业。1991年工作以来，相继承担了《会计学原理》、《统计学原理》、《统计学》、《企业经济活动分析》、《经济统计学》、《旅游电子商务》、《西方经济学》、《政治经济学》、《市场营销实训》、《电子商务概论》、《电子商务案例分析》、《网络营销》、《外贸实务》、《国际贸易理论》、《国际贸易实务》、《外贸理论与实务》、《国际贸易理论与实务》、《社会统计学》、《SPSS的应用》、《国际投资》、《国际经济合作》、《国际贸易综合实训》、《进出口操作实务》、《外贸单证》、《外贸单证实务》、《外贸函电》、《计量经济学》、《金融计量学及软件应用》以及公开选修课程《多元统计分析》和《国际经济学》等30门课程的交叉综合教学任务；主要从事国际贸易、经济增长和计量经济研究，主持市级、校级和省级课题5项，公开发表论文30余篇。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, '安徽财经大学', NULL, NULL, NULL, '硕士毕业于安徽财经大学国际经济与贸易学专业。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('496', '张莉娜', '商学院', '副教授', NULL, '', '张莉娜，中国人民大学经济学硕士，副教授，人力资源管理师，电子商务创业导师，双能型教师。 多年以来，主要从事劳动经济与人力资源管理方面的教学及研究工作，主讲《招聘与录用》《培训与人力资源开发》《人员素质测评》《企业文化学》《论文写作与研究方法》《管理学原理》等课程，先后主持教科研课题14项，其中省级质量工程课题1项，安徽省教育厅人文社科重点项目立项2项，地方企事业单位委托资助课题6项，发表教科研论文多篇。参与撰写 的 《NVC重构视角下长三角低附加值传统产业转移及发展思路》曾获安徽省社科联学术年会省社科优秀奖，主持的池州市社科联课题曾获池州市社科联项目优秀奖。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '大学经济学硕士，副教授，人力资源管理师，电子商务创业导师，双能型教师。 多年以来，主要从事劳动经济与人力资源管理方面的教学及研究工作，主讲', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('497', '王来宾', '商学院', '副教授', NULL, '', '王来宾，博士，副教授，硕士生导师。多年来，主要从事人力资源管理、残疾人社会保障等方面的教学和研究工作，先后主持安徽省哲学社会科学项目、安徽省教育厅高校人文社科重点项目等省部级项目以及企业委托项目等5项课题的研究工作，发表学术论文20余篇，其中SCI/SSCI论文2篇、CSSCI论文和EI论文各1篇、北大核心论文2篇。主持安徽省传统专业改造提升项目和安徽省教育教学改革研究重点项目等省级质量工程2项。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '博士，副教授，硕士生导师。多年来，主要从事人力资源管理、残疾人社会保障等方面的教学和研究工作，先后主持安徽省哲学社会科学项目、安徽省教育厅高校人文社科重点项目等省部级项目以及企业委托项目等', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('499', '杨群', '商学院', '副教授', '养老保障、人力资源管理等方面的教学和研究工作', '', '杨群，女，本硕毕业于安徽师范大学，管理学硕士，副教授。多年来，主要从事养老保障、人力资源管理等方面的教学和研究工作。先后主持安徽省哲学社会科学规划项目、安徽省教育厅人文社科研究重点项目、安徽省社会科学创新发展项目、池州市社科联等单位项目以及校级各类项目等10余项课题的研究工作，发表教科研论文10余篇，参编教材1部。指导学生团队在专业学科和技能竞赛、创新创业训练项目等大学生学科竞赛中获奖，多次获评优秀指导教师。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, '安徽师范大学', NULL, NULL, NULL, '大学，管理学硕士，副教授。多年来，主要从事养老保障、人力资源管理等方面的教学和研究工作。先后主持安徽省哲学社会科学规划项目、安徽省教育厅人文社科研究重点项目、安徽省社会科学创新发展项目、池州市社科联等单位；大学生学科竞赛中获奖，多次获评优秀指导教师。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('500', '文静', '商学院', '副教授', NULL, '', '文静，中南财经政法大学硕士，副教授，硕士生导师，皖南民俗文化与旅游发展研究院研究员，安徽省黄梅戏文化研究会理事，曾担任安徽省中小学教师资格证面试考官。 多年来，主要从事企业管理、教育学、产业经济学、文化与旅游等方面的教学和研究工作，曾主持安徽省哲学社科规划项目、安徽省教育厅人文社科重点研究项目、池州学院质量工程校级教研项目等多项课题的研究工作，发表本科学报论文16篇，EI收录期刊论文2篇，及其他论文多篇。论文曾获2023年安徽省社科联第十八届学术年会论文三等奖和2024年第十一届皖江地区历史文化研讨会论文二等奖。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, '中南财经政法大学', NULL, NULL, NULL, '大学硕士，副教授，硕士生导师，皖南民俗文化与旅游发展研究院研究员，安徽省黄梅戏文化研究会理事，曾担任安徽省中小学教师资格证面试考官。 多年来，主要从事企业管理、教育学、产业经济学、文化与旅游等方面的教学和；本科学报论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('501', '刘飞', '商学院', '副教授', NULL, '', '刘飞，日本桃山学院大学博士、博士后，副教授，博士生导师、外国留学生硕士生导师。曾工作于四川轻化工大学。目前兼任教育部研究生学位论文评审专家、北京大学光华管理学院硕士论文评审专家、中国教育技术协会中等职业教育专业委员会智库专家、四川省天府英才、自贡市高层次人才-市级领军人才、自贡市/宜宾市学术和技术带头人后备人选、自贡市社科新型智库专家。曾任四川省青年联合会第十四届委员会委员，自贡市青年联合会第十三届委员会常委、副主席。 先后主持各级课题44项，其中全国农业教指委项目1项、省部级项目6项、教育部产学合作协同育人项目1项、四川高校哲学社会科学重点研究基地项目7项、四川省高等学校人文社会科学重点研究基地项目8项。发表学术论文40余篇，其中SCI/SSCI/CSSCI/中文核心等30余篇。获得四川省教学成果奖3项、市级社会科学优秀成果奖4项。2022年获国际学术组织颁发“Best Researcher Award”。 《加快跨境电商发展需着力打破人才瓶颈》的建议2018年11月被民盟中央采纳；《基于食品安全事件的食品监督反思》2019年3月被民盟四川省委采纳；《关于实行旅游联票制度的建议》2018年5月被自贡市政协采纳。', '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, '日本桃山学院大学', NULL, NULL, NULL, '大学博士、博士后，副教授，博士生导师、外国留学生硕士生导师。曾工作于四川轻化工大学。目前兼任教育部研究生学位论文评审专家、北京大学光华管理学院硕士论文评审专家、中国教育技术协会中等职业教育专业委员会智库专', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('502', '余丙南', '商学院', '副教授', NULL, '', NULL, '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, '硕士，副教授，中国知识产权研究会高校专家委员会委员，安徽省法学法律专家库成员，池州市人大常委会立法专家顾问。近几年主要从事知识产权法', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('503', '潘霞', '商学院', '副教授', NULL, '', NULL, '0', '0', '0', '2026-06-05 16:59:34', '2026-06-05 16:59:34', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('504', '班爱玲', '大数据与人工智能学院', '班爱玲-大数据与人工智能学院', NULL, '', '班爱玲，女，1982年7月，安徽巢湖人，副教授，硕士。2005年6月毕业于淮南师范学院，获得理学学士学位，2009年6月毕业于上海师范大学数理学院，获得理学硕士学位。 主讲课程： 高等数学，线性代数，概率论与数理统计，初等数论。 研究领域与方向： 微分方程与动力系统 主持与参与的教科研项目： 1、池州学院引进研究生科研启动项目：“具有阻尼的Sine-Gordon方程的核截面的存在性”（2009Rc010），主持 2、池州学院校级自然重点项目：具有临界增长指数的强阻尼非线性波动方程的全局吸引子（2013ZRZ006），主持 3、池州学院校级自然重点项目：具有强阻尼随机波动方程的动力学渐近行为的研究（2016ZRZ009），主持 4、池州学院校级教研一般项目：数学建模思想在高等数学教学中的应用（2010jy042），主持 5、安徽省教育厅自然科学研究重点项目：几类时滞扩散模型的行波解及其渐近性质研究（KJ2016A517）,参与 6、安徽省自然科学基金青年项目：几类非单调时滞扩散系统的行波解研究（1708085QA13），参与 7、安徽省教育厅教研重点项目：线性代数精品线下开放课程(2018kfk051)，参与 8、池州学院校级教学团队：代数类课程群教学团队(2016XJXTD02)，参与 9、池州学院校级教学团队：微分方程及其应用教学团队(2018XJXTD03)，参与 教科研论文：', '0', '0', '0', '2026-06-05 17:03:48', '2026-06-05 17:03:48', NULL, '淮南师范学院', NULL, '高等数学，线性代数，概率论与数理统计，初等数论。 研究领域与方向： 微分方程与动力系统 主持与参与的教科研项目： ', NULL, '硕士。；学士学位，；大学数理学院，获得理学硕士学位。 主讲课程： 高等数学，线性代数，概率论与数理统计，初等数论。 研究领域与方向： 微分方程与动力系统 主持与参与的教科研项目： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('505', '刘妍', '大数据与人工智能学院', '副教授', NULL, '', NULL, '0', '0', '0', '2026-06-05 17:03:48', '2026-06-05 17:03:48', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('506', '赵舵舵', '大数据与人工智能学院', '副教授', NULL, '', '赵舵舵，副教授，男，汉族，1983年10月生，安徽太湖人，黄山学院本科，安庆师范大学硕士研究生.曾访学东南大学数学学院. E-mail: zdd@czu.edu.cn 研究领域和方向： 微分方程、图论 主讲课程： 数学分析、数学分析选讲、常微分方程、现代控制理论基础、高等数学 教科研论文： 1.Kirchhoff Index and Degree Kirchhoff Index of Tetrahedrane-Derived Compounds [J]. Symmetry, 2023, 15, 1122. (SCI)(第一作者) 2.Mean-square consensus of a semi-Markov jump multi-agent system based on event-triggered stochastic sampling [J].Mathematical Biosciences and Engineering, 2023, 20(8): 14241-14259.(SCI)(第一作者) 3.一类变系数齐次线性微分方程组的解法[J].黑河学院学报,2023,14(06):182-185.(第一作者) 4.一类时变偶阶微分方程的Philos型准则[J].廊坊师范学院学报(自然科学版),2023,23(04):20-26.(第一作者) 5.苯环线性六角链中任意两点间的电阻距离[J].黄山学院学报,2023,25(05):1-5.(第一作者) 6.探析高等数学课程思政体系的构建策略[J].数学学习与研究,2022(24):8-10.(第一作者) 7.含位势的非线性双调和方程解的存在性[J].池州学院学报,2017,31(03):31-32. (第一作者) 8.浅析常微分方程教学方法[J].考试周刊,2014(33):49. (第一作者) 9.一类非线性椭圆型方程边值问题的可解性[J].池州学院学报,2013,27(06):37-38+44. (第一作者) 10.一类椭圆型方程边值问题的可解性[J].安庆师范学院学报(自然科学版),2011,17(02) :1-3+6. (第一作者) 教科研项目 ： 主持项目 1.安徽省教育厅优秀青年教师培育项目，YQYB2023059. 2.池州学院校级重点项目，基于事件触发的半马尔科夫跳变多智能体系统一致性,CZ2023ZRZ04. 3.池州学院校级线上课程，数学分析,2022XXSKC09. 4.池州学院校级科研重点项目，双调和方程可解性研究，CZ2018ZRZ05. 5.教育部中西部青年骨干教师访学项目. 6.安徽省教育厅教学研究项目，应用型本科高校高等数学课程思政化的有效路径探析，2020jyxm1291. 7.池州学院校级科研重点项目，多调和方程可解性研究，2014ZRZ007. 8.池州学院引进研究生科研启动项目，非线椭圆方程可解性研究，2011RC037. 参与项目 1.安徽省课程思政教学团队：微分方程及其应用课程思政教学团队，2020kcszjxtd57. 2.安徽省普通高校教学示范课：常微分方程，2020SJJXSFK1764. 获奖情况： 1.2023年，指导学生参加全国大学生数学竞赛获二等奖一人，三等奖一人. 2.2023年，获2022年度考核优秀. 3.2023年，获2022年度师德考核优秀. 4.2022年，指导学生参加全国大学生数学竞赛获一等奖两人，三等奖一人. 5.2022年，指导学生参加全国大学生奥林匹克数学竞赛获银奖两人，铜奖两人. 6.2022年，指导学生获全国大学生创新训练项目国家级项目一项，省级项目两项. 7.2021年获2018-2019、2019-2020两年度校级优秀教学质量奖. 8.2021年获安徽省教学创新大赛池州学院选拔赛二等奖. 9.2021年获校级教坛新秀. 10.2020年获安徽省优秀线上教学课程（数学分析）. 11.2020年获池州学院优秀线上教学课程（高等数学）. 12.2020年获安徽省教育教学联盟同课异构三等奖. 13.2019年获2016-2017、2017-2018两年度校级优秀教学质量奖. 14.2019年获院级优秀共产党员荣誉称号. 15.2018年加入池州学院微分方程优秀教学团队. 16.2017年获校级青年教师技能大赛优秀奖. 17.2017年“数学分析”课程课件被评为校级优秀多媒体教学课件奖. 18.2016年获校级优秀辅导员称号. 19.2015年“高等数学C”课程试卷被评为池州学院优秀试卷. 20.2014年“高等数学”课程教案被评为池州学院优秀教案奖. 21.2014年“高等数学C1”课程试卷获校级优秀试卷. 22.2014年，年度考核优秀等次.', '0', '0', '0', '2026-06-05 17:03:48', '2026-06-05 17:03:48', NULL, '太湖人，黄山学院', NULL, '数学分析、数学分析选讲、常微分方程、现代控制理论基础、高等数学 教科研论文： ', NULL, '本科，安庆师范大学硕士研究生.曾访学东南大学数学学院. ；本科高校高等数学课程思政化的有效路径探析，；大学生数学竞赛获二等奖一人，三等奖一人. ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('507', '杨利', '大数据与人工智能学院', '高级实验师', '嵌入式系统、物联网等方向的教学与研究工作', '', '杨 利，高级实验师，男，汉族，1980年12月出生，湖北武汉人。2003年7月毕业于长江大学计算机科学与技术专业，获工学学士学位。2013年12月毕业于南昌航空大学信息工程学院，获计算机应用技术工程硕士学位。主要从事嵌入式系统、物联网等方向的教学与研究工作。 讲授课程：无线传感器网络、嵌入式系统工程实践、ARM原理及应用、网页设计与制作、C语言程序设计、数据库技术与应用。 累计发表教科研论文10篇，第一作者4篇，副主编教材4部。主持完成池州学院校级科研重点项目1项、一般项目1项。主持教研项目2项，参与省校级教科研多项。 2012年、2014年、2021年年度考核优秀，获池州学院数学与计算机学院优秀共产党员称号2次、获池州学院教学成果三等奖1项、优秀试卷奖2项、优秀课内实践教学教案奖1项、优秀课程教案奖1项、优秀多媒体教学课件奖2项、青年教师教学技能比赛优秀奖1项。指导学生大学生创新创业训练计划项目3项，中国大学生服务外包创新创业大赛省级三等奖1项、安徽省机器人大赛省级三等奖2项、安徽省物联网应用创新大赛省级三等奖1项。', '0', '0', '0', '2026-06-05 17:03:48', '2026-06-05 17:03:48', NULL, '长江大学', NULL, NULL, NULL, '大学计算机科学与技术专业，获工学学士学位。；大学信息工程学院，获计算机应用技术工程硕士学位。主要从事嵌入式系统、物联网等方向的教学与研究工作。 讲授课程：无线传感器网络、嵌入式系统工程实践、；大学生创新创业训练计划项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('508', '王巍', '大数据与人工智能学院', '副教授', NULL, '', '王巍，男，1988年9月生，安徽池州人，副教授，2010年毕业于安徽大学经济学院，获经济学学士学位；2012年毕业于上海海事大学经济与管理学院，获经济学硕士学位。 E-mail:czu_wangwei@163.com 研究领域和方向： 非参数统计；概率极限理论；经济统计 主讲课程： 多元统计分析、非参数统计、概率论与数理统计等 科研论文： 1. Wang Wei ,WuYi ,WangWenqin ,ZhouKai, ChenKanandTaoXinran.Hajek–Renyi-type inequality for ( α , β )-mixing sequences and its application to change-point model.Journal of Inequalities and Applications,2022, 130 (2022). （SCI） 2. Wang W ei , HuangHaiwu,WuYi,ChenKan.On the uniform consistency of frequency polygons for ρ - -mixing samples.Journal of Mathematical Inequalities.2021,15(3), 1287-1298.( SCI ) 3. Wang Wei, Wu Yi. Consistency of nearest neighbor estimator of density function for m-END samples. Brazilian Journal of Probability and Statistics , 2022, 36(2), 369–384.( SCI ) 4. Wang Wei , Wu Qingqing, Tang Xufei. 2021. Kernel density estimation under widely orthant dependence.中国科学技术大学学报.2022,52(02).( CSCDE ) 5. 王巍 ,郑文慧.突发公共卫生事件对安徽省经济影响的差异性分析.安庆师范大学学报(社会科学版),2020,39(03)，24-28. 6. 王巍 ,郑文慧,唐焰飞.基于网络文本分析的池州市旅游情感与综合形象感知分析.池州学院学报,2020,34(03)，69-71. 教科研项目 ： 1.安徽省教学研究一般项目:统计学专业课程建设中创客元素的嵌入研究—以《金融数学》为例（2020jyxm1282），2020年; 2.池州学院大规模在线开放课程示范项目:多元统计分析（2019XMOOC09），2019年; 3.池州学院教学研究一般项目：《金融数学》课程建设中创客元素的嵌入研究（2019XJYXM34），2019年; 4.安徽高校优秀青年人才支持计划一般项目（gxyq2022112)，2022年; 5.安徽省高校人文社会科学研究重点项目：复杂相依数据下我国碳市场价格相依性风险的统计测度研究（SK2021A0739），2021年; 6.池州学院校级自然重点项目：基于Divisia理论的在线大数据高频CPI指数设计研究（CZ2019ZRZ03），2019年； 获奖情况： 1.2016年获池州学院青年教师教学技能比赛三等奖； 2.2017、2019、2020年获得池州学院优秀教学质量奖优秀教学质量奖； 3.2021年获安徽省高校教师教学创新大赛池州学院选拔赛三等奖； 4.2019年指导学生获安徽省大学生统计建模大赛一等奖； 5.2019年指导学生获第九届全国大学生市场调查与分析大赛安徽省一等奖。', '0', '0', '0', '2026-06-05 17:03:48', '2026-06-05 17:03:48', NULL, '安徽大学经济学院', NULL, '多元统计分析、非参数统计、概率论与数理统计等 科研论文： ', NULL, '大学经济学院，获经济学学士学位；；大学经济与管理学院，获经济学硕士学位。 ；大学学报.', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('509', '包小兵', '大数据与人工智能学院', '副教授', NULL, '', '包小兵，男，1981年8月生，安徽庐江人，副教授，硕士。2012年毕业于安徽大学计算数学专业，获理学硕士学位，现任大数据与人工智能学院应用数学教研室主任，池州学院校级教坛新秀。 办公地点 ：博弈北204 E-mail: xiaobingb@czu.edu.cn 研究领域和方向： 微分方程数值解，智能算法 主讲课程： 数值计算方法，最优化方法，高等数学，线性代数，高等代数，数学建模与实验 科研论文： [1]一类奇异摄动反应扩散方程数值模拟中的参数估计,池州学院学报,2015,29(6):21-22; [2]差分进化算法在奇异摄动问题数值模拟中的应用,铜仁学院学报,2017,19(3):107-101; [3] An efficient adaptive grid method for a system of singularly perturbed convection-diffusion problems with Robin boundary conditions, Advances in Difference Equations,6,2021 https://doi.org/10.1186/s13662-020-03166-y (SCI二区,通讯作者); [4] Efficient Numerical Method for Reaction-Diffusion Problems Based on Particle Swarm Optimization Algorithm, ICNC-FSKD 2020, AISC 1348, 2021, 401–409, https://doi.org/10.1007/978-3-030-70665-4_46 (EI会议)； [5]奇异摄动反应扩散方程的后验误差估计及自适应算法,应用数学和力学,2021,42(3): 323-330(CSCD核心); [6]一类奇异摄动对流扩散方程组的自适应网格方法的收敛性分析,应用数学,2021,34(1): 184-193(CSCD扩展）； [7] An optimal adaptive grid method based on L1 scheme for a nonlinear Caputo fractional differential equation, Fractal and Fractional, 2022,1-13(SCI三区,通讯作者)； [8]基于混合有限差分格式的非线性奇异摄动问题的最大范数的后验误差估计,工程数学学报,2022,39(3):428-438 (CSCD核心). 教科研项目： 1.池州学院自然科研一般项目:基于朴素贝叶斯的中文文本情感分类研究(2014ZR005); 2.池州学院自然科研重点项目：基于差分进化算法的Volterra积分微分方程的数值方法研究(2018ZRZ06) ; 3.安徽省高校优秀青年人才支持一般项目(gxyq2021225); 4.安徽省重大线上教学改革研究项目：“互联网+”背景下大学生公共课线上教学的探讨与实践(2020zdxsjg240,参与,排名第二). 获奖情况： 1. 2014年获池州学院青年教师技能大赛二等奖; 2. 2014年被评为池州学院优秀辅导员； 3. 2014年获得池州学院2012-2013、2013-2014优秀教学质量奖； 4. 2016年获安徽省教学成果一等奖(排名第三) 5. 2016年获池州学院2014-2015学年校级优秀教案奖； 6. 2016年指导学生参加全国大学生数学建模竞赛获省二等奖1项； 7. 2017年获安徽省第二届应用型本科高校联盟青年教师教学竞赛理科组二等奖； 8. 2017年获安徽省教学成果二等奖(排名第三)； 9. 2018年获池州学院2016-2017学年校级优秀试卷奖； 10. 2019年获池州学院2016-2017、2017-2018优秀教学质量奖； 11. 2020年获校级“教坛新秀”称号； 12. 2020年指导学生参加第十二届大学生数学竞赛获省一等奖1项； 13. 2020年指导学生参加全国大学生数学建模竞赛获省二等奖1项； 14. 2020年指导学生参加亚太地区大学生数学建模竞赛获得二等奖1项； 15. 2021年指导学生参加全国大学生数学建模竞赛获省二等奖3项； 16. 2021年指导学生参加第四届中青杯全国大学生数学建模竞赛获本科组二等奖1项； 17. 2021年指导学生参加"认证杯"数学中国数学建模国际赛 获H奖、M奖各1项； 18. 2021年指导学生参加第十四届“认证杯”数学中国数学建模网络挑战赛全国比赛第一阶段二等奖1项； 19. 2022年指导学生参加亚太地区大学生数学建模竞赛获得一等奖1项； 20. 2022年指导学', '0', '0', '0', '2026-06-05 17:03:48', '2026-06-05 17:03:48', NULL, '安徽大学', NULL, '数值计算方法，最优化方法，高等数学，线性代数，高等代数，数学建模与实验 科研论文： ', NULL, '硕士。；大学计算数学专业，获理学硕士学位，现任大数据与人工智能学院应用数学教研室主任，池州学院校级教坛新秀。 办公地点 ：博弈北；大学生公共课线上教学的探讨与实践', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('510', '曹怀火', '大数据与人工智能学院', '教授', NULL, '', '曹怀火，男，汉族，1974年11月生，安徽东至人，教授，博士研究生结业，理学硕士学位，研究方向应用偏微分方程。 讲授课程：高等数学、高等代数、线性代数、常微分方程、数学物理方程、概率论与数理统计、数学史、科研论文写作。 教科研成果：发表教、科研论文35篇，其中独撰或第一作者20篇、SCI(或EI)收录8篇、CSCD(或扩展版)论文10篇。主持完成安徽省高校省级精品资源共享课程(2012gxk110)、省级教学团队(2019jxtd116)，参与国家自然科学青年基金项目(11301044，第一参与人)，主持完成安徽省教育厅自然科学研究重点项目(KJ2015A251)、一般项目( KJ2009B101)，池州学院自然科学研究重点项目2项和一般项目1项，池州学院与池州市教体局合作重点研究项目1项(JK2023014)。 发表科研论文（英文）： 1.Stationary Patterns of a Predator–Prey Modelwith Prey-Stage Structure and Prey-Taxis. International Journal of Bifurcation and Chaos,2021. 2.A new analysismethod for chemotaxis-induced instability in multi-species host-parasitoid systems.Advances in Mathematical Physics, 2017. 3.Global solutions in the species competitive chemotaxis system with inequal diffusion rates.Discrete Dynamics in Nature and Society. 2016. 4.An Improved Sextic Spline Method for Solving Singularly Perturbed Boundary Value Problems.应用数学，2012. 5.A fourth-order method of the convection-diffusion equations with Neumann boundary conditions.Applied Mathematics andComputation, 2011. 6.Numerical solution of telegraphic equations with source term using the generalized trapezoidal formula.2011 Fourth International Joint Conference on Computational Sciences and Optimization, 2011. 7.Non-polynomial Spline Difference Schemes forSolving Second-order Hyperbolic Equations.I.J.Information Technology and ComputerScience, 2011. 8.Multiple Positive Solutions of Three-Point Boundary Value Problems for Systems of Nonlinear Second Order Differential Equations.大学数学,2011. 9. Global Existence and Convergence of Solutions to a Cross-Diffusion Cubic Predator-Prey System with Stage Structure for the Prey.Boundary Value Problems, 2010. 10.Parametric Cubic Spline Methods for Solving Hyperbolic Equations. The 2nd International Conference on Information Engineering and Computer Science 2010. 11. Global Existence and Stability of Solutions to a Cubic Predator-Prey System with Cross-Diffusion.应用数学，2009. 12.Uniform Boundedness and Stability of Solutions to a ', '0', '0', '0', '2026-06-05 17:03:48', '2026-06-05 17:03:48', NULL, NULL, NULL, NULL, NULL, '博士研究生结业，理学硕士学位，研究方向应用偏微分方程。 讲授课程：高等数学、高等代数、线性代数、常微分方程、数学物理方程、概率论与数理统计、数学史、科研论文写作。 教科研成果：发表教、科研论文；大学数学,', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('511', '殷晓玲', '大数据与人工智能学院', '教授', NULL, '', '殷晓玲，安徽枞阳人，教授，安徽工业大学兼职硕士生导师。2000年毕业于淮北师范大学计算机科学与技术专业，获理学学士学位；2007年毕业于西北大学计算机软件与理论专业，获工学硕士学位。主持教育厅自然科学重点项目、高等学校优秀青年人才基金项目、校级自然科学重点项目、校级一般项目各一项；参加厅级重点、校级重点等多项。主持省级质量工程项目、校级质量工程重点项目、校级一般项目一项；参加省级质量工程项目、校级重点等多项。主编教材两部，副主编两部。在一类刊物发表论文两篇以上，二类及其它刊物发表论文多篇。针对课程教学发表教学论文多篇。 E-mail:yxl@czu.edu.cn 研究领域和方向：机器学习、数据结构与算法、信息安全。 主讲课程：C语言程序设计、数据结构。 获奖情况：获校级教学成果二等奖、优秀毕业论文指导教师、优秀教案、教坛新秀、教学质量优秀奖等多项奖励，指导学生参加比赛获多项奖。', '0', '0', '0', '2026-06-05 17:03:48', '2026-06-05 17:03:48', NULL, '淮北师范大学', NULL, 'C语言程序设计、数据结构。 获奖情况：获校级教学成果二等奖、优秀毕业论文指导教师、优秀教案、教坛新秀、教学质量优秀奖等多项奖励，指导学生参加比赛获多项奖。', NULL, '大学兼职硕士生导师。；大学计算机科学与技术专业，获理学学士学位；；大学计算机软件与理论专业，获工学硕士学位。主持教育厅自然科学重点项目、高等学校优秀青年人才基金项目、校级自然科学重点项目、校级一般项目各一项；参加厅级重点、校级重点等多项。主持省级质量工程项目、校级质量工', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('512', '张秋华', '大数据与人工智能学院', '副教授', '随机微分方程，数理统计 主持的教科研项目： ', '', '张秋华，副教授，男，1981年9月生，安徽无为人。2004年毕业于安徽大学统计学专业，获理学学士学位，2010年毕业于华东师范大学统计学专业，获理学硕士学位。 E-mail: qhzhang@czu.edu.cn 主讲课程： 概率论与数理统计，抽样技术，高等数学，解析几何 研究方向： 随机微分方程，数理统计 主持的教科研项目： 1、安徽省教育厅科研重点项目：几类带Levy跳的随机种群系统的动力学性质研究(KJ2018A0578)，在研 2、安徽省教育厅科研一般项目：随机泛函微分方程稳定性问题的研究(KJ2013B178),完成 3、安徽省教育厅高校优秀拔尖人才项目：国内访学项目（gxgnfx2019055） 4、池州学院科研重点项目：多重比较的第一类错误率控制研究（2012ZRZ005），完成 5、池州学院科研一般项目：基于Logistic模型的池州市温室气体排放量估算与预测（XKY201306），完成 6、池州学院大规模在线开放课程（MOOC）示范项目：抽样技术（2018XMOOC02），在研 7、池州学院教研一般项目：应用型院校高等数学实践教学环节的教学研究与实践（2013jyxm46），完成 研究成果： 1、Stationary Distribution and Extinction of a Stochastic SIQR Model with Saturated Incidence Rate.Mathematical Problems in Engineering.2019,SCI（第一作者） 2、时滞非局部扩散Lotka-Volterra竞争系统行波解的存在性.山东大学学报（理学版）.2015,CSCD核心,（第一作者）； 3、一类具有庇护效应的阶段结构时滞Holling-III型捕食-食饵模型的稳定性和Hopf分支.淮北师范大学学报（自然科学版）.2017,（第一作者） 4、寿命服从威布尔分布的产品失效时间的预测.池州学院学报.2011,（第一作者） 5、求解VG方程参数的混合杂草算法.池州学院学报.2015,（第一作者） 获得的主要奖励： 2005年，池州学院教学技能大赛三等奖 2011年，育部科技司和社科司授予教育系统先进个人 2013年，校级教学成果三等奖 2014年，池州学院教学单项奖 池州学院2017年、2019年优秀共产党员 池州学院2009年度、2013年度、2016年度、2017年度考核优秀等次', '0', '0', '0', '2026-06-05 17:03:48', '2026-06-05 17:03:48', NULL, '安徽大学', NULL, '概率论与数理统计，抽样技术，高等数学，解析几何 研究方向： 随机微分方程，数理统计 主持的教科研项目： ', NULL, '大学统计学专业，获理学学士学位，；大学统计学专业，获理学硕士学位。 ；大学学报', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('513', '操漫成', '大数据与人工智能学院', '副教授', NULL, '', NULL, '0', '0', '0', '2026-06-05 17:03:48', '2026-06-05 17:03:48', NULL, NULL, NULL, NULL, NULL, '博士名录 专任教师 专职辅导员 产业教师 外聘教师 党群工作 党建动态 专题教育 党员发展 理论学习 工会动态 教学管理 教学动态 管理制度 培养方案 质量工程 实践教育基地 实践教学 百校工程 科研工作', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('514', '桂旺生', '大数据与人工智能学院', '副教授', '数学教学工作', '', '桂旺生，男，1966年12月生，汉族，安徽池州人，硕士，副教授，主要从事数学教学工作。 主讲课程： 高等数学，实变函数，泛函分析，数学分析，中学数学研究，微分方程，线性代数等 主持安徽省教育厅自然科学研究项目一项：具p-Laplace算子高阶微分方程（组）边值问题正解的存在性（KJ2009B234z），池州学院自然重点项目一项：分数阶微分方程边值问题正解存在性研究。 发表论文15篇，其中4篇发表CSCD和原安徽省教育厅国家级期刊上。2010年高等数学试卷获校级优秀奖。', '0', '0', '0', '2026-06-05 17:03:48', '2026-06-05 17:03:48', NULL, NULL, NULL, '高等数学，实变函数，泛函分析，数学分析，中学数学研究，微分方程，线性代数等 主持安徽省教育厅自然科学研究项目一项：具p', NULL, '硕士，副教授，主要从事数学教学工作。 主讲课程： 高等数学，实变函数，泛函分析，数学分析，中学数学研究，微分方程，线性代数等 主持安徽省教育厅自然科学研究项目一项：具', NULL, NULL);
