INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('536', '贡贵训', '文学与传媒学院', '教授', '汉语方言学、地方文化 讲授课程：现代汉语、语言学概论等 教育经历： ', '', NULL, '0', '0', '0', '2026-06-05 17:15:49', '2026-06-05 17:15:49', NULL, '博士研究生', NULL, '', NULL, '博士研究生 ；大学汉语言文学本科；大学 汉语言文字学 硕士研究生 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('537', '汤文益', '文学与传媒学院', '教授', NULL, '', '基本情况 姓名 汤文益 性别 男 职称 教授 所属系 中文系 是否硕导 否 最高学历 博士研究生 Email 39648752@qq.com 详细情况 所在学科专业 中国语言文学 研究方向 文学教育、高等教育管理 讲授课程 文学概论、外国文学等 教育经历 学士（2003）、硕士（2010）、博士（2023）。 工作经历 助教（2004）、讲师（2008）、副教授（2013），获青年教师指导教师资格：教学型（2015）、科研型（2023），历任校党委组织部组织科副科长、科长，干部科长、副部长，党委办公室副主任、主任，现任校党委委员、宣传部（统战部）部长、文明办主任。 科研项目 主持省高校优秀青年人才项目、省高校优秀拔尖人才培育项目、省高校人文社会科学重点研究项目、省级质量工程重点研究项目等7项，参与国家级、省级科研项目等10余项。 学术论文 在《比较教育研究》《出版科学》《中国教育报》《江苏教育》《应用型高等教育研究》等刊物发表学术论文20余篇。 著作教材 出版《文学课堂：实践与反思》（2021），参编《外国文学鉴赏辞典》（2009），参加《大学生文学素养》（2014）编写及其省级规划教材修订项目（2019），参编《新时代劳动教育》教材（2021），参与（排名第二）国家级一流本科课程建设（2023）。 获奖情况 安徽省高校优秀党务工作者（2011）、池州学院青年教师教学技能大赛一等奖（2011）、安徽省省级“教坛新秀”（2014）、安徽省教学成果奖（三等奖）（2015）、安徽省“双争活动”优秀共产党员并被《安徽日报》专题报道（2017）、安徽省优秀党务工作者（2021）、安徽省“三项课题”研究成果优秀奖（2021）等，多次获校优秀教学质量奖。 社会兼职', '0', '0', '0', '2026-06-05 17:15:49', '2026-06-05 17:15:49', NULL, '博士研究生', NULL, NULL, NULL, '博士研究生 ；学士；硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('538', '张银飞', '文学与传媒学院', '教授', NULL, '', '基本情况 姓名 张银飞 性别 男 职称 教授 所属系 中文系 是否硕导 否 最高学历 博士研究生 Email 297104779@qq.com 详细情况 所在学科专业 中国语言文学 研究方向 中国现当代美学及朱光潜美学、明代诗学、桐城派诗学 讲授课程 《 文学理论 》《 大学生文学素养 》 等 教育经历 2003.09-2007.06 安庆师范大学 汉语言文学 本科 / 学士 2007.09-2010.06 安庆师范大学 中国古代文学 研究生 /硕士 2021.09-2024.06 安徽大学 美学 研究生 /博士 工作经历 2010.07--2013.12 铜陵学院 助教 2014.01--2019.12 铜陵学院 讲师 2020.01--2021.07 铜陵学院 副教授 2024.08 至今 池州学院 副教授 科研项目 主持各级各类科研项目 1 0 余项，其中省 部 级项目 5项，1项课题研究成果被铜陵市委领导作肯定性批示，并建议采纳、应用 与 推广。此外，参与各级各类项目 10余项，其中参与国家社科重大项目1项，参与安徽省高校优秀团队项目1项（第二）： 1.安徽省哲学社会科学规划项目：“方以智诗学辨体理论研究”，省级，主持； 2.安徽省社会科学创新发展研究课题项目：“中西互为体用视域下朱光潜诗美思想的多维创构——以《诗论》境界论为中心”，省级，主持； 3.安徽省社会科学创新发展研究课题项目：“社会主义核心价值观视域下桐城文化传承与创新路径研究”，省级，主持； 4.安徽省高校青年人才支持计划重点项目：“朱光潜《诗论》境界论研究”，省级，主持； 5.安徽省高校科研计划重点项目：“朱光潜《诗论》诗境论的话语体系转换及其美学思想构建研究”，省级，主持。 学术论文 在《青海社会科学》《人文杂志》等 CSSCI来源期刊和《安徽日报（理论版）》发表学术论文近20篇，另撰写的理论文章被省领导作肯定性批示1次： 1.《被误读的朱光潜：对陶渊明公案的澄清》，《人文杂志》，CSSCI， 2.《诗学辨体理论与晚明诗学思潮——以方以智的〈诗说〉为中心》，《青海社会科学》，CSSCI； 3.《着力发展新型公共文化空间》，《安徽日报（理论版）》，二类，被省领导作肯定性批示； 4.《深度挖掘中华优秀传统文化的当代价值》，《文化中国学刊（加拿大）》。 著作教材 无 获奖情况 荣获各级各类荣誉近 20项，其中省级2项，市级2项： 1. 安徽省社科联： “三项课题”研究活动优秀成果，二等奖； 2. 安徽省教育厅：教学成果奖，三等奖； 3. 铜陵市人民政府：铜陵市第九届（ 2019-2021年度）社科优秀成果奖，三等奖； 4. 铜陵市委宣传部：思想政治工作优秀研究成果，一等奖； 社会兼职 1.安徽省哲学社会科学规划项目评审专家库评审专家； 2.铜陵市社会科学专家库文学领域入库专家； 3.安徽省美学学会会员； 4.桐城派研究会会员。', '0', '0', '0', '2026-06-05 17:15:49', '2026-06-05 17:15:49', NULL, '博士研究生', NULL, NULL, NULL, '博士研究生 ；大学生文学素养 ；大学 汉语言文学 本科 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('539', '王保成', '文学与传媒学院', '教授', NULL, '', '基本情况 姓名 王保成 性别 男 职称 副教授 所属系 中文系 是否硕导 否 最高学历 博士 Email Chwangbc@126.com 详细情况 所在学科专业 汉语言文字学 研究方向 古文字与出土文献 讲授课程 古代汉语、中国古典文献学 教育经历 1993.9-1996.6 池州学院（高等教育） 2003.9-2006.6 云南民族大学（研究生教育） 2010.10-2013.12 安徽大学（研究生教育） 工作经历 1996.7-2003.8 老洲中学从教 2006.7- 至今 池州学院从教 科研项目 1. 池州学院研究生科研启动项目《枞阳东乡方言的调查研究》（ XYK200615 ），主持，结题。 2. 安徽大学研究生学术创新研究项目《三国砖铭的整理与研究》（ yfc100031 ），主持，结题。 3. 安徽省教育厅人文社科基金项目《长沙走马楼三国吴简文字研究》（ SK2013B333 ），主持，结题。 4. 安徽省高校人文社科基地重点项目《三国吴简文字整理与研究》（ SK2015A006 ），主持，结题。 5. 国家社会科学基金项目《汉字发展史视域下三国吴简文字研究》（ 17BBY128 ） , 主持，在研。 学术论文 1. 《 20 世纪出土吉语玺释文补正》，《安庆师范学院学报》， 2012 （ 6 ），独著。 2. 《翼城大河口霸伯簋试解》，《中原文物》， 2013 （ 2 ），独著。 3. 《 字新解》，《中国文字研究》， 2013 （ 2 ），独著。 4. 《頍方彝新解》，《励耘语言学刊》， 2015 （ 1 ），独著。 5. 《 “ 悬米 ” 释义》，《池州学院学报》， 2015 （ 2 ），独著。 6. 《重庆丰都东汉纪年陶铭试解》，《励耘语言学刊》， 2016 （ 2 ），独著。 7. 《二十世纪出土古玺释文补正》，《考古与文物》 ， 2016 （ 5 ），独著。 8. 《连云港西汉铜镜铭文补释》，《励耘语言学刊》， 2016 （ 3 ），独著。 9. 《重庆丰都东汉纪年陶盘试解》，《考古与文物》， 2019 （ 1 ），独著。 10. 《二十世紀出土戰國官璽釋文校補》，《出土文献》， 2019 （ 1 ），独著。 著作教材 无 获奖情况 无 社会兼职 无', '0', '0', '0', '2026-06-05 17:15:49', '2026-06-05 17:15:49', NULL, NULL, NULL, NULL, NULL, '博士 ；大学；大学', NULL, NULL);
