INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('551', '刘玮', '文学与传媒学院', '博士', NULL, '', '基本情况 姓名 刘玮 性别 女 职称 所属系 （教研室） 中文系 是否硕导 否 最高学历 博士研究生 Email 854357748@qq.com 详细情况 所在学科 专业 语言学及应用语言学 研究方向 语文教育史 讲授课程 小学语文教学法 教育经历 2010 年 9 月至 2014 年 6 月 淮阴师范学院 文学院 汉语言文学（师范） 2014 年 9 月至 2016 年 6 月 杭州师范大学 人文学院 学科教学（语文） 2021 年 9 月 至 2025 年 6 月 扬州大学 文学院 语言学及应用语言学 工作经历 2016-2021 南京市光华东街小学 小学语文教师 科研项目 学术论文 1. 《胡乔木的写作观及其对当代写作教学的启示》，《语文建设》， 2022 年第 3 期。 2 . 《正确把握网络流行语的规范性和价值导向》，《新华日报》， 2024 年 11 月 8 日。 3 . 《“双减”背景下小学一年级语文标准化教学的“减”与“不减”》，发表于《中国标准化》 ， 2023 年第 2 期。 4 . 《守正创新谱新篇巧把金针度与人——评徐林祥主编 < 中学语文课程标准与教材研究（第 2 版） > 》发表于《中学语文》， 2024 年第 25 期。 著作教材 获奖情况 社会兼职', '0', '0', '0', '2026-06-05 17:16:27', '2026-06-05 17:16:27', NULL, '博士研究生', NULL, '小学语文教学法', NULL, '博士研究生 ；大学 人文学院 学科教学；大学 文学院 语言学及应用语言学 工作经历 ', NULL, NULL);
