INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('569', '李华维', '文学与传媒学院', '副教授', '泰语、中泰语言比较、对外汉语', '', '副教授。博士研究生。研究方向：泰语、中泰语言比较、对外汉语。主讲课程：现代汉语、现代汉语词汇研究、对外汉语教学概论、对外汉语教学法、对外汉语词汇教学、大学生文学素养。邮箱：97078703@qq.com', '0', '0', '0', '2026-06-05 17:17:20', '2026-06-05 17:17:20', NULL, '博士研究生', NULL, '现代汉语、现代汉语词汇研究、对外汉语教学概论、对外汉语教学法、对外汉语词汇教学、大学生文学素养', NULL, '副教授。博士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('580', '郑玲', '文学与传媒学院', '副教授', NULL, '', '基本情况 姓名 郑玲 性别 女 职称 副教授 所属系 中文系 是否硕导 否 最高学历 硕士 Email 44711685@qq.com 详细情况 所在学科专业 中国古代文学 研究方向 唐宋文学 讲授课程 《中国古代文学》《大学生文学素养》 教育经历 2000年9月-2004年7月 安徽师范大学汉语言文学专业 本科 2004年9月-2007年7月 厦门大学中文系中国古代文学专业 硕士 工作经历 2007年7至今 池州学院文学与传媒学院 科研项目 1.晚唐池州诗人群体研究（安徽省教育厅人文社科重点项目，三类），立项年份： 2016年，项目编号：SK2016A0650（已结题）； 2 . 舒亶研究（校级人文社科项目，五类），立项年份：2014年，项目编号：2014RW019（已结题） ； 3.北宋扬州文学研究（研究生科研启动项目，五类），立项年份：2007年，项目编号： XYK200716 （已结题）。 学术论文 1.随其资质 与之形貌——叶适碑志文写人艺术探微，《温州大学学报》2019年第1期； 2.文化地理视域下晚唐池州诗风探析，《阜阳师范学院学报》2018年第1期； 3.王安石的女性观——以女性墓志中的女性形象为论述中心，《黄山学院学报》2017年第4期； 4.叶适女性墓志探析，《六盘水师范学院学报》2018年第2期； 5.秦观“词心”研究述评，《池州学院学报》2013年第2期； 6.《宋史•舒亶传》正补三则，滁州职业技术学院学报2017年第6期； 7. 秦观“词心”研究述评，池州学院学报2013年第6期。 著作教材 无 获奖情况 无 社会兼职 无', '0', '0', '0', '2026-06-05 17:17:20', '2026-06-05 17:17:20', NULL, '硕士', NULL, '《中国古代文学》《大学生文学素养》', NULL, '硕士 ；大学生文学素养；大学汉语言文学专业 本科 ', NULL, NULL);
