INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('610', '朱晶', '艺术与教育学院', '朱晶-艺术与教育学院', NULL, '', '基本情况 姓名 朱晶 性别 女 职称 讲 师 所属系 音乐学系 最高学历 研究生 Email 4 23022029 @ qq.com 详细情况 学科专业 音乐学 研究方向 声乐演唱 讲授课程 声乐 教育经历 2 004.09 - 2008.07 海南大学音乐表演专业 2 010.09 - 2013.07 安徽师范大学音乐学专业 工作经历 2 013.07 - 至今 池州学院艺术与教育学院声乐教师 科研项目 2015年主持校级人文社科项目《以“品”促“声”——艺术鉴赏在声乐演唱中的价值体现》 学术论文 2015年 池州学院学报 《谈歌唱之“品” ——以<送给妈妈的茉莉花>为例》（ISSN 1674-1102 2015年第4期） 著作教材 获奖情况 1. 2013年度池州学院新进教师教学技能比赛一等奖 2. 2015年青年教师教学技能大赛三等奖 3. 2016年安徽省第八届魅力新星全国青少年才艺展示活动“优秀园丁”称号 社会兼职 2016年挂职 池州市贵池区幼儿园副园长', '0', '0', '0', '2026-06-05 17:34:04', '2026-06-05 17:34:04', NULL, NULL, NULL, NULL, NULL, '大学音乐表演专业 ；大学音乐学专业 工作经历 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('611', '靳琦', '艺术与教育学院', '靳琦-艺术与教育学院', '舞蹈教育与教学研究', '', '助教。研究生。研究方向：舞蹈教育与教学研究。主讲课程：《舞蹈（1-7）》 ；《儿童舞蹈基础》 ；《儿童舞蹈素材》 ；《儿童舞蹈表演》 ；《儿童舞蹈编创》。邮箱：695963101@qq.com', '0', '0', '0', '2026-06-05 17:34:04', '2026-06-05 17:34:04', NULL, NULL, NULL, '《舞蹈（1-7）》 ；《儿童舞蹈基础》 ；《儿童舞蹈素材》 ；《儿童舞蹈表演》 ；《儿童舞蹈编创》', NULL, '助教。研究生', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('613', '余义兵', '外国语学院', '教授', NULL, '', '基本情况 姓名 余义兵 性别 男 职称 教授 所属系部 英语系 最高学历 硕士研究生 详细情况 所在学科专业 英语语言文学 研究方向 翻译、跨文化交流和英语教育 讲授课程 学术论文写作、大学英语等 教育经历 华东师范大学；2005年选派赴澳大利亚进修，获TESOL证书 科研项目 1.安徽省高等学校人文社科项目：委婉语的美学认知研究（2010sk512）； 2.安徽省哲学社会科学规划项目：传播学视角下的旅游外宣翻译研究——以皖南国际旅游文化示范区为例（AHSK11-12D213）； 3.池州市社科联项目：国际化进程中池州旅游文化资源翻译研究（A201211）； 4.安徽省教育科学规划项目：农村中学英语课程资源开发研究（JG1212）； 5.全国高校文科学报编辑学研究项目：数字化背景下地方高校学报集群化发展研究（2013ZC14）； 6.安徽省人文社科重点项目：一带一路背景下地方旅游文化国际传播研究（SK2019A0725）； 7.教育部产学协同育人项目：公共外语数字化教学资源共建共享模式研究（202102093009）', '0', '0', '0', '2026-06-05 17:37:33', '2026-06-05 17:37:33', NULL, NULL, NULL, NULL, NULL, '硕士研究生 详细情况 所在学科专业 英语语言文学 研究方向 翻译、跨文化交流和英语教育 讲授课程 学术论文写作、大学英语等 教育经历 华东师范大学；', NULL, NULL);
