INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('615', '刘波', '外国语学院', '讲师', NULL, '', '基本情况 姓名 刘波 性别 女 职称 讲师 所属系部 英语系 最高学历 硕士研究生 Email 550445572@qq.com 详细情况 所在学科专业 英语语言文学 研究方向 认知语言学、翻译 讲授课程 基础英语、新视野大学英语 教育经历 2005 年 9 月 -2009 年 7 月，安徽大学 2009 年 9 月 -2011 年 7 月，中国石油大学（北京） 工作经历 无 科研项目 新闻 Daily Report 与英语听力水平提高研究 学术论文 从认知诗学下的语篇世界理论看《喧嚣与骚动》、 概念整合理论对歇后语的阐释等 著作教材 无 获奖情况 优秀党务工作者、优秀共产党员、优秀辅导员、优秀实习指导教师等 社会兼职 无', '0', '0', '0', '2026-06-05 17:37:33', '2026-06-05 17:37:33', NULL, '硕士研究生', NULL, NULL, NULL, '硕士研究生 ；大学英语 教育经历 ；大学 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('616', '徐海雁', '外国语学院', '助教', NULL, '', '基本情况 姓名 徐海雁 性别 女 职称 讲师 所属系部 英语系 最高学历 硕士研究生 详细情况 所在学科专业 翻译硕士 研究方向 国际交流与传播；地方文化外译 讲授课程 基础英语；英语口语；跨文化交际；英语演讲与辩论；跨文化商务交际教程 教育经历 / 工作经历 / 科研项目 （1）主持池州学院重点人文社科研究项目《科技赋能下非物质文化遗产外宣翻译与传播策略研究——以池州傩戏为对象》， 立项时间，2024年6月； （2）主持池州市发改委横向项目《首个全国生态日池州市主题宣传活动翻译服务》，立项时间，2023年8月； 学术论文 《美国华裔文学的中国戏剧翻译研究—以赖声川的《暗恋桃花源》英译本为例.》黑龙江教育学院学报，第一作者，2019.12 著作教材 / 获奖情况 获得第十五届“外教社杯”全国高校外语教学大赛安徽赛区决赛一等奖； 获得“天柱山杯”安徽省第六届徽文化国际传播翻译大赛二等奖 社会兼职 地方外事翻译；法律案件陪同翻译等', '0', '0', '0', '2026-06-05 17:37:33', '2026-06-05 17:37:33', NULL, NULL, NULL, NULL, NULL, '硕士研究生 详细情况 所在学科专业 翻译硕士 研究方向 国际交流与传播；地方文化外译 讲授课程 基础英语；英语口语；跨文化交际；英语演讲与辩论；跨文化商务交际教程 教育经历 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('617', '王祖彤', '外国语学院', '助教', NULL, '', '基本情况 姓名 王祖彤 性别 女 职称 助教 所属 系部 英语系 最高学历 硕士研究生 详细情况 所在学科专业 学科教学（英语） 研究方向 英语教学论 讲授课程 英语教学法、英语教学研究方法及论文写作、大学英语 教育经历 2017.09—2021.06 巢湖学院外国语学院 2021.09—2024.06 安庆师范大学外国语学院 工作经历 2024.07—至今 池州学院外国语学院 专任教师 科研项目 1.主持2022年度安徽省新时代育人质量工程项目（研究生教育）省级研究生创新创业项目 《青听童语——“双减”政策背景下英语歌曲在中学英语课堂的创新应用》（项目编号：2022cxcysj164） 2.主持2021年度校级研究生学术创新项目 《青听童语——“双减”政策背景下英语歌曲在中学英语课堂的创新应用》（项目编号：2021yjsXSCX024） 3. 2023年度安徽省新时代育人质量工程项目省级研究生创新创业项目 《用英语讲好安庆故事——基于皖江文化元素的多模态英语学习资源的开发与运用》（项目编号：2023cxcysj140） 4. 2023年校级大学生创新创业训练计划项目《英语学科教师教育类课程思政资源库建设》 （项目编号：X202310372005） 学术论文 著作教材 获奖情况 社会兼职', '0', '0', '0', '2026-06-05 17:37:33', '2026-06-05 17:37:33', NULL, NULL, NULL, NULL, NULL, '硕士研究生 详细情况 所在学科专业 学科教学；大学英语 教育经历 ；大学外国语学院 工作经历 ', NULL, NULL);
