INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('623', '王志宏', '外国语学院', '副教授', NULL, '', '副教授。博士。主讲课程：中国的民主、商务英语翻译、新编大学英语阅读教程、数码科幻艺术、三维数码设计。社会兼职：中国逻辑学会语用学专业委员。邮箱：648014087@qq.com', '0', '0', '0', '2026-06-05 17:37:33', '2026-06-05 17:37:33', NULL, '博士', NULL, '中国的民主、商务英语翻译、新编大学英语阅读教程、数码科幻艺术、三维数码设计', NULL, '副教授。博士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('624', '刘翠萍', '外国语学院', '副教授', NULL, '', '基本情况 姓名 刘翠萍 性别 女 职称 副教授 所属系部 英语系 最高学历 本科 Email 543794773@qq.com 详细情况 所在学科专业 英语语言文学 研究方向 外宣翻译、词语语用、英语教学、二语习得 讲授课程 英语教学法、英语词汇学、英语教学技能训练、大学英语、旅游翻译等 教育经历 1998.9-2002.7 阜阳师范学院就读 2008.9-2011.6 安徽大学同等学历课程研修 2024.9-2025.6 江南大学访学 工作经历 2002.7-2007.2 池州师范专科学校任教 2007.3- 至今 池州学院任教 科研项目 主持的科研项目： 1.安徽省教育厅人文社科项目“九华山旅游景点公示语汉英翻译研究 （2011SK505）”； 2.池州学院人文重点项目“多模态话语分析视角下公益广告的语用研究（2013RWZ003）”； 3.池州学院人文重点项目“译介学视角下九华山旅游景点外宣翻译研究（2017RWZ013）”； 4.池州学院横向课题“九华黄精产品外宣翻译研究”。 主持的教学项目： 1.英语词汇学（安徽省省级课程思政示范课程），安徽省教育厅，2021-2023； 2.英语词汇学（安徽省省级教学示范课），安徽省教育厅，2021-2023； 3.新文科视域下《英语词汇学》生态课堂教学模式的构建及应用，安徽省教育厅，2024-2026； 4.新文科视域下《英语词汇学》生态课堂教学模式的构建及应用，池州学院重点教研项目，2023-2025； 5.池州学院平天湖小学校校合作实践教育基地项目，池州学院教研项目，2024--2026。 学术论文 [1] 刘翠萍.国内外传统文化翻译研究热点与趋势——基于CiteSpace知识图谱的可视化分析[J].池州学院学报,2024,38(04):50-53. [2] 刘翠萍,李奕华.课程思政背景下“英语词汇学”教学改革探索与实践[J].海外英语,2021,(15):16-17. [3] 刘翠萍,李奕华.基于CiteSpace科学知识图谱的国内外宣翻译研究[J].哈尔滨学院学报,2021,42(07):110-114. [4] 刘翠萍,李奕华.新世纪以来我国外宣翻译研究的知识图谱分析[J].吉林工程技术师范学院学报,2021,37(02):74-77. [5] 刘翠萍,刘军,陈新苗.九华山旅游景点标识牌英译[J].教育现代化,2019, 6(69):263-264. [6] 刘翠萍,陈新苗.非英语专业大学生自主性英语学习能力调查研究[J].教育教学论坛,2018,(10):239-241. [7] 刘翠萍.公益广告的多模态解读——以央视公益广告“妈妈的等待”篇为例[J].牡丹江教育学院学报,2016,(05):25-26. [8] 刘翠萍.互联网时代“英语词汇学”教学策略研究——以池州学院为例[J].兰州教育学院学报,2016,32(03):132-133. [9] 刘翠萍.关联理论视角下公益广告的解读[J].池州学院学报,2012, 26 (04):74-76. [10]刘翠萍.模因论视角下九华山旅游景点公示语的翻译研究[J].宿州学院学报,2011,26(06):68-69+74. [11]刘翠萍.功能语言学视角下英语语篇赏析[J].黄山学院学报,2010, 12 (06):79-81. [12]刘翠萍,刘小平.启发式英语课堂教学中的提问策略研究[J].科教文汇(中旬刊),2010,(14):124-125. [13]刘翠萍.及物性分析与新闻语篇解读[J].池州学院学报,2010,24 (01): 85-86. [14]刘翠萍.英汉称谓语中的性别歧视语对比研究[J].考试周刊,2008,(29): 184-186. [15]鲁萍,刘翠萍.从语言规划视角看九华山景区符号景观的研究路径[J].池州学院学报,2024,38(05):52-55. [16]李奕华,刘翠萍,罗娟.基于“对分课堂”的英语写作课程混合式教学模式构建与效果研究[J].池州学院学报,2022,36(02):133-137. 著作教材 获奖情况 1.池州学院课程思政典型教学案例评审二等奖（2024）； 2.全国课程思政教学案例设计大赛三等奖（2024）； 3.池州学院优秀多媒体课件奖（2016）； 4.池州学院优秀教案奖（2016）； 5.安徽省高等学校师范生教学技能竞赛优秀指导教师(2023); 6. 论文“新世纪以来我国外宣翻译研究的知识图谱分析”，2019年获第一届“皖江论坛”征文三等奖； 7.论文“国内外传统文化翻译研究进展比较：基于CiteSpace知识图谱的可视化分析”，2023年获第四届“皖江论坛”征文三等奖； 8.论文“公示语跨文化翻译的关键要素与理论逻辑：基于扎根理论研究”，2024年获第五届“皖江论', '0', '0', '0', '2026-06-05 17:37:33', '2026-06-05 17:37:33', NULL, NULL, NULL, NULL, NULL, '本科 ；大学英语、旅游翻译等 教育经历 ；大学同等学历课程研修 ', NULL, NULL);
