INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('630', '胡琴', '外国语学院', '讲师', NULL, '', '基本情况 姓名 胡琴 性别 女 职称 讲师 所属 商务英语系 最高学历 硕士研究生 Email 553190151@qq.com 详细情况 所在学科专业 英语 研究方向 翻译 讲授课程 基础英语、大学英语 教育经历 2005.9-2009.6 合肥工业大学 英语专业 本科 2009.9-2012.6 合肥工业大学 外国语言学及应用语言学专业 硕士 工作经历 2012.07- 至今 池州学院外国语学院 教师 科研项目 1. 池州学院科研项目：安乐哲与罗思文《论语》英译策略探究（ 2015RW004 ） 2. 池州学院教研项目：池州学院大学英语听力自主学习实践研究（ 2016XJYXM57 ） 3. 校级精品线下开放课程： 2020XXXKC08 基础英语 2 学术论文 1. 中国网络流行语的语言特征及其英译策略 [J]. 蚌埠学院学报 , 2016 （ 01 ）： 112-114. 2. 刍议安乐哲和罗思文的 < 论语 > 英译策略 [J]. 佳木斯职业学院学报 , 2016 （ 08 ）： 332-333. 3. 大学生英语听力自主学习调查研究 —— 以池州学院为例 [J]. 池州学院学报， 2020(3) ： 137-139. 著作教材 获奖情况 1. 2016 年 10 月 池州学院“优秀辅导员” 2. 2019 年 10 月 “全国高校教师教学创新大赛 — 第五届外语微课大赛”全国决赛二等奖 3. 2021.07 池州学院“优秀共产党员” 社会兼职 无', '0', '0', '0', '2026-06-05 17:37:33', '2026-06-05 17:37:33', NULL, '硕士研究生', NULL, NULL, NULL, '硕士研究生 ；大学英语 教育经历 ；大学 英语专业 本科 ', NULL, NULL);
