INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('632', '吴丽莹', '外国语学院', '副教授', NULL, '', '基本情况 姓名 吴丽莹 性别 女 职称 副教授 所属 系部 商务英语系 最高学历 硕士研究生 Email 617211743@qq.com 详细情况 所在学科专业 英语语言文学 研究方向 跨文化研究 讲授课程 跨文化交际、综合商务英语、口译 教育经历 2005.09-2009.06 郑州航空工业管理学院 文学学士 2010.09-2013.07 温州大学外国语学院 英语语言文学硕士 2023.07至今 上海外国语大学英语学院 博士在读 工作经历 2013.07至今 池州学院外国语学院 专任教师 科研项目 1. 安徽省高等学校科学研究（人文社会科学）项目： 民俗视域下安徽声腔戏曲的跨文化传播研究 （2024AH052890），在研； 2. “世界语言与文化研究”青年课题：青阳腔跨文化传播的再叙事研究 （WYZL2023AH0010）,在研； 3. 池州市平天湖风景区管理委员会委托项目“齐山-平天湖景区旅游标牌资料翻译服务”（RH2300000371）项目，结项； 4. 安徽省高等学校省级示范教学示范课：跨文化交际（2020SJJXSFK1795），已结项：合格； 5. 池州学院课程思政示范课程：跨文化交际（2019XKCSZ05），已结项：良好； 6. 上海外语教育出版社外语类委托项目： “一带一路”语境下地方高校学生跨文化交际能力提升研究（SK2018A1159），已结项：合格； 7. 池州学院科研重点项目：国际赛事志愿服务英语用语标准化研究（2016RWZ008），已结项：良好； 8. 池州学院教研重点项目：基于学生需求的大学英语课堂实践教学模式研究（2014jyxm11），已结项：良好。 学术论文 1.吴丽莹. 关联论视角下的翻译策略[J].内蒙古农业大学学报（社会科学版），2013（2）:133-137. 2.吴丽莹.黄哲伦——美国华裔戏剧发展的缩影[J].牡丹江大学学报，2013，22（4）:63-65. 3.吴丽莹，汪亚楠.国标背景下池州公示语英译现状及对策探析[J].文化创新比较研究，2019（3）:60-61，64. 4.吴丽莹，余义兵.池州旅游文化外宣英译现状及对策研究[J].池州学院学报，2019(2):92-95. 5.吴丽莹. 学生学习需求下的大学英语课堂实践模式研究[J].黄山学院学报,2016(6):132-136. 6.吴丽莹.基于实践视角的英语交际能力提升策略——池州学院学生国际赛事志愿服务的现状反思[J].池州学院学报,2016(4)：138-140. 7.吴丽莹. 汉英语言中的语义模糊策略及效用分析[J].牡丹江教育学院学报，2016(6)：24-26,124. 8.吴丽莹.旅游外宣翻译视角下池州国际形象建设路径研究[C].安徽（池州）地域文化论坛，2018.11.18. 9.吴丽莹,余义兵.池州旅游文化外宣英译现状及对策研究[J].池州学院学报,2019,33(02):92-95. 10.吴丽莹,汪亚楠.国标背景下池州公示语英译现状及对策探析[J].文化创新比较研究,2019,3(32):60-61+64. 著作教材 获奖情况 1. 安徽省第三届教师教学创新大赛三等奖，2023年5月； 2. 第二届教师教学创新大赛二等奖（校级），池州学院，2021年12月； 3. “杏花村杯”第三届安徽省徽文化外宣翻译大赛一等奖，2021年11月； 4. 首届全国高等学校外语课程思政教学比赛二等奖，2020年12月； 5. 第11届“外教社杯”全国高校外语教学大赛安徽赛区本科跨文化组三等奖，2020年12月； 6. “教坛新秀”（校级），池州学院，2020年11月； 7. “英语专业口译课程课内实践应用”教学成果奖，二等奖（校级），池州学院，2018年1月； 8. 优秀教学质量奖，校级，池州学院，2017年4月； 9. 青年教师教学技能大赛，一等奖（校级），池州学院，2016年5月。 社会兼职', '0', '0', '0', '2026-06-05 17:37:33', '2026-06-05 17:37:33', NULL, '硕士', NULL, NULL, NULL, '硕士研究生 ；学士 ；大学外国语学院 英语语言文学硕士 ', NULL, NULL);
