INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('637', '张霞', '外国语学院', '讲师', NULL, '', '基本情况 姓 名 张霞 性 别 女 职 称 讲师 所属系 商务英语 最高学历 本科 Email 52502771@qq.com 详细情况 学科专业 英语 研究方向 英语语言文学 讲授课程 商务英语阅读、大学英语 教育经历 2000.09-2004.06 安徽师范大学外国语学院 2008.09-2009.06 南京师范大学外国语学院 工作经历 200 4 .09--至今 池州学院教师 科研项目 学术论文 试从《小癞子》中浅析流浪汉小说的文学特色《安徽文学》 我国生态批评理论发展综述《池州学院学报》 著作教材 获奖情况 2007年度考核优秀 2007教师课堂教学技能比赛二等奖 2004-2005 两学年度教学质量优秀奖 2015-2016 校级优秀试卷奖 2016指导学生荣获外研社杯阅读大赛安徽赛区二等奖和三等奖 2017指导学生荣获外研社杯阅读大赛安徽赛区三等奖 2020-2022 两学年度教学质量优秀奖 社会兼职', '0', '0', '0', '2026-06-05 17:37:33', '2026-06-05 17:37:33', NULL, NULL, NULL, NULL, NULL, '本科 ；大学英语 教育经历 ；大学外国语学院 ', NULL, NULL);
