INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('641', '黄颖', '外国语学院', '助教', NULL, '', '基本情况 姓 名 黄颖 性 别 女 职 称 助教 所属系 大学外语教学部 最高学历 硕士研究生 Email christinavew @ qq .com 详细情况 学科专业 外国语言文学 研究方向 语用学 讲授课程 《大学英语》《英语跨文化交际》《应用文写作》 教育经历 2017.09-2021.06 安徽工业大学 本科 2021.09-2024.06 河南科技大学 硕士 工作经历 2024.08- 池州学院外国语学院 专任教师 科研项目 池 州学院 2025 年校级 科研项目： 政务新媒体语用身份的调适与城市政社关系共构；在研 学术论文 1. 政务新媒体语用身份的调适与政社关系共构——基于“美丽重庆”政务微信的个案研究.外语学刊，2026(3): 48-55.（CSSCI） 2. 国际网络互动中身份构建的人际语用研究——以Quora为例.外语电化教学，2024(4): 85-90+113.（CSSCI） 3. 基于批评性话语分析框架的网络语言暴力研究[J]. 常州工学院学报（社科版），2023(3): 122-127. 著作教材 获奖情况 1. 洛阳市第十九次社会科学优秀成果一等奖 2. 2025 年外研社 “ 教学之星 ” 大赛全国复赛一等奖 3. 池州学院第三届课程思政教学比赛二等奖 4. 第六届全国高校教师教学创新大赛优秀奖 5. 2026 年全国大学生英语竞赛 C 类三等奖 指导教师 6. 2025 年全国大学生英语竞赛 C 类三等奖 指导教师 7. 第三届 BETT 杯全国大学生英语写作大赛全国二等奖 优秀指导老师 社会兼职', '0', '0', '0', '2026-06-05 17:37:33', '2026-06-05 17:37:33', NULL, '硕士研究生', NULL, NULL, NULL, '大学外语教学部 最高学历 硕士研究生 ；大学英语；大学 本科 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('642', '何姗姗', '外国语学院', '副教授', NULL, '', '基本情况 姓名 何姗姗 性别 女 职称 副教授 所属教研室 大学英语教研室 最高学历 研究生 Email 3066837045@qq.com 详细情况 所在学科专业 语言文学 研究方向 英语教育，地方文化外译 讲授课程 大学英语，跨文化交际英语，英诗欣赏 教育经历 2012.09-2015.06 安徽师范大学外国语学院 硕士 工作经历 2015.07- 至今 池州学院外国语学院 科研项目 1.主持安徽省人文重点项目《中国文化‘走出去’视域下安徽地域文化译介策略研究》（2024AH052878），在研； 2.主持安徽省人文重点项目《东至周氏家风家训探析——以域内传承和域外传播为视角》（SK2019A0716），已结题； 3.主持安徽省高校优秀青年人才支持计划项目《翻译适应选择论视域下的外宣英译研究--以池州齐山景区为例》（gxyq2020191），已结题。 学术论文 1.《拉拉的褐色披肩》中移民自我奋斗的迷思.盐城工学院学报(社会科学版),2024； 2.从《负暄闲语》看周馥对孔子礼学思想的继承和发展.兰州工业学院学报,2024； 3.生态翻译学视角下的地方文化外宣英译探究——以池州齐山景区为例.铜陵学院学报,2022； 4.东至周氏家风文化“走出去”传播研究.池州学院学报,2022； 5.多元智能理论在大学英语教学中的应用.池州学院学报,2018。 著作教材 无 获奖情况 1.2024年池州学院教书育人楷模； 2.2022年安徽省教坛新秀； 3.2021年池州学院教坛新秀； 4.2023年6月获得2020-2022两学年度优秀教学质量奖； 5.2019年4月获得2016-2018两学年度优秀教学质量奖； 6.2020年、2022年、2023 年参加外研社“教学之星”大赛，获得全国复赛二等奖； 7. 2022年参加第12 届“外教社杯”全国高校外语教学大赛，获得大学英语课程思政组二等奖； 8.2020年参加全国高校教师教学创新大赛-第六届外语微课大赛，获得三等奖； 9.2019 年参加第十届“外教社杯”全国高校外语教学大赛（大学英语组）获得三等奖。 社会兼职 无', '0', '0', '0', '2026-06-05 17:37:33', '2026-06-05 17:37:33', NULL, '硕士', NULL, NULL, NULL, '大学英语教研室 最高学历 研究生 ；大学英语，跨文化交际英语，英诗欣赏 教育经历 ；大学外国语学院 硕士 工作经历 ', NULL, NULL);
