INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('667', '郝惠惠', '外国语学院', '讲师', NULL, '', '基本情况 姓名 郝惠惠 性别 女 职称 讲师 所属教研室 小语种教研室 最高学历 本科 Email 526845242@qq.com 详细情况 所在学科专业 日本语语言与文学 研究方向 日本语语言与文化比较，日语教育 讲授课程 第二外国语（日语）；大学日语 教育经历 1998 年 9 月 --2002 年 7 月 湖北大学日语系 2011 年 7 月 --2014 年 7 月 厦门大学日语系 工作经历 2002 年 7 月 -- 至今 池州学院外国语学院 科研项目 校级课题：夏目漱石对鲁迅文学思想的影响 课题： XK0812 池州学院 2008 年 4 月 学术论文 1. 郝惠惠 . 浅议中国文化对日本文化及社会发展的影响 ,[J], 池州学院学报 ,2008 年 2 郝惠惠 . 浅谈夏目漱石对鲁迅文学思想的影响 ,[J] 考试周刊 ,2011 年第 60 期 3. 郝惠惠 . 论日语中“外来语”与日本语言的文化特点 [J] , 北京印刷学院学报， 2018,26 （ 4 ） :136-138. 4. 郝惠惠 . 中日茶文化比较及中国茶文化传播 [J]. 湖南科技学院学报， 2019,40 （ 2 ） :33-34. 5. 郝惠惠 . 论汉语日源外来词及其文化背景 [J], 科学与技术 ,2022 年 27 著作教材 无 获奖情况 1 ） 2006-2007 、 2007-2008 两学年度优秀教学质量奖； 2 ） 2010-2011 、 2011-2012 两学年度优秀教学质量奖； 3 ） 2012 年池州学院青年教师技能比赛 三等奖； 4 ） 2012 — 2013 ， 2013 — 2014 两学年度优秀教学质量奖 社会兼职 无', '0', '0', '0', '2026-06-05 17:37:33', '2026-06-05 17:37:33', NULL, NULL, NULL, NULL, NULL, '本科 ；大学日语 教育经历 ；大学日语系 ', NULL, NULL);
