INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('670', '孙佐', '机电工程学院', '半导体学院', '电气工程方面的科研和教学工作', '', '孙佐，男，工学硕士，教授，安徽省教学名师，安徽工业大学兼职硕士生导师。1988年6月毕业于淮南矿业学院（现为安徽理工大学）工业电气自动化专业；2015年2月-2008年3月在东南大学电气工程学院攻读在职研究生，获工学硕士学位；2010年9月至2011年7月在中国科学技术大学信息科学技术学院做访问学者。曾任池州学院机电工程学院（半导体学院）院长，安徽省半导体产业共性技术研究中心主任， 池州学院新能源与节能技术研究中心主任，池州市半导体行业协会副理事长，中国仪器仪表学会嵌入式仪表及系统技术分会理事。 主要从事电气工程方面的科研和教学工作。在国内核心学术刊物和国际学术会议上发表学术论文20余篇，其中被EI收录3篇，论文《一种高性价比并联混合有源电力滤波器》获第六届自然科学优秀学术论文三等奖。主持厅级及以上科研项目3项，参与厅级及以上项目10余项，主持及参与企业横向项目多项。主编教材2部，主持省级教学改革项目3项，获省级教学成果一、二、三等奖各1项。获得国家发明专利4项，实用新型专利6项。指导学生获学科与技能竞赛奖12项，其中国家一等奖1项，省级一等4项。 一、主要研究方向 （1）微机测控技术； （2）电力系统谐波抑制和无功补偿； （3）新能源发电等。 二、主要研究课题 1.主持人，2007.01-2009.12，安徽高校省级自然科学研究一般项目“新型电能质量监测与混合有源电力滤波技术应用基础理论研究”(编号:KJ2007B081)； 2.主持人，2010.01-2012.12，安徽高校省级自然科学研究重点项目“新能源发电并网运行关键技术研究”(编号: KJ2010A245)； 3.主持人，2006.11-2007.11，池州市科技研究项目“池州市电力系统电能质量存在问题分析及对策研究” (编号: 06002)； 4.主持人，2012.11-2014.12，安徽省质量工程重点教学研究项目“协同创新视角下的地方应用型高校实践教学体系改革与实践” (编号:2012jyxm562)； 5.主持人，2014.1-2015.12 ，安 徽省质量工程项目“电气工程及其自动化专业综合改革试点”（编号:2014zy077）； 6.主持人，2018.1-2019.12，安徽省质量工程项目“电子信息与电气虚拟仿真实验教学中心”（编号:2017sxzx42）； 7.负责人，2023.1-2024.12，安徽省现代产业学院“池州学院半导体现代产业学院”（编号:2022cyts029）。 三、主要论文 1.Novel Multiple-Loop Composite Control Strategy for Active Power Filter，EI收录，2010年6月； 2.新型双DSP结构混合有源电力滤波器控制系统，《计算机工程与应用》，2010年第15期； 3.有源电力滤波器全数字控制器，《电子技术应用》，2010年第1期； 4.并联混合有源电力滤波器拓扑比较研究，《电力电子技术》，2008年第1期； 5.一种高性价比并联混合有源电力滤波器，《中国电机工程学报》， 07年第36期（EI收录）； 6.双DSP结构电网谐波监测及保护一体化装置研究，《电子测量与仪器学报》，2007年第5期； 7.基于DSP和μC/OS-II多功能电力参数智能检测仪设计，《中国仪器仪表》，2006年第12期； 8.基于8XC196单片机的EPA和PTS实现伺服电机控制，组合机床与自动化加工技术，2005； 9.基于PTS A/D的综合参数检测装置的设计，仪表技术，2004； 10.高精度A/D转换器AD7730及其应用，仪表技术，2003； 11.Advances on Distributed Generation Technology， Elsevier，2012（ISTP 收录）； 12.转型背景下应用型高校提升教师 教学能力的途径及机制研究—以池州学院为例,大学教育，2016。', '0', '0', '0', '2026-06-05 17:40:03', '2026-06-05 17:40:03', NULL, '硕士', NULL, '计算机工程与应用、电子技术应用、电力电子技术、中国仪器仪表', NULL, '硕士，教授，安徽省教学名师，安徽工业大学兼职硕士生导师。；大学；大学电气工程学院攻读在职研究生，获工学硕士学位；', NULL, NULL);
