INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('674', '桂传友', '机电工程学院', '教师', NULL, '', '副教授。工学硕士。主讲课程：大学物理、大学物理实验、光电子技术实验、流体力学、大学生科学素养。校级教学成果', '0', '0', '0', '2026-06-05 17:40:03', '2026-06-05 17:40:03', NULL, '硕士', NULL, '大学物理、大学物理实验、光电子技术实验、流体力学、大学生科学素养', NULL, '授。工学硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('675', '苗纯', '机电工程学院', '教师', NULL, '', '副教授。硕士。主讲课程：光电检测技术、光学、数学物理方法、专业实验、大学物理、大学物理实验。主持教育厅高校人才重点项目1项', '0', '0', '0', '2026-06-05 17:40:03', '2026-06-05 17:40:03', NULL, '硕士', NULL, '光电检测技术、光学、数学物理方法、专业实验、大学物理、大学物理实验', NULL, '副教授。硕士', NULL, NULL);
