INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('677', '韩春宝', '机电工程学院', '半导体学院', '电机原理、自动控制原理、微机控制技术、电机与电器控制等电气工程方面的教学与科研工作', '', '韩春宝，男，安徽池州市人，副教授，现任池州学院国资处资产科科长。主要从事电机原理、自动控制原理、微机控制技术、电机与电器控制等电气工程方面的教学与科研工作；主要研究方向为微机控制及电机控制技术领域。', '0', '0', '0', '2026-06-05 17:40:03', '2026-06-05 17:40:03', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('678', '江海锋', '机电工程学院', '半导体学院', '透明导电氧化物材料的制备及物性研究、目前也从事第一性原理的计算研究', '', '个人基本信息： 江海锋，男，1981年生，副教授，博士，微电子科学与工程教研室教师。本科毕业于安徽师范大学物理学院，先后在广西大学和中科院固体所获得硕士和博士学位。 主要从事透明导电氧化物材料的制备及物性研究，目前也从事第一性原理的计算研究。主持安徽省自然科学基金青年项目、教育厅自然科学研究一般项目以及池州学院引进研究生科研启动项目各一项，并参加国家自然基金青年项目和省科技厅年度重点项目各一项。 所属系： 集成电路工程系 主讲课程： 《大学物理》、《电磁场与电磁波》、《固体物理》、《半导体物理》、《半导体器件》 研究领域： 透明导电氧化物材料的制备及物性研究、第一性原理的计算研究。 教科研项目： 1. 安徽省自然科学基金委员会，青年项目，1308085QA18，铜铁矿结构透明导电材料的实验与计算研究，2013-06至2015-06，5万元，结题，主持； 2. 安徽省教育厅，一般项目，KJ2013B172，p型铜基透明半导体的制备及物性研究，2013-01至2014-12，0.8万元，结题，主持； 3. 安徽省科技厅，科技攻关项目，11070203010，新型透明氧化物半导体异质结的制备与光伏效应研究，2012-01至2012-12，结题，参与； 4. 国家自然科学基金委，青年项目，10904151，新型层状Bi-Co-O基氧化物材料的制备与热电性能研究，2010-01至2012-12，结题，参与； 5. 集成电路设计与嵌入式应用研究中心（OP18100148） 项目负责人：徐华结， 参加； 6. 先进材料制备与成型技术工程研究中心（OP18100139） 项目负责人：潘培道， 参加； 7. 湍流预混燃烧化学热力学建表方法的降维研究（RD17100010） 项目负责人：唐鹏， 参加。 代表性论文/著作： 1. “Effects of citric acid on properties of single phase CuAlO2 thin films derived by chemical solution deposition” Journal of Alloys and Compounds 2009(487):404-408. (First author) 2. “Effect of Cr doping on the optical-electrical property of CuAlO2 thin films derived by chemical solution deposition” Thin Solid Films 2011(519):2559-2563. (First author) 3. “Effect of Mg substitution on the structural, optical and electrical properties of CuAlO2 thin films” Journal of Alloys and Compounds 2011(509):1768-1773. (First author) 4. “Comparative study of the structural, optical and electrical properties of CuAlO2 thin films on Al2O3 and YSZ substrates via chemical solution deposition” Journal of Sol-Gel Science and Technology 2011(58):12-17. (First author) 5. “Electric properties of bivalent cations (Be, Mg and Ca) substitution for Al in delafossite CuAlO2 semiconductor by first principles calculations” Journal of Alloys and Compounds 2013(553):245-252. (First author) 6. “First-principle study on O-A-O dumbbell of delafossite crystal” Journal of Alloys and Compounds 2014(582):64-68. (First author) 7. “Vacancies effect on structural, electronic and mechanical properties of delafossite CuAlO2” Physica B: Physics of Condensed ', '0', '0', '0', '2026-06-05 17:40:03', '2026-06-05 17:40:03', NULL, '广西大学和中科院固体所（硕士）', NULL, '《大学物理》、《电磁场与电磁波》、《固体物理》、《半导体物理》、《半导体器件》 研究领域： 透明导电氧化物材料的制备及物性研究、第一性原理的计算研究。 教科研项目： ', NULL, '博士，微电子科学与工程教研室教师。本科毕业于安徽师范大学物理学院，先后在广西大学和中科院固体所获得硕士和博士学位。 主要从事透明导电氧化物材料的制备及物性研究，目前也从事第一性原理的计算研究。主持安徽省自；大学物理', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('679', '吴荣华', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 吴荣华，男，1992年10月生，中共党员，讲师，工学博士，安徽枞阳人，现任池州学院机电工程学院专任教师。 联系方式： wrh187@126.com 所属系： 电气工程系 主讲课程： 《模拟电子技术》、《电路与分析》、《数字电子技术》 研究领域： 非线性电路系统分析与控制、忆阻非线性电路 教科研项目： [1] 国家自然科学基金项目，分数阶脉冲神经网络的类脑可塑性与混沌核边缘演变研究(No: 62466024)，2025.01-2028.12，30万元，在研，参与。 [2] 安徽省教育厅青年项目，电解高频开关电源中的逆变器非线性分析与控制策略研究(No: 2025AHGXZK40592)，2026.01-2027.12，10万元，在研，主持。 [3] 池州学院高层次人才科研启动基金项目，光伏逆变器的复杂动力学特性分析与混沌控制策略研究(No: CZ2025YJRC115)，2026.01-2029.01，20万元，在研，主持。 [4] 企业委托横向技术开发项目，智能机器人移动底盘避障算法优化(No: 2025HX0302)，2025.12-2027.12，5万元，在研，主持。 [5] 江西理工大学校级研究生专项项目，电解电镀高频开关电源的逆变器分数阶建模、动力学行为分析及控制研究(No: XY2023-B014)，2023.12-2024.12，0.5万元，结题，主持。 [6] 安徽文达信息工程学院校级重点项目，逆变器系统中的非线性现象分析及控制研究(No: XZR2021A08)，2021.06-2022.06，1万元，结题，主持。 代表性论文/著作： 1. Ronghua Wu ( 吴荣华 ) , Xiaohong, Zhang, Wei Jiang, Shaojiang Zhong. Bifurcation analysis and chaos control in a fourth-order DC-AC H-bridge inverter[J]. Nonlinear Dyn., 2025, 113:9005-9031. 2. Ronghua Wu ( 吴荣华 ) , Xiaohong, Zhang, Wei Jiang, Shaojiang Zhong. Bifurcation analysis and control in a second-order DC–AC inverter with quasi-PIR controller[J]. Commun. Nonlinear Sci. Numer. Simul., 2025, 145: 1-23. 3. Ronghua Wu ( 吴荣华 ) , Xiaohong, Zhang, Wei Jiang. Bifurcation analysis and control in a DC–AC inverter with PID controller[J]. Int. J. Circuit Theory Appl., 2025, 53(4): 2125-2153. 4. Ronghua Wu ( 吴荣华 ) , Xiaohong, Zhang, Wei Jiang. Bifurcation Analysis and Chaos Control of Carrier Phase-Shifted Cascaded H-bridge Inverter [J]. Int. J. Bifurcation Chaos, 2024, 34(08):1-17. 5. 吴荣华 , 张小红 , 江伟 . 幂次指数趋近律滑模控制逆变器的分岔与混沌 [J]. 控制理论与应用 , 2025, 42(2): 311-322. 6. 江伟 , 吴荣华 * （通信作者） , 袁芳 . 改进指数趋近律滑模控制的 H 桥逆变器的非线性动力学行为研究 [J]. 振动与冲击 , 2021, 40(9): 292-297. 7. 吴荣华 , 江伟 . 谷值电流控制的 H 桥逆变器的非线性现象 [J]. 安徽大学学报 ( 自然科学版 ), 2019, 43(02): 65-71. 8. 吴荣华 , 江伟 . SPWM-H 桥逆变器的非线性动力学行为研究 [J]. 内蒙古大学学报 ( 自然科学版 ), 2018, 49(06): 657-666. 国家发明专利： 1. 吴荣华 , 张小红 , 龙克柳 . 一种适用于 H 桥逆变器的分岔与混沌控制方法 [P]. 国家发明专利 . 申请日 :2023.07.29, 申请号 : 202310942004.0. 2. 吴荣华 , 董丽凤 , 张小红 . 一种适用于载波移相级联逆变器的分岔与混沌控制方法 [P]. 国家发明专利 . 申请日 : 2023.12.04,', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, NULL, NULL, '《模拟电子技术》、《电路与分析》、《数字电子技术》 研究领域： 非线性电路系统分析与控制、忆阻非线性电路 教科研项目： ', NULL, '博士，安徽枞阳人，现任池州学院机电工程学院专任教师。 联系方式： ；大学校级研究生专项项目，电解电镀高频开关电源的逆变器分数阶建模、动力学行为分析及控制研究；大学学报 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('680', '刘传洋', '机电工程学院', '半导体学院', '主要从事功率电子变换技术、新能源并网发电技术、机器视觉与深度学习领域的科研工作', '', '个人基本信息： 刘传洋，男，副教授，安徽工业大学兼职硕导。 所属系： 电气工程系 主讲课程： 《电路分析》、《电机学》、《电气控制与PLC》、《电力电子技术》、《DSP原理及应用》 研究领域： 主要从事功率电子变换技术、新能源并网发电技术、机器视觉与深度学习领域的科研工作。近年来以第一作者发表SCI/EI收录论文6篇，CSCD论文1篇。授权发明专利20余项。 教科研项目： 主持省级自然科学研究项目3项，参与安徽省重大科技专项项目一项；主持50万元横向课题2项。 代表性论文/专利： 1. Liu C, Wu Y, Liu J, et al. Thermal Defect Detection of Electrical Components in Transmission Lines Based on Infrared Images and Deep Learning[J]. IEEJ Transactions on Electrical and Electronic Engineering,2025. 2. 刘传洋，吴一全 . 基于深度学习的输电线路视觉检测方法研究进展 [J]. 中国电机工程学报 ,2023,43(19):7423-7446.DOI:10.13334/j.0258-8013.pcsee.221139. （ EI ）。该论文获《中国电机工程学报》 2024 年度 “ 高影响力论文 ” 奖。 3. 刘传洋，吴一全 . 基于红外图像的电力设备识别及发热故障诊断方法研究进展 [J]. 中国电机工程学报 , 2025, 45(06): 2171-2196. DOI:10.13334/j.0258-8013.pcsee.232167. （ EI ） 4. 刘传洋，吴一全，刘景景 . 基于视觉的输电线路金具锈蚀缺陷检测方法研究进展 [J]. 仪器仪表学报 ,2024,45(03):286-305.DOI:10.19650/j.cnki.cjsi.J2312071. （ EI ） 5. 刘传洋，吴一全，刘景景 . 无人机航拍图像中电力线检测方法研究进展 [J]. 中国图象图形学报 ,2023,28(10):3025-3048. （ CSCD ） 6. 刘传洋，吴一全，刘景景 . 无人机航拍图像中绝缘子缺陷检测的深度学习方法研究进展 [J]. 电工技术学报 , 2025, 40(09): 2897-2916. DOI:10.19595/j.cnki.1000-6753.tces.240610. （ EI ） 7. 刘传洋，吴一全，刘景景 . 螺栓 / 铆钉故障的视觉检测方法研究进展 [J]. 仪器仪表学报 ,2025,46(03):143-160.DOI:10.19650/j.cnki.cjsi.J2413553. （ EI ） 第一发明人授权发明专利 [1] 一种直流电源，专利号： ZL201510822282.8. 8. 一种混合控制的 LLC 谐振变换器，专利号： ZL201510818591.8. 9. 一种超声波检测装置，专利号： ZL201711263593.0. 10. 一种单相光伏并网发电系统，专利号： ZL201910405832.4. 11. 一种用于污水处理的智能控制系统，专利号： ZL202010382287.4. 12. 一种用于 BUCK 变换器的缓冲电路，专利号： ZL201810112268.2. 13. 一种自动加球机联锁控制电路，专利号： ZL201910718027.7.', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, NULL, NULL, '《电路分析》、《电机学》、《电气控制与PLC》、《电力电子技术》、《DSP原理及应用》 研究领域： 主要从事功率电子变换技术、新能源并网发电技术、机器视觉与深度学习领域的科研工作。近年来以第一作者发表SCI', NULL, '大学兼职硕导。 所属系： 电气工程系 主讲课程： ', NULL, NULL);
