INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('683', '钱叶册', '机电工程学院', '半导体学院', NULL, '', '钱叶册，男，硕士，副教授。主要承担《电力电子技术》、《供电技术》、《电力系统分析》、《电工电子技术》等课程的教学；主持省级质量工程项目1项，校级质量工程教研项目2项；指导国家级大学生创新创业训练项目4项；参与省级教学成果奖两项；主持安徽省教育厅科研自然重点项目1项，发表科研论文5篇，授权发明专利3项，实用新型专利4项。 一、主要研究方向 （1）电力电子技术； （2）电能质量治理； （3）太阳能发电技术等。 二、主要研究课题 1.主持人，安徽教育厅自然科学研究重点项目 高密度分布式电源接入主动配电网控制策略的研究 (编号：KJ2019A0860)。 2.主持人，安徽省质量工程项目 线上课程（原MOOC）《电工电子技术》(编号：2022xskc075)。 三、主要论文 1.Buck变换器的改进电流控制模式研究，《宿州学院学报》，2017年10月； 2.扬声器系统的多点均衡研究，《绥化学院学报》，2017年6月； 3.Buck变换器的控制及补偿网络设计，《浙江水利水电学院学报》，2017年3月。 4.双DSP控制的有源电力滤波器的研究，《自动化与仪器仪表》，2017年1月； 5.有源电力滤波器的一种新型复合控制方法的研究，《池州学院学报》，2015年12月； 四、国家发明专利 1.一种服务器机柜老化监控系统，专利号：（ZL201911329115.4），2022年5月； 2.一种服务器机柜的安装主架及其安装方法，专利号：（ZL201911329189.8），2021年1月； 3.一种太阳能热水器保温箱端盖滚压成型装置，专利号：（ZL201510035539.5），2018年4月。', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '硕士', NULL, '电力电子技术、供电技术、电力系统分析、电工电子技术、自动化与仪器仪表', NULL, '硕士，副教授。主要承担；大学生创新创业训练项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('684', '程慧', '机电工程学院', '半导体学院', NULL, '', NULL, '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, NULL, NULL, NULL, NULL, '硕士研究生，讲师。 上一篇： 韩春宝 下一篇： 刘传洋 版权所有: ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('685', '潘永强', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 男，中共党员，1992年生，安徽芜湖人，本硕博毕业于东南大学，2019-2020年期间于东京大学物性研究所联合培养。 所属系： 机电工程学院光电系 主讲课程： 大学物理 研究领域： 应用物理，凝聚态物理，超导物理（包括铜基超导粉体/靶材研制和应用化、铁基超导单晶制备和机理研究、镍基超导薄膜机理研究） 教科研项目： 1. 强磁场下 CaFe 1-x Co x AsF单晶的伊辛超导电性研究，YZJJ2023QN34，2023-01 至 2024-12 ，中科院院长基金青年项目，10万元，主持，结题。 2. 铁硒基超导体临界场对称性机理研究，CZ2025YJRC112，2025-11 至 2028-10， 池州学院人才引进科研启动基金，20万元，主持，在研。 3. 钇系超导靶材技术研制，2025HX0182，2025-11 至 2026-04，企业横向，14万元，主持，结题。 4. 强磁场下CaFe 1-x Co x AsF单晶的B c2 畸变行为研究，2025AHGXZK30382，2026-01 至 2027-12，安徽省教育厅，20万元，主持，在研。 代表性论文/著作： 1. Yongqiang Pan ; Nan Zhou; Bencheng Lin; Jinhua Wang; Zengwei Zhu; Wei Zhou; Yue Sun; Zhixiang Shi; Anisotropic critical current density and flux pinning mechanism of Fe 1+y Te 0.6 Se 0.4 single crystals, Superconductor Science and Technology , 2021, 35(1): 015002(2022). ( 第一作者 , 中科院一区 ,IF = 3.482). 2. Yongqiang Pan ; Wei Zhou; Jiajia Feng; Xiaolei Yi; Chunqiang Xu; Minghao Wang; Nan Zhou; Zhixiang Shi; Vortex phase diagram in 1111-type CaFe 0.89 Co 0.11 AsF single crystal, Superconductor Science and Technology , 35(2): 025007(2022). ( 第一作者 , 中科院一区 ,IF = 3.482). 3. Xiaofei Huang; Yue Sun; Yongqiang Pan ; Zhixiang Shi; Magnetization loops and nonscaling behavior of flux pinning force of Fe 1+y Te 1-x Se x studied by numerical simulation, Superconductor Science and Technology , 35: 105003(2022). ( 共同通讯作者 , 中科院一区 ,IF = 3.482). 4. Yongqiang Pan ; Nan Zhou; Wei Zhou; Tianyang Wang; Qiang Hou; Run Lv; Ming Cheng; Ruihuan Lan; Yifan Deng; Yu Zhao; Lanxin Liu; Wenhai Song; Yue Sun; Zhixiang Shi; Wenjian Lu; Xuan Luo; Yuping Sun. Abnormal Electronic Transport Properties with Hall Effect, Magneto-resistivity, and Phase Diagram in CaFeAsF Single Crystal, Journal of Materials Chemistry C , 13(7), 3362-3371 (2025).( 第一作者 , 中科院二区 ,IF = 6). 5. Yongqiang Pan ; Yue Sun; Nan Zhou; Xiaolei Yi; Qiang Hou; Jinhua Wang; Zenwei Zhu; Hiroyuki Mitamura; Masashi Tokunaga; Zhixiang Shi; Novel anisotropy of upper critical fields in Fe 1+y Te 0.6 Se 0.4 , Journal of Alloys and Compounds , 976: 173282(', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '东南大学', NULL, '大学物理 研究领域： 应用物理，凝聚态物理，超导物理', NULL, '大学，；大学物性研究所联合培养。 所属系： 机电工程学院光电系 主讲课程： 大学物理 研究领域： 应用物理，凝聚态物理，超导物理', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('686', '方勇', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 方勇 ，男，汉族，1986年9月出生，安徽人。北京科技大学材料科学与工程专业本科、硕士，东南大学光学工程专业博士。现任讲师。 联系方式：Yong.F.cz@outlook.com 所属系： 光电信息科学与工程 主讲课程： 《光电专业英语》《传感器实验》《光学实验》《大学物理》《大学物理实验》 研究领域： 光电探测器，纳米材料，宽禁带半导体 教科研项目： 无 代表性论文/著作： 1. Fang Y., Zhao Z., Weng Z., Zhu M., Lei W., Zhu Z., et al. "Variation in the optical properties of carbon dots fabricated by a green and facile strategy for solar-blind UV detection." The Journal of Physical Chemistry C. 2022. Vol. 126, no. 12. P. 5711-5721. 2. Fang Y., Zhao Z., Zhu M., Weng Z., Fang C., Jia X. "High-Responsivity Solar-Blind Ultraviolet Photodetectors Based on Carbon Nanodots/Graphene Hybrids." IEEE Transactions on Electron Devices, 2021, 68, 1101–1105. 3. Chen T., Fang Y., Zhu M., Zhao Z., Lei W., Zhu Z., Jiang H. "Solar-blind ultraviolet-visible dual-spectral photodetector based on carbon nanodots/flexible-silicon heterojunction." Sensors and Actuators, A: Physical. 2024. Vol. 365. P. 114820. 4. Fang Y., Zhao Z., Zhu M., Weng Z., Fang C., Jia X. Carbon Dots/Graphene Hybrids for UV Photodetectors. 3rd International Conference on Circuits, System and Simulation (ICCSS), Nanjing, China, pp. 37–40.', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '硕士', NULL, '《光电专业英语》《传感器实验》《光学实验》《大学物理》《大学物理实验》 研究领域： 光电探测器，纳米材料，宽禁带半导体 教科研项目： 无 代表性论文', NULL, '大学材料科学与工程专业本科、硕士，东南大学光学工程专业博士。现任讲师。 联系方式：；大学物理；大学物理实验', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('687', '吴亮', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 吴亮，男，1999年生，安徽宿松人。2020年毕业于中国科学技术大学天文学专业，获理学学士学位；2025年毕业于中国科学技术大学天体物理专业，获理学博士学位（硕博连读）。现任池州学院机电工程学院讲师。 所属系： 光电信息工程系 主讲课程： 大学物理B1、大学物理B2 研究领域： 主要从事活动星系核（AGN）与类星体的观测统计研究，重点关注尘埃环（dusty torus）的物理性质及其与周围结构的关系，具体包括：尘埃环与宽线区、窄线区及极向尘埃的几何关系；类星体光变行为与吸积盘湍流机制；类星体寄主星系恒星形成与超大质量黑洞吸积过程的协同演化。 教科研项目： 无 代表性论文/著作： 1. Liang Wu , Jun-Xian Wang, Luis C. Ho, Junfeng Wang, Zhicheng He. Tracing Star Formation in Quasar Hosts via [O II] λ3727: A Kinematically Consistent Approach. The Astrophysical Journal Letters, 2025. （ Nature Index 期刊 ，中科院 1 区，影响因子 11.7 ） 2. Liang Wu , Jun-Xian Wang, Wen-Ke Ren, Wen-Yong Kang. Is Quasar Variability Regulated by the Close Environment of Accretion? Monthly Notices of the Royal Astronomical Society, 2024, 533(1): 908–917. （中科院 2 区，影响因子 4.8 ） 3. Liang Wu , Jun-Xian Wang, Hao-Chen Wang, Wen-Yong Kang, Wei-Da Hu, Ting-Gui Wang, Hui-Yuan Wang. Ensemble Mapping the Inner Structure of Luminous Quasars. Monthly Notices of the Royal Astronomical Society, 2023, 522(1): 1108–1117. （中科院 2 区，影响因子 4.8 ） 4. Wei Liu, Liang Wu , Francisco Villaescusa-Navarro, Marco Baldi, Georgios Valogiannis, Wenjuan Fang. Probing Massive Neutrinos and Modified Gravity with Redshift-Space Morphologies and Anisotropies of Large-Scale Structure. Journal of Cosmology and Astroparticle Physics, 2025, JCAP04(2025)088. （中科院 2 区，影响因子 5.9 ）', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '中国科学技术大学', NULL, '大学物理B', NULL, '大学天文学专业，获理学学士学位；；大学天体物理专业，获理学博士学位；大学物理', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('688', '陶伟', '机电工程学院', '半导体学院', '超快光谱学、 教科研项目： 池州学院高层次人才科研启动基金项目、主持', '', '个人基本信息： 男，中共党员，安徽枞阳人，2025年博士毕业于北京师范大学；获理学博士学位。现为机电工程学院光电信息工程系专任教师。 所属系： 光电信息科学与工程 主讲课程： 《光电子技术》、《电磁场与电磁波》 研究领域： 超快光谱学， 教科研项目： 池州学院高层次人才科研启动基金项目，主持。 代表性论文/著作： 1. TAO W, Zhao Z, Kang J, et al. Solvent polarity-driven modulation of excited states: A DFT and spectroscopic analysis[J]. Journal of Photochemistry and Photobiology A: Chemistry, 2024: 115992.（一作） 2. Xue X, Du W, TAO W , et al. Giant Photon-Drag-Induced Ultrafast Photocurrent in Diamond for Nonlinear Photonics[J]. Laser & Photonics Reviews, 2024: 2301146-2301156. （共同一作） 3. ZHU J, WANG J, WANG G, ZHANG J, TAO W , LIU C, LIU M, ZHANG H, XIE R, YE F. Precise Identification of the Dimethyl Sulfoxide Triggered Tricarbonyldichlororuthenium (II) Dimer for Releasing CO [J]. The Journal of Physical Chemistry Letters, 2021, 12(19): 4658-65. 4. WANG K, XIE Y, LIU M, TAO W , ZHANG H, HUANG M, YOU J, LIU Y, LI Y, LI Z. High‐Contrast Polymorphic Luminogen Formed through Effect of Tiny Differences in Intermolecular Interactions on the Intramolecular Charge Transfer Process [J]. Advanced Optical Materials, 2020, 8(16): 2000436. 5. GAO S, ZHANG S, WANG C, YAN S, HAN X, JI X, TAO W , LIU J, WANG T, YUAN S. Discovery of a single-band Mott insulator in a van der Waals flat-band compound [J]. Physical Review X, 2023, 13(4): 041049.', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '北京师范大学', NULL, '《光电子技术》、《电磁场与电磁波》 研究领域： 超快光谱学， 教科研项目： 池州学院高层次人才科研启动基金项目，主持。 代表性论文', NULL, '博士毕业于北京师范大学；获理学博士学位。现为机电工程学院光电信息工程系专任教师。 所属系： 光电信息科学与工程 主讲课程： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('689', '汪新建', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 男，博士研究生，毕业于中国科学技术大学近代物理系（粒子物理与原子核物理），曾供职于华为 2012 实验室；现任职池州学院机电工程学院，专任讲师。 所属系： 光电信息科学与工程 主讲课程： 《量子力学》《大学物理》《大学物理实验》 研究领域： 重离子碰撞物理，粒子探测技术 教科研项目： （1）国家自然科学基金委员会, 面上项目, 利用表面电阻提高MRPC计数率的方法研究, 2020-01 至 2023-12, 65万元, 参与 （2）核探测与核电子学国家重点实验室, 自主课题, 高计数率环境下的高精度MRPC性能研究, 2022-04 至 2022-12, 22万元, 参与 （3）安徽省教育厅科学研究项目，重点项目，面向半导体精密量测的高性能交叉阳极MCP探测器研究，2026-01 至 2027-12，20万元，主持 （4）企业委托项目，高性能多阳极MCP探测器系统研究，2025-12 至 2026-12，40万元，主持 （5）企业委托项目，高能量分辨率X射线探测系统研制，2025-12 至 2026-12，40万元，主持 （6）企业委托项目，微通道板中子探测器读出系统及瞬态信号记录仪软件研制，2026-04 至 2027-03，77万元，主持 代表性论文/著作： 1. Wang X, Wang X, Ren Y, et al. Low-dose CT reconstruction by self-supervised learning in the projection domain[J]. Applied Radiation and Isotopes, 2026: 112675. 第一作者 2. Shuaike Lv; Changsheng Dai; Dongdong Hu; Tiancheng Zhong; Weifeng Wu; Xinjian Wang;Simulation of a time and spatial sensitive plastic scintillator detector, Nuclear Engineering and Technology, 2025, 58(1738-5733) 通讯作者 3. D. Hu; X. Wang; M. Shao; Y. Zhou; S. Ye; S. Lv; Y.D. Zhao; L. Zhao; H. Xu; Design and performance testing of a T0 detector for the CSR External-target Experiment, Nuclear Instruments and Methods in Physics Research Section A: Accelerators, Spectrometers, Detectors and Associated Equipment, 2023, 1057(168773) 共同第一作者 4. K. Wang; J. Zhou; X. Wang; X. Li; D. Hu; Y. Sun; Batch testing and noise rate optimization of MRPC3b for CBM-TOF/STAR-eTOF, Nuclear Instruments and Methods in Physics Research Section A: Accelerators, Spectrometers, Detectors and Associated Equipment, 2023,1057(168778) 共同第一作者 5. X. Wang; D. Hu; M. Shao; L. Zhao; Y. Sun; J. Lu; H. Xu; Y. Zhou; CEE inner TOF prototype design and preliminary test results, Journal of Instrumentation, 2022, 17(09): P09023 第一作者 6.Wang X, Wang K, Hu D, et al. A new MRPC prototype with diamond-like-carbon coated glass electrodes[J]. Journal of Instrumentation, 2021, 16(03): C03001., 第一作者', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '博士研究生', NULL, '《量子力学》《大学物理》《大学物理实验》 研究领域： 重离子碰撞物理，粒子探测技术 教科研项目： ', NULL, '博士研究生，毕业于中国科学技术大学近代物理系；大学物理；大学物理实验', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('690', '蔡华兵', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 蔡华兵，男，讲师，1992年出生，2019年毕业于南京大学物理学专业，博士学位。 所属系： 机电工程学院，光电信息工程系 主讲课程： 大学物理，大学物理实验 研究领域： 量子光学，相对论量子信息 教科研项目： 安徽省科技厅, 安徽省自然科学基金青年项目, 2008085QA25, 紧致闵可夫斯基时空中有关经典场与量子场的一些物理系统的性质研究, 2020-07至 2022-06, 10万元, 结题, 主持。 代表性论文/著作： 1. Huabing Cai , Ye-Jun Xu, Li-Gang Wang, Resonance interaction between two two-level entangled atoms moving through a dielectric medium, Advanced Quantum Technologies 9, e00628 (2026). 2. Huabing Cai, Li-Gang Wang, Blackbody-radiation-induced energy level shifts for a uniformly moving atom in a dielectric medium, Physical Review A 110, 063726 (2024). 3. Huabing Cai, Li-Gang Wang, Modification of stimulated transition processes of a uniformly moving atom by the presence of a dielectric medium in blackbody radiation, Physical Review A 108, 043715 (2023). 4. Huabing Cai, Li-Gang Wang, Motion-induced energy shifts of a multilevel atom in a black-body radiation field, European Physical Journal C 82, 37 (2022). 5. Huabing Cai, Velocity effect on the stimulated transition process of a multilevel atom in a thermal bath, European Physical Journal C 81, 673 (2021). 6. Hongsong Sun, Kaituo Zhang, Huabing Cai* , Inquiring the Unruh-DeWitt detector about the global property of spacetime, Classical and Quantum Gravity 38, 065017 (2021). 7. Huabing Cai, Zhongzhou Ren, Radiative properties of an inertial multilevel atom in a compactified Minkowski spacetime, Classical and Quantum Gravity 36, 165001 (2019). 8. Huabing Cai , Zhen Li, Zhongzhou Ren, Resonance interaction between uniformly rotating two-level entangled atoms, European Physical Journal Plus 133, 458 (2018). 9. Huabing Cai , Zhongzhou Ren, Resonance interaction between two two-level entangled atoms in cosmic string spacetime, Classical and Quantum Gravity 35, 235014 (2018). 10. Huabing Cai , Zhongzhou Ren, Transition processes of a static multilevel atom in the cosmic string spacetime with a conducting plane boundary, Scientific Reports 8, 11802 (2018). 11. Huabing Cai , Zhi Wang, Zhongzhou Ren, Radia', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '博士', NULL, '大学物理，大学物理实验 研究领域： 量子光学，相对论量子信息 教科研项目： 安徽省科技厅, 安徽省自然科学基金青年项目, ', NULL, '大学物理学专业，博士学位。 所属系： 机电工程学院，光电信息工程系 主讲课程： 大学物理，大学物理实验 研究领域： 量子光学，相对论量子信息 教科研项目： 安徽省科技厅, 安徽省自然科学基金青年项目, ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('691', '时安琪', '机电工程学院', '半导体学院', '低维材料的多尺度模拟与设计', '', '个人基本信息： 时安琪，女，中共党员，博士研究生。 所属系： 光电信息工程 主讲课程： 《大学物理》 研究领域： 低维材料的多尺度模拟与设计。 代表性论文/著作： 1. Direct Z-Scheme Photocatalytic System: Insights into the Formative Factors of Photogenerated Carriers Transfer Channel from Ultrafast Dynamics. ACS Catal . 2022, 12, 9570. （第一作者） 2. Sandwich-Polarized Heterojunction: Efficient Charge Separation and Redox Capability Protection for Photocatalytic Overall Water Splitting, ACS Appl. Mater. Interfaces 2022, 14, 32018. （第一作者） 3. Metal-Free Carbon Nitride Nanosheet Supported the Pentacoordinated Silicon Intermediates for Photocatalytic Overall Water Splitting, J. Phys. Chem. Lett . 2023, 14, 1918-1927. （第一作者） 4. The interlayer twist effectively regulates interlayer excitons in InSe/Sb van der Waals heterostructure, npj Computational Materials 10, Article number:190 (2024). （第一作者）', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '博士研究生', NULL, '《大学物理》 研究领域： 低维材料的多尺度模拟与设计。 代表性论文', NULL, '博士研究生。 所属系： 光电信息工程 主讲课程： ；大学物理', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('692', '陈钟', '机电工程学院', '半导体学院', '光-热-电-磁多场耦合功能材料的设计制备、微观机理、性能调控及微纳功能器件开发与应用', '', '个人基本信息： 陈钟，男，中共党员，理学博士，长期从事光-热-电-磁功能材料与器件领域的基础理论与应用研究，以第一作者或通讯作者在《Journal of Alloys and Compounds》《ACS Applied Energy Materials》《Physica B: Condensed Matter》等国内外学术期刊发表SCI收录论文10余篇。 邮箱：zchen@czu.edu.cn 所属系： 光电信息科学与工程 主讲课程： 《大学物理》《光电功能材料》 研究领域： 光-热-电-磁多场耦合功能材料的设计制备、微观机理、性能调控及微纳功能器件开发与应用。 教科研项目： 1. 新型镁基热电材料的可控制备及磁调控输运性质机理研究，安徽省教育厅重点项目（2025AHGXZK30133），2026.01-2027.12，20万，主持； 2. Bi 2 Te 3 基复合热电材料制备及输运性质调控研究 ，池州学院高层次人才科研启动基金项目（CZ2024YJRC25），2024.10-2027.09，20万，主持； 3. 消防机器人热电制冷系统集成关键技术研究，横向项目（2025HX0224），2025.12-2027.11，50万，主持； 4. 大学物理校级智慧课程，池州学院教学质量工程项目（2025XZHKC07），2026.01-2027.12，2万，主持； 代表性论文/著作： 1. Zhong Chen * , Wenming Deng, Xiaolei Yi, Wei Zhou, Chunqiang Xu, Wenke Bao, Qinqing Zhu, Large magnetoresistance and de Haas-van Alphen oscillation in La 3 Al 11 , J. Alloy. Compd. , 2026, 1055, 186444. 2. Zhong Chen , Mingxiang Xu, Anisotropic magnetoresistance and quantum oscillation in Sb 2 Te 3 single crystal synthesized by a Te-flux method, J. Alloy. Compd. , 2023, 947, 169671. 3. Wenhao Xie, Xianke Wu, Zhong Chen * , Chang Li, Wei Cao, Ziyu Wang, Enhancement of thermoelectric properties of p-Type Bi 0.4 Sb 1.6 Te 3 incorporated by BaFe 12 O 19 magnetic nanoparticles, ACS Appl. Energy Mater. , 2023, 6, 12013-12021. 4. Zhong Chen , Mingxiang Xu, Shukang Deng, Enhanced electrical transport properties of PbTe single crystal through Ga substitution synthesized by a Pb-flux method, J. Alloy. Compd. , 2022, 920, 165953. 5. Zhong Chen , Xin Ding, Mingxiang Xu, Low thermal conductivity and magneto-suppressed thermal transport in a highly oriented FeSb 2 single crystal, ACS Omega, 2021, 6(35), 22681-22687. 6. Zhong Chen , Yu Tang, Decong Li, Jianhong Liu, Lanxian Shen, Wenting Liu, Luqi Sun, Shukang Deng, Enhancement of electrical performance via carrier modulation in single crystalline PbTe prepared by Pb-flux method, J. Alloy. Compd. , 2019, 774: 282-289. 7. Zhong Chen , Yu Tang, Decong Li, Jianhong Liu, Wenting Liu, Luqi Sun, Wen Ge, Lanxian Shen, Shukang Deng, Enhanced elect', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, NULL, NULL, '《大学物理》《光电功能材料》 研究领域： 光', NULL, '博士，长期从事光；大学物理；大学物理校级智慧课程，池州学院教学质量工程项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('693', '员相焱', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 员相焱，男，中共党员，博士，籍贯山东省聊城市。2025年博士毕业于深圳大学光学工程专业，获工学博士学位，现为机电工程学院光电信息工程系专任教师。主要研究领域为稀土发光材料与金属卤化物发光材料的合成设计及其性能调控。以第一或通讯作者发表SCI收录论文26篇。 所属系： 光电信息工程系 主讲课程： 《光电检测显示技术》、《大学物理》 研究领域： (1) 稀土发光材料的设计合成、机理与应用探索 (2) 低维金属卤化物发光晶体的特性研究 教科研项目： 池州学院高层次人才科研启动基金项目，CZ2025YJRC53，主持。 代表性论文/著作： 近年发表的部分科研论文 1. Xiangyan Yun * , Xueping Zang, Haizhe Zhong, Denghui Xu*. A Sm 3+ -activated BaLaLiTeO 6 double perovskite phosphor for multimode optical thermometry, Optics and Laser Technology , 2026, 200, 115203. 2. Xiangyan Yun , Zexiang Liu, Baoxia Liu, Renping Cao, Jingheng Nie*. Anomalous dual self-trapped excitons emission induced by Sb 3+ doping in high-symmetry two-dimensional cesium cadmium chloride via local polarity, Journal of Colloid a nd Interface Science , 2026, 711, 140079. 3. Xiangyan Yun * , Haizhe Zhong, Xueping Zang, Mingjun Chen, Qingqing Cheng, Wei Tao, Heng Li, Zaifa Yang*. A dual-mode optical thermometric strategy based on a Dy 3+ -activated tellurate double perovskite phosphor, Journal of Photochemistry & Photobiology, A: Chemistry , 2026, 475, 117057. 4. Xiangyan Yun , Zexiang Liu, Denghui Xu*, Yumeng Shi*. Intrinsic Low-Symmetry-Assisted Growth and Efficient Luminescence in Zero-Dimensional Hybrid Chloride Single Crystals, Advanced Optical Materials , 2026, 14, e03404. 5. Xiangyan Yun , Xueping Zang, Haizhe Zhong, Mingjun Chen, Qingqing Cheng, Wei Tao, Heng Li, Zaifa Yang*. Multifunctional Eu 3+ -activated phosphors with single-band ratiometric thermometry and hidden anti-counterfeiting functions, Journal of Alloys and Compounds , 2026, 1051, 186013. 6. Xiangyan Yun , Hailin Zhou, Yanrong Zhu, Zexiang Liu*. Integration of temperature sensing and optical anti-counterfeiting in Bi 3+ /Sb 3+ co-doped in-based hybrid halides via STE engineering, Ceramics International , 2026, 52, 1157–1164. 7. Xiangyan Yun , Zexiang Liu, Jingheng Nie, Yanrong Zhu, Haizhe Zhong, Yumeng Shi*. Exciton relaxation modulation and lattice distortion in Rb 4 CdCl 6 :Sn 2+ /Bi 3+ toward tunable w', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '深圳大学光学工程（博士）', NULL, '《光电检测显示技术》、《大学物理》 研究领域： ', NULL, '博士，籍贯山东省聊城市。；博士毕业于深圳大学光学工程专业，获工学博士学位，现为机电工程学院光电信息工程系专任教师。主要研究领域为稀土发光材料与金属卤化物发光材料的合成设计及其性能调控。以第一或通讯作者发表；大学物理', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('694', '张云芳', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 张云芳，1992年生，安徽宿州人。2017年本科毕业于东北石油大学，电子科学与技术专业。2020年硕士毕业于深圳大学，光学工程专业。2025年博士毕业于深圳大学，光学工程专业。2025年7月入职池州学院机电工程学院讲师职位。 所属系： 光电信息科学与工程 主讲课程： l 信息光学 l 大学物理 研究领域： 飞秒激光直写光波导、光纤传感、表面增强拉曼传感器 教科研项目： 池州学院高层次人才科研启动基金项目，主持 代表性论文/著作： 1. Yunfang Zhang , Chupao Lin, Changrui Liao*, Kaiming Yang, Zhengyong Li, and Yiping Wang，Femtosecond laser-inscribed fiber interface Mach-Zehnder interferometer fortemperature-insensitive refractive index measurement，Optics Letters, 43(18),4421-4424, 2018. 2. Yunfang Zhang , Changrui Liao*, Chupao Lin, Yu Shao, Ying Wang, and Yiping Wang, Surface plasmon resonance refractive index sensor based on fiber-interfacewaveguide inscribed by femtosecond laser ， Optics Letters, 44(10), 2434-2437, 2019. 3. Yunfang Zhang , Yubin Deng, Han Liu, Longbiao Huang, Xin Ding, Zhiyong Bai, Changrui Liao, Yiping Wang, and Ying Wang*, Femtosecond laser fabrication of nanopillar arrays for Surface-Enhanced Raman scattering substrates, Optics and Laser Technology 181,111659, 2024. 4. Yunfang Zhang , Dejun Liu,*, Han Liu, Yubin Deng, Zhiyong Bai, Changrui Liao, Yiping Wang and Ying Wang, High Sensitivity SERS Substrate with Femtosecond Laser-Printed Nanohole Arrays, Sensors , 25 (12), 3680, 2025. 5. 林初跑， 张云芳 ，廖常锐，王义平，一种混合型光纤耦合器，中国实用新型专利，深圳大学， ZL201721435238.2 ，申请日： 2017.10.31 ，授权日： 2018.05.25 6. 廖常锐，王义平， 张云芳 ，林初跑，具有表面波导的单模光纤， SPR 生物传感器，中国发明专利，深圳大学，申请日： 2018.10.30 ，公开日： 2019.01.11 7. 廖常锐，王义平，林初跑， 张云芳 ，一种混合型光纤耦合器及其制备方法，中国发明专利，深圳大学，申请日： 2017.10.31 ，公开日： 2018.01.19', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '东北石油大学', NULL, 'l 信息光学 l 大学物理 研究领域： 飞秒激光直写光波导、光纤传感、表面增强拉曼传感器 教科研项目： 池州学院高层次人才科研启动基金项目，主持 代表性论文', NULL, '本科毕业于东北石油大学，电子科学与技术专业。；硕士毕业于深圳大学，光学工程专业。；博士毕业于深圳大学，光学工程专业。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('695', '王佳节', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 王佳节，男，1993年8月生，安徽南陵人。2015年获南京理工大学微电子学专业工学学士学位，2018年获南京理工大学光学工程专业工学硕士学位，2025年获南京理工大学光学工程专业工学博士学位。2025年6月入职池州学院，现为机电工程学院光电信息工程专业教师。 所属系： 光电信息工程系 主讲课程： 大学物理；光学设计 研究领域： 机器视觉与图像处理 教科研项目： 深海载人装备全国重点实验室开放基金课题， 面向深海无人潜水器对接任务的低照度强散射水下光电成像探测方法研究，2025-2027，参与 国家自然科学基金青年项目C类（62001234），主动偏振成像下基于视觉差异优化和表面特征反演的目标识别方法，2021-2023，参与。 代表性论文/著作： 1. Wang J , Wan M, Xu Y, et al. Underwater image restoration via constrained color compensation and background light color space-based haze-line model[J]. IEEE Transactions on Geoscience and Remote Sensing, 2024, 62: 1-15. 2. Wang J , Wan M, Cao X, et al. Active non-uniform illumination-based underwater polarization imaging method for objects with complex polarization properties[J]. Optics Express, 2022, 30(26): 46926-46943. 3. Wang J , Wan M, Gu G, et al. Periodic integration-based polarization differential imaging for underwater image restoration[J]. Optics and Lasers in Engineering, 2022, 149: 106785. 4. Wang J , Gu G, Wan M, et al. Dual-correlation transformation for image stitching[J]. Journal of Electronic Imaging, 2018, 27(3): 033040-033040. 5. 顾国华 , 王佳节 , 陈钱 , 等 . 二维旋转平台下的相机参数标定 [J]. 光学精密工程 , 2017, 25(7): 1890-1899.', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, NULL, NULL, '大学物理；光学设计 研究领域： 机器视觉与图像处理 教科研项目： 深海载人装备全国重点实验室开放基金课题， 面向深海无人潜水器对接任务的低照度强散射水下光电成像探测方法研究，', NULL, '大学微电子学专业工学学士学位，；大学光学工程专业工学硕士学位，；大学光学工程专业工学博士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('696', '杨程', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 杨程，男，1993年3月出生，汉族，安徽铜陵人，博士研究生学历。现为池州学院机电工程学院教师。 所属系： 光电信息工程系 主讲课程： 《大学物理》、《电磁场与电磁波》 研究领域： 光解自由基反应 教科研项目： 无 代表性论文/著作： 1. Cheng Yang, Kai Yi, Meirou Zhu, Jiangxue Yang, Yaxiong Wei*, Yongjia Shang, and Xinsheng Xu*. Photosensitive Damage of Dipeptides: Mechanism and Influence of Structure. Phys. Chem. Chem. Phys., 2023, 25, 4923-4928. 2. Cheng Yang, Jiangxue Yang, Xianling Gong, Yaxiong Wei*, and Xinsheng Xu*. Investigation on the Photoinduced Chemical Reaction between p-Benzoquinone and Tryptophan in Homogeneous Solution. Phys. Chem. Chem. Phys., 2022, 24, 14947-14952. 3. Cheng Yang, Meirou Zhu, Xianling Gong, Aiying Gao, and Xinsheng Xu*. H-atom Transfer Reaction of Photoinduced Excited Triplet Duroquinone with Tryptophan and Tyrosine in Acetonitrile-Water and Ethylene Glycol-water HomogeneousSolutions. Chin. J. Chem. Phys., 2021, 34, 256-262.', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '博士研究生', NULL, '《大学物理》、《电磁场与电磁波》 研究领域： 光解自由基反应 教科研项目： 无 代表性论文', NULL, '博士研究生学历。现为池州学院机电工程学院教师。 所属系： 光电信息工程系 主讲课程： ；大学物理', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('697', '程情青', '机电工程学院', '半导体学院', '纳米光学、手性光学、等离激元光电催化 教科研项目： 无 代表性论文/著作： 1. Qingqing Cheng', '', '个人基本信息： 程情青，女，中共党员，博士，2025年毕业于武汉大学，获理学博士学位。现为机电工程学院讲师。 所属系： 光电信息科学与工程 主讲课程： 《专业英语》《大学物理》 研究领域： 纳米光学、手性光学、等离激元光电催化 教科研项目： 无 代表性论文/著作： 1. Qingqing Cheng ； Jian Yang ； Lichao Sun* ； Chuang Liu ； Guizeng Yang ； Yunlong Tao ； Xuehao Sun ； Binbin Zhang ； Hongxing Xu ； Qingfeng Zhang* Tuning the Plexcitonic Optical Chirality using Discrete Structurally Chiral Plasmonic Nanoparticles ， Nano Lett. ， 2023 ， 23 ， 11376-11384. 2. Binbin Zhang; Qingqing Cheng; Jinyu DingJ; ian Yang; Yunlong Tao; Xuehao Sun; Xinhui Wang; Longxin Liu; Zixuan Yang; Sujing Zhang; Guizeng Yang; Lichao Sun*Qingfeng Zhang* Stimuli-Responsive Tunable Circular Dichroism Using Intrinsically Chiral Plasmon-Polyaniline Hybrid Nanostructures. Nano Lett. 2026, 26, 1, 448–457. 3. Guizeng Yang ； Yunlong Tao ； Qingqing Cheng ； Chuang Liu ； Binbin Zhang ； Xuehao Sun ； Yahui Yang ； Dandan Lu ； Jian Yang ； Lin-Long Deng ； Lichao Sun* ； Hongxing Xu ； Su-Yuan Xie ； Qingfeng Zhang* Shell Dependence of Highly Tunable Circular Dichroism in Chiral Hybrid Plasmonic Nanomaterials for Chiroptical Applications ACS Nano ， 2025 ， 19 ， 2961-2074. 4. Chuang Liu1, Yunlong Tao, Xuehao Sun, Zixu Wang, Guizeng Yang, Qingqing Cheng , Binbin Zhang, Jinling Wan, Lichao Sun, Qingfeng Zhang, Tuning the geometry, composition, and optical chirality of chiral Au nanorods for asymmetric nanocatalysis. 5. Chuang Liu, Lichao Sun, Guizeng Yang, Qingqing Cheng , Chen Wang, Yunlong Tao, Xuehao Sun, Zixu Wang, Qingfeng Zhang Chiral Au–Pd Alloy Nanorods with Tunable Optical Chirality and Catalytically Active Surfaces. Small, 2024, 20 (23): 2310353. 6. Guizeng Yang, Lichao Sun, Yunlong Tao, Qingqing Cheng , Xuehao Sun, Chuang Liu, Qingfeng Zhang Chiral AuCu Heterostructures with Site-Specific Geometric Control and Tailored Plasmonic Chirality ， Sci. China Chem. ， 2023 ， 66 ， 3280-3289.', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '武汉大学', NULL, '《专业英语》《大学物理》 研究领域： 纳米光学、手性光学、等离激元光电催化 教科研项目： 无 代表性论文', NULL, '博士，；大学，获理学博士学位。现为机电工程学院讲师。 所属系： 光电信息科学与工程 主讲课程： ；大学物理', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('698', '陈铭鋆', '机电工程学院', '半导体学院', '发光材料、光电子器件 教科研项目： 1.池州学院高层次人才科研启动基金项目、CZ2025YJRC107、主持', '', '个人基本信息： 陈铭鋆，男，1992年3月出生于湖北省蕲春县。2016年本科毕业于湖北工程学院光源与照明专业，获工学学士学位；2024年博士毕业于河北大学光学工程专业，获工学博士学位。现为机电工程学院专任教师，讲师。 所属系： 光电信息工程系 主讲课程： 《激光技术及应用》、《光电子器件与工艺》 研究领域： 发光材料、光电子器件 教科研项目： 1.池州学院高层次人才科研启动基金项目，CZ2025YJRC107，主持。 2.高效近红外激发发射碳点的构筑及其光热诊疗一体化的研究 ， 国家自然科学基金面上项目，参与。 3.基于光谱调控、基质重构方式硅基氮化物白色荧光粉的实现及机理研究，国家自然科学基金青年科学基金项目，参与。 代表性论文/著作： 1. Mingjun Chen , Li Guan, Haotian Ma, You Zhang, Yufeng Chang, Fenghe Wang, Zhenyang Liu, and Xu Li. Spectral Regulation of Carbon Dots and the Realization of Single Component Solar-Simulated White Light-Emitting Diodes. ACS Photonics , 2023, 10, 2730 - 2738. 2. Mingjun Chen , Guoyi Dong, Xue Li, Zichen Gao, Hao Feng, Fenghe Wang, Li Guan, Xu Li. Influence of MoS 2 quantum dots size on the properties of memristor devices. Optik-International Journal for Light and Electron Optics , 2020, 207, 163776. 3. Hanqing Gu*, Mingjun Chen* , Zhibao Wang, Wenming Zhang, Zhanyu Li. Enhancing H + intercalation kinetics and stability in Cu 2+ pre-intercalated d-MnO 2 for aqueous aluminum batteries. Journal of Energy Chemistry , 2024, 102, 126 - 133. 4. Kai Du*, Jiaqi Guo*, Chenxi Song*, Xin Liu*, Mingjun Chen* , Dachao Yuan, Runping Ye, Xingyuan San, Yaguang Li, Jinhua Ye. Persistent photothermal CO 2 methanation without external energy input. Energy & Environmental Science , 2024. 5. Ziyang Cui, Jianmin Song, Mingjun Chen , Weiyue Wang, Wenming Zhang, Qiancheng Zhu. Non-completely selenized Cu-OSe nanowires as potassium-philic host for anode-free potassium metal batteries. Energy Storage Materials , 2024. 71, 103649. 6. Chen Zhang, Mingjun Chen , Xiaohui Zhao, Wenming Zhang, Zhanyu Li. High-performance MnSe 2 -MnSe heterojunction hollow sphere for aluminum ion battery. Journal of Colloid and Interface Science , 2023, 652, 1438 - 1446. 7. Yong Lu, Mingjun Chen , Yi Wang, Yunhai Hu, Xiaoxu Wang, Wenming Zhang, and Zhanyu Li. Interaction Mechanism between Cyano-Organic Molecular Structures and Energy Storage of Aluminum Complex Ions in Aluminum Batteries. Small Me', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '河北大学光学工程（博士）', NULL, '《激光技术及应用》、《光电子器件与工艺》 研究领域： 发光材料、光电子器件 教科研项目： ', NULL, '本科毕业于湖北工程学院光源与照明专业，获工学学士学位；；博士毕业于河北大学光学工程专业，获工学博士学位。现为机电工程学院专任教师，讲师。 所属系： 光电信息工程系 主讲课程： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('699', '王子', '机电工程学院', '半导体学院', '1. 光纤激光器 2. 光纤传感系统融合与量测 3. 光通讯架构设计 教科研项目： 1. 池州学院高层次人才科研启动基金项目、CZ2025YJRC116、主持', '', '个人基本信息： 王子，男，1995年生于江苏省徐州市睢宁县。2019年毕业于虎尾科技大学电子工程系，获工学学士学位。2025年毕业于台湾科技大学电子工程系，获工学博士学位。现任机电工程学院讲师。 所属系： 光电信息科学与工程 主讲课程： 光纤通信原理，信息光学等 研究领域： 1. 光纤激光器 2. 光纤传感系统融合与量测 3. 光通讯架构设计 教科研项目： 1. 池州学院高层次人才科研启动基金项目，CZ2025YJRC116，主持。 2. 池州学院校级重点自然科学研究项目，CZ2025ZRZ02，主持。 3. 企业委托横向技术开发项目，2025HX0268，主持。 代表性论文/著作： 1. Z. Wang , S. Afifah, S.-K. Liaw*, C.-H. Yeh, and J.-K. Chen, "Stable Sub-KHz Linewidth Fiber Laser using Saturable Absorber Integrated Four-Subring Resonators," IEEE Photonics Technology Letters , vol. 36, no. 2, pp. 63-66, 15 Jan.15, 2024. 2. Z. Wang , J.-K. Wei, P.-C. Chen, S.-K. Liaw*, J.-K. Chen and C.-H. Yeh,"Eight-Wavelength Selectable Single-Longitudinal- Mode Fiber Laser Using 1× 8 Arrayed Waveguide Grating and Passive Triple Subring Resonators," IEEE Photonics Journal , vol. 16, no. 5, pp. 1-7, Oct. 2024. 3. Z. Wang , Y.-E. Zou, C.-Y. Guo, S.-K. Liaw*, Y.-M. Yang, B.-H. Lee, and C.-H. Yeh, "Integration of BOTDA and φ-OTDR Distributed Fiber Sensing for Multiple Parameters Monitoring," Physica Scripta , Article vol. 100, no. 4, p. 13, Apr 2025. 4. Z. Wang , B. Pamukti, F.-C. Meng, S.-K. Liaw, C.-H. Yeh and J.-K. Chen, "Single-Longitudinal Mode Ytterbium-Doped Fiber Laser Using Four 2 × 2 Fiber Couplers for Multiple Subring Ring Cavities," IEEE Journal of Quantum Electronics , vol. 61, no. 2, pp. 1-6, Apr 2025. 5. Z. Wang , Y.-H. Tsai, S.-K. Liaw*, J.-K. Chen, Y.-W. Wang and C.-H. Yeh "Passively Mode-Locked Yb-Doped Fiber Laser Seeded MOPA System for High-Power Pulse Amplification," Fiber and Integrated Optics , vol. 45, no. 2, p.105-117, Feb 2026. 6. B. Pamukti, Z. Wang , M. Fajar, S.-K. Liaw*, C.-H. Yeh and F.-L. Yang. "Deep Learning and Time Series Signal Processing for Bending Detection in Mining Environment Using Optical Fiber Sensor," Optical Fiber Technology , vol. 88, pp.103819, May, 2024. 7. L. Marlina, Z. Wang , M. Fajar, S.-K. Liaw*, and A. Hatta, "Performance Investigation of Underwater Wireless Optical Communication Systems Using RGB lasers with Differen', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '虎尾科技大学', NULL, '光纤通信原理，信息光学等 研究领域： ', NULL, '大学电子工程系，获工学学士学位。；大学电子工程系，获工学博士学位。现任机电工程学院讲师。 所属系： 光电信息科学与工程 主讲课程： 光纤通信原理，信息光学等 研究领域： ', NULL, NULL);
