INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('707', '刘志成', '机电工程学院', '半导体学院', NULL, '', NULL, '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '', NULL, '《机械专业英语》、《船体结构》、《船舶概论》 研究领域： 航空航天、船舶、高速列车等领域内关键金属材料与焊接结构的疲劳失效机理分析、基于物理', NULL, '博士，池州学院机电工程学院讲师。；大学机械工程专业，；大学机械与运载工程学院，担任特种装备教育部先进设计与仿真重点实验室、核装备可靠性湖南省重点实验室专任实验师；', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('708', '杨鑫', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 杨鑫，男，汉族，工学博士，池州学院机电工程学院，讲师。 所属系： 机械工程系 主讲课程： 《机械制图》 研究领域： 纺织机械设计开发与纺织结构可视化 教科研项目： 无 代表性论文/著作： 1. Yang X, Bi S, Shao H, et al. Rotary Three-Dimensional Braider Design Method Based on the Average Cutting Circle Strategy [J]. Engineering, 2025. 2. Yang X, Lu C, Bi S, et al. Fiber-level automatic modeling strategy of 3D rotary braided preform based on motion information [J]. COMPOSITE STRUCTURES, 2025, 354. 3. Yang X, Lu C, Shao H, et al. High-resolution fiber-level simulation of knitted patterns [J]. Computer-Aided Design, 2025, 188: 103913. 4. Yang X, Zhang C, Shao H, et al. Design optimization of a three-dimensional hexagonal braiding technique [J]. Textile research journal, 2024, 95(7-8): 688-704. 5. 杨鑫 , 邵慧奇 , 蒋金华 , et al. 六角形编织物的微观结构模拟 [J]. 纺织学报 , 2021, 42(4): 85-92. 6. 杨鑫 , 邵慧奇 , 蒋金华 , et al. Tsuzuki 旋转式立体编织机编织件的结构模拟与设计 [J]. 东华大学学报 ( 自然科学版 ), 2021, 47(6): 51-7. 专利： 1. 陈南梁 , 杨鑫 , 邵慧奇 , 等 . 基于四切口拨盘设计的旋转式三维编织机 [P]. 上海市 :CN202210643282.1,2023-03-10. 2. 陈南梁 , 杨鑫 , 蒋金华 , 等 . 旋转型三维编织机编织底盘的设计方法 [P]. 上海市 :CN202210643294.4,2023-04-25. 3. 杨鑫 , 邵慧奇 , 蒋金华 , 等 . 基于三切口拨盘设计的旋转式三维编织机 [P]. 上海市 :CN202210643296.3,2023-08-01. 软件著作权： 1. 旋转型三维编织机控制软件 .V1.0.', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, NULL, NULL, '《机械制图》 研究领域： 纺织机械设计开发与纺织结构可视化 教科研项目： 无 代表性论文', NULL, '博士，池州学院机电工程学院，讲师。 所属系： 机械工程系 主讲课程： ；大学学报 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('709', '张东', '机电工程学院', '半导体学院', '多孔介质流体动力学、传质传热学 教科研项目： 纤维纱线液氨闪爆晶变改性关键装备技术研究 代表性论文/著作： 1. 张东', '', '个人基本信息： 张东，男，1989年出生，安徽舒城籍，毕业于东华大学机械工程学院机械工程系，博士研究生。 所属系： 机械设计制造及其自动化 主讲课程： 机械设计、机械制造工艺学、先进制造技术 研究领域： 多孔介质流体动力学、传质传热学 教科研项目： 纤维纱线液氨闪爆晶变改性关键装备技术研究 代表性论文/著作： 1. 张东 ; 孟婥 ; 纱筒残余氨的扩散过程建模与数值模拟 , 纺织学报 , 2017.9 月 , 38(9): 156 162. 2. Dong Zhang; Zhuo Meng; Yize Sun ; Mass Transport of Liquid Ammonia in Fiber Modification Process, Heat Transfer Research, 2019, 50(18): 1749-1766. 3. Zhuo Meng; Dong Zhang; Yize Sun ; Model of Non-equilibrium Drying Hollow Cylindrical Porous Media, Heat Transfer Research, 2019, 51(8): 723-739.', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '博士', NULL, '机械设计、机械制造工艺学、先进制造技术 研究领域： 多孔介质流体动力学、传质传热学 教科研项目： 纤维纱线液氨闪爆晶变改性关键装备技术研究 代表性论文', NULL, '大学机械工程学院机械工程系，博士研究生。 所属系： 机械设计制造及其自动化 主讲课程： 机械设计、机械制造工艺学、先进制造技术 研究领域： 多孔介质流体动力学、传质传热学 教科研项目： 纤维纱线液氨闪爆晶', NULL, NULL);
