INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('711', '舒俊成', '机电工程学院', '半导体学院', '结构动力学与振动控制 教科研项目： 池州学院高层次人才科研启动基金项目、主持', '', '个人基本信息： 舒俊成，男，1991年生，工学博士，现任机电工程学院机械工程系专任教师。邮箱：shujcheng@163.com 所属系： 机械工程系 主讲课程： 理论力学 研究领域： 结构动力学与振动控制 教科研项目： 池州学院高层次人才科研启动基金项目，主持。 代表性论文/著作： 1. Juncheng Shu, Erming He, Yongzhi Li, et al. The vibration reduction index allocation method for aircraft vibration comfort design[J]. Mechanics of Advanced Materials and Structures, 2024, 31(27): 9611-9624. 2. Juncheng Shu, Erming He, Yongzhi Li, et al. The quasi-zero stiffness seat vibration isolator design to improve cockpit vibration comfort[J]. Journal of Vibration Engineering & Technology. 2024, 12(4):5999-6014. 3. 舒俊成 , 贺尔铭 , 易金翔 , 等 . 发动机振动载荷向客舱座椅传递特性研究 [J]. 西北工业大学学报 ,2020, 38(6): 1163-1170. 4. 舒俊成 , 贺尔铭 . 振动传递路径频域分析方法研究进展 [J]. 机械科学与技术 , 2020, 39(11): 1647-1655.', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, NULL, NULL, '理论力学 研究领域： 结构动力学与振动控制 教科研项目： 池州学院高层次人才科研启动基金项目，主持。 代表性论文', NULL, '博士，现任机电工程学院机械工程系专任教师。邮箱：；大学学报 ,', NULL, NULL);
