INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('719', '鞠薇', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 2019年12月博士毕业于合肥工业大学计算机与信息学院，方向信号与信息处理，现为池州学院机电工程学院讲师。 所属系： 电子信息工程系 主讲课程： 数字电子技术，python程序设计，物联网导论，大学生科学素养 研究领域： 光谱信号处理，无人机遥感信号处理 教科研项目： （1）安徽省教育厅自然科学项目重大项目——基于轻量级Transformer-增强DANN的无人机高光谱小麦赤霉病早期识别方法研究，批准号：2025AHGXZK20128，主持，20万元； （2）安徽省教育厅自然科学项目重点项目——开放光路大气污染气体红外光谱在线快速定性识别方法研究，批准号：KJ2021A0026，主持，6万元； （3）智能互联系统安徽省实验室开放课题——基于深度学习的睡眠呼吸暂停综合征检测方法研究，批准号：PA2021AKSK0112，主持，3万元； 代表性论文/著作： 1. Feature Pyramid Serial Attention Network for Underwater Image Enhancement[J], Applied Optics, 2026, 65(8):2721-2737 2. Supervised Alignment Perception and Modality Difference Selection Enhanced SAR-Optical Fusion for Cloud Removal[J], IEEE Transactions On Geoscience and Remote Sensing, 2025, 63(4706015) 3. 集成学习结合波长选取的有机物红外光谱定量回归方法研究 [J], 光谱学与光谱分析 [J], 2023, 43(1): 239-247 4. Rapid Identification of Atmospheric Gaseous Pollutants Using Fourier-Transform Infrared Spectroscopy Combined with Independent Component Analysis[J], Journal Of Spectroscopy, 2020: 8920732. 5. 基于 SimAM － ConvNeXt － FL 的茶叶病害小样本分类方法研究 [J]. 农业机械学报 , 2024, 55(3):275-281', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '合肥工业大学', NULL, '数字电子技术，python程序设计，物联网导论，大学生科学素养 研究领域： 光谱信号处理，无人机遥感信号处理 教科研项目： ', NULL, '博士毕业于合肥工业大学计算机与信息学院，方向信号与信息处理，现为池州学院机电工程学院讲师。 所属系： 电子信息工程系 主讲课程： 数字电子技术，；大学生科学素养 研究领域： 光谱信号处理，无人机遥感信号处理 教科研项目： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('720', '师道田', '机电工程学院', '半导体学院', '主要从事 宽禁带半导体材料生长及器件制备研究 教科研项目： 池州学院高层次人才科研启动基金项目、CZ2024YJRC028、主持', '', '个人基本信息： 师道田，男，安徽省亳州人，博士研究生，讲师。 所属系： 电子信息工程系 主讲课程： 数字电子技术、模拟电子技术 研究领域： 主要从事 宽禁带半导体材料生长及器件制备研究 教科研项目： 池州学院高层次人才科研启动基金项目，CZ2024YJRC028，主持。 代表性论文/著作： 1. 师道田 , 孙晴 , 钱叶旺 , 等 . 基于蒙特卡洛方法的 β-Ga2O3 肖特基势垒二极管质子辐照效应研究 [J]. 人工晶体学报 ,2026,55(02):233-240.DOI:10.16553/j.cnki.issn1000-985x.2025.0190. 2. Pan Huang1, Lufeng Chen1, Daotian Shi1 , Yunbin He*, et al, MgO (100) as an affordable support for heteroepitaxial growth of high-quality β-Ga2O3 thin films and related highly-sensitive solar-blind UV photodetectors. Appl. Surf. Sci, 634, (2023) 157641. （ SCI Q1 Top IF ： 6.7 ） 3. Daotian Shi †, Guoxiang Wang*, et al, Preparation and thermoelectric properties of MoTe2 thin films by magnetron co-sputtering, Vacuum ， 2017, 138: 101-104. （被引 16 次， Q2 ， IF ： 4.0 ） 4. Daotian Shi †, Guoxiang Wang*, et al, Enhanced thermoelectric properties in Cu-doped Sb2Te3 films, Vacuum ， 2017, 145: 347-350. （被引 20 次， Q2 ， IF ： 4.0 ） 5. Guoxiang Wang ， Chao Li ， Daotian Shi , Controllable crystal growth and fast reversible crystallization-To-Amorphization in Sb2 Te-TiO2 films. Scientific Reports (ISSN: 2045-2322), 2017, 7:46279. （ Q2 ， IF ： 4.6 ） 6. 何云斌， 师道田 等，一种氮元素掺杂 p 型氧化镓薄膜及其制备方法和应用，发明专利，已授权。 7. 何云斌， 师道田 等，一种 p 型氧化镓薄膜及其制备方法和应用，发明专利，已授权。', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '博士研究生', NULL, '数字电子技术、模拟电子技术 研究领域： 主要从事 宽禁带半导体材料生长及器件制备研究 教科研项目： 池州学院高层次人才科研启动基金项目，CZ', NULL, '博士研究生，讲师。 所属系： 电子信息工程系 主讲课程： 数字电子技术、模拟电子技术 研究领域： 主要从事 宽禁带半导体材料生长及器件制备研究 教科研项目： 池州学院高层次人才科研启动基金项目，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('721', '段丽凤', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 段丽凤，讲师，工学博士，毕业于日本国立电气通信大学，研究方向为光电子技术，激光技术，量子通信，量子光学。 所属系： 电子信息科学与技术 主讲课程： 数字电子技术、专业英语、物联网技术、大学物理、大学生科学素养 代表性论文/著作： 1. Lifeng Duan, Aojie Xu, Lirong Wang and Yun Zhang, "Accessing the spectrum of a single-photon by the Hong-Ou-Mandel Interference," Opt. Express 32, 5418–5428 (2024). （期刊论文） 2. Lifeng Duan, Aojie Xu, and Yun Zhang, "Spectral Characterization of Two-Photon Interference between Independent Sources," Photonics 10, 1125 (2023). （期刊论文） 3. 李廷鱼 , 段丽凤 , " 分离式 Ⅱ 类匹配三共振复合型光学参量振荡器及其量子关联特性 ," 量子光学学报 32, 010101 (2026). ( 期刊论文 ) 4. Aojie Xu, Lifeng Duan, Lirong Wang and Yun Zhang, "Characterization of two-photon interference between a weak coherent state and a heralded single photon state," Opt. Express 31, 5662–5669 (2023). （期刊论文）', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '日本国立电气通信大学', NULL, '数字电子技术、专业英语、物联网技术、大学物理、大学生科学素养 代表性论文', NULL, '博士，毕业于日本国立电气通信大学，研究方向为光电子技术，激光技术，量子通信，量子光学。 所属系： 电子信息科学与技术 主讲课程： 数字电子技术、专业英语、物联网技术、大学物理、大学生科学素养 代表性论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('722', '查超飞', '机电工程学院', '半导体学院', '半导体光电器件 教科研项目： (1) 池州学院高层次人才科研启动基金项目、(RZ2500000985)、主持', '', '个人基本信息： 查超飞，男，1997年生，博士，籍贯安徽省安庆市。本科毕业于中南大学计算机学院，于北京邮电大学获得硕士和博士学位，现为电子信息工程系专任教师。主要研究领域为半导体光电器件。已发表SCI收录论文8篇。 所属系： 电子信息工程系 主讲课程： 《数字信号处理》、《信息论基础》 研究领域： 半导体光电器件 教科研项目： (1) 池州学院高层次人才科研启动基金项目，(RZ2500000985)，主持。 (2) 池州学院校级自然重点项目，(CZ2025ZRZ01)，主持。 代表性论文/著作： 1. Effective Surface Passivation of GaAs Nanowire Photo-detectors by a Thin ZnO Capping[J]. Nanoscale, 2024, DOI: 10.1039/D4NR01022A. 2. Low-Consumption Synaptic Devices Based on Gate-All-Around InAs Nanowire Field-Effect Transistors. Nanoscale research letters, 2022, 17(1): 101. 3. An artificial optoelectronic synapse based on an InAs nanowire phototransistor with negative photoresponse. Optical and Quantum Electronics, 2021, 53(10):1-12. 4. Plasmon-enhanced deep-sub wavelength lateral nanowire solar cells[J]. Optical and Quantum Electronics. 2024, 56(3):378. 5. Non-111-oriented semiconductor nanowires:growth, properties, and applications[J], Nanoscale, 2023, 15, 3032-3050. 6. Initialization of Nanowire or Cluster Growth Critically Controlled by the Effective V/III Ratio at the Early Nucleation Stage[J], The Journal of Physical Chemistry Letters, 2023, 14 (19), 4433-4439. 7. Low-threshold miniaturized core-shell GaAs/InGaAs nanowire/quantum-dot hybrid structure nanolasers[J], Optics & Laser Technology, 2022, 152, 108150, ISSN 0030-3992.(SCI) 8. Initialization of Nanowire or Cluster Growth Critically Controlled by the Effective V/III Ratio at the Early Nucleation Stage[J], The Journal of Physical Chemistry Letters, 2023, 14 (19), 4433-4439.(SCI)', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '北京邮电大学（硕士）', NULL, '《数字信号处理》、《信息论基础》 研究领域： 半导体光电器件 教科研项目： ', NULL, '博士，籍贯安徽省安庆市。本科毕业于中南大学计算机学院，于北京邮电大学获得硕士和博士学位，现为电子信息工程系专任教师。主要研究领域为半导体光电器件。已发表', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('723', '孙萍', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 孙萍，讲师，工学博士，毕业于南京邮电大学，研究方向为无线通信。 所属系： 电子信息科学与技术 主讲课程： 数字电子技术、电子开发实训 代表性论文/著作： 1. P. Sun, B. Wang, “Optimal Transmission Design for Near-Field Integrated Sensing, Communication, and Powering Systems,” IEEE Transactions on Aerospace and Electronic Systems, 2026. 2. P. Sun, B. Wang, “Near-Field Beam Focusing for Integrated Sensing and Communication Systems,” IEEE Internet of Things Journal, 2025, 12(12): 18643-18650. 3. P. Sun, Y. Ma, Q. Yang, et al., “XL-RIS Enabled Near- Field Integrated Sensing and Wireless Power Transfer,” IEEE Internet of Things Journal, 2025,12(14): 28723-28730.', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '南京邮电大学', NULL, '数字电子技术、电子开发实训 代表性论文', NULL, '博士，毕业于南京邮电大学，研究方向为无线通信。 所属系： 电子信息科学与技术 主讲课程： 数字电子技术、电子开发实训 代表性论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('724', '丁红菲', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 丁红菲，男，1984年出生，中共党员，安徽濉溪人，博士研究生/讲师 所属系： 电子信息工程系 主讲课程： 《电子测量技术》、《电工电子技术》 研究领域： 冶金智能制造与流程管理、自动化控制与设计等 教科研项目： 主持池州学院高层次人才科研基金启动项目：基于冷轧带钢生产过程的连退炉温度控制研究，20万元 代表性论文/著作： 1. Improved terminal sliding mode control for the looper tension system under matched and unmatched disturbances using a novel reaching law, IEEE Internet of Things Journal , 2026, vol. 13, no. 10, pp. 22501-22513. 2. An improved strength pareto evolutionary algorithm 2 for constrained multiobjective optimization problems in continuous annealing furnace, Steel Research International , 2026, 97: 2662-2671. 3. Model free adaptive control of strip temperature in continuous annealing furnace based on quantum-behaved particle swarm optimization[J]. Nonlinear Dynamics , 2025, 113: 629-643. 4. A reinforcement learning integral sliding mode control scheme against lumped disturbances in hot strip rolling[J]. Applied Mathematics and Computation , 2024, 465: 12840 5. Predictive modeling of strip temperature in continuous annealing furnace: An improved optimization algorithm[J]. ISIJ International , 2024, 64(5): 808-816.', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '博士研究生', NULL, '《电子测量技术》、《电工电子技术》 研究领域： 冶金智能制造与流程管理、自动化控制与设计等 教科研项目： 主持池州学院高层次人才科研基金启动项目：基于冷轧带钢生产过程的连退炉温度控制研究，', NULL, '博士研究生', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('725', '郑德宇', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 郑德宇，男，讲师 所属系： 机械工程系 主讲课程： 机械制图，机械创新设计 研究领域： 长期从事高温合金热变形过程中的形性调控研究，致力于人工智能算法在金属多物理场、多尺度动态耦合模型中的优化应用，专注于提升涡轮盘整体热成形过程中的组织均匀性与成形质量。 教科研项目： 1. 管道泄露声音采集装置的设计与制造技术研究（横向项目） 2. 热处理工艺对镍基合金晶粒演化及第二相析出的影响规律研究（校科研启动项目） 3. 基于机器学习的数据驱动高温合金热变形多机制微观组织预测模型研究（省重点科研项目） 代表性论文/著作 1. Deyu Zheng, Yufeng Xia, Haihao Teng, Yingyan Yu. Application of Genetic Algorithm to Improve the Predictive Stability of BP-ANN Constitutive Model for GH4706 Superalloy[J]. Journal of central south university. 31, 693–708 (2024). 中科院二区 2. Deyu Zheng, Yufeng Xia, Yang Zeng, Jie Zhou. Dynamic Recrystallization Process Simulation of GH4706 Alloy by Level-Set Method[J]. Acta Metallurgica Sinica, 2025, 61(9), 1425-1437. 中科院二区 3. Deyu Zheng, Yufeng Xia, Haihao Teng, Yingyan Yu. Multi-object optimization of forging process parameters for super large turbine disc based on Taguchi method[J]. Rare Metal Materials and Engineering, 2024,53(07):1887-1895. 中科院四区 4. Deyu Zheng, Yufeng Xia, Jie Zhou. Microstructure Homogenization Control of GH4706 Alloy by Hot Deformation Maps[J]. Rare Metal Materials and Engineering, 2025, 54(12): 3000-3009. 中科院四区 5. 郑德宇，夏玉峰，滕海灏，张雪，权国政 . 化学元素在钛铝异种合金焊接增材中的作用研究进展 [J]. 材料热处理学报 , 2021, 42(06): 11-21. CSCD 6. 郑德宇，夏玉峰，张森峰，常玥莹，李松林，周杰 . 工艺参数对 GH4706 合金微观组织均匀细化的影响 [J]. 塑性工程学报 ,2025,32(05):143-152. CSCD 7. 杨伟 , 郑德宇 , 张森峰 , 等 .GH4706 高温合金本构模型的人工神经网络优化 [J]. 热加工工艺 ,2025,54(22):103-108+113. 8. 郑德宇 . 基于实例推理的模具设计技术研究 [J]. 山东工业技术 ,2014,(14):187. 9. 郑德宇 . 关于《机械制造技术》教材中一些问题的思考 [J/OL]. 中文科技期刊数据库（文摘版）教育 ,2016(8). 10. 郑德宇 . 冲压加工中的送料装置的研究 [J]. 科教导刊 - 电子版（中旬） ,2015(6):170-170. 专利 1. 郑德宇 , & 陈佳 . (2019). 一种冲压下模具 (CN Patent No. 208427616U). 2. 郑德宇 , & 陈佳 . (2019). 一种方便使用的零件量尺 (CN Patent No. 208751393U). 3. 夏玉峰 , 周杰 , 肖贵乾 , 张建生 , 张焱城 , & 郑德宇 . (2024). 一种 GH4706 合金的高精度本构模型构建方法 (CN Patent No. 118586186A). 教材 1. 机械工程材料与热处理，第二主编，北京：北京希望电子出版社， 2018. ISBN978-7-83002-632-5 2. 自动控制原理，第一副主编，延边：延边大学出版社， 2017. ISBN978-7-5688-2596-2 3. 液压与气压传动技术，第一副主编，成都：西南交通大学出版社， 2019. ISBN978-7-5643-7058-9 4. 机械制图，第三副主编，吉林：吉林大学出版社， 201', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, NULL, NULL, '机械制图，机械创新设计 研究领域： 长期从事高温合金热变形过程中的形性调控研究，致力于人工智能算法在金属多物理场、多尺度动态耦合模型中的优化应用，专注于提升涡轮盘整体热成形过程中的组织均匀性与成形质量。 教科研项目： ', NULL, '大学出版社， ；大学出版社， ；大学出版社， ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('726', '韩军', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 韩军，讲师，工学博士，毕业于暨南大学，研究方向为工程力学。 所属系： 电子信息工程系 主讲课程： 离散数学 代表性论文/著作： 1. Jun Han, Hong Yuan, Jiayu Wu. Interfacial behavior of pipe joints under torsion load. Acta Mechanica Solida Sinica, 2015,28(5):521-535.(SCI)', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '暨南大学', NULL, '离散数学 代表性论文', NULL, '博士，毕业于暨南大学，研究方向为工程力学。 所属系： 电子信息工程系 主讲课程： 离散数学 代表性论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('727', '岐少鹏', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 岐少鹏，男 ，博士，2023.03-2025.7 中国科学技术大学 - 博士后，合作导师：熊宇杰、龙冉教授；2017.03-2022.12，东南大学材料物理与化学博士。 所属系： 电子信息工程 主讲课程： 大学物理 研究领域： 等离激元光催化 教科研项目： 1. 中国海洋石油集团有限公司“十四五”重大科技项目“二氧化碳光电催化技术研究”(2023.03-2024.10) ①负责等离激元-简并半导体催化复合体系的结构设计、制备、表征以及光催化 CO 2 还原性能评估。 ②负责基于等离激元活化 CO2 催化体系的规模放大装置设计方案研究，包括：催化剂材料放大合成工艺研发、反应工艺设计以及规模放大光催化反应器设计。 2. 主持基金： 中国博士后科学基金第 76 批面上资助(2024M763152) 3. “钼基等离激元催化剂全光谱驱动 CO2催化性能研究” (2025.01-2025) 代表性论文/著作： 1. Qi S., Liu, G., Zhang K., Chen, J., Zhao, Y., Lou, Y.*. Colloidal Synthesis of Plasmonic Ultrathin Transition-Metal Oxide Nanosheets, ACS Sustainable Chemistry & Engineering, 2022, 10 (29), 9565-9572. (IF: 7.1; 中科院分区 : 1 区 ; 第一作者 ) 2. Qi S., Liu, G., Chen, J., Lou, Y.*, Zhao, Y.*. Surface Coordination Layer to Enhance the Stability of Plasmonic Cu Nanoparticles, Journal of Physical Chemistry C, 2021, 125 (50), 27624-27630. (IF: 3.3; 中科院分区 : 3 区 ; 第一作者 ) 3. Qi S., Liu, G., Tan, L., Chen, J., Lou, Y.*, Zhao, Y.*. Top-Down Fabrication of Colloidal Plasmonic MoO3-x Nanocrystals via Solution Chemistry Hydrogenation, Chemical Communications, 2020, 56 (35), 4816-4819. (IF: 4.3; 中科院分区 : 2 区 ; 第一作者 ) 4. Qi S., Zhao, B., Zhou, B., Jiang X.*. An Electrochemical Immunosensor Based on Pristine Graphene for Rapid Determination of Ractopamine, Chemical Physics Letters, 2017, 685, 146-150. (IF: 2.8; 中科院分区 : 3 区 ; 第一作者 ) 5. Qi S., Zhao B, Tang H, Jiang X*. Determination of Ascorbic Acid, Dopamine, and Uric Acid by A Novel Electrochemical Sensor Based on Pristine Graphene, Electrochimica Acta. 2015; 161, 395-402. (IF: 5.5; 中科院分区 : 2 区 ; 第一作者 ) 6. Liu G., Qi S., Chen J., Lou Y.*, Zhao Y.*, Burda C.*, Cu-Sb-S Ternary Semiconductor Nanoparticle Plasmonics, Nano Letters, 2021, 21 (6), 2610-2617. (IF: 9.6; 中科院分区 : 2 区 ) 7. Liu G., Kolodziej C., Jin R., Qi S., Lou Y.*, Chen J., Dechen Jiang*, Zhao Y.*, Burda C.*. MoS2-Stratified CdS-Cu2-xS Core-Shell Nanorods for Highly-Efficient Photocatalytic Hydrogen Production, ACS Nano, 2020, 14 (5), 5468-5479. (IF: 15.8; 中科院分区 : 1 区 ) 8. Qi ', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '东南大学（博士）', NULL, '大学物理 研究领域： 等离激元光催化 教科研项目： ', NULL, '博士，；大学 ；博士后，合作导师：熊宇杰、龙冉教授；', NULL, NULL);
