INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('730', '洪锋', '机电工程学院', '半导体学院', '《信号与系统》、《模拟电子技术》、《电工电子技术》、《高频电子技术》及《数字信号处理》等课程的教学', '', '洪锋，男，副教授，工学硕士，池州学院智能感知与计算研究中心主任，中国计算机协会（ CCF ）专业会员，现为池州学院人事处师资科（职称办）科长（主任）。主要从事《信号与系统》、《模拟电子技术》、《电工电子技术》、《高频电子技术》及《数字信号处理》等课程的教学。近年来，发表论文 10 余篇，其中 SCI 收录论文 6 篇， CSCD 收录论文 4 篇；主持省级科研项目 1 项，省级质量工程项目 2 项，校级教科研项目 3 项；获发明专利 1 项，实用新型专利多项。目前担任池州市贵池区科技咨询专家。 主要研究方向： 1. 智能信息处理； 2. 半导体集成电路近似计算与优化。', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '硕士', NULL, '信号与系统、模拟电子技术、电工电子技术、高频电子技术、数字信号处理', NULL, '硕士，池州学院智能感知与计算研究中心主任，中国计算机协会', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('731', '陈艳', '机电工程学院', '半导体学院', '《数字电子技术》、《通信原理》、《数字图像处理》和《数字电子技术实验》等课程教学', '', '陈艳：硕士研究生，讲师，主要从事《数字电子技术》、《通信原理》、《数字图像处理》和《数字电子技术实验》等课程教学。主持教育厅重点科研项目一项，校级科研项目三项，主持校级质量工程项目三项，第一作者发表SCI、EI检索论文两篇。', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, NULL, NULL, NULL, NULL, '硕士研究生，讲师，主要从事', NULL, NULL);
