INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('736', '赵俊', '机电工程学院', '半导体学院', NULL, '', '个人简介： 赵俊，安徽舒城人，1990年5月出生。2008年本科毕业于安徽师范大学，应用化学专业。2017年硕士毕业于安徽师范大学，物理化学专业。2025年博士毕业于复旦大学，材料与化工专业。2013年在安徽众锐质量检测有限公司从事空气质量检测工作，2017年在安徽华东光电技术研究所从事金属表面处理工艺开发工作。2025年加入池州学院机电工程学院集成电路工程系，从事教学与科研工作。 主讲课程 ： 离散数学，单片机原理与应用。 研究领域 ： 柔性电子，复合材料，贵金属纳米材料制备与催化。 教科研项目 ： 无 代表性论文/著作 ： 1. Three-Dimensional Interconnect Technologies for Advanced Flexible Electronics. Advanced Materials 2025 , e10294 ； 2. Diblock Copolymer Brush-Based Adhesion Coupling Agents, Advanced Functional Materials 2025 , 2423298 ； 3. Skin-Integrated Electrodes Based on Room-Temperature Curable, Highly Conductive Silver/Polydimethylsiloxane Composites, Small 2024 , 20 (23), 2309470; 4. Simultaneous tunable structure and composition of PtAg alloyed nanocrystals as superior catalysts, Nanoscale 2016, 8 (32), 14971-14978. 5. Formation of Graphene–Silicon Junction by Room Temperature Reduction With Simultaneous Defects Removal, IEEE Transactions on Electron Devices 2021, 68 (2), 873-878. 6. 一种银粉表面脂肪酸的处理方法及其在硅基导电胶的应用。 ZL 202110237911.6. 7. 一种阶梯固化硅胶膜的制备方法及其在表皮电子领域的应用。 ZL 202110597378.4.', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '安徽师范大学', NULL, '离散数学，单片机原理与应用', NULL, '本科毕业于安徽师范大学，应用化学专业。；硕士毕业于安徽师范大学，物理化学专业。；博士毕业于复旦大学，材料与化工专业。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('737', '郭威', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 郭威，男，汉族，中共党员，2023年3月毕业于中国科学技术大学，获工学博士学位，现任池州学院机电工程学院专任教师。 所属系： 集成电路工程系 教科研项目： 安徽省博士后基金（E44GEDAB）《SiO 2 @SiC陶瓷纤维气凝胶的焦耳快速加热制备及其高温隔热应用研究》 代表性论文/著作： 1. Wei Guo , Zheng Zhang, Nian Li, Min Xi, Cui Liu, Shudong Zhang* and Zhenyang Wang, * Hollow flower-like TiO 2 @Cs x WO 3 hybrid for effective thermal management using a UV/NIR light absorbing shield strategy，Journal of Materials Chemistry A, 2025,13, 3163-3173. (一作，中科院二区，TOP，IF=10.8) 2. Wei Guo , Cui Liu, Nian Li, Min Xi, Yamin Che, Shudong Zhang* and Zhenyang Wang, * Micelle Dynamic Reconstruction to Effectively Modulate the Transmission of Smart Windows ， JPCC, 2022, 126, 4872-4880. ( 一作，中科院二区， IF=2.8) 3. Wei Guo , Cui Liu, Nian Li, Min Xi, Yamin Che, Changlong Jiang, Shudong Zhang* and Zhenyang Wang, * A highly transparent and photothermal composite coating for effective anti-/de-icing of glass surfaces ， Nanoscal Advance, 2022, 4, 2884-2892. ( 一作 , 中科院三区 , IF=4.6) 4. Huan Xu, Cui Liu, Wei Guo ,* Nian Li, Yang Chen, Xiaolin Meng, Mengjie Zhai, Shudong Zhang* , Zhenyang Wang, * Sodium alginate/ Al 2 O 3 fiber nanocomposite aerogel with thermal insulation and flame retardancy properties ， Chemical Engineering Journal, 2024, 489, 151223. ( 第一通讯，中科院一区， TOP ， IF=13.4) 5. Zheng Zhang, Wei Guo ,* Nian Li, Min Xi, Cui Liu, Shudong Zhang* and Zhenyang Wang, * Highly oriented SiC@SiO2 ceramic fiber aerogels with good anisotropy of the thermal conductivity and high temperature resistance ， Advanced Science. 2025, 17, 2416740.( 第一通讯，中科院一区，顶刊， IF=17.5) 6. Xiaolin Meng, Cui Liu, Jixiang Zhang, Wei Guo ,* Nian Li, Yang Chen, Huan Xu, Min Xi, Shudong Zhang* and Zhenyang Wang, * Thermal-insulating ceramic fiber aerogels reinforced by fusing knots of overlapping fibers for superelasticity and high compression resistance ， Journal of Materials Chemistry A, 2024, 12, 16079-16086. ( 第一通讯，中科院二区， TOP ， IF=10.8) 7. Yang Chen, Wei Guo , Shudong Zhang, *Jixiang Zhang, *Huan Xu, Nian Li, Xiaolin Meng, Min Xi, Cui Liu, * Zhenyang Wang, *', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '中国科学技术大学', NULL, NULL, NULL, '大学，获工学博士学位，现任池州学院机电工程学院专任教师。 所属系： 集成电路工程系 教科研项目： 安徽省博士后基金', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('738', '谢小雨', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 谢小雨，男，汉族，中共党员，2023年6月毕业于东南大学，获工学博士学位，现任池州学院机电工程学院专任教师。个人邮箱：xiexy@czu.edu.cn 所属系： 集成电路工程系 主讲课程： 《半导体器件》《IC版图设计》 研究领域： 半导体材料及光电子器件 教科研项目： 国家自然科学基金委员会, 面上项目, 62075041, 基于经典磁控溅射的一维核壳纳米结构径向异质结的精准构建与光电功能, 2021-01-01 至 2024-12-31, 63万元, 结题, 参与 代表性论文/著作： 1. Xie, Xiaoyu; Wang, Ru; Ma, Yi; Chen, Jinping; Shi, Zengliang; Cui, Qannan; Li, Zhiyong; Xu, Chunxiang; Sulfate-Functionalized Core-Shell ZnO/CdS/Ag2S Nanorod Arrays with Dual-Charge-Transfer Channels for Enhanced Photoelectrochemical Performance, Acs Applied Energy Materials,2022, 5(5): 6228-6237. 2. Xie, Xiaoyu; Wang, Ru; Ma, Yi; Chen, Jinping; Cui, Qiannan; Shi, Zengliang; Li, Zhiyong; Xu, Chunxiang; Photothermal-Effect-Enhanced Photoelectrochemical Water Splitting in MXene-Nanosheet-Modified ZnO Nanorod Arrays, Acs Applied Nano Materials, 2022, 5(8): 11150-11159. 3. Xie, Xiaoyu; Wang, Ru; Chen, Jinping; Ma, Yi; Li, Zhiyong; Cui, Qiannan; Shi, Zengliang; Xu, Chunxiang; Hydrophilic polypyrrole and g-C3N4 co-decorated ZnO nanorod arrays for stable andefficient photoelectrochemical water splitting, Dalton Transactions, 2022, 51(47): 18109-18117. 4. Wang, Ru; Xie, Xiaoyu; Xu, Chunxiang; Ji, Rendong; Shi, Zengliang; Cui, Qiannan; Wang, Mingliang; A Z-scheme 2D/0D ZnIn2S4/ZnO heterostructure for efficient photocatalytic degradation of tetracycline: energy band engineering and morphology modulation, Catalysis Science & Technology, 2023, 13(2): 426-436. 5. Wang, Ru; Xie, Xiaoyu; Xu, Chunxiang; Lin, Yi; You, Daotong; Chen, Jinping; Li, Zhuxin; Shi, Zengliang; Cui, Qiannan; Wang, Mingliang; Bi-piezoelectric effect assisted ZnO nanorods/PVDF-HFP spongy photocatalyst for enhanced performance on degrading organic pollutant, Chemical Engineering Journal, 2022, 439: 135787. 6. 谢小雨 ; 何瑞 ; 郭丛 ; 雍文炯 ; 杨广涛 ; 异质结电池的制备方法、异质结电池以及电池组件 , 2024-11-28, 中国 , CN202411727752.8 ( 专利 ) 7. 谢小雨 ; 高展 ; 郭丛 ; 王永恒 ; 杨广涛 ; 硅异质结太阳能电池及其制备方法、光伏组件、光伏系统 ,2024-08-13, 中国 , CN202411106952.1 ( 专利 ) 8. 谢小雨 ; 郭丛 ; 高展 ; 雍文炯 ; 杨广涛 ; 异质结太阳能电池及其制备方法、光伏组件、光伏系统 ,202', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '东南大学', NULL, '《半导体器件》《IC版图设计》 研究领域： 半导体材料及光电子器件 教科研项目： 国家自然科学基金委员会, 面上项目, ', NULL, '大学，获工学博士学位，现任池州学院机电工程学院专任教师。个人邮箱：', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('739', '梁琦', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 梁琦，池州学院机电工程学院讲师，微电子科学与工程系专任教师，2022年博士毕业于北京工业大学材料科学与工程专业，研究领域为宽带隙半导体材料与器件制备，主要包括GaN薄膜材料与器件、纳米ZnO的制备。主讲课程包括：微电子材料、微电子工艺、单片机原理与应用。现已第一作者发表SCI论文7篇，以共同作者发表论文2篇，申请国家发明专利一篇，主持横向课题一项，参与了国家自然基金面上项目1项。 所属系： 微电子科学与工程系 研究领域： 纳米半导体材料与器件制备 代表性论文/著作： 1. Q. Liang , X. R Guo, T. T Quan, F. C Meng. P123 assisted synthesis and characterization of urchin-like γ-Al 2 O 3 hollow microspheres. Journal of Advanced Ceramics, 2016, 5(3): 225-231. 2. Q. Liang , R. Z Wang, M. Q Yang, Y. Ding, C. H Wang. A green, low-cost method to prepare GaN films by plasma enhanced chemical vapor deposition. Thin Solid Film, 2020, 710: 138266. 3. 梁琦 ，王如志，杨孟骐，王长昊，刘金伟 . Al 2 O 3 衬底无催化剂生长 GaN 纳米线及其光学性能研究 . 物理学报， 2020 ， 69(8): 087801. 4. Q. Liang , M. Q Yang, C. H Wang, R. Z Wang. A simple method to synthesize worm-like AlN nanowires and its field emission studies. Chinese Physics B, 2021, 30(8): 087302. 5. 梁琦 ，杨孟骐，张京阳，王如志 . PECVD 法制备高结晶 GaN 薄膜及其光电响应性能研究 . 物理学报， 2022 ， 71(9): 097302. 6. Qi Liang , Weifeng Wu, Huajie Xu, Effect of [100] preferred orientation on photoelectric properties of GaN films prepared by PECVD method, Optical Materials 2025, 168: 117367. 7. Qi Liang , Weifeng Wu ， Huajie Xu, Tailoring crystal quality in ZnO nanomaterials for enhanced photocatalytic performances toward removals of organic pollutants for environmental protection. Journal of nanoparticle research, 2026. 8. Qi Liang , Huajie Xu, Weifeng Wu ， The preparation of n-type GaN films with good crystal quality by plasma enhanced chemical vapor deposition for optoelectronic devices.( 第一作者，手稿在投 ) 9. X. Y Feng, R. Z Wang, Q. Liang , Y. H Ji, M. Q Yang. Direct growth of GaN nanowires by Ga and N 2 without catalysis. Crystal Growth & Design, 2019 ， 19: 2687-2694. 10. 杨孟骐，姬宇航， 梁琦 ，王长昊，张跃飞，张铭，王波，王如志 . 四方结构 GaN 纳米线制备、掺杂调控及其场发射性能研究 . 物理学报， 2020, 69(16): 167805. 专利： 王如志， 梁琦 ，杨孟骐 . 一种高结晶 GaN 薄膜的制备方法 . ( 公开号： CN113930745A)', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '北京工业大学', NULL, NULL, NULL, '博士毕业于北京工业大学材料科学与工程专业，研究领域为宽带隙半导体材料与器件制备，主要包括', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('740', '胡华奎', '机电工程学院', '半导体学院', '(1) 半导体光电器件设计、机理与应用探索 (2) 半导体工艺研究 教科研项目： (1) 池州学院高层次人才科研启动基金项目、 CZ2024YJRC20 、主持', '', '个人基本信息： 胡华奎，男，博士，籍贯安徽省安庆市。2023年博士毕业于中科院微电子研究所微电子学与固体电子学专业，获工学博士学位，现为机电工程学院微电子科学与工程系专任教师。主要研究领域为半导体光电器件设计及其制作。以第一或通讯作者发表SCI收录论文10篇。 所属系： 微电子科学与工程系 主讲课程： 《集成电路设计》、《集成电路封装与测试》、《微电子学概论》 研究领域： (1) 半导体光电器件设计、机理与应用探索 (2) 半导体工艺研究 教科研项目： (1) 池州学院高层次人才科研启动基金项目， CZ2024YJRC20 ，主持。 (2) 池州学院校级自然重点项目，(CZ2024ZRZ07)，主持。 (3) 安徽省教育厅自然科学重点项目，(2025AHGXZK30591)。 代表性论文/著作： 1.Huakui Hu, Jiangtao Ding, Yao Yu, et al. Structural diversity in dual-focused vortices via superposed spiral zone plates[J]. Optics Communications, 2026, 604: 132850. 2.Huakui Hu, Weifeng Wu, Huajie Xu, et al. Phase quasi-random squares spiral zone plates with single-focus diffraction[J]. Journal of the Optical Society of America A, 2025, 42: 834-841. 3.Huakui Hu, Jiangtao Ding, Weifeng Wu, et al. Hexagonal diffraction gratings generated by convolutional neural network-based deep learning for suppressing high-order diffractions[J]. Journal of the Optical Society of America A, 2024, 41: 1987-1993. 4.Jiangtao Ding, Huakui Hu, Weifeng Wu, et al. Depth of focus enhancement of the linear fractal zone plates[J]. AIP Advances, 2025, 15(11): 115303. （通讯作者） 5.Hu Huakui, Zhang Xiaomeng, Li Hailiang, et al. Self-standing Quasi-random-dots fork gratings for single-order diffraction[J]. Journal of Applied Physics, 2022, 132(22): 223105. 6.Hu Huakui, Cao Fulin, Zhao Yue. Extending Focal Depth of Flower-Shaped Optical Vortex with Composited Spiral Zone Plate Grating[J]. Photonics 2022, 9: 371. 7.Hu Huakui, Cao Fulin, Zhao Yue, et al. Spiral modulated groove position gratings for the generation of two focused optical vortices with equal intensity[J]. Optik, 2022, 266: 169581. 8.Hu Huakui, Xie Changqin, Niu Jiubin, et al. Quantum-dot-array square spiral zone plates with single-order focus[J]. Optik, 2023, 278: 170745. 9. 胡华奎 , 曹富林 , 赵越 , 谢常青 . 单级变栅距叉形光栅 [J]. 光学学报 , 2022, 42(14): 1405005. 10. 胡华奎 , 丁江涛 , 江海锋 , 等 . 准随机点阵二维叉形光栅的设计与表征 [J]. 北京大学学报 ( 自然科学版 ), 2025, 61(04): 650-658.', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, NULL, NULL, '《集成电路设计》、《集成电路封装与测试》、《微电子学概论》 研究领域： ', NULL, '博士，籍贯安徽省安庆市。；博士毕业于中科院微电子研究所微电子学与固体电子学专业，获工学博士学位，现为机电工程学院微电子科学与工程系专任教师。主要研究领域为半导体光电器件设计及其制作。以第一或通讯作者发表；大学学报 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('741', '张子建', '机电工程学院', '半导体学院', NULL, '', '个人基本信息： 张子建，男，中共党员，1994年9月生于江西上饶。本科毕业于太原科技大学焊接技术与工程专业，后在北京科技大学材料科学与工程专业完成硕士、博士阶段学习，深耕材料科学领域多年，具备扎实的专业基础与科研能力。联系电话：18513832833，电子邮箱：zhangzijian8020@163.com。 所属系： 集成电路工程 主讲课程： 《单片机原理与应用》，《单片机课程设计》 研究领域： 先进陶瓷基复合材料、高导热电子封装材料和电子基板 教科研项目： 无 代表性论文/著作： 1. Zijian. Zhang , Xinbo He* et al., Effect of the content and shape of filled particles on the properties of bimodal diamond/SiC composites. Diamond and Related Materials 155 (2025) 112373. (IF=4.3) 2. Zijian. Zhang , Xinbo He* et al., Preparation of diamond/RB-SiC composite with low residual silicon and high diamond content by infiltration. Journal of Alloys and Compounds 1018 (2025) 179147. (IF=5.8) 3. Zijian. Zhang , Xinbo He* et al., Effect of forming pressure on microstructure and properties of diamond/SiC composites. Journal of Alloys and Compounds 1010 (2025) 177305. (IF=5.8) 4. Zijian. Zhang , Xinbo He* et al., Preparation of bimodal-diamond/SiC composite with high thermal conductivity. Journal of the European Ceramic Society 44, 643-650 (2024). (IF=5.7) 5. Zijian. Zhang , Xinbo He* et al., Reach on the preparation process of diamond/SiC composites with bimodal diamond particle. Composites Communications 39 (2023) 101569. (IF=6.5) 6. Xinbo He*, Zijian. Zhang , et al., Research on maximizing the diamond content of diamond/SiC composite. Journal of the European Ceramic Society 42, 3127-3134 (2022). (IF=5.7)', '0', '0', '0', '2026-06-05 17:41:37', '2026-06-05 17:41:37', NULL, '后在北京科技大学（硕士）', NULL, '《单片机原理与应用》，《单片机课程设计》 研究领域： 先进陶瓷基复合材料、高导热电子封装材料和电子基板 教科研项目： 无 代表性论文', NULL, '本科毕业于太原科技大学焊接技术与工程专业，后在北京科技大学材料科学与工程专业完成硕士、博士阶段学习，深耕材料科学领域多年，具备扎实的专业基础与科研能力。联系电话：', NULL, NULL);
