INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('747', '程海峰', '旅游与历史文化学院', '程海峰-旅游与历史文化学院', NULL, '', NULL, '0', '0', '0', '2026-06-05 17:44:22', '2026-06-05 17:44:22', NULL, '', NULL, '旅游服务礼仪、导游业务 研究领域： 旅游管理与规范 教科研项目： ', NULL, '本科毕业于安徽师范大学旅游管理专业，获得管理学学士学位，；硕士毕业于安徽师范大学人文地理专业，获得管理学硕士学位，现为旅游与历史文化学院专业教师，副教授。 所属系： 旅游管理 主讲课程： 旅游服务礼仪、导游业务 研究领域： 旅游管理与规范 教科研项目： ；大学生茶文化创意大赛 二等奖； ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('748', '查晓莉', '旅游与历史文化学院', '查晓莉-旅游与历史文化学院', '旅游地理与旅游规划', '', '个人基本信息： 查晓莉，女，出生于安徽巢湖居巢区， 2014 年本科毕业于安徽师范大学旅游管理专业，获管理学学士学位， 2017 年 硕士毕业于安 徽师范大学人文地理学专业，获理学硕士学位，现为旅游与历史文化学院专任教师，讲师。 所属 系 ： 旅游管理系 主讲课程： 旅游学概论、旅游政策法规、导游业务 研究领域： 旅游地理与旅游规划；旅游者行为 教科研项目： 主持： 1. 九华山新浪官方微博影响力研究（池州学院人文社科一般项目（ CZ2018RW01 ），已结项； 2. 安徽省博物馆难忘旅游体验及形成机制研究（安徽省教育厅高校人文社会科学重点研究项目（ SK2021A0116 ），在研； 3. 《导游业务》线下课程（池州学院校级质量工程项目（ 2022XXXKC09 ），已结项。 代表性论文 /著作： 1. 上海迪士尼客源市场特征及分布研究，《池州学院学报》， 2021 年第 5 期； 2. 皖江城市带 5A 级旅游景区新浪微博影响力研究，《铜陵学院学报》， 2020 年第 5 期； 3. 基于网络游记的访沪国内游客旅游流网络结构特征，《池州学院学报》， 2020 年第 3 期； 4. 上海迪士尼国内旅游流地理分布与流动特征，《旅游学刊》， 2019 年第 6 期； 5. 基于旅游数字足迹的访沪国内旅游者时空行为研究，《旅游研究》， 2017 年第 4 期。 主要 获奖情况： 1. 池州学院 2019 年度考核优秀； 2. 池州学院 2020 年度双能型教师， 2021 年 3 月； 3. 池州学院 2021 年度师德师风考核优秀； 4. 指导学生获第十二届全国旅游院校导游服务技能大赛高等院校组英语导游服务一等奖和普通话导游服务三等奖， 2021 年 5 月； 5. 指导学生获第十七届“挑战杯”全国大学生课外学术科技作品竞赛红色专项活动安徽省省级二等奖， 2021 年 6 月； 6. 池州学院优秀实习指导老师， 2022 年 4 月； 7. 池州学院 2020-2021 、 2021-2022 两学年度优秀教学质量奖， 2023 年 6 月； 8. 指导学生获第十四届全国旅游院校导游服务技能大赛高等院校组英语导游服务三等奖和普通话导游服务三等奖， 2024 年 5 月； 8. 池州学院 2024 年度考核优秀、师德师风考核优秀。', '0', '0', '0', '2026-06-05 17:44:22', '2026-06-05 17:44:22', NULL, '安徽师范大学人文地理学（硕士）', NULL, '旅游学概论、旅游政策法规、导游业务 研究领域： 旅游地理与旅游规划；旅游者行为 教科研项目： 主持： ', NULL, '本科毕业于安徽师范大学旅游管理专业，获管理学学士学位， ；硕士毕业于安 徽师范大学人文地理学专业，获理学硕士学位，现为旅游与历史文化学院专任教师，讲师。 所属 系 ： 旅游管理系 主讲课程： 旅游学概论、旅游政策法规、导游业务 研究领域： 旅游地理与旅游规划；旅；大学生课外学术科技作品竞赛红色专项活动安徽省省级二等奖， ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('749', '沈姗姗', '旅游与历史文化学院', '沈姗姗-旅游与历史文化学院', NULL, '', NULL, '0', '0', '0', '2026-06-05 17:44:22', '2026-06-05 17:44:22', NULL, '', NULL, '研学旅行课程开发、研学旅行实务、导游基础知识、茶艺与茶文化', NULL, '本科毕业于安徽师范大学旅游管理专业，获管理学学士学位； ；大学旅游管理专业，获管理学硕士学位。 现为池州学院旅游与历史文化学院专任教师，副教授。 所属系 ：旅游管理系 主讲 课程： 研学旅行课程开发、研学旅行实务、导游基础知识、茶艺与茶文化 研究领域： 旅游地理；本科院校', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('750', '祝亚雯', '旅游与历史文化学院', '祝亚雯-旅游与历史文化学院', NULL, '', '个人基本信息： 祝亚雯，女，出生于安徽铜陵铜官山区， 2007 年本科毕业于安徽师范大学旅游管理专业，获管理学学士学位， 2010 年硕士毕业于安徽师范大学旅游管理专业，获管理学硕士学位， 2024 年博士毕业于韩国南首尔大学市场营销专业，现为旅游与历史文化学院专任教师，副教授。 所属系： 旅游管理 主讲课程： 旅游规划与开发 研究领域： 文化旅游规划与开发 教科研项目： 1. 皖南古村落历史记忆认知与影响研究（安徽省教育厅人文社科重点项目 SK2021A0744 ） 2. 皖南古村落历史文化景观发展过程及其开发研究（安徽省教育厅人文社科重点项目 SK2018A0635 ） 3. 应用型高校旅游管理专业“双师双能型”教师队伍建设研究——以池州学院为例（安徽省质量工程教学研究重点项目 2021jyxm1010 ） 4. 旅游地理学（安徽省教学示范课 2020SJJXSFK1760 ） 代表性论文 / 著作： 1. 基于景观记忆视角的铜陵大通古镇历史文化景观认知与活态保护研究 ，《黄山学院学报》， 2023 年第 1 期。 2. 皖南古村落文化景观研究进展，《黑河学院学报》 ,2020 年第 2 期。 3. 全域旅游背景下杏花村文化旅游区旅游开发，《池州学院学报》 ,2017 年第 6 期。 4. 基于地统计学方法的区域旅游空间结构研究 —— 以皖南国际文化旅游示范区为例，《地理科学》 ,2016 年第 11 期。 5. 高校学术会议旅游市场开发初步研究 ，《地域研究与开发》， 2010 年第 5 期 主要 获奖情况： 1. 安徽省社会科学界第十八届学术年会论文二等奖， 2023 年 11 月。 2. 安徽省第七届自然科学优秀学术论文三等奖， 2013 年 4 月。 3. 池州市第六届社会科学论文优秀奖 ， 2021 年 1 月。', '0', '0', '0', '2026-06-05 17:44:22', '2026-06-05 17:44:22', NULL, '安徽师范大学', NULL, '旅游规划与开发 研究领域： 文化旅游规划与开发 教科研项目： ', NULL, '本科毕业于安徽师范大学旅游管理专业，获管理学学士学位， ；硕士毕业于安徽师范大学旅游管理专业，获管理学硕士学位， ；博士毕业于韩国南首尔大学市场营销专业，现为旅游与历史文化学院专任教师，副教授。 所属系： 旅游管理 主讲课程： 旅游规划与开发 研究领域： 文化旅游规划与开发 教科研项目： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('751', '夏丽丽', '旅游与历史文化学院', '夏丽丽-旅游与历史文化学院', '旅游企业管理、旅游规划与开发 主要教科研项目： 窗体底端 1.基于旅游环境承载力的九华山旅游开发研究（校级科研项目： 2016RW003 ）', '', '窗体顶端 夏丽丽，女，安徽池州人， 2007年至2011 年就读于安徽师范大学旅游管理专业，获管理学学士学位； 2011 年至 2014年就读于安徽师范大学旅游管理专业，获管理学硕士学位 。 2014年7月在池州学院工作至今 ，现为旅游与历史文化学院专业教师，讲师。 所属系： 旅游管理 主讲课程： 旅游服务礼仪、酒店市场营销、茶艺与茶文化 研究领域： 旅游企业管理、旅游规划与开发 主要教科研项目： 窗体底端 1.基于旅游环境承载力的九华山旅游开发研究（校级科研项目： 2016RW003 ）； 2.应用型本科院校《旅游市场营销》课程改革与实践（校级教研项目： 2016XJYXM72 ）； 3.去商业化背景下宗教文化旅游地发展困境与再生——以九华山为例（省人文社科重点项目：SK2019A0302） ； 4.参编《导游综合知识》 ，安徽师范大学出版社， 2015年6月第一版，撰写第七章和第九章，共计13046字。 代表性科研成果： 窗体底端 1.贵池区旅游人才供给现状与发展对策研究，池州学院学报，2015年第3期 ； 2.九华山风景区最大承载量测算研究，池州学院学报，2017年第3期 ； 3.九华山风景区旅游人才供给现状与发展对策研究，黄山学院学报，2017年第4期 。 窗体顶端 主要获奖情况： 1.池州学院青年教师教学技能大赛 二等奖， 2016年； 窗体底端 窗体底端 2.窗体顶端 2. 指导学生参加 “徽府茶行杯”2018年中国（安徽）大学生茶文化创新大赛，获个人二等奖、三等奖各1人次和团队二等奖，2018年 。 3. 池州学院 “双能型”教师 （ 2019年） ，拥有国家导游员资格证、中级茶艺师资格证、礼仪指导师证书，参与多项地方旅游规划项目， 2015年5月至2016年7月挂职于池州市旅游委员会规划与发展科。', '0', '0', '0', '2026-06-05 17:44:22', '2026-06-05 17:44:22', NULL, '安徽师范大学', NULL, '旅游服务礼仪、酒店市场营销、茶艺与茶文化 研究领域： 旅游企业管理、旅游规划与开发 主要教科研项目： 窗体底端 ', NULL, '大学旅游管理专业，获管理学学士学位； ；大学旅游管理专业，获管理学硕士学位 。 ；本科院校', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('752', '施香君', '旅游与历史文化学院', '施香君-旅游与历史文化学院', '旅游企业管理 教科研项目： ', '', '施香君，女， 1993 年 11 月生，安徽安庆人， 2016 年毕业于铜陵学院公共事业管理专业，获得管理学学士学位， 2019 年毕业于南京财经大学工商管理学院旅游管理专业，获得管理学硕士学位。 2019 年 7 月进入池州学院旅游与历史文化学院工作，担任旅游管理专业教师。 教授课程 ：旅游目的地管理；旅游电子商务 研究方向： 旅游企业管理 教科研项目： 1. 池州市社科联 2023 年一般课题 “ 池州市旅游业高质量发展水平测度及障碍因素分析 ”( 编号 :2023YB06) 2. 池州学院人文一般项目 “ 池州市数字经济与旅游业高质量发展的耦合协调及影响因素分析 ”( 项目编号 :CZ2024RW08) 研究成果： 1. 旅游网站信任度及其影响因素分析 - 以携程网为例 [J]. 南京财经大学学报 .2018 2. 基于网络文本的池州牯牛降景区旅游形象感知研究 [J]. 科技风 , 2024 联系方式： Email:1750967484@qq.com', '0', '0', '0', '2026-06-05 17:44:22', '2026-06-05 17:44:22', NULL, '硕士', NULL, NULL, NULL, '学士学位， ；大学工商管理学院旅游管理专业，获得管理学硕士学位。 ；大学学报 .', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('753', '钟奇峰', '旅游与历史文化学院', '钟奇峰-旅游与历史文化学院', '旅游管理 教科研项目： 1.《杏花村志》中的昭明信仰及十二景译介研究（安徽省高等学校人文社科重点项目（SK2019A0715）', '', '钟奇峰，男，出生于安徽合肥市肥东县，1999-2003年先后于合肥学院、合肥师范学院学习英语专业，获本科学历，2007年硕士毕业于云南大学国际关系专业，获法学硕士学位，拥有英语导游资格证，初级英语导游员，池州学院“双能型”教师，现为旅游与历史文化学院副教授。 所属系： 旅游管理 主讲课程： 旅游英语、管理沟通、管理学原理、导游英语口语 研究领域： 旅游管理 教科研项目： 1.《杏花村志》中的昭明信仰及十二景译介研究（安徽省高等学校人文社科重点项目（SK2019A0715）； 2.池州市外语旅游人才现状及需求研究（池州学院科研项目（XKY201401）； 3.旅游英语线上课程，校级质量工程（2022XXSKC03）； 4.池州学院合肥融创乐园创新创业教育实践基地, 校级质量工程（2022XSCJD01） 代表性论文： 1.现代酒店人本管理存在问题及应对措施—以杭州星级酒店为案例,《池州学院学报》，2012年第3期； 2.情景教学法在酒店英语教学中应用分析,《西北成人教育学院学报》，2015年第2期； 3.池州市外语旅游人力资源存在问题及对策研究,《西北成人教育学院学报》，2016年第2期； 4.旅游城市形象宣传研究—以池州为例，《长春工程学院学报》，2019年第3期； 5.经济发展对水资源需求预测分析，《湖北第二师范学院学报》，2020年第2期； 6.公示语现状及存在问题实证研究，《长春工程学院学报》，2020年第2期； 7.《杏花村志》中的十二景译介研究，《绵阳师范学院学报》，2020年第7期； 8.《杏花村志》中的昭明碑文英译分析—以郭西昭明庙记为例，《黑河学院学报》，2020年第7期。 主要获奖情况： 1.池州学院2013、2021年度考核“优秀”； 2.池州学院“双能型”教师，2019年5月； 3.指导第九届“挑战杯红色专项”安徽省二等奖，2021年6月； 4.指导第七届“互联网+大学生创新创业大赛” 池州学院金奖，2021年7月；安徽省铜奖，2021年11月； 5.池州学院教学成果奖一等奖，2021年11月；安徽省教学成果奖三等奖，2022年4月； 6.指导第十二届、十三届全国大学生电子商务“三创赛”池州学院三等奖、二等奖。 7.池州学院“优秀毕业实习指导老师”,2022年4月； 8.指导第八届“互联网+大学生创新创业大赛”池州学院一等奖，2022年10月。 9.2020-2021、2021-2022两学年度优秀教学质量奖，池州学院，2023年6月。 10.指导安徽省高等学校师范生教学技能大赛二等奖，安徽省教育厅，2024年11月。 11.池州学院2024年教学月活动“优秀工作者”，池州学院，2025年1月。 12.2024-2025学年度教学考核优秀，池州学院，2025年11月。', '0', '0', '0', '2026-06-05 17:44:22', '2026-06-05 17:44:22', NULL, '云南大学', NULL, '旅游英语、管理沟通、管理学原理、导游英语口语 研究领域： 旅游管理 教科研项目： ', NULL, '本科学历，；硕士毕业于云南大学国际关系专业，获法学硕士学位，拥有英语导游资格证，初级英语导游员，池州学院；大学生创新创业大赛', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('754', '黄沛', '旅游与历史文化学院', '教师', NULL, '', '教授。研究方向：旅游企业管理、研学旅游。主讲课程：旅游经济学、旅行社经营管理、旅游服务礼仪', '0', '0', '0', '2026-06-05 17:44:22', '2026-06-05 17:44:22', NULL, '', NULL, '旅游经济学、旅行社经营管理、旅游服务礼仪', NULL, '', NULL, NULL);
