INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('760', '方翀博', '旅游与历史文化学院', '教师', '智慧旅游、生态康养文旅、生态保护与游客管理', '', '教授。年硕士毕业于日本北海道大学实践环境科学专业，获环境学硕士。研究方向：智慧旅游，生态康养文旅，生态保护与游客管理。主讲课程：酒店客户管理，食品营养与卫生', '0', '0', '0', '2026-06-05 17:44:22', '2026-06-05 17:44:22', NULL, '日本北海道大学实践环境科学（硕士）', NULL, '酒店客户管理，食品营养与卫生', NULL, '日本北海道大学实践环境科学专业，环境学硕士', NULL, NULL);
