INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('766', '王丹', '旅游与历史文化学院', '教师', '旅游目的地管理、民宿经营管理、酒店管理、文旅融合、邮轮旅游', '', '教授。月获得台湾公立高雄餐旅大学的理学硕士。研究方向：旅游目的地管理、民宿经营管理、酒店管理、文旅融合、邮轮旅游。主讲课程：连锁餐饮运营与管理，旅游消费者行为，酒店数字化运营', '0', '0', '0', '2026-06-05 17:44:22', '2026-06-05 17:44:22', NULL, '月获得台湾公立高雄餐旅大学（硕士）', NULL, '连锁餐饮运营与管理，旅游消费者行为，酒店数字化运营', NULL, '得台湾公立高雄餐旅大学的理学硕士', NULL, NULL);
