INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('769', '严娟娟', '旅游与历史文化学院', '教师', '人工智能时代消费者行为研究、管理案例开发', '', '教授。研究方向：人工智能时代消费者行为研究，管理案例开发。主讲课程：《经济学原理》《人力资源管理》《质性', '0', '0', '0', '2026-06-05 17:44:22', '2026-06-05 17:44:22', NULL, NULL, NULL, '《经济学原理》《人力资源管理》《质性', NULL, NULL, NULL, NULL);
