INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('775', '吴照红', '旅游与历史文化学院', '旅游管理系负责人', '环境政策研究、生态旅游、康养旅游、农文旅融合、消费者行为研究等', '', '个人基本信息： 吴照红，女，出生于山西省长治市，2017年本科毕业于福建师范大学旅游管理专业，获管理学学士学位，2019年硕士毕业于福建农林大学农村与区域发展专业，获农学硕士学位，2024年博士毕业于中国农业科学院生态学专业，获理学博士学位，现为旅游与历史文化学院专任教师，讲师。 所属系： 旅游管理 主讲课程： 研学旅行指导师实务、旅游产品策划与设计 研究领域： 环境政策研究，生态旅游，康养旅游，农文旅融合，消费者行为研究等。 代表性论文 /著作： 1. Zhaohong Wu, Wenyuan Hua, Liangguo Luo*, Congcong Gao，Jie Zhu*, Deconstructing Adoption Intentions: Water-Fertilizer Technology in 629 Households,[J].Environmental Impact Assessment Review, 110, 2024, 107691. 2. Zhaohong Wu, Wenyuan Hua, Liangguo Luo*, Katsuya Tanaka. Technical Efficiency of Maize Production and Its Influencing Factors in the World’s Largest Groundwater Drop Funnel Area, China.[J].Agriculture. 2022, 12, 649. 3.Wenyuan Hua, Zhaohong Wu, Congcong Gao, Liangguo Luo*, Sustaining resource-orientedsanitation behaviors through informal institutions: Evidence from China,[J].Journal of Cleaner Production,425, 2023, 138886. 4. 吴照红 ,李宁辉,马朝红,冉秦,吴道宁,罗良国.湖北水稻化肥减施增效技术应用耦合协调分析[J].农村经济与科技,2021, 3,1-5. 5.高聪聪,花文元, 吴照红 ,陈之晗,郑向群,罗良国.寒旱地区农村改厕技术模式评价指标体系构建[J].农业资源与环境学报,2023, 40,1265-1274. 6.薛澜,刘恩露,杨亚红,李中恺,杨舒慧, 吴照红 .一种生物滞留联合透水铺装循环利用雨污水的洗车系统[P].CN201821795930.0, 2019-07-26.', '0', '0', '0', '2026-06-05 17:44:22', '2026-06-05 17:44:22', NULL, '福建师范大学', NULL, '研学旅行指导师实务、旅游产品策划与设计 研究领域： 环境政策研究，生态旅游，康养旅游，农文旅融合，消费者行为研究等。 代表性论文 ', NULL, '本科毕业于福建师范大学旅游管理专业，获管理学学士学位，；硕士毕业于福建农林大学农村与区域发展专业，获农学硕士学位，；博士毕业于中国农业科学院生态学专业，获理学博士学位，现为旅游与历史文化学院专任教师，讲师。 所属系： 旅游管理 主讲课程： 研学旅行指导师实务、旅游产品策划与设计 研究领域： 环境政策研究，生态旅游，康养', NULL, NULL);
