INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('791', '杨春艳', '旅游与历史文化学院', '教师', '文化产业策划', '', '教授。研究方向：文化产业策划。主讲课程：文化文化产业策划实务；影视产业经营与管理；管理学原理；会展创意策划与实务；人力资源管理；大学生传统文化素养；传统手工技艺创意开发', '0', '0', '0', '2026-06-05 17:44:22', '2026-06-05 17:44:22', NULL, NULL, NULL, '文化文化产业策划实务；影视产业经营与管理；管理学原理；会展创意策划与实务；人力资源管理；大学生传统文化素养；传统手工技艺创意开发', NULL, NULL, NULL, NULL);
