INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('874', '许苗苗', '材料与环境工程学院', '教师', '环氧树脂胶粘剂、有机硅胶粘剂、聚氨酯胶粘剂、PET发泡材料', '', '年本科毕业于安徽师范大学应用化学专业，获理学学士。研究方向：环氧树脂胶粘剂、有机硅胶粘剂、聚氨酯胶粘剂、PET发泡材料。主讲课程：涂料与粘合剂、聚合物基复合材料工程、高分子纳米复合材料、材料概论、无机无机非金属材料工厂设计', '0', '0', '0', '2026-06-05 17:47:49', '2026-06-05 17:47:49', NULL, '安徽师范大学', NULL, '涂料与粘合剂、聚合物基复合材料工程、高分子纳米复合材料、材料概论、无机无机非金属材料工厂设计', NULL, '安徽师范大学应用化学专业，理学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('875', '吴茫', '材料与环境工程学院', '教师', '生物质基高分子材料的合成及功能应用', '', '年本科毕业于安徽农业大学材料科学与工程专业，获工学学士。研究方向：生物质基高分子材料的合成及功能应用。主讲课程：《材料科学基础》、《材料选择与应用》等', '0', '0', '0', '2026-06-05 17:47:49', '2026-06-05 17:47:49', NULL, '安徽农业大学', NULL, '《材料科学基础》、《材料选择与应用》等', NULL, '安徽农业大学材料科学与工程专业，工学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('876', '龚淑芬', '材料与环境工程学院', '教师', '环境微生物研究和水污染控制', '', '年本科毕业于安庆师范大学环境科学专业获学士学位，2014年硕士。研究方向：环境微生物研究和水污染控制。主讲课程：环境工程微生物学、泵站与管道工程、环境土建工程、水污染控制工程实验、大气污染控制控制实验等', '0', '0', '0', '2026-06-05 17:47:49', '2026-06-05 17:47:49', NULL, '安庆师范大学环境科学专业（学士）', NULL, '环境工程微生物学、泵站与管道工程、环境土建工程、水污染控制工程实验、大气污染控制控制实验等', NULL, '安庆师范大学环境科学专业，学士学位', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('877', '凌雯', '材料与环境工程学院', '教师', '土壤重金属修复、植物营养学、固废资源化利用', '', '年本科毕业于安庆师范大学环境科学专业，获理学学士。研究方向：土壤重金属修复、植物营养学、固废资源化利用。主讲课程：环保设备基础', '0', '0', '0', '2026-06-05 17:47:49', '2026-06-05 17:47:49', NULL, '安庆师范大学', NULL, '环保设备基础', NULL, '安庆师范大学环境科学专业，理学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('878', '羊礼敏', '材料与环境工程学院', '羊礼敏-池州学院材料与环境工程学院', '生态毒理和环境污染修复等方面研究', '', '年本科毕业于安庆师范大学环境科学专业，获理学学士。研究方向：生态毒理和环境污染修复等方面研究。主讲课程：基础化学实验和仪器分析实验等', '0', '0', '0', '2026-06-05 17:47:49', '2026-06-05 17:47:49', NULL, '安庆师范大学', NULL, '基础化学实验和仪器分析实验等', NULL, '安庆师范大学环境科学专业，理学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('880', '吴小说', '材料与环境工程学院', '吴小说-池州学院材料与环境工程学院', '功能配位聚合物 教科研项目： 教研项目： 1.2023年校级质量工程项目线下课程“大学化学”（2023XXXKC01）', '', '个人基本信息： 吴小说，女，出生于安徽省枞阳县，2006年本科毕业于阜阳师范大学化学专业，获理学学士学位， 2009年硕士毕业于首都师范大学分析化学专业，获理学硕士学位，2020年博士毕业于南京工业大学应用化学专业，获工学博士学位，现为材料与环境工程学院新能源材料与器件专业，高级实验师。 所属教研室： 新能源材料与器件 主讲课程： 大学化学、大学化学实验、基础化学实验、材料性能测试实验等 研究领域： 功能配位聚合物 教科研项目： 教研项目： 1.2023年校级质量工程项目线下课程“大学化学”（2023XXXKC01）； 2.2015年校级教学研究项目“基于发展性评价的基础化学实验评价考核方式的研究”（2015jyxm25）。 科研项目： 1.铋/铅氧簇基配位聚合物室温磷光材料的制备及性能研究（KJ2021A1134），安徽省高等学校科学研究项目重点项目； 2.室温磷光金属氧簇基配位聚合物的合成及复合薄膜技术研究(CZ2021GP11)，池州学院国家基金培育项目（自然）。 代表性论文 / 著作： [1] Xiao-Shuo Wu , Ru Zhang, Jian-Lan Liu. An unusual Pb8clusters based coordination polymer with room-temperature orange phosphorescence. Journal of Solid State Chemistry, 2021, 301: 122298. [2] Xiao-Shuo Wu , Yue-Rou Tang, Jian-Lan Liu,et al.,Comprehensively Understanding the Steric hindrance Effect on the Coordination Sphere of Pb 2+ Ions and Photophysical Nature of Two Luminescent Pb(II)-Coordination Polymers[J]. Dalton Trans., 2019, 48, 13841-13849. [3] Xiao-Shuo Wu , Yi-Xiong Wang, Shan-Qing Li, et al. Metal ion coordination enhancing quantum efficiency of ligand phosphorescence in a double-stranded helical chain coordination polymer of Pb 2+ with nicotinic acid. Dalton Trans., 2018, 47, 14636-14643. [4]一种单核铜配合物及其制备方法和应用，专利号：ZL 2020 1 1313735.1，专利授权日：2023年10月13日', '0', '0', '0', '2026-06-05 17:47:49', '2026-06-05 17:47:49', NULL, '阜阳师范大学', NULL, '大学化学、大学化学实验、基础化学实验、材料性能测试实验等 研究领域： 功能配位聚合物 教科研项目： 教研项目： ', NULL, '本科毕业于阜阳师范大学化学专业，获理学学士学位， ；硕士毕业于首都师范大学分析化学专业，获理学硕士学位，；博士毕业于南京工业大学应用化学专业，获工学博士学位，现为材料与环境工程学院新能源材料与器件专业，高级实验师。 所属教研室： 新能源材料与器件 主讲课程： 大学化学、大学化学实验、基础化学实验、材料性能测试', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('881', '李善青', '材料与环境工程学院', '李善青-池州学院材料与环境工程学院', '材料表面微观结构及催化机理的理论模拟', '', '副教授。年本科毕业于山东大学化学专业，获理学学士。研究方向：材料表面微观结构及催化机理的理论模拟。主讲课程：结构化学、物理化学、基础化学实验4A（物化）', '0', '0', '0', '2026-06-05 17:47:49', '2026-06-05 17:47:49', NULL, '山东大学', NULL, '结构化学、物理化学、基础化学实验4A（物化）', NULL, '山东大学化学专业，理学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('882', '王阳阳', '材料与环境工程学院', '王阳阳-池州学院材料与环境工程学院', '纳米材料的制备及其在水污染治理中的研究', '', '年硕士毕业于安徽建筑大学材料学专业，获工学硕士。研究方向：纳米材料的制备及其在水污染治理中的研究。主讲课程：固体化学、功能材料概论、材料化学', '0', '0', '0', '2026-06-05 17:47:49', '2026-06-05 17:47:49', NULL, '安徽建筑大学材料学（硕士）', NULL, '固体化学、功能材料概论、材料化学', NULL, '安徽建筑大学材料学专业，工学硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('883', '施慧', '材料与环境工程学院', '施慧-池州学院材料与环境工程学院', '高分子材料', '', '年本科毕业于安徽工程大学应用化学专业，获理学学士。研究方向：高分子材料。主讲课程：物理化学、无机化学、物理化学实验', '0', '0', '0', '2026-06-05 17:47:49', '2026-06-05 17:47:49', NULL, '安徽工程大学', NULL, '物理化学、无机化学、物理化学实验', NULL, '安徽工程大学应用化学专业，理学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('884', '吴敏', '材料与环境工程学院', '吴敏-池州学院材料与环境工程学院', '木质素基功能性材料、木质素基超级电容器、木质素高值化利用', '', '获工学学士学位。研究方向：木质素基功能性材料，木质素基超级电容器，木质素高值化利用。主讲课程：化工环境保护与安全技术', '0', '0', '0', '2026-06-05 17:47:49', '2026-06-05 17:47:49', NULL, NULL, NULL, '化工环境保护与安全技术', NULL, '获工学学士、工学学士学位', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('885', '周莉', '材料与环境工程学院', '教师', '锂离子电池', '', '年本科毕业于合肥大学能源化学工程专业，获工学学士。研究方向：锂离子电池。主讲课程：基础化学实验、材料测试技术实验', '0', '0', '0', '2026-06-05 17:47:49', '2026-06-05 17:47:49', NULL, '合肥大学', NULL, '基础化学实验、材料测试技术实验', NULL, '合肥大学能源化学工程专业，工学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('886', '丁德博', '材料与环境工程学院', '丁德博-池州学院材料与环境工程学院', NULL, '', '本科。研究方向：有机反应和金属有机反应的研究、光催化CO2还原。主讲课程：材料热力学', '0', '0', '0', '2026-06-05 17:47:49', '2026-06-05 17:47:49', NULL, '', NULL, '材料热力学', NULL, '', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('888', '俞念胜', '马克思主义学院', '俞念胜-池州学院马克思主义学院', NULL, '', '俞念胜，教授，武汉大学法学博士、国家二级心理咨询师、省级线上教学名师、池州市拔尖人才、硕士生导师；兼任安徽省社科界青年学者协会理事、《安徽省情》特邀专家。 主要研究方向为执政党建设与思想政治教育原理与方法。主持国家社科基金一般项目 1项、教育部人文青年项目1项、省规划办和省社科联项目4项以及其他省厅级课题10余项；主持安徽省质量工程重大教学改革项目2项。出版专著1部、编著4部，发表学术论文30余篇。荣获市厅级奖项5项，其中“新时代提升党的组织工作质量：认识逻辑与实践路径”论文荣获安徽省社科联第十八届学术年会一等奖。 近年来，为安徽省人大代表、池州市人大、市检察院、市纪委监委、县区政府等党政机关和企事业单位开设讲座近 50场次。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, NULL, NULL, NULL, NULL, '大学法学博士、国家二级心理咨询师、省级线上教学名师、池州市拔尖人才、硕士生导师；兼任安徽省社科界青年学者协会理事、', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('889', '方旭东', '马克思主义学院', '方旭东-池州学院马克思主义学院', NULL, '', '方旭东 ， 男 ， 群众 ， 讲师 。 2018 年 1 月毕业于 上海 大学 社会 学院 社会学 专业，获 社会学博士 学位； （ 1999年—2003年7月、2007年9月—2010年7月，陕西师范大学政治经济学院社会学本科、哲学与政府管理学院社会学硕士就读） 。现为池州学院马克思主义学院 教师 。 一、项目情况 参加国家社会科学基金项目两项，主持省、市哲学社会科学规划项目各一项。 二、著作情况 专著一部，《 “家”与乡土性》（33万字），江苏人民出版社，2025； 发表学术论文 30余篇。主要期刊论文： 1、《从乡村表述危机到城乡接合度》，社会科学论坛，2019.2 ，独作； 2、《事件团结：新媒体与新乡贤共同体》，学术界（C刊），2017.11，独作； 3、《家庭与社会：一项西方社会思想史的探索 》，学术界（C刊），2016.11，《社会学》（人大复印资料）2017年第3期全文转载，独作； 4、《过度单身：一项时间社会学的探索》，中国青年研究（C刊），独作，《城市社会学研究》2016年第10期收录； 5、《剩女、个体主义及家庭》，社会科学论坛，2016.7，独作，《社会学文摘》2016年第4期转载； 6、《相亲：成家通途还是两性区隔》，2016.6，社会科学论坛，独作； 7、《后现代主义视阈下的“山寨文化”》，山西师大学报；2010.3，独作； 8、《费孝通第一次学术思想的转变：从功能主义到结构功能主义》，江南大学学报，2009.6，独作； 9、《马凌诺斯基的赞美》，天涯，2009.4，独作。 10、费孝通与《江村经济》，百年潮，2008.12；独作。 三、 获奖情况 《过度单身：一项时间社会学的探索》， 2016年中国社会学年会二等奖优秀论文； 《费孝通功能主义思想嬗变及其本土化》，陕西师范大学 2010年度研究生优秀学位论文； 《村民自治：实际运行中的困惑》， 2005年安徽省社会学年会三等奖优秀论文，2005。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, NULL, NULL, NULL, NULL, '大学 社会 学院 社会学 专业，获 社会学博士 学位； ；大学政治经济学院社会学本科、哲学与政府管理学院社会学硕士就读；大学报；', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('890', '尹文汉', '马克思主义学院', '尹文汉-池州学院马克思主义学院', NULL, '', NULL, '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, NULL, NULL, NULL, NULL, '本科毕业于湘潭大学哲学系，；大学法学硕士学位。；大学中国传统创造转化研究中心研究员，安徽省赵朴初研究会学术咨询委员会委员。曾受聘为安徽师范大学马克思主义研究中心暨安徽省高校培育和践行社会主义核心价值观智库研究员，江西师范大学宗教研究所研究员，台湾宜兰大', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('891', '牛俊友', '马克思主义学院', '牛俊友-池州学院马克思主义学院', NULL, '', '牛俊友，男， 1979年3月生，山东临沂人，中共党员，哲学博士，副教授；先后毕业于山东财经大学、西南大学、南京大学，分别获得文学学士、法学硕士和哲学博士学位；主要学术兴趣为欧陆哲学，具体从事德国古典哲学、国外马克思主义研究；近年来，先后获批省部级人文社会科学基金项目1项、厅市级项目2项、校级教改项目1项，在《自然辩证法研究》《南京师大学报》《学海》《海南大学学报》等CSSCI期刊上发表4篇学术论文，另外发表多篇省级期刊论文。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '山东财经大学、西南大学', NULL, NULL, NULL, '博士，副教授；先后毕业于山东财经大学、西南大学、南京大学，分别获得文学学士、法学硕士和哲学博士学位；主要学术兴趣为欧陆哲学，具体从事德国古典哲学、国外马克思主义研究；近年来，先后获批省部级人文社会科学基金；大学报；大学学报', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('892', '曹家慧', '马克思主义学院', '曹家慧-池州学院马克思主义学院', '音乐美学与艺术哲学方向研究', '', '曹家慧，女，1988年11月生，安徽滁州人，中共党员，哲学博士，讲师；先后毕业于淮南师范学院、南京艺术学院、华东师范大学，分别获文学（音乐学）学士、艺术学硕士和哲学博士；主要从事音乐美学与艺术哲学方向研究；近年在《交响》《黄钟》《天津音乐学院学报》《南京艺术学院学报(音乐与表演)》等刊物发表论文；现任池州学院马克思主义学院思想政治理论课程教师，同时担任习研社指导教师。 一、发表论文 1.曹家慧.德勒兹“界域—解域”的艺术生成论[D].南京艺术学院,2017. 2.曹家慧.启山林以筚路·缘人文而彰美——访音乐美学家刘承华教授[J].交响(西安音乐学院学报),2019. 3.曹家慧.茅原音乐美学学术贡献刍议[J].黄钟(武汉音乐学院学报),2020. 4.曹家慧.存在于客观的精神文化传统之中——茅原先生三个文本对音乐作品存在方式的回答[J].天津音乐学院学报,2020. 5.曹家慧.茅原音乐美学思想分期考察[J].南京艺术学院学报(音乐与表演),2020. 6.曹家慧.德勒兹与加塔利的“点-圈-线”音乐美学观，董树宝主编，美学与美育研究[M].北京：文化艺术出版社,2024. 7.曹家慧.从具身认知到感性言说:音乐语言的共情特性刍议[J].交响(西安音乐学院学报),2025. 二、获奖情况 1.论文《音乐信息中的情动主体考察》获第七届全国高等音乐教育学科发展征文比赛三等奖。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '淮南师范学院', NULL, NULL, NULL, '博士，讲师；先后毕业于淮南师范学院、南京艺术学院、华东师范大学，分别获文学；学士、艺术学硕士和哲学博士；主要从事音乐美学与艺术哲学方向研究；近年在', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('893', '郑龙发', '马克思主义学院', '郑龙发-池州学院马克思主义学院', NULL, '', '郑龙发 ，男，安徽东至人， 1970年生，马克思主义学院副教授。2000年6月毕业于复旦大学历史学系中国近现代史专业，获历史学硕士学位。2009年6月毕业于上海师范大学历史学系世界史专业，获历史学博士学位。曾担任池州学院历史与社会学系副主任，池州学院马克思主义学院副院长，池州学院皖南民俗文化与旅游发展研究院副院长。长期承担历史学本科专业世界史课程教学任务和全校各专业思想政治理论课教学任务，多次获得安徽省教学成果奖和池州学院教学质量奖。出版专著《爱德华·布莱登泛非主义思想研究》吉林人民出版社；《韩国独立运动政党与社团研究》中国社会科学出版社两部。在《安徽史学》、《韩国研究论丛》、韩国《禅文化研究》等学术期刊发表论文多篇。主持安徽省和池州学院教学研究项目和人才科研项目多项。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '复旦大学', NULL, NULL, NULL, '大学历史学系中国近现代史专业，获历史学硕士学位。；大学历史学系世界史专业，获历史学博士学位。曾担任池州学院历史与社会学系副主任，池州学院马克思主义学院副院长，池州学院皖南民俗文化与旅游发展研究院副院长。长期承担历史学本科专业世界史课程教学任务和全校各专业', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('894', '刘振宏', '马克思主义学院', '刘振宏-池州学院马克思主义学院', NULL, '', '刘振宏，男，中共党员，副教授（ 2016），法学博士（2011）。2011年6月毕业于安徽师范大学政治学院马克思主义基本原理专业，获法学博士学位；中国人民大学经济学院（2016.09-2017.06）访问学者；复旦大学马克思主义学院（2023.09-2024.06）访问学者。现为池州学院马克思主义学院教师。 一、项目情况 主持安徽省高校人文社科重大项目 2项，安徽省哲学社会科学一般项目1项，安徽省高校"三全育人"综合改革和思想政治能力提升计划项目3项（弘扬社会主义核心价值观名师工作室、教学重点难点项目、教学成果推广），省质量工程（重点）项目2项，横向项目1项。 二、著作情况 主编《毛泽东思想和中国特色社会主义理论体系立体化实践教程》（辽宁大学出版社， 2019），《立德树人视域下医学生医德教育研究》（安徽师范大学出版社，2021） 三、获奖情况 1、安徽省教学成果一等奖，排名第三，2020年； 2、安徽省首届高校思想政治课教学展示暨教师说课比赛二等奖（2019年，研究生思政课）', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '安徽师范大学政治学院', NULL, NULL, NULL, '博士；大学政治学院马克思主义基本原理专业，获法学博士学位；中国人民大学经济学院；大学马克思主义学院', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('895', '王发友', '马克思主义学院', '王发友-池州学院马克思主义学院', NULL, '', '王发友，男，汉族，中共党员，教授，博士。 2016年6月毕业于东南大学人文学院科学技术哲学专业，获博士学位。现为池州学院马克思主义学院教工第六支部书记，兼任中国自然辩证法研究会问题哲学专业委员会副主任。 一、项目情况 1.主持省级高校思想政治工作能力提升项目——弘扬核心价值观名师工作室“高校《毛泽东思想与中国特色社会主义理论体系概论》课程实践教学研究（思政理论课教师）”，项目编号Sztsjh2019-2-41，二类，已结项； 2.主持省级质量工程项目-思政课教研项目“‘三全育人’视域下职业院校思政课实践教学模式探究”，项目编号2019szjy087，已结项； 3.主持2017年度安徽高校人文社会科学研究重点项目“科学哲学视域下的综合进化论研究”（SK2017A0892），三类，已结项； 4.参与2017年度教育部人文社会科学研究一般项目（示范马克思主义学院和优秀教学科研团队建设项目）——示范优秀教学科研团队建设项目：《职业院校思想政治理论课实践教学研究》（17JDSZK031），三类，排名第三，已结项； 5.主持2020年安徽省“三全育人”试点省建设暨高校思想政治工作能力提升项目：思想政治理论课实践教学团队（sztsjh-2020-7-17），三类，已结项。 二、著作情况 1.出版专著《科学哲学视域下的综合进化论研究》，2020年8月，安徽师范大学出版社，书号：ISBN978-7-5676-3503-6，独著，22.7万字。 2.论文《论克洛斯的工程设计思想》，2013年8月发表于《自然辩证法研究》ISSN1000-8934;CN11-1649/B;第8期，二类，CSSCI，独撰。 3.论文《合成生物环境释放的风险管控》，2014年10月，《自然辩证法研究》（ISSN1000-8934）,总第320期，二类，CSSCI，独撰； 4.论文《合成生物技术的追问与反思》，2015年7月，《自然辩证法研究》（ISSN1000-8934）,总第329期，二类，CSSCI，独撰。 5.论文《综合进化论的两条进化路径》，2019年6月，《安徽工业大学学报》（社会科学版）（ISSN1671—9247），总第148期，三类，排名第一； 6.论文《师德建设的伦理-实践向度》，2019年11月，《盐城师范学院学报》（人文社会科学版）（ISSN1003—6873），总第180期，三类，独撰； 7.论文《The Rationality of the Evolutionary Synthesis and Its Competing Theories》，2023年3月，《Iris Online Journal of Arts and Social Sciences》， 独撰； 8．论文《Promoting the Innovation and Development of Problem Philosophy In The New Era: Summary of the 3rd National Academic Symposium on Problem Philosophy》，2023年6月，《Iris Online Journal of Arts and Social Sciences》，排名第一。 三、获奖情况 1．在2018-2020学年“三育人”先进个人评选活动中，荣获管理育人先进个人荣誉称号； 2. 在 2023年度师德考核中获得优秀等次； 3.在2023年度考核中获得优秀等次； 4.在2023-2024学年度教师教学工作年度考核中获得优秀等次。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '东南大学人文学院', NULL, NULL, NULL, '博士。 ；大学人文学院科学技术哲学专业，获博士学位。现为池州学院马克思主义学院教工第六支部书记，兼任中国自然辩证法研究会问题哲学专业委员会副主任。 一、项目情况 ；大学出版社，书号：', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('896', '孙宇', '马克思主义学院', '孙宇-池州学院马克思主义学院', NULL, '', '孙宇，男，中共党员，副教授。 2016年6月毕业于中南大学马克思主义基本原理专业，获法学博士学位。现为池州学院马克思主义学院专任教师。 先后主持完成省级课题 3个，厅级课题2个，出版专著1本，发表论文10余篇，其中C刊3篇。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '中南大学', NULL, NULL, NULL, '大学马克思主义基本原理专业，获法学博士学位。现为池州学院马克思主义学院专任教师。 先后主持完成省级课题 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('897', '黎俊祥', '马克思主义学院', '黎俊祥-池州学院马克思主义学院', NULL, '', '黎俊祥，男，中共党员，副教授，博士。 2002年6月毕业于安徽师范大学社会学院历史教育专业，获学士学位；2005年7月毕业于安徽师范大学社会学院中国近现代史专业，获硕士学位；2011年7月毕业于安徽大学历史系历史文献学专业，获博士学位。现为池州学院马克思主义学院系主任。 一、项目情况 1、2006年度安徽省高校青年教师科研资助计划项目：晚清统治集团与清末新政改革（2006jqw182）。 2、2007年度池州学院教研项目：《中国近代史》教学资源库建设（2007XJ013）。 3、2010年省级重点学科C类专门史委托课题：“近代史料笔记与社会史研究”（ZMS201001）。 4、2011年安徽省教育厅优秀青年人才基金项目：“晚晴史料笔记与社会史研究”（2011SQRW150）。 5、2013年，“应用型高等教育历史学专业保障体系建设研究”，池州学院应用性高等教育保障体系建设项目。 6、2014年，近代以来皖南灾荒与农业生产研究(XKY201414)，池州学院2014年度研究中心项目。 7、2014年，清末新政时期的安徽民变研究(2014ZMS001)，池州学院省级重点学科专门史委托项目。 8、2016年，“中国近现代史纲要”实践教学模式改革研究，池州学院教学研究项目。 9、2018年，“中国近现代史纲要”精品线下课程，安徽省教育厅质量工程项目。 10、2021年，“池州地区红色文化资源传承与创新研究”，安徽省教育厅人文社科重点研究项目。 11、2021年，“新时代“形势与政策”课程改革创新路径研究 ——以州学院为例”，安徽省思想政治理论课教研项目。 二、著作情况 1、参编《大学生传统文化素养》，江苏凤凰美术出版社，2014年出版。 2、参编《池州抗日战争史稿》，中央文献出版社，2015年出版。 3、参编《池州抗日文化史料辑录》，中央文献出版社，2018年版。 4、独著《近代史料笔记研究》，安徽师范大学出版社，2022年版。 获奖情况 1、2008年池州学院青年教师教学技能大赛三等奖。 2、2006-2008年池州学院“优秀辅导员”。 3、2010年，“《中国近现代史纲要》网络教学平台的构建”获校级优秀教学成果奖二等奖。 4、2012年，获安徽省教学技能竞赛指导奖，（三等奖二人次）。 5、2012年，“中国近现代史纲要”获池州学院2011-2012学年池州学院优秀多媒体课件奖。 6、2013年，“创新历史学专业实践教学活动的探索”获省级教学成果奖三等奖。 7、2013年，获第五届安徽省高等学校师范生教学技能比赛竞赛本科文科三等奖指导奖（三等奖1人次）。 8、2013年，“中国近代史”，获池州学院2012年度优秀试卷奖。 9、2013年，“中国通史2”，获2012-2013学年池州学院优秀课内实践教学教案奖。 10、2014年，“史学论文写作”，获2013-2014学年优秀课内实践教学教案奖。 11、2017年，参编《池州抗日战争史稿》，获池州市第五届社科奖一等奖（2014-2015）。 12、2017年，《新四军七师沿江团池州抗战述评》，获池州市纪念中国人民解放军建军90周年暨新四军成立80周年征文一等奖。 13、2017年，“中国近代史”，获2015-2016学年优秀多媒体教学课件奖。 14、2017年，获池州学院“优秀共产党员”荣誉称号。 15、2018年，获池州学院“优秀共产党员”荣誉称号。 16、2018年，“以实践能力为核心的师范类本科生教学技能培养模式探究”，校级教学成果奖二等奖 17、2019年，获池州学院“最美教师”提名奖。 18、2019年，获池州学院2016-2017、2017-2018两学年度优秀教学质量奖', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '安徽师范大学社会学院', NULL, NULL, NULL, '博士。 ；大学社会学院历史教育专业，获学士学位；；大学社会学院中国近现代史专业，获硕士学位；', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('898', '庞超', '马克思主义学院', '庞超 -池州学院马克思主义学院', NULL, '', '庞超，男，群众，讲师，哲学博士。 2017年毕业于四川大学哲学系，2024年12月毕业于南京大学哲学学院，获哲学博士学位；2020年—2022年曾受国家留学基金委（CSC）资助于德国耶拿大学哲学系联合培养。现为池州学院马克思主义学院讲师。 研究方向为德国古典哲学、实践哲学，曾在《中国社会科学报》、大学学报发表论文 2篇；曾参与过国社科一般项目并结项出版。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '四川大学', NULL, NULL, NULL, '博士。 ；大学哲学系，；大学哲学学院，获哲学博士学位；', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('899', '屈伯文', '马克思主义学院', '屈伯文-池州学院马克思主义学院', NULL, '', '屈伯文，男，群众，副教授，博士。 2018年6月毕业于同济大学人文学院外国哲学专业，获哲学博士学位。现为池州学院马克思主义学院教师。主持省部级科研项目2项，发表《复旦学报（社会科学版）》等核心期刊论文若干篇，译有《西方文明的统一》（大象出版社2013年版）等。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '同济大学人文学院', NULL, NULL, NULL, '博士。 ；大学人文学院外国哲学专业，获哲学博士学位。现为池州学院马克思主义学院教师。主持省部级科研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('900', '王海燕', '马克思主义学院', '王海燕-池州学院马克思主义学院', NULL, '', '王海燕 ， 女 ， 中共党员 ， 博士研究生 。 2024 年 12 月毕业于 安徽 大学 哲学 学院 中国哲学 专业，获 哲学博士 学位。现为池州学院马克思主义学院 思政课教师。 一、著作情况 [1]王海燕. 葛洪、孔子隐士观异同探析 [J].齐齐哈尔大学学报（哲学社会科学版），2021 . [2]王海燕. 道家与儒家君主为政之道比较分析 [J].沈阳师范大学学报（社会科学版） ， 2022. [3]王海燕.道家成就理想人格的双重路径[J].黑河学院学报，2023.', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, NULL, NULL, NULL, NULL, '博士研究生 。 ；大学 哲学 学院 中国哲学 专业，获 哲学博士 学位。现为池州学院马克思主义学院 思政课教师。 一、著作情况 ；大学学报', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('901', '程莉', '马克思主义学院', '程莉-池州学院马克思主义学院', NULL, '', '程莉，女， 1969年12月生，安徽池州人。旅游与历史文化学院副教授、博士。1989年7月毕业于安庆师范学院外语系；1998年7月毕业于南京大学历史系，获历史学硕士 学位； 2005年7月，毕业于南京大学历史系，获历史学博士学位。2010年9月至2011年7月，南京大学访问学者。2016年11月，赴马来西亚博特拉大学作为期一周访问。 E-mail:2443253407@qq.com 研究领域和方向 中国近现代史；中国近现代经济史 主讲课程 中国历史与文化（ 3）；中华人民共和国史；中国经济史；中国近现代史纲要 论文 1.试论周学熙民初财政改革，学海，2005年第1期。 2.袁世凯与周学熙，广西社会科学，2005年第2期。 3.周学熙采取公司制组织企业的特点及启示，池州师专学报，2007年第4期。 4.周学熙资本企业家族式管理之成败分析，池州学院学报，2008年第6期。 5 .东至周氏家族人才辈出及原因分析，池州学院学报，2010年第4期。 6.皖籍实业家周学熙与近代华北社会变迁，安庆师范学院学报（社会科学版），2012年第5期。 7.周馥玄孙启晋先生祖籍祭扫记，池州学院学报，2015年第4期。 8.省历史学会2016年年会暨“东至周氏家族与区域历史文化”学术研讨会综述，安徽社科界，2016年第11期。 9.东至周家家风家训分析，池州学院学报，2017年第4期。 10李鸿章、孙家鼐所撰周馥父母墓志铭考辨，内蒙古科技与经济，2018年第20期。 论著、教材 1.出版专著《近代实业家周学熙研究》，合肥工业大学出版社，2006年版。 2.参编汪志国教授主编的教材《中国历史与文化》 （下）》（安徽省高校 “十一五”省级规划教材），合肥工业大学出版社2005年版，中国 经济史部分，约 7万字。 课题 1.参与谈家胜主持省教委课题：池州现代茶叶经济史研究，2000年。 2.主持池州学院人文社会科学重点研究项目：北洋实业巨擘——东至人周学熙企业经营管理思想研究，项目编号：2006xk01。 3.主持安徽省教育厅人文社科一般项目：东至周氏家族与近代华北社会变迁，项目编号：2010sk515。 4.主持安徽省第三批C类重点学科（专门史）委托项目，近代苏皖两省实业家比较研究，项目编号ZMS201004，池州学院首批特色专业建设项目。 参加学术会议提交论文 1.2009年参加安徽省历史学年会暨“安徽三大家族与近代中国实业”研讨会，提文《东至周氏家族人才辈出及原因分析》著录在专著《安徽三大家族与近代中国实业研究》（施立业，李良玉主编，合肥工业大学出版社2010年版）中。 2.2015年参加在首都师范大学历史学院召开的《纪念周馥诞辰178周年暨周氏家族与近代中国社会文化变迁研讨会》，提交论文《动荡中的崛起，变革中的发展——东至周氏家族百年研究》并作发言。 3.2016年皖江文化学术研讨会提交论文《 东至周氏家族研究：直隶工艺总局与近代华北社会变迁 》，已经著录于 2016年皖江文化论文集中。 4.2016年安徽省历史学年会暨“东至周氏家族与区域历史文化”学术研讨会提交论文《李鸿章、孙家鼐所撰周馥父母墓志铭考辨》。 5.2017年安徽省历史学会学习十九大精神暨“纪念安徽省建省350周年”学术年会提交论文《近代苏皖两省实业家统计及分析》。 6.2018年提交安徽省历史学会2018年会暨“纪念改革开放四十周年”学术研讨会论文《论企业发展道路与地方经济关系——以苏皖两省近代典型实业家为研究中心》。 获奖情况 1.2007年池州市社会科学奖二等奖 2.《中国历史与文化（3）》课程教案获2008-2009学年优秀教案奖 3.2009年度考核获优秀等次 4.2013-2014学年第1学期《中华人民共和国史》课程试卷获校级优秀试卷奖', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '安庆师范学院', NULL, NULL, NULL, '博士。；大学历史系，获历史学硕士 学位； ；大学历史系，获历史学博士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('902', '张暴默', '马克思主义学院', '张暴默-池州学院马克思主义学院', '《习近平新时代中国特色社会主义思想概论》、《中国近现代史纲要》课的教学工作', '', '张暴默 ， 女 ， 中共党员 ， 法学硕士 。 2020 年 6 月毕业于 中共四川省委党校中共党史 专业，获 法学硕士 学位 。 现为池州学院马克思主义学院 教师 ，主要从事《习近平新时代中国特色社会主义思想概论》、《中国近现代史纲要》课的教学工作。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, NULL, NULL, NULL, NULL, '硕士 。 ；硕士 学位 。 现为池州学院马克思主义学院 教师 ，主要从事', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('903', '余道棋', '马克思主义学院', '余道棋-池州学院马克思主义学院', NULL, '', '余道棋 ， 女 ， 中共党员 ， 助教 ， 硕士研究生 。 2023 年 6 月毕业于 河海 大学 马克思主义 学院 马克思主义哲学 专业，获 哲学硕士 学位。现为池州学院马克思主义学院 思政课教师，兼职 2024级思想政治教育专业辅导员 。 2025年9月，获池州学院智慧教学大赛人文社科组二等奖； 2025年7月，获池州市大中小学思政课一体化建设论文评选三等奖。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, NULL, NULL, NULL, NULL, '硕士研究生 。 ；大学 马克思主义 学院 马克思主义哲学 专业，获 哲学硕士 学位。现为池州学院马克思主义学院 思政课教师，兼职 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('904', '朱娟娟', '马克思主义学院', '朱娟娟-池州学院马克思主义学院', NULL, '', NULL, '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, NULL, NULL, NULL, NULL, '大学思想政治教育专业，获法学硕士学位。主要从事思想政治理论课教学，主讲:毛泽东思想和中国特色社会主义理论体系概论。 一、主持的项目 ；本科院校辅导员在大学生资助工作中的角色定位，项目编号：；大学生思想政治教育生活化中的路径探析', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('905', '周芳', '马克思主义学院', '周芳-池州学院马克思主义学院', NULL, '', '周芳，女，汉族， 1981年12月生，安徽潜山人，中共党员，现任池州学院马克思主义学院思政课教师，副教授。2003年6月毕业于安庆师范学院思想政治教育专业，获法学学士学位，2006年9月至2009年6月在南京师范大学在职攻读硕士学位，获马克思主义理论与思想政治教育专业硕士学位。2003年9月至今一直从事思想政治理论课教学和研究，系统讲授过《毛泽东思想概论》、《邓小平理论和“三个代表”重要思想概论》、《毛泽东思想和中国特色社会主义理论体系概论》、《大学生德行素养》和《形势与政策》等课程，参与编写校本教材《形势与政策》、《大学生德行素养》。主持校级课题三项，发表学术论文多篇，先后获得校级优秀教学质量奖、优秀多媒体教学课件奖等荣誉称号。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '安庆师范学院', NULL, NULL, NULL, '学士学位，；大学在职攻读硕士学位，获马克思主义理论与思想政治教育专业硕士学位。；大学生德行素养', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('906', '张燕', '马克思主义学院', '张燕-池州学院马克思主义学院', NULL, '', '张燕，女，中共党员，助教，硕士研究生。 2024年6月毕业于安徽大学马克思主义学院思想政治教育专业，获硕士学位。现为池州学院马克思主义学院教师。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '安徽大学马克思主义学院', NULL, NULL, NULL, '硕士研究生。 ；大学马克思主义学院思想政治教育专业，获硕士学位。现为池州学院马克思主义学院教师。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('907', '檀向群', '马克思主义学院', '檀向群-池州学院马克思主义学院', NULL, '', '檀向群， 女 ，中共党员，副教授，硕士。 2012年7月毕业于安徽大学历史系历史文献专业，获硕士学位；2022年赴北京师范大学访学。现为池州学院马克思主义学院毛泽东思想和中国特色社会主义理论体系概论 系主任、教师第五党支部书记，池州市齐山平天湖文化研究会副会长 。 一、项目情况 主持省社科项目 2项，市校级项目多项。 二、著作情况 出版著作 1部，发表论文多篇。 三、 获奖情况 获池州市社科第二届三等奖、第四届三等奖。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '安徽大学', NULL, NULL, NULL, '硕士。 ；大学历史系历史文献专业，获硕士学位；；大学访学。现为池州学院马克思主义学院毛泽东思想和中国特色社会主义理论体系概论 系主任、教师第五党支部书记，池州市齐山平天湖文化研究会副会长 。 一、项目情况 主持省社科项目 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('908', '冯懿', '马克思主义学院', '冯懿-池州学院马克思主义学院', '马克思现代性思想以及道德批判理论研究', '', '冯懿，女， 1988年11月生，江苏省沭阳人，中共党员，毕业于云南农业大学，获得法学硕士学位；学术兴趣为马克思主义伦理学，主要从事马克思现代性思想以及道德批判理论研究；近年来，先后参与省部级人文社会科学基金项目1项、厅市级项目2项，在省级期刊发表4篇学术论文。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '云南农业大学', NULL, NULL, NULL, '大学，获得法学硕士学位；学术兴趣为马克思主义伦理学，主要从事马克思现代性思想以及道德批判理论研究；近年来，先后参与省部级人文社会科学基金项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('909', '杨慧宇', '马克思主义学院', '杨慧宇-池州学院马克思主义学院', NULL, '', '杨慧宇，女，中共党员，副教授，硕士研究生。 2009年06月毕业于安徽师范大学政法学院思想政治教育专业，获法学学士学位；2012年6月毕业于安徽师范大学政法学院中国哲学专业，获哲学硕士学位。现为池州学院马克思主义学院专职教师。 一、项目情况 1、主持池州学院校级人文一般项目：老子“自然”思想与池州生态文明建设（2015RW001），已结项； 2、主持池州学院校级人文重点项目：马克思主义生态观视域下大学生环保意识提升路径研究——以池州学院为例（CZRWZ04），已结项； 3、主持安徽省“三全育人”试点省建设暨高校思想政治工作能力提升项目——安徽省思政课“精彩一课”（sztsjh-2022-11-38），已结项。 二、著作情况 1、《高校“形势与政策”课教师素质研究》，第一作者，发表于《襄阳职业技术学院学报》2016年第七期； 2、《辅导员角色与高校思政教育工作》，独撰，发表于《池州学院学报》2017年第三期； 3、《老子“自然”思想与生态文明建设》， 独撰， 发表于《池州学院学报》 2018年第四期； 4、《新时代高校思想政治理论课教学评价体系研究》，独撰，发表于《池州学院学报》2019年第六期； 5、《新发展理念下大学生生态意识培育研究》，独撰，发表于《赤峰学院学报》2024年第七期。 获奖情况 1、2013年4月，获得池州学院校级“优秀教学新手”称号； 2、2015年6月，获池州学院青年教师教学技能大赛一等奖； 3、2019年4月，获得池州学院青年教师教学竞赛人文社会科学组第一名； 4、2019年4月，获安徽省第四届普通高校青年教师教学竞赛三等奖； 5、2021年9月，获安徽省第五届普通高校青年教师教学竞赛一等奖； 6、2022年9月，获得池州学院“教书育人楷模”荣誉称号； 7、 2023年4月，获安徽省质量工程“教坛新秀”荣誉称号； 8、 2024年9月，获池州学院“优秀教师” 荣誉 称号。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '安徽师范大学政法学院', NULL, NULL, NULL, '硕士研究生。 ；大学政法学院思想政治教育专业，获法学学士学位；；大学政法学院中国哲学专业，获哲学硕士学位。现为池州学院马克思主义学院专职教师。 一、项目情况 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('910', '余丹', '马克思主义学院', '余丹-池州学院马克思主义学院', NULL, '', '余丹，女，中共党员，副教授，硕士研究生。 2010年6月毕业于桂林理工大学人文社会科学学院马克思主义基本原理专业，获法学学位。 一、项目情况 1、主持安徽省哲学社会科学青年项目：《“微时代”下大学生社会责任感教育模式研究》。 2、主持安徽省教育厅人文重点项目：“优良家风融入高校思想政治教育的内在机理与优化策略研究—以皖南地域家风文化为例”。 3、主持安徽省教育厅人文重点项目：“中华优秀传统文化融入新时代廉洁文化建设研究”。 4、主持安徽省质量工程重点教研项目：“大思政课”视阈下高校思想政治理论课实践效应激活研究一以池州学院为例”。 二、参编教材 1、《大学生德行素养》，凤凰出版社，2014年8月。 2、《思想政治理论课学训教程》，东北大学出版社，2015年3月。 三、获奖情况 1、获省级教学成果三等奖，排名第一。 2、获安徽省第六届高校青年教师教学竞赛三等奖。 3、获校级教坛新秀荣誉称号 4、获校级线上教学优秀教师奖 5、获校级青年教师技能大赛一等奖”', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '桂林理工大学', NULL, NULL, NULL, '硕士研究生。 ；大学人文社会科学学院马克思主义基本原理专业，获法学学位。 一、项目情况 ；大学生社会责任感教育模式研究', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('911', '刘伟', '马克思主义学院', '刘伟 -池州学院马克思主义学院', NULL, '', '刘伟，男，中共党员，助教，硕士研究生。 2023年6月毕业于安徽医科大学马克思主义学院马克思主义基本原理专业，获法学硕士学位。现为池州学院马克思主义学院专职思政课教师。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '安徽医科大学', NULL, NULL, NULL, '硕士研究生。 ；大学马克思主义学院马克思主义基本原理专业，获法学硕士学位。现为池州学院马克思主义学院专职思政课教师。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('912', '黄若男', '马克思主义学院', '黄若男-池州学院马克思主义学院', NULL, '', '黄若男，女， 1997年9月生，河南驻马店人，中共党员。毕业于东北石油大学马克思主义学院，获法学硕士学位，曾获研究生国家奖学金、东北石油大学优秀毕业生等荣誉。现任池州学院马克思主义学院专职思政课教师，主要讲授《马克思主义基本原理》《中国近现代史纲要》《形势与政策》等课程，2025年7月获得池州市大中小学思政课一体化建设专题论文评选二等奖。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '东北石油大学', NULL, NULL, NULL, '大学马克思主义学院，获法学硕士学位，曾获研究生国家奖学金、东北石油大学优秀毕业生等荣誉。现任池州学院马克思主义学院专职思政课教师，主要讲授', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('913', '施雯', '马克思主义学院', '施雯-池州学院马克思主义学院', NULL, '', '施雯，女 ， 中共党员 ， 助教 ， 硕士。 2021年6月毕业于安徽工程大学马克思主义学院思想政治教育专业，获法学硕士学位；现为池州学院马克思主义学院专职思政课教师 一、项目情况 2022.11月参与池州学院“新时代老田吴氏家风”校级人文一般项目； 2023.9月主持池州市社科联“家教家庭家风在基层社会治理中作用研究—以池州家风文化馆的建设为例 ”项目； 2024.10参与池州学院“马克思分配正义思想的当代价值研究”校级人文一般项目； 二、获奖情况 2024.12获池州市举办大中小学思政课一体化教学比赛大学学段优秀个人奖； 2024.06获2022-2023.2023-2024两学年年度优秀教学质量奖； 2025.06获安徽省青教赛池州学院初赛一等奖； 2025.09获池州学院三下乡社会实践先进个人。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '安徽工程大学', NULL, NULL, NULL, '硕士。 ；大学马克思主义学院思想政治教育专业，获法学硕士学位；现为池州学院马克思主义学院专职思政课教师 一、项目情况 ；大学学段优秀个人奖； ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('914', '罗晓彤', '马克思主义学院', '罗晓彤-池州学院马克思主义学院', NULL, '', '罗晓彤，女， 1998生，中共党员，历史学硕士，主要研究方向中国近现代史，主要讲授课程《中国近现代史纲要》、《形势与政策》。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, NULL, NULL, NULL, NULL, '硕士，主要研究方向中国近现代史，主要讲授课程', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('915', '陈鑫', '马克思主义学院', '陈鑫-池州学院马克思主义学院', NULL, '', '陈鑫，男， 1980年9月生，安徽池州人，中共党员，池州学院马克思主义学院教师，副教授。2002年7月毕业于安徽师范大学思想政治教育专业；2009年6月， 毕业于 南京师范大学 思想政治教育专业， 获马克思主义理论与思想政治教育专业硕士学位。 2002年7月至今一直在池州学院从事思想政治理论课教学，先后担任《马克思主义哲学原理》、《思想道德修养》、《思想道德修养与法律基础》、《形势与政策》和《思想道德与法治》课程的教学，主要研究方向为高校思想政治教育。 一、项目情况 1.主持池州学院教研课题《高校思想政治理论课有效教学研究》，已结项； 2.主持安徽省教育厅思政处专项课题《高校和谐校园文化与思想政治教育的良性互动研究》，已结项； 3.主持安徽省本科高校思政理论课中青年教师教学能力拓展项目，已结项； 4.主持安徽省教育厅课题《文化多元化背景下高校思想政治理论课有效教学研究》，已结项； 5.主持池州学院人文重点课题《中国特色社会主义文化自信研究》，已结项； 6.主持安徽省教育厅“三全育人”课题《新时代大学生文化自信培育研究》，已结项。 二、著作情况 1.《思想政治理论课学训教材》，东北大学出版社，2015年，副主编； 2.《新时期大学生成长成才实践与探索》，合肥工业大学出版社，2017年，副主编； 3.《哲学与价值观教育》，上海大学出版社，2017年，第二著者； 4.《高校和谐校园文化与思想政治教育的良性互动研究》，池州学院学报，2012年第五期； 5.《当代大学生诚信教育现状及对策研究》，合肥工业大学学报（社会科学版），2013年第一期，独著； 6.《论高校思想政治理论课有效教学》，池州学院学报，2014年第二期，第一著者； 7.《思想政治教育视阈下当代大学生文化自信培育路径研究》，阜阳师范学院学报（社会科学版），2017年第五期，独著； 8.《论文化自信的理论渊源与时代价值》，安徽理工大学学报（社会科学版），2020年第六期，独著。 三、教学获奖情况 1.2005年5月，获池州学院2002—2004两学年度教学质量优秀奖； 2.2006年6月，获池州学院教师课堂教学技能比赛二等奖； 3.2007年3月，获池州学院2004—2006两学年度教学质量优秀奖； 4.2010年1月，获池州学院优秀多媒体课件奖； 5.2010年6月，获“池州学院教坛新秀”称号； 6.2010年12月，获池州学院2008—2010两学年教学质量优秀奖； 7.2013年1月，获池州学院2010—2012两学年度教学质量优秀奖； 8.2015年1月，获池州学院2012—2014两学年教学质量优秀奖； 12.2012年11月，获安徽省多媒体软件大赛多媒体课件类二等奖； 13.2012年11月，获安徽省多媒体软件大赛精品课程类三等奖； 14.2015年9月，获“安徽省教坛新秀”称号。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '安徽师范大学', NULL, NULL, NULL, '大学思想政治教育专业；；大学 思想政治教育专业， 获马克思主义理论与思想政治教育专业硕士学位。 ；本科高校思政理论课中青年教师教学能力拓展项目，已结项； ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('916', '杨昌和', '马克思主义学院', '杨昌和-池州学院马克思主义学院', NULL, '', '杨昌和， 1977年1月生，安徽池州人，中共党员。2002年毕业安徽师范大学，法学学士。现任池州学院马克思主义学院专职教师，主讲课程《思想道德修养与法律基础》、《公务员管理》、《形势与政策》等。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, NULL, NULL, NULL, NULL, '大学，法学学士。现任池州学院马克思主义学院专职教师，主讲课程', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('917', '潘蕾', '马克思主义学院', '潘蕾-池州学院马克思主义学院', NULL, '', '潘蕾，女， 1977年6月生，安徽师范大学经济法政学院毕业，法学学士。现任池州学院马克思主义学院讲师。主要从事思想政治理论课的教学，讲授过《思想道德修养与法律基础》、《形势与政策》、《大学生德行素养》、《伦理学》、《国际关系》、《思想政治教育学原理》、《马克思主义经典著作选读》等课程，参与多项厅级、校级科研和教研课题，参编教材《思想道德修养与法律基础》、《思想道德修养与法律基础课教学案例解析》、《形势与政策》、《大学生德行素养》等。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '大学经济法政学院', NULL, NULL, NULL, '大学经济法政学院毕业，法学学士。现任池州学院马克思主义学院讲师。主要从事思想政治理论课的教学，讲授过；大学生德行素养；大学生德行素养', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('918', '彭梅', '马克思主义学院', '彭梅-池州学院马克思主义学院', NULL, '', '彭梅 ， 女 ， 中共党员 ， 讲师 ， 硕士研究生 。 2012 年 7 月毕业于 西华师范 大学 马克思主义 学院 思想政治教育 专业，获 法学硕士 学位。现为池州学院马克思主义学院 《 思想道德与法治 》 课程专职教师 。 一、项目情况 参与 2014年度安徽省哲学社会科学规划青年项目(AHSKQ2014D75)； 参与安徽省高等学校质量工程重大教学项目 (2017jyxm0576,2018jyxm0636)、安徽省教育厅人文社科重点项目(SK2018A0624)、池州学院人文社科重点项目(Z2018DJZ02)； 二、著作情况 1.参与编全国普通高等院校十二五规划课程教材《形势与政策》，撰写第十一讲“构筑新型大国关系”。在21世纪全国普通高等院校思想政治理论课规划教材《思想政治理论课学训教程》一书中撰写思想道德修养与法律基础篇“第五章”内容。 2.发表论文：《提升高校思想政治理论课实践教学实效性探究》，发表于《文教资料》；《高校女教职工身心健康发展探析》，发表于《祖国》；《安徽省高校思想政治理论课实效性现状分析》，发表于《池州学院学报》；《“微时代”背景下大学生社会责任感探析》，发表于《菏泽学院学报》；《新时代家庭观探究》发表于《时代人物》。 三、获奖情况 2013年12月获得池州学院优秀多媒体教学课件奖； 2016年1月获池州学院优秀教案奖； 2016年5月参与青年教师教学技能大赛获得二等奖； 2017年4月获得池州学院年度优秀课内实践教学教案奖； 2019年11月获校级教学成果奖二等奖（思政类）； 2020年1月获省级教学成果奖三等奖； 2021年获校级教学成果奖一等奖； 2023年度考核中获得优秀等次； 2023年度师德考核中获得优秀等次 2025年获青教赛校级二等奖（思政专项）。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, NULL, NULL, NULL, NULL, '硕士研究生 。 ；大学 马克思主义 学院 思想政治教育 专业，获 法学硕士 学位。现为池州学院马克思主义学院 ；大学生社会责任感探析', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('919', '钱景', '马克思主义学院', '钱景-池州学院马克思主义学院', NULL, '', '钱景 ， 女 ， 中共党员 ， 讲师 ， 校级 “双能型”教师，硕士研究生 。 2020 年 7 月毕业于 安徽师范大学法学院宪法学与行政法学 专业，获 法学硕士 学位。现为池州学院马克思主义学院 专职思政课教师，池州市人民检察院特邀检察官助理 。 近年来，主持多项市级 科研项目、 校级 教研项目 ， 参与多项省级教研、科研项目； 发表学术论文多篇 ； 曾获市级法治建设理论文章和调研报告评选优秀奖、第五届全国高校教师教学创新比赛校赛优秀奖；多次指导学生参加安徽省 “未来律师辩论赛”获得二、三等奖，校级“大学生讲思政课”比赛二等奖。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, NULL, NULL, NULL, NULL, '硕士研究生 。 ；大学法学院宪法学与行政法学 专业，获 法学硕士 学位。现为池州学院马克思主义学院 专职思政课教师，池州市人民检察院特邀检察官助理 。 近年来，主持多项市级 科研项目、 校级 教研项目 ， 参与多项省级教研；大学生讲思政课', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('920', '余芳芸', '马克思主义学院', '余芳芸-池州学院马克思主义学院', NULL, '', '余芳芸 ， 女 ， 中共党员 ， 助教 ， 硕士研究生 。 2023 年 6 月毕业于 安徽师范 大学 马克思主义 学院 马克思主义理论 专业，获 法学硕士 学位。 一、项目情况 主持池州学院校级人文项目：《思想政治教育叙事研究》', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, NULL, NULL, NULL, NULL, '硕士研究生 。 ；大学 马克思主义 学院 马克思主义理论 专业，获 法学硕士 学位。 一、项目情况 主持池州学院校级人文项目：', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('921', '王珊珊', '马克思主义学院', '王珊珊-池州学院马克思主义学院', NULL, '', '王珊珊，女，中共党员，硕士研究生，毕业于江西科技师范大学社科部德育学专业，获教育学硕士学位，现为池州学院马克思主义学院教师。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '江西科技师范大学', NULL, NULL, NULL, '硕士研究生，毕业于江西科技师范大学社科部德育学专业，获教育学硕士学位，现为池州学院马克思主义学院教师。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('922', '何丹丹', '马克思主义学院', '何丹丹-池州学院马克思主义学院', NULL, '', '何丹丹，女，陕西省商洛人，中共党员，法学硕士，主要研究青少年社会工作；主要讲授《科学社会主义概论》等课程。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, NULL, NULL, NULL, NULL, '硕士，主要研究青少年社会工作；主要讲授', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('923', '吴磊', '马克思主义学院', '吴磊-池州学院马克思主义学院', NULL, '', '吴磊，男，汉族，1995年7月生，安徽池州人，中共党员，马克思主义学院思政课专任教师，讲师。2022年6月毕业于华南师范大学中国史专业，获历史学硕士学位。主要讲授《习近平新时代中国特色社会主义思想概论》、《中国近现代史纲要》等课程。荣获2025年安徽省第七届高校青年教师教学比赛（思政组）二等奖，参与国家级、省部级课题多项，主持校级、市级课题多项，发表论文数篇。', '0', '0', '0', '2026-06-05 17:50:03', '2026-06-05 17:50:03', NULL, '华南师范大学', NULL, NULL, NULL, '大学中国史专业，获历史学硕士学位。主要讲授', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('924', '蔡瑞宝', '体育学院', '蔡瑞宝-体育学院', NULL, '', '蔡瑞宝，男，1982年10月出生，汉族，安徽霍邱人,职称：教授。2010年于南京师范大学体育科学学院硕士研究生毕业，获得体育教育训练学硕士学位。 教学效果情况： 1.2012年12月参加安徽省体育教师说课比赛获三等奖； 2.2016年10月获校级教学成果三等奖，2017年、2018年获校级教学成果一等奖；3.指导学生参加体育竞赛获得一类教学效果2项，二类教学效果2项，三类教学效果10余项； 4.2019年5月获得“双能型”教师资格； 5.2021年11月获校级教坛新秀； 6.2025年3月获校级教学名师。 科研教研情况： 1.主持省级质量工程教学研究重点项目1项，主持校本一流教材1项，主持校级教学创新团队1项，主持校地合作项目1项，主编《大学体育与健康》教材，北京工业大学出版社，2024年9月第一版； 2.主持安徽省哲学规划办青年项目1项，主持安徽省高校优秀青年人才支持计划重点项目1项，主持安徽省教育厅人文社科重点项目2项，参与国家教育部课题1项，在一类期刊发表学术论文6篇，在三类期刊发表学术论文20余篇。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, '大学体育科学学院', NULL, NULL, NULL, '大学体育科学学院硕士研究生毕业，获得体育教育训练学硕士学位。 教学效果情况： ；大学体育与健康；大学出版社，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('925', '曹红敏', '体育学院', '曹红敏-体育学院', NULL, '', '1982年生，华南师范大学民族传统体育学硕士，教授，硕士生导师。池州学院皖南民俗文化研究中心（省级）兼职研究员，省级《射艺》课程思政示范课程负责人，校“社会体育指导与管理”教学团队负责人，校科研型导师、校双能型教师，获武术兵道一级裁判员、教练员、武术一级社会体育指导员、气排球国家一级裁判员等称号。 主要承担《射艺》、《短兵》、《武术》、《健身气功》等课程的教学任务。近年来，主持安徽省高校人文社会科学重点研究项目项目2项，安徽省质量工程教育教学项目1项，省级课程思政示范课程1项，一类专业实践1项，校级人文重点项目2项，教学研究项目3项，校级教学创新团队1个，校级课程思政示范课程1校，校级校本教材1项，校级教学成果三等奖1项，指导学生参加学科竞赛共获得：一类教学效果10项、二类教学效果3项、三类教学效果9项，荣获安徽省社会科学届第十八届学术年会论文二等奖1项。在本科学报发表教科研论文20余篇，发表SCI科研论文2篇。 邮箱： 738441717@QQ.com 电话：13856602411', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '大学民族传统体育学硕士，教授，硕士生导师。池州学院皖南民俗文化研究中心；本科学报发表教科研论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('926', '林宏牛', '体育学院', '林宏牛-体育学院', NULL, '', '林宏牛，男，1966年7月出生，汉族，安徽枞阳人，教授职称，主要承担足球专业课教学。 教学和教学效果情况： 1.2000年12月校级教学成果三等奖； 2.2015年1月主编《大学生体育与健康导读》在池州市第四届社会科学奖获三等奖； 3.2018年1月获校级教学成果一等奖； 4.2016年10月指导国家级大创项目一项； 5.2017年在安徽省大学生羽毛球比赛中指导学生在女子团体（丙组）获第二名（二类教学效果）； 6.2017年在安徽省大学生羽毛球比赛中指导学生在男子团体（丙组）获第四名（三类教学效果）； 7.2017年在安徽省大学生羽毛球比赛中指导学生在丙组女子双二第五名，男子单打第六名（三类教学效果）； 8.2017年在安徽省大学生羽毛球比赛中指导学生在丙组获三等奖5项（四类教学效果）； 科研教研项目情况： 2012年参与国家体育总局课题一项《公共治理视域里农村社区体育对留守儿童心理成长干预研究》（编号1647SS12040），2013年12月主持省级综合改革试点项目《社会体育指导与管理（体育旅游）》（编号2013zy082），2014年主持安徽省体育社会科学重点研究项目《皖南国际旅游文化示范区体育旅游融合发展研究》（编号ASS2014119），2014年主持安徽省社科规划办项目《徽州民俗体育文化的流变、生态环境及现代性生成机制研究》（编号AHSKY2014D101）；2018年主持校级教学研究重点项目《池州学院公共体育俱乐部实体化管理及运行机制研究》（编号2018XJYXM07）。 论文方面： 2018年《奥运会互联网信息传播模式：演进脉络、传播特征与发展趋势》发表于《成都体育学院学报》第5期；（被新华文摘2018年第24期全文转载），在三类期刊发表学术论文10余篇。 任职期间社会职务： 2011年12月安徽省体育产业研究中心专家委员会委员； 2017年12月第二届安徽省社会体育指导员协会副会长； 2018年9月安徽省学校体育教学指导委员会委员。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '大学生体育与健康导读；大学生羽毛球比赛中指导学生在女子团体；大学生羽毛球比赛中指导学生在男子团体', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('927', '汪海滨', '体育学院', '汪海滨-体育学院', NULL, '', '汪海滨，池州学院体育学院党委书记，1972年8月生，安徽池州人，本科学历，硕士学位，副教授。 近期发表论文： 1．体育教育专业学生体育教育能力的培养，池州学院学报 2. 体育锻炼对肥胖儿童足底压力的影响，哈尔滨体育学院学报 3. 皖江城市带龙舟运动的发展构想，绵阳师范学院学报 4. 公共治理视域里我国农村社区体育发展探析，唐山师范学院学报 5. 安徽省中学体育骨干教师现状调查，池州学院学报 6．安徽省高校体育教育专业学生科研能力低的归因分析，铜陵学院学报 科研课题： 1．参与2012国家体育总局体育哲学社会科学研究一般项目“公共治理视域里农村社区体育对留守儿童心理成长干预研究”（项目批准号1647SS12040）', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '本科学历，硕士学位，副教授。 近期发表论文： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('928', '刘德森', '体育学院', '刘德森-体育学院', NULL, '', '刘德森，性别男，汉族，1983年10月生，山东青州人，中共党员，硕士研究生，双能型教师，副教授职称。 2010--2022连续12年获校“优秀教学质量奖”；曾获2024年度“校级优秀教师”、2025年度“校级教书育人楷模”等称号，在第4届中国大学生武术长短兵锦标赛中，获得“优秀教练员”。 2019年接受中国中央电视台专访，专访内容收录在中央电视台纪录频道纪录片《藏着的武林》第三集----“藏 .大隐于市”。2025年7月应安徽广播电视台邀请，参加纪录片《新安江》的拍摄，将明代徽州武术家程冲斗所著武术古籍《耕余剩技》中的《单刀法选》内容进行复原、解读，成片收录在第八集《匠心守艺》。 2023年指导学生在第3届全国大学生武术长短兵锦标赛获得4枚金牌、2枚银牌、1枚铜牌；中安教育网和安徽教育网分别对我校学子参赛获奖的情况进行了报道； 2024年指导学生在第4届中国大学生武术长短兵锦标赛中获得3枚金牌、2枚银牌、2枚铜牌； 2024年指导学生在第一届亚洲大学生武术锦标赛长短兵项目获得1枚金牌、1枚银牌、1枚铜牌； 2025年指导学生在第5届中国大学生武术长短兵锦标赛中获得1枚金牌、1枚银牌、2枚铜牌。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士研究生，双能型教师，副教授职称。 ；大学生武术长短兵锦标赛中，获得；大学生武术长短兵锦标赛获得', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('929', '赵永兴', '体育学院', '赵永兴-体育学院', NULL, '', '赵永兴，男，安徽淮北人，1990年8月生，硕士（在读博士），副教授。 主要教学成果： 1、2017年获池州学院“教学新手”称号 2、2018年参加安徽省第四届普通高等学校体育教师教学技能比赛获丙组三等奖 3、2018年指导学生参加安徽省第十四届运动会高校部羽毛球比赛获女子双打一等奖、女子团体一等奖、男子双打二等奖 4、2019年带领学生参加安徽省龙舟公开赛（贵池站）获第二名 科研情况： 1、主持《精准扶贫视角下体育文化与乡村旅游融合发展研究》（校级人文社科研究一般项目 CZ2018RW11）在研 2、参与《全民健身背景下皖南区域体育文化研究》（校级人文社科研究一般项目 2016RW015）已结项 3、精准扶贫背景下池州市体育文化与乡村旅游融合发展研究《山西农经》2019.06 4、池州市农村体育发展的制约因素研究《池州学院学报》2019.06 5、池州市女大学生健身意识调查研究《科技视界》2019.04', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士；博士；大学生健身意识调查研究', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('930', '王小双', '体育学院', '王小双-体育学院', NULL, '', '王小双，女，安徽合肥人，1991年1月生，研究生学历，硕士学位，副教授。 主要教学成果： 1、2016年获池州学院“教学新手”称号； 2、2017年参加安徽省第三届青年教师教学比赛获人文社科组三等奖； 3、2016年指导学生参加全国啦啦操联赛（合肥站）获得技巧啦啦操规定套路冠军并荣获“优秀教练”称号； 4、2017年指导马生虎参加安徽省健身健美锦标赛获得男子健美60KG级别季军、冠军总决赛季军；指导高天参加安徽省健身健美锦标赛获得男子健身模特级别季军、冠军总决赛季军； 5、2018年指导学生参加第五届大学生艺术展演获二等奖，个人获优秀指导教师； 6、2018年指导学生参加安徽省第十四届运动会高校部健美操比赛获女子三人操第二名、男子五人操第二名、混合双人操第三名、混合五人操第三名、女子五人操第四名、混合三人操第五名、男子三人操第六名等； 个人参赛获奖： 1、2012年参加安徽省健美操锦标赛获专业组女子单人操第二名； 2、2013年参加全国啦啦操总决赛获爵士自选套路第二名； 3、2014年参加安徽省第十四届运动会高校部健美操比赛获专业组女子三人操第一名、女子五人操第一名； 4、2014年参加全国啦啦操锦标赛获集体技巧三级自选动作第二名； 5、2014年参加全国健身健美锦标赛获健身瑜伽B组季军； 6、2015年参加全国健身健美冠军总决赛获健身小姐季军； 7、2016年代表中国参加第五十届亚洲健身健美锦标赛获得亚军； 8、2016年参加全国健身健美公开赛获健身小姐冠军； 裁判及教练等级： 1、健美操国家一级裁判员； 2、舞蹈啦啦操国家一级裁判员、舞蹈一级教练员、技巧啦啦操一级教练员； 3、健身健美国家一级裁判员、国际级私人教练、CBBA独立培训师、中国健美健身国家队队员； 科研情况： 1、主持《全民健身背景下皖南区域体育文化研究》（校级人文社科研究一般项目2016RW015）已结项； 2、主持《全域旅游视角下体育特色小镇建设发展研究——以九华山运动休闲特色小镇为例》（校级人文社科研究一般项目CZ2018RW09）在研； 3、主持《多元智能理论视角下高校瑜伽课程教学模式构建与改革研究》（校级教学研究一般项目2017XJYXM18）在研； 4、全民健身背景下皖南区域民俗体育文化研究《科技经济导刊》2018.08； 5、安徽省学校体育场地发展现状及对策研究《赤峰学院学报》2018.04；', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士学位，副教授。 主要教学成果： ；大学生艺术展演获二等奖，个人获优秀指导教师； ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('931', '杨辉霞', '体育学院', '杨辉霞-体育学院', '健美操、瑜伽教学工作', '', '杨辉霞，女、安徽芜湖县，1986年2月，研究生，硕士，体育教育训练学，副教授，主要从事健美操、瑜伽教学工作。 教学效果： 1、在2014年获得《体育管理导论》优秀多媒体教学课件制作 2、2016年获得《体育管理导论》教学单项奖，优秀教案 3、2018获得大学体育《健美操俱乐部》课程优秀教案 主持课题： 主持《生态视角下的高校休闲体育教育研究（以池州市为例）课题校级 发表论文： 1、大健康视域下高校大学生体质全面发展的新思路 商丘师范学院学报 2、体质健康视角下的大学校园足球课程体系构建 池州学院学报 3、解剖学视角下的瑜伽体位技术分析及训练研究赤峰学院学报(自然科学版) 4、新形势下高校大学生体育素质的培养——以体育专业学生瑜伽教学为例运动 5、休闲体育在池州地区高校体育教育中的发展研究当代体育科技 6、体育专业瑜伽课教学内容及教学考核研究 文体用品与科技 7、从中国传统文化视角对标准化武术器械的设计研究 当代体育科技', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士，体育教育训练学，副教授，主要从事健美操、瑜伽教学工作。 教学效果： ；大学体育；大学生体质全面发展的新思路 商丘师范学院学报 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('932', '朱永飞', '体育学院', '朱永飞-体育学院', '武术跨文化传播、民族传统体育历史与文化。 先后主持校级研究项目', '', '朱永飞（1981-），安徽枞阳人，硕士研究生，副教授，武术套路国家一级裁判员。 研究方向：武术跨文化传播、民族传统体育历史与文化。 先后主持校级研究项目3项，发表各类论文10余篇。参与安徽省哲学社会科学项目、安徽省体育社会科学重点项目、安徽省教学质量工程项目等。第九届、第十一届全国体育科学大会专题报告。 主讲课程：武术套路、散打、跆拳道、健身气功、射艺、体育科研方法、体育社会学。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, '武术套路、散打、跆拳道、健身气功、射艺、体育科研方法、体育社会学。', NULL, '硕士研究生，副教授，武术套路国家一级裁判员。 研究方向：武术跨文化传播、民族传统体育历史与文化。 先后主持校级研究项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('933', '吴加弘', '体育学院', '吴加弘-体育学院', NULL, '', '吴加弘，1979年2月，副教授，安徽师范大学硕士研究生，体育教育硕士，研究方向，民俗体育学，教授主课，田径. 主要教学成果： 1、国家田径一级裁判员 2、荣获安徽省第十三届运动会“优秀教练员”称号（2014） 3、获校第三届就业创业指导课程教学大赛优秀奖（2014） 4、《体育旅游学概论》课程课件获校2014—2015学年优秀多媒体教学课件奖（2016年） 5、“大学体育（体育俱乐部）”课程教案获校2015—2016学年优秀教案奖（2017年） 6、2017年安徽省大学生田径运动会，岳顺在男子丙组跳高项目以1.86米第五名成绩，荣获二等奖（2017年） 7、2018年安徽省第十四届田径运动会，王婷玉在女子甲组跳远项目以5.27米第五名成绩，荣获二等奖。（2018年） 8、获校教学成果奖（竞赛类）一等奖（2018年） 主要科研成果： 主持项目： 1.皖南传统古村落民俗文化保护与开发研究——以池州传统古村落为研究对象课题项目号（SK2017A0647 ） 安徽省教育厅人文社科重点项目，三类，完成 2.安徽省高校教职工羽毛球运动现状调查及对策研究——以池州学院为例 课题项目号（2015RWZ017） 池州学院人文社科重点项目，四类，完成 3.池州学院体育系学生大运动量运动训练后身体机能快速恢复的方法及手段研究 课题项目号（2011RC033） 池州学院人文社科重点项目，四类，完成 1.安徽省体育组织加强党的建设研究 课题项目号（AJCS2018217） 安徽省体育局一般项目，在研 参与项目： 1.安徽省高等学校人文社会科学研究重点项目《基于民族体育的视角研究池州傩舞的传承与发展》，项目编号：SK2016A0648，三类，结项 论文： 1.《FIFA11+练习对高校足球运动员膝踝关节肌力、本体感受和动态平衡的研究》天津体育学院学报,2019 2.陀螺运动历史沿革、价值功能及发展对策探究.通化师范学院学报,2018 3.陀螺运动历史变迁及现代生存机制研究.怀化学院学报,2018 4.安徽省高校教职工羽毛球常见运动损伤成因调查及预防对策.通化师范学院报,2016 5.关于“国务院建设全国2万所中小学足球特色学校”决定的思考.武夷学院学报,2015 6.强训后机体能量快速恢复方法及手段的探讨.体育科技文献通报,2013 7.体育明星偶像崇拜的社会效应分析.池州学院学报,2011 8.软式排球与新农村体育之研究.池州学院学报,2009', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, '授，安徽师范大学', NULL, NULL, NULL, '大学硕士研究生，体育教育硕士，研究方向，民俗体育学，教授主课，田径. 主要教学成果： ；大学体育；大学生田径运动会，岳顺在男子丙组跳高项目以', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('934', '薛天庆', '体育学院', '薛天庆-体育学院', NULL, '', '薛天庆，池州学院体育学院党委副书记，安徽萧县人，1980年9月出生，中共党员，硕士学位，副教授职称，双能型教师，主要担任网球、体操及大学生网球体育俱乐部教学工作。 政治表现和职业素养获奖情况： 1、2014年9月被评为校就业工作“先进个人”； 2、2016年获得被评为校“优秀共产党员”； 3、2017年被评为校“优秀党务工作者”； 4、2018年被评为校“优秀共产党员”。 主要教学效果： 1、2016年4月在安徽省大学生网球比赛中指导学生在男子双打（甲组）获第三名； 2、2018年在4月在安徽省第十四届运动会高校组网球比赛中指导学生获甲组男子单打一等奖； 3、2018年在4月在安徽省第十四届运动会高校组网球比赛中指导学生获丙组混双一等奖； 4、2018年在4月在安徽省第十四届运动会高校组网球比赛中指导学生获丙组女子团体一等奖； 主要教科研情况： 一、课题 1、2012年参与国家体育总局课题一项《公共治理视域里农村社区体育对留守儿童心理成长干预研究》（编号1647SS12040）； 2、2012年主持省体育总局课题一项《安徽省体育旅游可持续发展研究——以池州市为例》（编号：ASS2012307）； 3、2013年主持院级教研项目《基于ISO9000族标准的高校社会体育专业实习质量管理评价研究》（编号：2012jyxm025）； 4、2014年参与安徽省社科规划办项目《徽州民俗体育文化的流变、生态环境及现代性生成机制研究》（编号：AHSKY2014D101）； 5、2017年主持安徽省社科规划办项目《池州市体育旅游与佛教文化旅游融合发展策略研究》（编号：AHSKQ2017D60）； 二、论文 1、2017年10月《池州市体育旅游开发策略探析》发表于《赤峰学院学报》第10期 2、2018年4月《论当代体育娱乐化动因及其转向》发表于《吉林体育学院学报》第2期 3、2018年7月《“翻转课堂”教学模式在网球俱乐部教学中的应用探析———以池州学院为例》发表于《赤峰学院学报》第7期 4、2018年8月《“成为人”:休闲体育发展的时代诉求》发表于《吉林体育学院学报》第6期 5、2018年10月《中国男篮职业联赛外籍球员的现状分析》发表于《菏泽学院学报》第5期', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士学位，副教授职称，双能型教师，主要担任网球、体操及大学生网球体育俱乐部教学工作。 政治表现和职业素养获奖情况： ；大学生网球比赛中指导学生在男子双打', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('935', '袁空军', '体育学院', '袁空军-体育学院', NULL, '', '姓名：袁空军 籍贯：甘肃省环县 性别：女 出生年月：1980年9月 学历：硕士研究生 学位：硕士 职称：副教授 主要教学成果： 1、荣获池州学院“最美教师”称号（2016） 2、获校青年教师技能大赛三等奖（2015年） 3、《体操》课程教案获校2014—2015学年优秀教案奖（2016年） 4、田径国家一级裁判员 主要科研成果： 主持项目：安徽省高等学校人文社会科学研究重点项目：《基于民族体育的视角研究池州傩舞的传承与发展》，项目编号：SK2016A0648，三类，完成 参与项目：安徽省高等学校人文社会科学研究重点项目《皖南传统古村落民俗体育文化保护与开发研究——以池州国家级传统古村落为研究对象》，项目编号：SK2017A0647，三类，完成 论文： 1、《广场舞和太极拳锻炼对中老年女性动态平衡能力的影响》，《北京体育大学学报》2018年第3期。 2、《安徽省高校教职工羽毛球运动发展探究》，《池州学院学报》2016年第6期。 3、《贵池傩舞的文化人类学分析》，《黄山学院学报》2018年第2期。 4、《高校体育保健课程建设研究》，《西昌学院学报》2018年第3期。 5、《快乐体操引入高校教学的实验研究》发表于《商丘师范学院学报》2018年第6期。 6、《课外体育活动对农村留守儿童心理干预的实验探究》，《兰州文理学院学报》2018年第4期', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士研究生 学位：硕士 职称：副教授 主要教学成果： ；大学学报', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('936', '杨广艳', '体育学院', '杨广艳-体育学院', NULL, '', '杨广艳，女，江苏赣榆人，1980年4月出生，硕士研究生，副教授。 曾主持安徽省体育局课题一项（已结题），主持校级课题2项（已结题），参与各类课题多项，发表各类教科研论文10余篇。现主持校级教研课题一项（定向运动）。参加2014年青年教师教学技能大赛获校级二等奖。 指导的“体育系赴岳西县爱心支教暑期社会实践团”在 2012年荣获安徽省大中专学生志愿者暑期“三下乡”社会实践活动优秀团队二等奖。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士研究生，副教授。 曾主持安徽省体育局课题一项', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('937', '邹政', '体育学院', '邹政-体育学院', NULL, '', '邹政，籍贯，安徽合肥，1967年12月出生，体育教育与训练专业，研究生学历，硕士学位，副教授。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士学位，副教授。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('938', '毕存箭', '体育学院', '毕存箭-体育学院', NULL, '', '毕存箭，男，山东曲阜人，中共党员，博士毕业于华东师范大学运动人体科学专业，副教授、硕士生导师，池州学院体育学院副院长。 所属系：运动人体科学 主讲课程：健康教育学、体育科学研究方法 研究领域：儿童青少年身心健康促进、运动与脑健康、体质健康测评与干预 教科研项目（主持）： 国家社会科学基金一般项目：家校社联动改善青少年抑郁症状的追踪及智慧运动干预研究（25BTY107），2025年 教育部人文社会科学青年项目：家校社共育模式对青少年心肺耐力与执行功能的促进研究（23YJC890002），2023年 安徽省哲学社会科学规划项目：青少年24 h活动行为与执行功能的关联及促进研究（AHSKQ2024D087），2024年 安徽省教育厅高校科研重点研究项目：安徽省儿童青少年心肺耐力与执行功能的关系及其运动干预研究（2022AH051824），2022年 代表性论文/著作： Bi C, Lin H, Zhang J, et al. Regional variation in growth status: A cross-sectional survey among Tibetan adolescents living at three different high altitudes in Tibet, China. American Journal of Human Biology, 2022, 29:23856.（SCI/SSCI双收录，第一作者） Bi C, Lin H, Zhang J, et al. Association between Sleep Quality and Depression Symptoms in Chinese College Students during the COVID-19 Lockdown Period. Children (Basel), 2022, 9(8):1237.（SCI收录，第一作者） Bi C, Cai R, Zhao Y, et al. Associations between cardiorespiratory fitness and executive function in Chinese adolescents. Scientific Reports, 2024, 14(1):21089.（SCI收录，第一作者） Wang Y, Bi C（通讯作者）, Liu H, et al. Association of sugar-sweetened beverage consumption with psychological symptoms among Chinese university students during the COVID-19 pandemic. Frontiers in Psychology, 2022, 13:1024946.（SCI/SSCI双收录，通讯作者） Liu H, Bi C（通讯作者）, Lin H, et al. Compared with dietary behavior and physical activity risk, sedentary behavior risk is an important factor in overweight and obesity. BMC Pediatrics, 2022, 22(1):582.（SCI收录，通讯作者） 毕存箭,尹小俭,施利娟,等.中高强度课堂体育锻炼对藏族初一年级学生心肺耐力和执行功能的干预效果.中国学校卫生, 2024, 45(3): 322-325.（北大核心，三类） 参编《健康教育学》，尹小俭、陶芳标、叶心明主编，高等教育出版社2025年 副主编《大学体育与健康》，北京工业大学出版社，2024年 主要获奖情况： 安徽省社会科学界学术年会论文三等奖，2025年 安徽省体育科学学会专题报告二等奖，2025年 社会服务与兼职： 安徽省体育科普工作委员会主任委员 安徽省体育科学学会常务理事', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, '华东师范大学', NULL, '健康教育学、体育科学研究方法 研究领域：儿童青少年身心健康促进、运动与脑健康、体质健康测评与干预 教科研项目', NULL, '博士毕业于华东师范大学运动人体科学专业，副教授、硕士生导师，池州学院体育学院副院长。 所属系：运动人体科学 主讲课程：健康教育学、体育科学研究方法 研究领域：儿童青少年身心健康促进、运动与脑健康、体质健康；大学体育与健康；大学出版社，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('939', '元晓华', '体育学院', '元晓华-体育学院', NULL, '', '姓名：元晓华 籍贯：河南省安阳市汤阴县 出生日期：1978.12.1（身份证为1978.7.1） 学历：研究生 学位：博士 职称：副教授 主要教学成果： 1.2010年12月荣获校级2008-2009、2009-2010两学年度优秀教学质量奖 2.2010年6月荣获校级2010年度教坛新秀奖。 3.2013年1月荣获校级2010-2011、2011-2012两学年度优秀教学质量奖 4.2016年1月荣获校级2013-2014、2014-2015两学年度优秀教学质量奖 5.2019年4月荣获校级2016-2017、2017-2018两学年度优秀教学质量奖 科研成果： 1.高等师范院校研究生体育价值观现状分析.池州学院学报，2009年第一期 2.论符号消费与休闲体育消费伦理构建.绵阳师范学院学报，2009年第二期 3.当代中国社会分层与休闲体育发展策略研究.乐山师范学院学报，2010年第五期 4.小城市休闲体育发展研究——一安徽省池州市为例.牡丹江师范学院学报(自 然科学版），2011年第三期 5.池州市城市居民体育休闲现状调查.菏泽学院学报，2011年第五期 6.普通高校健美操教学改革研究——以安徽省池州学院为例.长江师范学院学报 7.普通高校体育专业健美操普修课程实施策略研究.长沙大学学报，2013年第五期 8.基于傩舞的健美操课程构想.池州学院学报，2014年第三期 9.武术与巫傩的渊源关系.佳木斯教育学院学报，2014年第六期', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '博士 职称：副教授 主要教学成果： ；大学学报，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('940', '罗永义', '体育学院', '罗永义-体育学院', NULL, '', '罗永义，河南郸城人，1975年4月生，体育学博士，教授职称。主要承担《体育社会学》《社会体育活动方案设计与组织》《民族传统体育》《短兵》等专业理论与实践课，以及《武术》《足球》等项目的大学体育教学工作。曾主持教育部、安徽省社科规划办、安徽省教育厅科研课题4项，参与国家社科课题3项及其他省部级课题多项。在体育科学、北京体育大学学报等发表教科研论文20余篇。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '博士，教授职称。主要承担；大学体育教学工作。曾主持教育部、安徽省社科规划办、安徽省教育厅科研课题；大学学报等发表教科研论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('941', '赵春州', '体育学院', '赵春州-体育学院', NULL, '', '赵春州，男，河南开封人，博士毕业于北京师范大学，体育教育训练学专业，研究方向为篮球教学与训练，公共体育教学部主任。 一、教学情况 主讲课程：篮球、运动训练学，注重教学方法创新与学生实践能力培养。 二、代表性论文/著作（近三年） Fixation control and three-point field goal percentage in female collegiate basketball players: an eye-tracking study. Scientific Reports, 2026（SCI收录，通讯作者） Exercise intensity and shooting position modulate fixation behavior and 2-point shooting accuracy in elite female basketball players: An eyetracking study. PLoS One, 2026, 21(4): e0348017（SCI收录，通讯作者） Impact of visual attention training on visual control and 3-point field goal percentage in semi-professional basketball players.Frontiers in Psychology, 2026, 17: 1567764（SSCI收录，通讯作者） The expert’s fixation: cognitive efficiency and attentional selectivity in wheelchair curling athletes across the expertise spectrum. Frontiers in Psychology, 2026: 1739477（SSCI收录，第二作者） Empirical study on Visual Attention Characteristics of basketball players of different levels during free throw shooting. Peer J, 2023, 11: e16607.（SCI收录，第一作者） Study on the relationship between fixation characteristics and hit rate in psychological procedure training of free throw. PLOS ONE, 2024, 19(5): e0293436（SCI收录，第一作者） Investigation of eye movement characteristics during free throws at varying intensities among basketball players and its correlation with free throw percentage. PLOS ONE, 2024, 9(8): e0299938（SCI收录，第一作者） Investigating the Eye Movement Characteristics of Basketball Players Executing 3-Point Shot at Varied Intensities and their Correlation with Shot Accuracy. Peer J，2024, 12: 17634.（SCI收录，第一作者）。 高校女子篮球运动员不同强度状态下罚球视觉注意特征研究.第十四届全国体育科学大会——论文专题报告, 2025: 381-382.第一作者。 不同水平运动员罚篮过程中注视特征实证研究.第十三届全国体育科学大会论文摘要集, 2023:47-48.第一作者。 罚篮心理程序干预对注视特征和命中率的影响研究.第十三届全国体育科学大会论文摘要集, 2023: 71-73. 参编《义务阶段体育与健康教师用书——篮球运动》，人民教育出版社，2024年。 三、教科研项目 广东省教育厅项目：基于准军事化管理机制下军事训练与体育教学融合路径探索（2020WQNCX259），主持。 广东省社会科学项目：高职院校国防教育的德育功能及实施路径研究（SL19YB03-1），主持。 国家社会科学基金一般项目：教师专业化视阈下卓越体育教师培养体系构建研究（22BTY055），参与。 中国高等学会重大项目：高水平运动队建设模式与策略研究（22TY0201），参与。 四、主要获奖 广东省第四届高校青', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, '北京师范大学', NULL, '篮球、运动训练学，注重教学方法创新与学生实践能力培养。 二、代表性论文', NULL, '博士毕业于北京师范大学，体育教育训练学专业，研究方向为篮球教学与训练，公共体育教学部主任。 一、教学情况 主讲课程：篮球、运动训练学，注重教学方法创新与学生实践能力培养。 二、代表性论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('942', '孙建中', '体育学院', '孙建中-体育学院', NULL, '', '孙建中，男，1982年10月出生，汉族，山东省临沂人，中国科学院大学，博士研究生，主要承担健康评价与运动处方课程教学。 课题： 1.企业横向课题，《符合人体形态学的刀具研发》，到账经费40.1万元。 2. 池州市社会科学界联合会课题，构建“CPR+AED”高安全水平全民健身公共服务体系，主持。 3江西省社会科学界联合会，江西省大气PM2.5对儿童青少年健康危害及控制对策研究，项目编号：19ZK34，已结题，主持。 论文： 1.SCI论文：A comparative study on the physical fitness ofcollege students from different grades and majors in Jiangxi province； 2. CSCD论文：终末回旋伸膝抗阻训练干预对老年男性股内斜肌厚度的影响； 3.教研论文：An empirical study on flipped classroom in college physical education theory course. 专著： 《地方城市矿业经济与体育产业融合发展战略研究报告》，（2019Z00408），ISBN 978-7-215-12189-8, CIP (2019)288964,第一主编.河南人民出版社。 专利： 1.一种符合人体形态学的家用刀具。实用新型，专利号：ZL 202122427652.1，公告号：CN 216422628U。 2. 一种排球挂网带。实用新型，专利号：ZL 2020 2 1608079.3.公开号：CN212817964 U. 获奖： 1.第六届江苏省大学生体育产业创新创业大赛，《智能化“无菌”空气质量提升系统—地下氧吧健身房》，优秀指导教师，二等奖； 2.江西省第十九次社会科学优秀成果奖，三等奖； 3.江西省高校第一届体育人文社会科学优秀成果奖，特等奖。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '大学，博士研究生，主要承担健康评价与运动处方课程教学。 课题： ；大学生体育产业创新创业大赛，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('943', '吴乐乐', '体育学院', '吴乐乐-体育学院', '长期从事慢性疾病的机制与干预研究，重点关注运动干预在老年人慢性病防控中的作用。通过融合体育科学、分子生物学等多学科交叉方法，系统探讨', '', '吴乐乐，男，1990年5月生，安徽池州人，中共党员，研究生学历，生物医学博士，拥有海外博士后研究经历,现任体育学院讲师。 研究方向： 长期从事慢性疾病的机制与干预研究，重点关注运动干预在老年人慢性病防控中的作用。通过融合体育科学、分子生物学等多学科交叉方法，系统探讨“运动—慢性病—基因表达网络”之间的相互作用机制，致力于构建基于分子标志物的精准运动干预模型，为健康促进与个体化康复提供理论支撑与实践策略。 科研情况： 曾在胃肠病等医学期刊发表多篇文章，并主持或参与过多项国家级项目，曾荣获博士研究生国家奖学金。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '博士，拥有海外博士后研究经历,现任体育学院讲师。 研究方向： 长期从事慢性疾病的机制与干预研究，重点关注运动干预在老年人慢性病防控中的作用。通过融合体育科学、分子生物学等多学科交叉方法，系统探讨；博士研究生国家奖学金。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('944', '郭亚茹', '体育学院', '郭亚茹-体育学院', NULL, '', '郭亚茹，女，1994年5月出生，汉族，河南商丘人，研究生学历，博士学位。2025年毕业于华东师范大学，运动人体科学专业，主要研究方向为儿童青少年体质健康测评与运动干预、体脑融合与执行功能发展。 一、教学情况 主要承担“体育科研方法”“健康教育学”等课程的教学工作，注重科研思维训练与解决实际问题能力的同步培养。 二、课题： 1. 主持：青少年健康评价与运动干预教育部重点实验室建设项目（已结项） 2. 参与：国家自然科学基金面上项目、国家社会科学基金一般项目、上海市哲学社会科学规划课题、上海市教育科学研究项目、教育部人文青年基金项目、国家卫健委项目、教育部教育质量评估中心项目等7项。 三、代表性成果： 1. Guo Y , Yin X, Sun Y, Zhang T, et al. Research on Environmental Influencing Factors of Overweight and Obesity in Children and Adolescents in China[J]. Nutrients. 2022;14(1).【SSCI & SCI】 2. Guo Y , Yin X, Xu J, et al. The Relationship Between Sedentary Behavior and Non-Suicidal Self-injury Behavior among Adolescents in China[J]. Front. Psychiatry. 2024, 15:1489707.【SSCI & SCI】 3. Guo Y , Yin X, Wu H, et al. Trends in Overweight and Obesity Among Children and Adolescents in China from 1991 to 2015: a Meta-Analysis[J]. Int. J. Environ. Res. Public Health . 2019;16(23).【SSCI & SCI】 4. Zhang T, Li M, Zhang F, Yang X, Sun P, Yin X, Liu Y* and Guo Y*(通讯作者). Physical activity in adolescents of different family socioeconomic status: the moderating role of gender[J]. Front. Pediatr. 2025, 13:1559554.【SCI】 5. Cai R, Guo Y and Lu C (2025) The revised version of the Physical Self-Description Questionnaire-Short for Chinese middle school students. Front. Psychol. 16:1513882. doi: 10.3389/fpsyg.2025.1513882【SSCI & SCI】 6. Jun Hong, Yuan Liu, Yaru Guo , et al. The joint association between sleep quality, moderate-to-vigorous physical activity, cardiorespiratory fitness, and working memory in Chinese adolescents[J]. BMC Public Health. 2025, 25(1). 7. 孙洁丽, 郭亚茹 .青少年静态行为与抑郁症状的相关性研究[J].体育学刊,2024,31(5):68-74.【CSSCI来源期刊】 四、参编书籍 《中小学生安全手册—运动安全》，人民卫生出版社，2022-01，ISBN：9787117327541', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, '华东师范大学', NULL, NULL, NULL, '博士学位。；大学，运动人体科学专业，主要研究方向为儿童青少年体质健康测评与运动干预、体脑融合与执行功能发展。 一、教学情况 主要承担', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('945', '孙啟建', '体育学院', '孙啟建-体育学院', NULL, '', '孙啟建，安徽肥东人，1988年4月，中共党员，讲师，硕士学位 曾带领校田径队多次在省级比赛获奖，在国内期刊上公开发表论文数篇。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士学位 曾带领校田径队多次在省级比赛获奖，在国内期刊上公开发表论文数篇。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('946', '付豪', '体育学院', '付豪-体育学院', NULL, '', '付豪、安徽铜陵、1990.10.29、研究生学历、硕士学位，讲师、自由式轮滑国际A级裁判员、自由式轮滑国家级教练员 一、教师实践业绩 情况： 1、中国轮滑协会教材编写委员会成员；《世界轮联2026版自由式轮滑竞赛规则》翻译组成员； 2、长期参与国内外各大自由式轮滑项目赛事执裁工作。曾参与执裁：2018-2025全国自由式轮滑锦标赛；2019-2025全国少年轮滑-自由式轮滑锦标赛；中华人民共和国第十三届运动会轮滑项目比赛；2023年中华人民共和国第一届学生青年运动会-自由式轮滑技术官员；2023年世界自由式轮滑锦标赛-自由式轮滑NTO；第十九、二十届亚洲轮滑锦标赛-自由式轮滑ITO；2023-2025全国中学生轮滑锦标赛；2025成都世界运动会等。 二、带队比赛 情况： 1、带队参加2023年全国大学生轮滑锦标赛，获得2金4银2铜； 2、带队参加2024年全国大学生轮滑锦标赛，获得1金1铜； 3、带队参加2025全国大学生轮滑锦标赛，获得2银1铜。 三、 科研情况： 在各类期刊发表学术论文6篇，主持参与各类教科研项目6项。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士学位，讲师、自由式轮滑国际；大学生轮滑锦标赛，获得；大学生轮滑锦标赛，获得', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('947', '赵振红', '体育学院', '赵振红-体育学院', NULL, '', '赵振红，出生于1991年8月9日，安徽安庆人，研究生，硕士学位，讲师。指导学生2018年“超级杯”全国气排球联赛总决赛女子大学生组比赛获得第二名。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士学位，讲师。指导学生；大学生组比赛获得第二名。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('948', '郑凯', '体育学院', '郑凯-体育学院', NULL, '', '籍贯：河南省信阳市 出生日期：1990.08.1 学历：硕士研究生 学位：硕士 职称：讲师 主要成果： 1、三类教学效果奖（安徽省十四届省运会高校部篮球赛女子丙组二等奖），2018年； 2、校级课题《四人制篮球对篮球运动方式的影响研究》2016RW07、人文一般，2018年已结题； 3、《全国绿色运动会对池州公开水域游泳比赛的影响研究》，《当代体育科技》2017第35期； 4、《池州市中小学开展游泳安全教育课程的必要性研究》，《当代体育科技》2018第9期； 5、《四人制篮球对篮球运动方式的影响研究》，《池州学院学报》，2018年第三期；', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士研究生 学位：硕士 职称：讲师 主要成果： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('949', '张锰锰', '体育学院', '张锰锰-体育学院', NULL, '', '张锰锰，1986年生，山东邹城人，硕士研究生，讲师，国家级气排球裁判员。 教育经历：2013年6月毕业于曲阜师范大学体育科学学院，获得教育学硕士学位。 研究领域和方向：排球，专项训练理论与研究，社会体育，休闲体育 主讲课程：主要承担排球、台球、拓展训练等教学任务。 学术研究：近年来在国内各级各类期刊上发表论文多篇，承担校级课题1项。 教学与训练：2016年5月训练学生参加2016安徽省大学生排球赛（丙组），获得男子丙组第六名；2017年11月训练生参加2017安徽省大学生排球赛（丙组），获得男子丙组第五名；2018年4月训练学生参加第十四届安徽省运动会高校部排球赛（丙组），获得男子丙组第四名。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, '曲阜师范大学体育科学学院', NULL, '主要承担排球、台球、拓展训练等教学任务。 学术研究：近年来在国内各级各类期刊上发表论文多篇，承担校级课题', NULL, '硕士研究生，讲师，国家级气排球裁判员。 教育经历：；大学体育科学学院，获得教育学硕士学位。 研究领域和方向：排球，专项训练理论与研究，社会体育，休闲体育 主讲课程：主要承担排球、台球、拓展训练等教学任务。 学术研究：近年来在国内各级各类期刊上发表论文多篇，；大学生排球赛', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('950', '马力', '体育学院', '马力-体育学院', '篮球教学、训练工作、“双能型”教师', '', '马力，男，安徽颍上人，1985年6月生，硕士研究生，讲师职称，体育教育训练学，篮球国家一级裁判、气排球国家一级裁判；主要从事篮球教学、训练工作，“双能型”教师。 教学效果： 1、指导学生参加全国绿色健身大赛全国拔河新星赛（池州站）草地拔河 第二名； 2、安徽省第三届普通高校体育教师教学技能比赛三等奖； 3、指导学生参加安徽省十四届运动会高校部篮球比赛女子丙组二等奖； 4、指导学生参加2024年安徽省大学生体育联赛田径比赛获二等奖2项，三等奖1项。 科研业绩： 入职以来主持教科研项目4项，发表论文10余篇，主要有： 课题： 1、池州市休闲体育建设中的网络思维（校级） 2、安徽省高校公共体育篮球有效教学研究（校级） 3、乡村振兴背景下池州地区民俗体育服务乡村社会治理的实施路径研究（校级重点） 4、皖南民俗体育与旅游融合的创新路径研究 （教育厅重点 ） 论文： 1、传统文化视角下武术器械（刀）的设计改良探究； 2、基于大健康视角及应用型培养模式下的高校休闲体育专业建设路径——以池州学院为例 3、乡村振兴背景下民俗体育文化传承困境与纾解路径； 4、乡村振兴背景下民俗体育参与乡村社会治理融合路径研究——以池州地区舞龙习俗为例； 5、村落民俗体育与乡村旅游融合发展的机理与实践路径——以池州区域为例 。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士研究生，讲师职称，体育教育训练学，篮球国家一级裁判、气排球国家一级裁判；主要从事篮球教学、训练工作，；大学生体育联赛田径比赛获二等奖', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('951', '温宝林', '体育学院', '温宝林-体育学院', NULL, '', '姓名：温宝林 籍贯：安徽省东至县 性别：男 出生年月：1982年7月 学历：硕士研究生 学位：硕士 职称：讲师 毕业于安徽师范大学体育学院，2011年进入池州学院任教，主要担任公体田径、网球、足球俱乐部教学，现担任保卫处治安管理科副科长。多次荣获池州学院“优秀辅导员”，“就业先进个人”，“资助先进个人”等称号，近年来在国内各级各类期刊上发表论文多篇，承担校级课题2项。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, '安徽师范大学体育学院', NULL, NULL, NULL, '硕士研究生 学位：硕士 职称：讲师 毕业于安徽师范大学体育学院，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('952', '汪潇恒', '体育学院', '汪潇恒-体育学院', NULL, '', '汪潇恒，池州学院体育学院体育舞蹈专业讲师。本科毕业于安徽师范大学体育学院，后保送本校研究生于安徽师范大学就读，获硕士学位。国家一级体育舞蹈裁判，安徽省啦啦操二级裁判、教练员。主要研究领域和方向为体育舞蹈教学、表演与竞赛。主要承担体育舞蹈专项、健美操普修、瑜伽选修等课程。先后在《池州学院学报》、《体育科技》中发表研究论文数篇。 编排指导国标舞集体舞剧目《红高粱》荣获安徽省第五届大学生艺术展演艺术类专业甲组二等奖；指导舞蹈《盛世鸿姿》荣获安徽省“同铸复兴路 共圆中国梦”艺术表演类节目甲组三等奖；获安徽省普通高校教师说课比赛丙组三等奖；获池州学院2013届青年教师技能比赛一等奖。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, '安徽师范大学体育学院', NULL, NULL, NULL, '本科毕业于安徽师范大学体育学院，后保送本校研究生于安徽师范大学就读，获硕士学位。国家一级体育舞蹈裁判，安徽省啦啦操二级裁判、教练员。主要研究领域和方向为体育舞蹈教学、表演与竞赛。主要承担体育舞蹈专项、健美；大学生艺术展演艺术类专业甲组二等奖；指导舞蹈', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('953', '张敏', '体育学院', '张敏-体育学院', NULL, '', '张敏，男，中共党员，湖南株洲县人，1984年5月生，硕士研究生，讲师职称。 学习经历： 2003.09——2007.06 衡阳师范学院 体育教育 本科/学士 2007.09——2010.06 安徽师范大学 体育人文社会学 硕士/研究生 工作经历： 2010.07至今，池州学院教员、助教、讲师 指导课程： 足球（普修、专选）、木球、大学体育（足球俱乐部）。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士研究生，讲师职称。 学习经历： ；本科；学士 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('954', '刘崇', '体育学院', '刘崇-体育学院', NULL, '', '刘崇，1983年5月23日出生，籍贯为河北省安国市，2009年毕业于河北师范大学，运动人体科学专业，硕士研究生，讲师。 荣誉、获奖情况： 1、2010年池州学院年度考核为优 2、2011年荣获池州学院青年教师技能大赛一等奖 3、2012年荣获池州学院优秀试卷奖 4、2012年荣获校级教学成果奖 5、2013年荣获池州学院优秀课件奖 6、2013年荣获池州学院学生工作案例评选二等奖 7、2013年荣获池州学院青年教师技能大赛三等奖 8、2014年荣获池州学院优秀试卷奖 9、2014年荣获池州学院优秀辅导员 10、2015年荣获池州学院优秀试卷奖 11、2015年荣获安徽省高校体育教师说课比赛三等奖 12、2016年荣获池州学院优秀试卷奖 13、2018年荣获池州学院优秀课件奖 科研情况： 1、主持校级教学研究重点项目一项。 2、主持安徽省高等学校优秀青年人才基金重点项目一项。 3、刘崇，闫芬，李颖等.太极拳、健步走对改善女性老年人静态平衡功能效果的对比研究[J].中国康复医学杂志，2009，24(5):445-447. 4、杜洁,刘崇.交谊舞、健步走对改善女性老年人静态平衡能力的对比研究[J].中国康复医学杂志,2009,24(9):844-845. 5、刘崇,任立峰,史建伟等.人体平衡能力的评价系统[J].中国组织工程研究与临床康复，2009,13(2):363-367. 6、刘崇，赵焕彬，林宏牛.太极拳、交谊舞对改善女性老年人静态平衡能力的对比研究[C].第十三届全国运动生物力学交流大会，2009年10月. 7、刘崇，林宏牛，赵焕彬.太极拳改善老年人静态平衡能力的生物力学分析[C].第十四届全国运动生物力学交流大会，2010年10月. 8、刘崇,阎芬,曹冰等.运动延缓老年人平衡能力下降的研究进展[J].中国康复医学杂志,2009,(7):670-673.', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, '河北师范大学', NULL, NULL, NULL, '大学，运动人体科学专业，硕士研究生，讲师。 荣誉、获奖情况： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('955', '牛银涛', '体育学院', '牛银涛-体育学院', NULL, '', '牛银涛，男，1995年11月出生，汉族，河南南阳人，讲师，运动人体科学专业硕士研究生。 主要研究方向为：运动训练监控与应用，发表学术论文数篇，参加学术会议数次。参与教育部人文社会科学基金项目1项和黑龙江省自然科学基金项目1项等。 主要承担《运动生理学》、《体育科研方法》、《体育健身原理与方法》、《健康体适能》、《网球》和《足球》等专业理论与实践课。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士研究生。 主要研究方向为：运动训练监控与应用，发表学术论文数篇，参加学术会议数次。参与教育部人文社会科学基金项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('956', '罗丹妮', '体育学院', '罗丹妮-体育学院', '运动训练 羽毛球国家一级裁判员', '', '姓名：罗丹妮 出生日期:1996年6月 民族：汉族 籍贯：安徽六安 学历：硕士研究生 职称：讲师 研究方向：运动训练 羽毛球国家一级裁判员', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士研究生 职称：讲师 研究方向：运动训练 羽毛球国家一级裁判员', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('957', '章杰', '体育学院', '章杰-体育学院', NULL, '', '章杰，男，1994年2月出生，汉族，安徽池州人，讲师。2020年于安徽师范大学体育学院硕士研究生毕业，获得运动训练专业硕士学位。 教学和教学效果情况： 主要承担羽毛球、户外运动指导、健身理论与指导等课程教学； 2022年指导学生获得安徽省第十五届运动会羽毛球高校部比赛二等奖1项、三等奖5项； 2021-2022年指导学生立项大学生创新创业大赛国家级2项，省级1项。 教研科研情况： 1、2023年主持安徽省高校科研哲学社会科学重点研究项目《长三角区域体育产业高质量发展指数测度与综合评价研究》（2023AH052350) 2、2021年主持校级科研项目《人口老龄化背景下安徽省体育产业与养老产业耦合研究》（CZ2021RW13） 3、2021年主持校级教研项目《成果导向理念下劳动教育与社会体育指导与管理专业毕业实习课程设计的融合研究》(2021XLDXM04) 4、税收负担、税制结构对企业外源融资的影响研究——基于体育产业上市公司的经验数据，《荆楚理工学院学报》2021年10月第5期 5、老龄化背景下体育产业与养老产业融合模式与发展路径研究，《池州学院学报》2022年6月第3期 6、高校体育课程思政建设的内在逻辑、现实困境与优化路径研究，《体育科学进展》2022年6月10卷2期 个人专业实践情况： 羽毛球国家一级裁判员、羽毛球国家级社会体育指导员、池州市羽毛球协会理事、德国职业运动康复师认证、山地户外社会体育指导员、健美操中级社会体育指导员、田径二级裁判员、木球二级裁判员、教练员。 2021年获得第十四届全国运动会群众组羽毛球项目安徽省选拔赛混合双打第二名（获得全运会参赛资格）； 2022年获得安徽省第十五届运动会青少年部羽毛球比赛裁判员“体育道德风尚奖”； 2015-2023年多次获得池州市羽毛球男子单打、男子双打、混合双打冠军。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, '师范大学体育学院', NULL, NULL, NULL, '大学体育学院硕士研究生毕业，获得运动训练专业硕士学位。 教学和教学效果情况： 主要承担羽毛球、户外运动指导、健身理论与指导等课程教学； ；大学生创新创业大赛国家级', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('958', '吴明浩', '体育学院', '吴明浩-体育学院', NULL, '', '吴明浩，男，1995年7月出生，汉族，安徽宣城人，讲师，2021年于安徽师范大学体育学院硕士研究生毕业，获得体育经营与管理专业硕士学位。 教学情况： 1、主要承担户外运动与指导、拓展训练、体育旅游概论、野外生存和定向运动等课程教学； 2、2022年指导学生获得长三角绿水青山运动会池州九华山定向越野挑战赛男女子前三名； 3、指导学生大学生创新创业大赛国际级、省级多项立项。 教研科研情况： 1、主持校级科研一项；参与多项教育部、省级课题； 2、发表学术论文数篇，参加学术会议多次。 个人实践情况： 1、卡巴迪国家级教练员、裁判员，多次执裁国家级赛事； 2、山地户外国家级裁判、师资，多次执裁国家级赛事。', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, '师范大学体育学院', NULL, NULL, NULL, '大学体育学院硕士研究生毕业，获得体育经营与管理专业硕士学位。 教学情况： ；大学生创新创业大赛国际级、省级多项立项。 教研科研情况： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('959', '史由甲', '体育学院', '史由甲-体育学院', NULL, '', '史由甲，女，1996年7月出生，汉族，安徽亳州人，讲师，2023年硕士毕业于吉林体育学院体育教学专业。 教学情况： 1、主要承担网球、体育概论、乒乓球等课程教学； 2、2024年带领网球队甲组运动员参加高校大学生网球联赛； 3、现任体育学院棒垒球训练队教练员与乒乓球社团指导教师； 教研科研情况： 1、发表学术论文数篇，参与《民族传统冰雪项目》一书的编写，任副主编。 个人实践情况： 1、网球PTR教练员、网球二级裁判员； 2、国家职业资格游泳救生员、中级游泳教练员、裁判员； 3、国家职业资格滑雪教练员，并参与“百万学子上冰雪”滑雪教学活动； 4、垒球国家二级裁判员、安徽省棒垒球协会软式棒垒球ST（手套）教练员 5、全国跳绳二级裁判员', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, '吉林体育学院', NULL, NULL, NULL, '硕士毕业于吉林体育学院体育教学专业。 教学情况： ；大学生网球联赛； ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('960', '刘静静', '体育学院', '刘静静-体育学院', NULL, '', '刘静静，女，1992年6月出生，汉族，安徽合肥人，讲师。 2018年于安徽师范大学体育学院硕士研究生毕业，获得运动训练硕士学位。 教学和教学情况： 1、主要承担体育赛事管理、游泳、水上救护等课程教学； 2、2022年指导学生参加安徽省第十五届运动会高校部游泳丙组比赛获得：二类教学效果5项，三类教学效果3项； 3、指导学生大学生创新创业大赛国际级、省级多项立项； 教研科研情况： 1、发表学术论文数篇，参与省级课题多项； 2、2023年6月获校级先进个人表彰；', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, '师范大学体育学院', NULL, NULL, NULL, '大学体育学院硕士研究生毕业，获得运动训练硕士学位。 教学和教学情况： ；大学生创新创业大赛国际级、省级多项立项； 教研科研情况： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('961', '徐军', '体育学院', '徐军-体育学院', NULL, '', '徐军，安徽合肥人，1990年10月16日出生，研究生学历、硕士学位、全国武术冠军、国家武术运动健将、国家一级武术裁判、国家武术六段、国家援外教练员。 个人获奖情况： 2002年：安徽省第十届武术套路省运会（规定拳第一名） 2002年：安徽省第十届武术套路省运会（集体基本功第一名） 2005年：全国武术套路少年赛（棍术第二名） 2006年：全国武术套路青年赛（棍术第一名） 2008年：获得全国武术套路锦标赛（个人体育道德风尚奖） 2009年：第十一届全国运动会决赛（刀棍全能第七名） 2009年：全国武术套路冠军赛（扑刀第一名） 2009年：世界武术套路邀请赛黄山论剑（刀棍全能第一名） 2012年：全国武术套路王中王比赛（棍术第三名） 2012年：巴西世界邀请赛（刀棍全能冠军） 执教经历： 2012年担任台湾省苗栗市主教练 2013年担任新加披主教练 2013年担任泰国国家队主教练 2014年-2016年担任印度尼西亚雅加达队教练 现任池州学院体育教师 科研情况： 在各类期刊发表学术论文2篇', '0', '0', '0', '2026-06-05 17:52:09', '2026-06-05 17:52:09', NULL, NULL, NULL, NULL, NULL, '硕士学位、全国武术冠军、国家武术运动健将、国家一级武术裁判、国家武术六段、国家援外教练员。 个人获奖情况： ', NULL, NULL);
