INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('965', '沈孟湄', '文学与传媒学院', '教授', NULL, '', '沈孟湄教授 所在学科专业 ：新闻与传播 研究方向 ：文化传播、艺术传播、城市传播 讲授课程 ：视听语言、传播学概论、影视剧作 教育经历 ：世新大学传播研究所博士班毕业 工作经历 传媒实务工作经历:记者、总编辑、节目制作、主持 学术工作经历:高校传媒系教授 科研项目 安徽省2022年度高等学校科学研究项目（哲学社会科学）重点项目主持人项目名称:数字时代安徽省城市传播发展路径研究：城市媒体融合与文化传播。项目编号:2022AH051819 2021年校级质量工程重点项目主持人。项目名称:新媒体视野下整合“以学生为中心”教学改革实践方案暨行动研究—以传媒类课程为例。项目编号: 2020XJYXM15 安徽省2024年度高等学校科学研究项目（哲学社会科学）重点项目第一参与人。项目名称:AIGC浪潮下主流意识形态传播及风险防范体系构建研究。项目编号:2024AH052912 2023年池州市社科联课题项目参与人。项目名称:基于漫画读本的新时代池州廉洁文化建设研究。项目编号: 2023ZD02 2022年池州学院校级科研项目校级人文重点项目参与人。项目名称:乡村振兴背景下皖南农村地区“三农”短视频的内容生产与传播研究。项目编号: CZ2022RWZ07 2022年池州学院校级教学研究重点项目参与人。项目名称:新文科背景下新闻传播学科课程思政实施路径研究——以“新闻采写”课程为例。项目编号2022XJY 学术论文 沈孟湄．城市形象短视频视听编码与文化记忆建构［J］.传播与版权，2024(19):39-43. 沈孟湄.高校线上教学的师生互动与传播策略研究——基于电脑中介传播的视角［J］.池州学院学报,2021,35(01):123-127. 沈孟湄，刘昭忠，甘星月.微博城市符号传播建构：以皖南三城为例［J］.新闻研究导刊，2024,15（05）：23-25. 沈孟湄，周成．城市媒体文化传播新闻符号化路径［J］.中国地市报人，2024(05)：13-16. 陈聪，沈孟湄．短视频赋能新时代乡村治理的传播进路［J］.盐城师范学院学报（人文社会科学版），2025,45(05):117-124. 周成，沈孟湄．池州诗意文化的城市符号建构与城市形象传播［J］.大众文艺，2024(09)：226-228. 王祎凡，李昕冉，徐琦琦，沈孟湄.皖南红色文化视听传播融合路径［J］.中国地市报人，2025(08): 44-46. 陈甜甜、夏雅洁、闵晓彤、沈孟湄.城市IP动画设计的创新路径——以池州市为例［J］.新传奇，2025(46): 97-99. 研讨会论文 2025年4月25日《生成式AI赋能传媒课程教学与师生关系重塑》。世新大学新闻学系第十三届「新闻的政治、文化与科技」国际学术研讨会 2023年4月26日《概念错位下的新闻公共性迷思与破解》。世新大学新闻学系第十一届「新闻的政治、文化与科技」学术研讨会 2022年4月《从“防疫五月天”到“五汉废言”：新闻修辞角色建构与解构》。世新大学新闻学系第十届「新闻的政治、文化与科技」学术研讨会 著作教材 《数字语艺-理论与实践》，2021年9月，五南图书出版，合著。 获奖情况 池州学院2020-2021、2021-2022两学年度优秀教学质量奖 指导2024年度国家级大学生创新创业项目项目名称：城市IP传播动画设计创新路径—以池州为例。项目编号:202411306006 指导2022年度国家级大学生创新创业项目项目名称:城市传播多元创新策略－以池州市为例；项目编号:202211306009 指导2023度省级大学生创新创业训练计划项目-创新训练项目项目名称:红色文化视听传播融合路径——以安徽市县级融媒体中心为例。项目编号: S202311306101 指导的作品在2025安徽省大学生微电影大赛二等奖1项、三等奖1项 指导的作品在安徽省大学生质量文化与品牌创意大赛荣获二等奖2项 指导的作品参加2022年安徽省大学生原创文学新星大赛,获小说组三等奖,作品名称《红色日记》 指导的作品参加第十四届安徽省百所高校百万大学生科普创意创新大赛获省级三等奖,作品名称《YYDS!为什么说网络爬虫是“蜘蛛侠”？》 指导的作品在中国国际大学生创新大赛（2024）池州学院校级选拔赛获特等奖1项、二等奖2项、三等奖1项', '0', '0', '0', '2026-06-05 19:30:34', '2026-06-05 19:30:34', NULL, NULL, NULL, NULL, NULL, '大学传播研究所博士班毕业 工作经历 传媒实务工作经历:记者、总编辑、节目制作、主持 学术工作经历:高校传媒系教授 科研项目 安徽省；大学新闻学系第十三届；大学新闻学系第十一届', NULL, NULL);
