INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('967', '王鹏', '文学与传媒学院', '博士', '文化影像表达 与传播 ；中国传统艺术美学；高校美育与公共文化传播 等 。 讲授课程： 纪录片创作、 艺术美学 等。 教育经历 ', '', NULL, '0', '0', '0', '2026-06-05 19:30:34', '2026-06-05 19:30:34', NULL, '博士研究生', NULL, '纪录片创作、艺术美学等', NULL, '大学 最高学历 博士研究生 ；学士 学位。 ；大学音乐学院，获艺术学硕士学位 ， 主要研究中国音乐史、音乐美学 。 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('968', '朱天成', '文学与传媒学院', '', '影视批评、新媒体艺术、中国现当代美术研究', '', '讲师。博士。研究方向：影视批评、新媒体艺术、中国现当代美术研究。主讲课程：艺术美学、二维动画、中国艺术史。邮箱：373937537@qq.com', '0', '0', '0', '2026-06-05 19:30:34', '2026-06-05 19:30:34', NULL, '博士', NULL, '艺术美学、二维动画、中国艺术史', NULL, '讲师。博士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('969', '曹敬波', '文学与传媒学院', '', '影视艺术与新媒体传播', '', '副教授。博士研究生。研究方向：影视艺术与新媒体传播。主讲课程：《影视美学》《视听节目编导》《视听语言》。发表论文20余篇。省教学成果；省教坛新秀。社会兼职：中国高等院校影视学会影视教育专业委员会理事；池州市影视艺术家协会理事。邮箱：850726081@qq.com', '0', '0', '0', '2026-06-05 19:30:34', '2026-06-05 19:30:34', NULL, '博士研究生', NULL, '《影视美学》《视听节目编导》《视听语言》', NULL, '副教授。博士', NULL, NULL);
