INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('972', '王家泠', '文学与传媒学院', '教授', NULL, '', '基本情况 姓名 王家泠 性别 女 职称 教授 所属系 广告学系 是否硕导 是 最高学历 博士 Email 3 302235281@ qq .com 详细情况 所在学科专业 传播学 研究方向 品牌传播、媒体文化 讲授课程 品牌战略与管理、消费者行为心理学、广告文化学、 网络专题策划与制作 、网络活动策划、 广告媒体投放 等 教育经历 台湾 大学 中国文学研究所 博士 台湾 大学 中国文学研究所 硕士 台湾 大学 中国文学 本科 工作经历 传媒实务工作经历 ： 北京创盛视联数码科技有限公司 、 北京吾人吾幸影视网络科技公司 、 北京天浩盛世娱乐集团 学术工作经历 ： 安徽池州学院 、 台湾大学 、 台湾师范大学 、 台湾世新大学 科研项目 2023 年 池州学院人文社会科学研究重点项目 ， “ 基于数字化技术的安徽传媒融合发展模式研究 ——以数字化转型为切入点 ” ，项目主持人。 2022 年 池州市社科联重点项目 ， “ 融媒体时代安徽池州区域品牌传播竞争力研究 ” ，项目主持人。 学术论文 近三年学术论文 ： 1.互联网时代粉丝社群网络构造样态分析, 新闻研究导刊, 2021(12). 2.新媒体环境下的“粉丝”文化和身份认同研究, 视界观, 2021(13). 3.融媒体时代安徽池州区域品牌传播竞争力研究, 百科论坛 , 2023(5). 4.Research on fan culture communication mechanism based on interactive ritual chain theory. Frontier Computing. Theory, Technologies and Applications, 2023(5) : 1519-1524. ［EI《工程索引》数据库收录］ 著作教材 《 新闻传播的发展与媒体融合研究 》，副主编， 北京 ， 中国国际广播出版社 ， 2022 年 9月 ， 5-8章，11.8万字。 《 众媒时代新闻传播转变研究 》，副主编， 北京 ， 中国原子能出版社 ， 2023 年 4月 ， 4-7章，11.7万字。 获奖情况 无 社会兼职 无', '0', '0', '0', '2026-06-05 19:30:34', '2026-06-05 19:30:34', NULL, '博士', NULL, '品牌战略与管理、消费者行为心理学、广告文化学、网络专题策划与制作、网络活动策划、广告媒体投放等', NULL, '博士 ；大学 中国文学研究所 博士 台湾 大学 中国文学研究所 硕士 台湾 大学 中国文学 本科 工作经历 传媒实务工作经历 ： 北京创盛视联数码科技有限公司 、 北京吾人吾幸影视网络科技公司 、 北京天浩盛世娱；大学 、 台湾师范大学 、 台湾世新大学 科研项目 ', NULL, NULL);
