INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('974', '张媛媛', '文学与传媒学院', '', '广告实务与品牌传播方向', '', '副教授。硕士研究生。研究方向：广告实务与品牌传播方向。主讲课程：图形创意、字体设计、标志设计、平面广告设计、互动设计、书籍装帧。邮箱：175770738@qq.com', '0', '0', '0', '2026-06-05 19:30:34', '2026-06-05 19:30:34', NULL, '硕士研究生', NULL, '图形创意、字体设计、标志设计、平面广告设计、互动设计、书籍装帧', NULL, '副教授。硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('975', '张漫宇', '文学与传媒学院', '', NULL, '', '博士。研究方向：人机交互。邮箱：441042777@qq.com', '0', '0', '0', '2026-06-05 19:30:34', '2026-06-05 19:30:34', NULL, '博士', NULL, '', NULL, '', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('976', '吴晴', '文学与传媒学院', '副教授', NULL, '', '基本情况 姓名 吴晴 性别 女 职称 副教授 所属系 动画系 是否硕导 否 最高学历 硕士研究生 Email 466740090@qq.com 详细情况 所在学科专业 戏剧与影视学 研究方向 动漫设计与理论研究 讲授课程 动画概论、计算机图形图像设计、动漫立体造型、动漫周边产品设计、二维动画设计与制作、动画后期制作 教育经历 2013-2016年 安徽工程大学 2008-2012年 齐齐哈尔大学 工作经历 2016-至今 池州学院 科研项目 1.主持:校级科研重点项目:扁平化设计在动漫角色中的创意研究——以池州傩戏为例（2017RWZ014），四类，立项年月：2017年12月，在研，有阶段性成果（以第一作者公开发表论文）。 2.参与：校级科研一般项目：戏曲题材的少儿动画研究——以黄梅戏为例（2017RW019），五类，第6，立项年月：2017年12月，在研，有阶段性成果。 学术论文 1.黑白木刻画在动画设计中的运用教学研究，2018-06，普洱学院学报，CN53-1224/G4，第3期，三类，第一作者。 2.数字绘画技术对二维动画制作的影响，2018-08，普洱学院学报，CN53-1224/G4，第4期，三类，第一作者。 3.基于当代语境下影视动画视听语言的思考，2018-08，科教文汇，CN 34-1274/G，第8期，四类，第一作者。 4.池州傩戏面具在扁平化角色设计中的应用，2018-09，电视指南，CN11-5054/J，第9期，四类，第二作者。 著作教材 无 获奖情况 无 社会兼职 无', '0', '0', '0', '2026-06-05 19:30:34', '2026-06-05 19:30:34', NULL, '硕士研究生', NULL, '动画概论、计算机图形图像设计、动漫立体造型、动漫周边产品设计、二维动画设计与制作、动画后期制作', NULL, '硕士研究生 ；大学 ；大学 工作经历 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('977', '蔡圆寒', '马克思主义学院', '蔡圆寒-池州学院马克思主义学院', NULL, '', '蔡圆寒 ， 女 ， 中共党员 ， 助教 。 2023 年 6 月毕业于 安徽 大学 徽学与中国传统文化研究院中国史 专业，获 历史学硕士 学位 ， 在校期间获安徽大学优秀毕业生称号 。现为池州学院马克思主义学院 形势与政策教研室专职教师，主要讲授《中国近现代史纲要》《思想道德与法治》《习近平总书记关于教育的重要论述》《形势与政策》等课程。 项目情况 1.《东至周氏家风助力党风廉政建设》 （项目编号：RH2400001286） 2.《东至周氏家族近现代转型研究》（项目编号：CZ2024RW05） 3.《地方文化资源赋能大中小思政课一体化建设的路径——以池州市为例》（项目编号：JK2024067） 4.《五四精神与新时代青年的使命担当——马克思主义在中国早期传播的实践启示》（教改项目） 二、获奖情况 1.2025年池州市大中小学思政课一体化建设专题论文评选一等奖； 2.2024年安徽省第三届大学生讲思政课比赛三等奖指导教师； 3. 2024年池州学院“教学活动月”优秀工作者。', '0', '0', '0', '2026-06-05 19:40:08', '2026-06-05 19:40:08', NULL, NULL, NULL, NULL, NULL, '大学 徽学与中国传统文化研究院中国史 专业，获 历史学硕士 学位 ， 在校期间获安徽大学优秀毕业生称号 。现为池州学院马克思主义学院 形势与政策教研室专职教师，主要讲授；大学生讲思政课比赛三等奖指导教师； ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('978', '叶美', '马克思主义学院', '叶美-池州学院马克思主义学院', NULL, '', '叶美 ， 女 ， 中共党员 ， 硕士研究生 。 2024 年 7 月毕业于 安徽 大学 马克思主义 学院 马克思主义基本原理 专业，获 法学 学位。现为池州学院马克思主义学院 专职思政课教师，主要讲授《马克思主义基本原理》《中国近现代史纲要》《习近平总书记关于教育的重要论述研究》《形式与政策》等课程。', '0', '0', '0', '2026-06-05 19:40:10', '2026-06-05 19:40:10', NULL, NULL, NULL, NULL, NULL, '硕士研究生 。 ；大学 马克思主义 学院 马克思主义基本原理 专业，获 法学 学位。现为池州学院马克思主义学院 专职思政课教师，主要讲授', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('979', '肖新乐', '材料与环境工程学院', '', '1.燃料电池隔膜开发', '', '教授。年硕士毕业于合肥工业大学大学化学工程专业，获工科硕士。研究方向：1.燃料电池隔膜开发。主讲课程：化工原理、材料工程基础、化工环境保护与安全技术、化工原理实验等', '0', '0', '0', '2026-06-05 19:45:47', '2026-06-05 19:45:47', NULL, '合肥工业大学大学化学工程（硕士）', NULL, '化工原理、材料工程基础、化工环境保护与安全技术、化工原理实验等', NULL, '合肥工业大学大学化学工程专业，工科硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('980', '汪鹏飞', '材料与环境工程学院', '', '功能纳米材料、清洁能源材料', '', '教授。年获南京大学理学博士学位，教授，硕士。研究方向：功能纳米材料、清洁能源材料。主讲课程：物理化学、材料合成与制备技术、材料综合性设计实验、材料合成与制备实验', '0', '0', '0', '2026-06-05 19:45:49', '2026-06-05 19:45:49', NULL, '年获南京大学（博士）', NULL, '物理化学、材料合成与制备技术、材料综合性设计实验、材料合成与制备实验', NULL, '南京大学理学博士学位', NULL, NULL);
