INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('982', '王文韬', '材料与环境工程学院', '', '功能高分子材料结构设计及应用、柔性离子凝胶及气凝胶材料研究', '', '副教授。年博士后出站于深圳大学光学工程博士。研究方向：功能高分子材料结构设计及应用，柔性离子凝胶及气凝胶材料研究。主讲课程：高分子材料，聚合反应工程，科技英语', '0', '0', '0', '2026-06-05 19:46:09', '2026-06-05 19:46:09', NULL, '年博士后出站于深圳大学（博士）', NULL, '高分子材料，聚合反应工程，科技英语', NULL, '教授。年博士、光学工程博士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('983', '伍光辉', '材料与环境工程学院', '', '有机合成、有机光电功能材料', '', '副教授。年毕业于安徽大学化学与材料工程学院无机化学专业，获硕士。研究方向：有机合成、有机光电功能材料。主讲课程：有机化学、仪器分析、有机化学实验。安徽省教学成果奖三等奖（项目编号：2013cgj172，第三完成人）；', '0', '0', '0', '2026-06-05 19:46:11', '2026-06-05 19:46:11', NULL, '硕士', NULL, '有机化学、仪器分析、有机化学实验', NULL, '安徽大学化学与材料工程学院无机化学专业，硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('984', '傅妍芳', '材料与环境工程学院', '', '环境经济学、固体废物资源化、碳排放与环境管理', '', '副教授。年毕业于安徽大学应用化学专业，获理学学士。研究方向：环境经济学，固体废物资源化，碳排放与环境管理。主讲课程：固体废物处理与处置（双语），物理污染控制工程', '0', '0', '0', '2026-06-05 19:46:16', '2026-06-05 19:46:16', NULL, '安徽大学', NULL, '固体废物处理与处置（双语），物理污染控制工程', NULL, '安徽大学应用化学专业，理学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('985', '李敏', '材料与环境工程学院', '', NULL, '', '副教授。研究方向：功能陶瓷材料。主讲课程：《材料科学基础》', '0', '0', '0', '2026-06-05 19:46:18', '2026-06-05 19:46:18', NULL, '', NULL, '《材料科学基础》', NULL, '', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('986', '吴秋艳', '材料与环境工程学院', '', '功能性配合物材料', '', '高级实验师。年本科毕业于湖南大学化学专业，获理学学士。研究方向：功能性配合物材料。主讲课程：无机化学实验、分析化学实验、仪器分析实验、材料测试技术实验。获得2018年度“最美教师”称号', '0', '0', '0', '2026-06-05 19:46:20', '2026-06-05 19:46:20', NULL, '湖南大学', NULL, '无机化学实验、分析化学实验、仪器分析实验、材料测试技术实验', NULL, '湖南大学化学专业，理学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('987', '章敏', '材料与环境工程学院', '', '功能有机小分子合成及应用', '', '副教授。年本科毕业于安徽师范大学化学专业，获理学学士。研究方向：功能有机小分子合成及应用。主讲课程：分析化学、专业英语、基础化学实验3A（有机）、化学综合实验。2016年 池州学院优秀教案奖；', '0', '0', '0', '2026-06-05 19:46:25', '2026-06-05 19:46:25', NULL, '安徽师范大学', NULL, '分析化学、专业英语、基础化学实验3A（有机）、化学综合实验', NULL, '安徽师范大学化学专业，理学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('988', '桂美芳', '材料与环境工程学院', '', '光分析化学', '', '副教授。年本科毕业于安徽师范大学化学专业，获理学学士。研究方向：光分析化学。主讲课程：《无机化学》、《无机及分析化学》、《仪器分析》等。2016年《无机及分析化学》获校级优秀多媒体课件奖；', '0', '0', '0', '2026-06-05 19:46:28', '2026-06-05 19:46:28', NULL, '安徽师范大学', NULL, '《无机化学》、《无机及分析化学》、《仪器分析》等', NULL, '安徽师范大学化学专业，理学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('989', '甘杰', '材料与环境工程学院', '', '能源催化、纳米材料', '', '副教授。年博士毕业于华东理工大学化学工程专业，获得工学博士。研究方向：能源催化、纳米材料。主讲课程：《化工热力学》、《科技英语》、《聚合反应工程》、《专业文献检索》、《发光原理与发光材料》、《材料物理实验》、《科技绘图与写作》', '0', '0', '0', '2026-06-05 19:46:30', '2026-06-05 19:46:30', NULL, '华东理工大学化学工程（博士）', NULL, '《化工热力学》、《科技英语》、《聚合反应工程》、《专业文献检索》、《发光原理与发光材料》、《材料物理实验》、《科技绘图与写作》', NULL, '华东理工大学化学工程专业，得工学博士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('990', '王红新', '材料与环境工程学院', '', '污染土壤生态修复及健康风险评价', '', '副教授。年博士毕业于南京农业大学生态学专业，获理学博士。研究方向：污染土壤生态修复及健康风险评价。主讲课程：环境学概论、环境工程原理、科技英语、土壤污染监测与分析。获年度考核优秀3次：2007年、2016年、2023年；', '0', '0', '0', '2026-06-05 19:46:36', '2026-06-05 19:46:36', NULL, '南京农业大学生态学（博士）', NULL, '环境学概论、环境工程原理、科技英语、土壤污染监测与分析', NULL, '南京农业大学生态学专业，理学博士', NULL, NULL);
