INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('992', '葛俊彦', '材料与环境工程学院', '', '现主要从事生态环境及生物无机复合功能材料研究', '', '副教授。月硕士毕业于安徽师范大学生态学专业，获理学硕士。研究方向：现主要从事生态环境及生物无机复合功能材料研究。主讲课程：《生物化学》、《化学基础实验》', '0', '0', '0', '2026-06-05 19:46:43', '2026-06-05 19:46:43', NULL, '硕士', NULL, '《生物化学》、《化学基础实验》', NULL, '安徽师范大学生态学专业，理学硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('993', '黄劲松', '材料与环境工程学院', '', '果蔬采后生物学', '', '副教授。年本科毕业于安徽农业大学食品科学专业，获工学学士。研究方向：果蔬采后生物学。主讲课程：应用化学科技英语、无机及分析化学实验、大学化学实验', '0', '0', '0', '2026-06-05 19:46:44', '2026-06-05 19:46:44', NULL, '安徽农业大学', NULL, '应用化学科技英语、无机及分析化学实验、大学化学实验', NULL, '安徽农业大学食品科学专业，工学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('994', '黄志良', '材料与环境工程学院', '', '电缆护套料改性和3D打印可降解塑料', '', '副教授。年毕业于合肥工业大学材料学专业，获硕士。研究方向：电缆护套料改性和3D打印可降解塑料。主讲课程：高分子物理、高分子成型设备与模具', '0', '0', '0', '2026-06-05 19:46:46', '2026-06-05 19:46:46', NULL, '硕士', NULL, '高分子物理、高分子成型设备与模具', NULL, '合肥工业大学材料学专业，硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('995', '钱立武', '材料与环境工程学院', '', '稀土功能材料', '', '副教授。年硕士毕业于安徽师范大学有机化学专业，获理学硕士。研究方向：稀土功能材料。主讲课程：化工原理﹑光电功能材料﹑化工技术经济﹑稀土材料与应用。2015年，获安徽省级质量工程教学成果奖三等奖', '0', '0', '0', '2026-06-05 19:46:48', '2026-06-05 19:46:48', NULL, '安徽师范大学有机化学（硕士）', NULL, '化工原理﹑光电功能材料﹑化工技术经济﹑稀土材料与应用', NULL, '安徽师范大学有机化学专业，理学硕士', NULL, NULL);
