INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('997', '任珊', '材料与环境工程学院', '', '电催化CO2还原、超级电容器', '', '副教授。年博士毕业于苏州大学化学专业，获理学博士。研究方向：电催化CO2还原，超级电容器。主讲课程：《新能源器件与系统》《材料合成与制备实验》《化工原理实验》《材料分析测试方法》《电化学实验》', '0', '0', '0', '2026-06-05 19:46:51', '2026-06-05 19:46:51', NULL, '苏州大学化学（博士）', NULL, '《新能源器件与系统》《材料合成与制备实验》《化工原理实验》《材料分析测试方法》《电化学实验》', NULL, '苏州大学化学专业，理学博士', NULL, NULL);
