INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('999', '于磊', '材料与环境工程学院', '', '固体废弃物处理处置及资源化利用', '', '副教授。获工学学士学位。研究方向：固体废弃物处理处置及资源化利用。主讲课程：材料分析测试方法、工程制图', '0', '0', '0', '2026-06-05 19:46:54', '2026-06-05 19:46:54', NULL, NULL, NULL, '材料分析测试方法、工程制图', NULL, '。获工学学士、工学学士学位', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1000', '严永新', '材料与环境工程学院', '', '有机合成。主讲课程：有机化学、有机化学实验、仪器分析实验等', '', '副教授。年本科毕业于安徽师范大学化学教育专业，获理学学士。研究方向：有机合成。主讲课程：有机化学，有机化学实验，仪器分析实验等。池州学院优秀教学质量奖,2023年6月；', '0', '0', '0', '2026-06-05 19:46:57', '2026-06-05 19:46:57', NULL, '安徽师范大学', NULL, '有机化学，有机化学实验，仪器分析实验等', NULL, '安徽师范大学化学教育专业，理学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1001', '周瑾', '材料与环境工程学院', '', '功能高分子膜材料的制备与应用', '', '副教授。年本科毕业于安徽师范大学化学专业，获理学学士。研究方向：功能高分子膜材料的制备与应用。主讲课程：高分子化学、高分子物理、高分子材料与可持续发展、高分子化学实验、高分子物理实验等。安徽省科学技术奖三等奖(第三完成人)，2011年12月', '0', '0', '0', '2026-06-05 19:46:59', '2026-06-05 19:46:59', NULL, '安徽师范大学', NULL, '高分子化学、高分子物理、高分子材料与可持续发展、高分子化学实验、高分子物理实验等', NULL, '安徽师范大学化学专业，理学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1002', '刘廷国', '材料与环境工程学院', '', '主要从事农副产品深加工及功能性高吸水性材料的合成与应用研究、', '', '副教授。年本科毕业于华中农业大学食品科技学院食品科学与工程专业，获工学学士。研究方向：主要从事农副产品深加工及功能性高吸水性材料的合成与应用研究，。主讲课程：材料分析测试方法、高分子材料研究方法、生物化学等。先进科研工作者，2018年6月；', '0', '0', '0', '2026-06-05 19:47:02', '2026-06-05 19:47:02', NULL, '华中农业大学食品科技学院', NULL, '材料分析测试方法、高分子材料研究方法、生物化学等', NULL, '华中农业大学食品科技学院食品科学与工程专业，工学学士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1003', '詹庆', '材料与环境工程学院', '詹庆-池州学院材料与环境工程学院', '过渡金属硫化物的掺杂性能研究', '', '年硕士毕业于南京工业大学有机化学专业，获理学硕士。研究方向：过渡金属硫化物的掺杂性能研究。主讲课程：精细有机合成、基础化学实验3A（有机）', '0', '0', '0', '2026-06-05 19:50:21', '2026-06-05 19:50:21', NULL, '南京工业大学有机化学（硕士）', NULL, '精细有机合成、基础化学实验3A（有机）', NULL, '南京工业大学有机化学专业，理学硕士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1004', '周恺', '大数据与人工智能学院', '教授/博士', NULL, '', '周恺，男，汉族，博士，教授，安徽省数学会理事、安徽省工业与应用数学学会理事，池州学院应用数学研究中心负责人。2011年6月毕业于中山大学数学与计算科学学院，获理学博士学位；2015年9月进入上海师范大学数学博士后流动站，2017年11月出站；2017年7月-8月赴法国斯特拉斯堡大学高等数学研究所访问。安徽省教学名师，安徽省模范教师，安徽省教科文卫体系统师德先进个人，安徽省教坛新秀，池州学院青年教师导师。 E-mail: zk1984@163.com 研究领域和方向： 常微分方程、泛函微分方程、动力系统 主讲课程： 数学分析、常微分方程、高等数学、概率论与数理统计、数学史、随机过程、控制论基础等 科研论文： 1. Kuilin Wu, Kai Zhou.Traveling waves in a nonlocal dispersal SIR model with standard incidence rate and nonlocal delayed transmission.Mathematics,2019, 7: 641.（SCI） 2. Qiuhua Zhang, Kai Zhou.Stationary distribution and extinction of a stochastic SIQR model with saturated incidence rate. Mathematical Problems in Engineering, 2019, Article ID 3575410.（SCI） 3. Yanfang Fu, Kai Zhou. Global stability of a stochastic Beddington-DeAngelis type predator-prey model with time delay and stage structure forprey incorporating refuge. Journal of Physics: Conference Series，2019.（EI） 4. Qiuhua Zhang, Kai Zhou. Extinction and persistence of a stochastic SIRS model with nonlinear incidence rate and transfer from infectious to susceptible. Journal of Physics: Conference Series，2019.（EI） 5. Gao Fang，Li Xiaoxin，Zhou Kai，Liu Jia-Bao. The Extremal Graphs of Some Topological Indices with Given Vertex k-Partiteness. Mathematics,2018, 6: 271.（SCI） 6. Kai Zhou, Maoan Han, Qiru Wang. Traveling wave solutions for a delayed diffusive SIR epidemic model with nonlinear incidence rate and external supplies. Mathematical Methods in the Applied Sciences, 2017,40:2772-2783.（SCI） 7. Kai Zhou. Existence of traveling wave solutions in m-dimensional delayed lattice dynamical systems with competitive quasimonotone and global interaction. Journal of Nonlinear Sciences and Applications, 2017,10:3630-3642.（SCI） 8. Kai Zhou, Qi-Ru Wang. Existence of traveling waves for a delayed SIRS epidemic diffusion model with saturation incidence rate. Abstract and Applied Analysis, 2014, Article ID 369072,8 pages.（SCI） 9. Kai Zhou, Qi-Ru Wang. Existence and asymptotics of traveling wave fronts for a delayed nonlocal di', '0', '0', '0', '2026-06-05 20:01:04', '2026-06-05 20:01:04', NULL, '中山大学', NULL, '数学分析、常微分方程、高等数学、概率论与数理统计、数学史、随机过程、控制论基础等 科研论文： ', NULL, '博士，教授，安徽省数学会理事、安徽省工业与应用数学学会理事，池州学院应用数学研究中心负责人。；大学数学与计算科学学院，获理学博士学位；；大学数学博士后流动站，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1005', '张钦礼', '大数据与人工智能学院', '教授/博士', NULL, '', '张钦礼，男，河北廊坊人，教授，博士。 研究领域和方向：模糊集理论，粗糙集理论，证据理论，粒计算及人工智能等。 主讲课程：《离散数学》、《算法设计与分析》及《数据结构》等。 科研论文： 1.Q.L. Zhanget al.New uncertainty measurement for categorical data based on fuzzy information structures:an application in attribute reduction, Information Sciences,2021,中科院SCI一区； 2. Q.L. Zhang et al.Uncertainty measurement for single cell RNA-seq data based on class-consistent technology with application to semi-supervised gene selection, Applied SoftComputing, 2023,中科院SCI一区； 3. Q.L. Zhang et al.Attribute reduction algorithms with an anti-noise mechanism for hybrid data based on fuzzy evidence theory, Engineering Applications of Artificial Intelligence, 2024,中科院SCI二区； 4. Q.L. Zhang et al. Attribute reduction based on D-S evidence theory in a hybrid information system, International Journal of Approximate Reasoning, 2022,中科院SCI二区; 5. Q.L. Zhang et al. Attribute reduction for set-valued data based on D-S evidence theory, International Journal of General Systems, 2022,中科院SCI三区。', '0', '0', '0', '2026-06-05 20:01:19', '2026-06-05 20:01:19', NULL, NULL, NULL, '《离散数学》、《算法设计与分析》及《数据结构》等。 科研论文： ', NULL, '博士。 研究领域和方向：模糊集理论，粗糙集理论，证据理论，粒计算及人工智能等。 主讲课程：', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1006', '袁魏华', '大数据与人工智能学院', '教授/博士', NULL, '', '袁魏华，男，1977.06-，河北井陉人，教授，博士，硕士生导师。 E-mail:70293728@qq.com 研究领域和方向： 人工智能与计算机视觉、智能无人系统 主讲课程： 《模式识别与计算机视觉》、《机器学习》、《程序设计基础》 教科研项目 ： 1.安徽省科研创新团队—电子信息处理与材料器件创新团队，项目编号：2022AH010098.。 获奖情况： 1、获国家科技进步二等奖1项； 2、获军队科技进步一等奖1项； 3、获军队科技进步二等奖2项； 4、获军队科技进步三等奖5项； 5、获安徽省教学成果二等奖1项。', '0', '0', '0', '2026-06-05 20:01:21', '2026-06-05 20:01:21', NULL, NULL, NULL, '《模式识别与计算机视觉》、《机器学习》、《程序设计基础》 教科研项目 ： ', NULL, '博士，硕士生导师。 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1007', '张百顺', '大数据与人工智能学院', '教授/博士', NULL, '', '张百顺，男，1975.10-，河南兰考人，教授，博士。 E-mail:zbs01@163.com 研究领域和方向： 光电侦查、机器视觉 主讲课程： 《控制工程基础》、《兵器科学技术》、《机器学习》、《自然语言处理》、《C语言程序设计》 专著 ： 1.《兵器科学技术概论》，兵器工业出版社，2017.01； 2.《兵器科学技术总论》，兵器工业出版社，2018.02； 科研论文： 1.A non-reductive electrochemical sensor for ultrasensitive detection of pM-level TNT，Analytical Methods，2018.10,SCI； 2.用于选通成像的半导体激光器列阵光束整形技术研究，量子电子学报，2020.03； 3. Fe doped MoS2/polypyrrole microtubes towards efficient peroxidase mimicking and colorimetric sensing application，Dalton Transactions，2021.11,SCI；', '0', '0', '0', '2026-06-05 20:01:23', '2026-06-05 20:01:23', NULL, NULL, NULL, '《控制工程基础》、《兵器科学技术》、《机器学习》、《自然语言处理》、《C语言程序设计》 专著 ： ', NULL, '博士。 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1008', '方元康', '大数据与人工智能学院', '副教授/博士', NULL, '', '方元康，男， 1968 年 10 月生，安徽池州人，副教授，博士。 学术经历： 1990年阜阳师范学院数学系（本科） 2003年合肥工业大学计算机学院（硕士） 2009年南京航空航天大学计算机学院（博士） 研究领域和方向： 数据挖掘与分析、人工智能、软件形式化验证，共发表中英文论文26篇，第一作者15篇。其中5篇被《美国工程索引》数据库（EI）收录，3篇被《美国科技会议录索引》数据库（ISTP）收录，10篇被《中国科学引文数据库》（CSCD核心版）收录。“阳光高考工作室（高考志愿填报指导QQ：611173019）”负责人，近七年来专注于高考大数据的分析与研究，手机：13905663416，E-mail：fyk80@czu.edu.cn 主讲课程： 数据挖掘与分析、软件工程、JAVA程序设计、大学计算机导论等 荣誉及社会兼职： 1.International Symposium on Intelligence Computation and Applications；International Conference on Web Information Systems and Mining等国际会议论文特邀审稿专家 2.中国计算机学会（CCF）高级会员 3.安徽省教育厅重点科研项目评审专家库成员 4.荣获第二批池州学院青年教师导师（科研型）资格 5.分别荣获池州学院2008年度、2015年度考核优秀等次 6.国家级大学生创新创业指导教师 7.池州市人才招聘评审专家库成员 8.《池州学院学报》期刊论文审稿专家库成员 教科研项目： 1.高可信软件生产工具及集成环境，国家“863”重大科研资助项目计划(2009AA010307)，项目组成员 2.基于控制机制的软件可靠性新技术及其理论研究，国家自然科学基金项目（61100034），第一参与人. 3.基于抽象的软件符号模型检测研究，国家自然科学基金项目（61170043），项目组成员 4.基于RFID数据管理平台及环境污染事故危险源监管系统的研发，安徽省教育厅自然科学研究项目（KJ2011B108）主持人. 5.一种WEB日志挖掘系统的构建，池州学院自然科学研究项目（XK0829），主持人 6.《VFP程序设计》课程案例教学的设计及实施，池州学院教学研究项目（2007XJ015），主持人 发表的英文期刊论文： [1] Yuankang Fang , ZiyangZhen, ZhiqiuHuang, ChaoZhang,Multi-Objective Fuzzy Clustering Method for Image Segmentation Based on Variable-Length Intelligent Optimization Algorithm,Lecture Notes in Computer Science[J](2010,EI收录) [2] Yuankang Fang ,Zhiqiu Huang ,A Session Identification Algorithm Based On Frame Page And Pagethreshold, Lecture Notes in Computer Science[J](2010,EI收录) [3] Yuankang Fang , ZhiqiuHuang , An Improved Algorithm for Session Identification on Web Log,The 2010 International Conference on Web Information Systems and Mining ,(2010,EI收录) [4] Yuankang Fang , Luo Yuping,Ye Zan and Liu Ying,Research on Improve DBSCAN Algorithm Based On Ant Clustering，The Open Automation and Control Systems Journal[J]（2015,EI收录） [5] WANG Juan, ZHENG Shu-li, CAO Man-cheng, Yuankang Fang ,Improved Kerberos Protocol Based on Certificateless Key Agreement,Web Information Systems And Mining[J]（2013,EI收录） 发表的中文期刊论文： [1] 方元康 ,胡学钢,夏启寿. Web日志预处理中优化的会话识别方法[J].计算机工程,2009,(07):49-51. （ CSCD 核心版） [2] 方元康 ,胡学钢,夏', '0', '0', '0', '2026-06-05 20:01:34', '2026-06-05 20:01:34', NULL, NULL, NULL, '数据挖掘与分析、软件工程、JAVA程序设计、大学计算机导论等 荣誉及社会兼职： ', NULL, '博士。 学术经历： ；本科；大学计算机学院', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1009', '高芳', '大数据与人工智能学院', '副教授/博士', '化学图论 主持的教科研项目： ', '', '高芳，副教授，女，安徽东至人。2007年毕业于合肥工业大学信息与计算科学专业，获理学学士学位，2010年毕业于合肥工业大学应用数学专业，获理学硕士学位，2022年毕业于南京航天航空大学运筹学与控制论专业，获理学博士学位。 主讲课程： 高等数学，线性代数，近世代数，概率论与数理统计，图论 研究方向： 化学图论 主持的教科研项目： 1、安徽省教育厅示范基层教研室项目：应用数学（2020SJSFJXZZ297），主持 2、安徽省课程思政教学团队：微分方程及其应用课程思政教学团队(2020kcszjxtd57)，参与 3、安徽省教育厅教研重点项目：以本为本背景下的地方本科院校公共数学基础课程建设研究(2018jyxm0579)，参与 4、安徽省教育厅教研重点项目：线性代数精品线下开放课程(2018kfk051)，参与 5、池州学院校级教学团队：代数类课程群教学团队(2016XJXTD02)，参与 6、安徽省高校优秀青年人才支持计划项目(gxyq2019107)，主持 7、池州学院自然科研重点项目：图的若干Zagreb指标研究(2017ZRZ009)，主持 8、池州学院自然科研重点项目：量子纠错码的图论构造方法研究(2015ZRZ005)，主持 研究成果： 1、Graphs having extremal monotonic topological indices with bounded vertex k-partiteness.Journal of Applied Mathematics and Computing.2018，EI.(第一作者) 2、The extremal graphs of some topological indices with given vertex k-partiteness. Mathematics.2018，SCI.(第一作者) 3、Maximum augmented Zagreb index of graphs with a given vertex bipartiteness.中国科学技术大学学报.2019，CSCD核心.(第一作者) 4、A formula with its applications on the difference of Zagreb indices of graphs.Journal of Mathematical Chemistry. 2019，SCI.(第二作者) 5、On the reduced second Zagreb index of graphs.Rocky Mountain Journal of Mathematics. 2020，SCI. 6、On the difference of Mostar index and irregularity of graphs.Bulletin of the Malaysian Mathematical Sciences Society. 2021，SCI. 7、一类特殊的二阶常系数线性非齐次微分方程的解法.赤峰学院学报,2018.（第二作者） 8、一道求微分方程特解习题的推广.池州学院学报,2018.(第一作者) 获得的主要奖励： 2020年，池州学院校级“教坛新秀” 2021年，池州学院2021年度“教书育人楷模” 2018年，安徽省教学成果二等奖 2017年，安徽省高校数学微课程教学设计竞赛二等奖 2016年，池州学院工会先进工作者 池州学院2016年、2018年优秀共产党员 池州学院2012年度、2016年度考核优秀等次 2012年，池州学院青年教师技能比赛三等奖 获池州学院教学单项奖多次', '0', '0', '0', '2026-06-05 20:01:39', '2026-06-05 20:01:39', NULL, '合肥工业大学', NULL, '高等数学，线性代数，近世代数，概率论与数理统计，图论 研究方向： 化学图论 主持的教科研项目： ', NULL, '大学信息与计算科学专业，获理学学士学位，；大学应用数学专业，获理学硕士学位，；大学运筹学与控制论专业，获理学博士学位。 主讲课程： 高等数学，线性代数，近世代数，概率论与数理统计，图论 研究方向： 化学图论 主持的教科研项目： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1010', '柳思维', '商学院', '柳思维-商学院', NULL, '', '柳思维，博士，管理科学与工程专业，韩国又松大学访问学者，高级电子商务师（一级国家职业资格证书），池州市侨联副秘书长，池州学院侨联秘书长，池州市半导体行业协会理事。先后荣获安徽省青年岗位能手、安徽省教学成果奖二等奖、池州学院优秀共产党员、校级教坛新秀、双能型教师、省赛评委，省级赛事优秀裁判、安徽省人力资源与社会保障厅电子商务技能鉴定专家等荣誉。主持国家级、省级各类科研课题30余项，国内外公开刊物发表成果6篇，编写及参编教材3部，指导学生团队获大学生学科与技能竞赛国家级、省级竞赛奖项80余项，其中一等奖 20余项，多次被评为优秀指导教师。长期深耕区域经济、电子商务发展等领域的理论与实证研究，积累了较为丰富的学术成果与教学实践经验，在专业教学、科学研究、实践育人方面成果突出。主讲网上零售理论与实战、客户关系管理、创新创业实战等课程。', '0', '0', '0', '2026-06-05 20:01:45', '2026-06-05 20:01:45', NULL, NULL, NULL, NULL, NULL, '博士，管理科学与工程专业，韩国又松大学访问学者，高级电子商务师；大学生学科与技能竞赛国家级、省级竞赛奖项', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1011', '赵梦婵', '商学院', '赵梦婵-商学院', NULL, '', '赵梦婵，池州学院商学院（法学院）讲师，经济学博士，毕业于安徽大学产业经济学专业。长期深耕产业经济、区域经济发展等领域的理论与实证研究，迄今已在《当代经济科学》《经济经纬》《产业经济研究》《经济体制改革》等CSSCI 来源期刊及SSCI期刊上发表学术论文10余篇。作为项目负责人，先后牵头承担安徽省哲学社会科学规划项目、安徽省社会科学创新发展研究课题、安徽省教育厅科学研究重大项目等省部级科研项3项，研究内容紧密围绕地方经济发展与产业转型升级的现实需求。指导学生参与A类、B类学科竞赛，累计斩获国家级、省级等各级奖项10余项，研究成果获得市厅级奖励1项，学术贡献与实践价值得到学界与业界的双重认可。', '0', '0', '0', '2026-06-05 20:01:47', '2026-06-05 20:01:47', NULL, '安徽大学', NULL, NULL, NULL, '博士，毕业于安徽大学产业经济学专业。长期深耕产业经济、区域经济发展等领域的理论与实证研究，迄今已在', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1012', '王娟', '大数据与人工智能学院', '副教授', '计算机教学法与计算机网络信息安全研究工作', '', '王娟，女，1977年9月出生，本科毕业于合肥工业大学计算机应用技术专业；2011年获合肥工业大学计算机与信息学院工程硕士学位，现为池州学院数学与计算机科学系副教授。 E-mail ： 158163633@qq.com 。 研究领域和方向： 主要从事计算机教学法与计算机网络信息安全研究工作。 主讲课程： C语言程序设计、数据库应用技术。 主要论文： 1. WANG Juan,Cao Man-cheng,Zhen Shu-li,Fang Yuan-kang. An Improved Kerberos Intra-domain Authentication Protocol Based-on Certificateless Public-key Cryptography，which will be published by Springer, Advances in Intelligent and Soft Computing(ISSN: 1867-5662). 2. 王娟,郑淑丽,操漫成,方元康.基于无证书密钥协商的Kerberos改进协议[J].计算机工程,2012,12(23):127-130. 3. 王娟,郑淑丽,方元康.无证书隐式认证改进的Kerberos单点登录协议[J].计算机工程与应用,2013,49(10):105-108. 4. 王娟.《Kerberos认证协议在电子商务中的应用研究》: [硕士学位论文].合肥工业大学，2011. 5. 王娟.一种综合认证策略在企业信息资源单点登录技术中的应用[J].池州学院学报,2010.6. 6. 王娟.一种基于无证书公钥密码学思想的Kerberos认证方案的改进[J],池州学院学报,2011.3 7. 王娟.VFP实验课中“任务驱动”教学法的应用[J],池州学院学报,2008,10(5). 8. 王娟.基于FP-Growth算法改进的多层次关联规则挖掘算法[J].电脑知识与技术,2008,10(7). 9. 王娟.应用技术型大学实施创客教育的路径探索[J].黄山学院学报,2017.12(6) 10. 王娟.应用技术型大学面向新农村建设实施创客教育的路径初探[J].池州学院学报,2018.12(6) 教科研项目： 教研项目： 主持：2015.12主持省级质量工程项目：应用型本科院校以计算机专业为依托实施创客教育的路径探索(2015jyxm01)，已结题； 参与：校级教研项目《面向电子商务专业的〈Java程序设计〉》已结题 科研项目： 主持： 1.2011.12主持省教育厅课题：基于无双线性对的无证书密钥协商协议在WSN密钥管理中的应用研究（KJ2012Z273），已结题； 2.2010.1主持池州学院课题：基于知识管理的办公自动化研究—以池州学院为例（2010ZR002），已结题 参与： 2012年1月参与安徽省科技厅课题:农产品安全信息查询系统与服务模式研究(12020503059)，已结题。 获奖情况： 2012.5获池州学院“青年教师教学技能大赛”二等奖； 2011.3获池州学院教育工会颁发的“三八”女教职工演讲比赛三等奖； 2011.5分获池州学院创先领导小组颁发的“创先争优在行动”主题演讲、征文比赛一等奖； 2012.3获池州学院教育工会颁发的“三八”女教职工演讲比赛二等奖； 2011.6获省教育工委“创先争优在行动”主题征文比赛优胜奖； 2011.6被中共池州学院委员会授予“优秀共产党员”称号； 2017年10月，获望江县“巾帼在行动”演讲比赛二等奖； 2017、2018连续两年，被望江县政府授予“优秀扶贫工作者”称号； 2018年11月，被望江县妇联推选为安庆市第十四次妇女代表大会代表； 2018年12月，获安徽省教科文卫体系统第二届“书香天使”读书活动征文比赛一等奖； 2017-2019连续三年，获望江县长岭镇优秀通讯员奖； 2017-2019连续三年，获得望江县土永村优秀共产党员称号。', '0', '0', '0', '2026-06-05 20:01:50', '2026-06-05 20:01:50', NULL, '合肥工业大学', NULL, 'C语言程序设计、数据库应用技术。 主要论文： ', NULL, '本科毕业于合肥工业大学计算机应用技术专业；；大学计算机与信息学院工程硕士学位，现为池州学院数学与计算机科学系副教授。 ；硕士学位论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1013', '余金湘', '商学院', '余金湘-商学院', '产业经济、经济监督等研究工作、在《中国软科学》《经济问题探索》《当代经济研究》等期刊发表多篇论文', '', '余金湘，南京农业大学经济学博士，讲师，主要从事产业经济、经济监督等研究工作，在《中国软科学》《经济问题探索》《当代经济研究》等期刊发表多篇论文。指导学生参加全国高校商业精英挑战赛全国总决赛和安徽省赛获奖3项，指导学生参加安徽省大学生服务外包创新创业大赛获二等奖1项。', '0', '0', '0', '2026-06-05 20:01:53', '2026-06-05 20:01:53', NULL, NULL, NULL, NULL, NULL, '大学经济学博士，讲师，主要从事产业经济、经济监督等研究工作，在；大学生服务外包创新创业大赛获二等奖', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1014', '王杰', '商学院', '王杰-商学院', '于数字经济、乡村振兴等方向研究', '', '【个人经历】王杰，南京林业大学管理学博士，现任池州学院商学院（法学院）数字经济系系主任，安徽工业大学商学院兼职硕士生导师。曾获博士研究生国家奖学金、南京林业大学优秀毕业生等荣誉。 【研究方向】目前主要从事于数字经济、乡村振兴等方向研究。 【科研项目】主持立项国家社会科学基金、安徽省哲学社会科学规划项目、安徽省社会科学创新发展课题、安徽省教育厅人文社会科学重点项目等课题6项。 【科研论文】以第一作者身份在《电子政务》《资源科学》《Frontiers in Psychology》等CSSCI/SSCI来源期刊发表论文11篇，总他引超700次，单篇最高被引248次，2024和2025年均入选中国知网高被引学者Top 5%名单。 【科研获奖】多次参加中国农林经济管理学术年会、“三农论坛”等高水平会议并作论文报告，曾获安徽省社科联“三项课题”研究活动一等奖、江苏省哲学社科界学术大会优秀论文一等奖等重要学术奖项。 【联系邮箱】wangj@czu.edu.cn。', '0', '0', '0', '2026-06-05 20:01:57', '2026-06-05 20:01:57', NULL, NULL, NULL, NULL, NULL, '大学管理学博士，现任池州学院商学院；大学商学院兼职硕士生导师。曾获博士研究生国家奖学金、南京林业大学优秀毕业生等荣誉。 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1015', '孙文婷', '商学院', '孙文婷-商学院', NULL, '', '孙文婷，南京林业大学管理学博士，池州学院商学院讲师，研究方向为农产品供应链数字技术应用决策和供应链金融等主题，主持一项江苏省研究生科研实践与创新项目，参与国家社会科学基金一般项目和国家社会科学基金后期资助项目等项目。在国家自然科学基金委委A类期刊、SCI、SSCI等来源期刊发表学术论文3篇，研究成果被《中国管理科学》、《系统工程理论与实践》等权威期刊引用。', '0', '0', '0', '2026-06-05 20:01:59', '2026-06-05 20:01:59', NULL, NULL, NULL, NULL, NULL, '大学管理学博士，池州学院商学院讲师，研究方向为农产品供应链数字技术应用决策和供应链金融等主题，主持一项江苏省研究生科研实践与创新项目，参与国家社会科学基金一般项目和国家社会科学基金后期资助项目等项目。在国', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1016', '孙良柱', '商学院', '孙良柱-商学院', NULL, '', '孙良柱，经济学博士，讲师，安徽工业大学硕士生导师，安徽省城市经济学会理事，安徽省工业和信息化厅财政资金评审专家，深圳市工业和信息化局财政资金评审专家。 主要从事货币政策、资产价格、产业政策等方面的教学和研究工作，先后参与国家社科基金重大项目、国家自科面上项目、教育部人文社科项目各1项，主持安徽省教育厅重点研究项目1项，深圳市、区委托的横向课题20余项。在国内核心期刊（CSSCI收录）、国外核心期刊（SSCI收录）上发表多篇高水平论文，其中JCR一区论文两篇，人大复印资料全文转载一篇,参与国家行业标准编制1项。', '0', '0', '0', '2026-06-05 20:02:00', '2026-06-05 20:02:00', NULL, '师，安徽工业大学', NULL, NULL, NULL, '博士，讲师，安徽工业大学硕士生导师，安徽省城市经济学会理事，安徽省工业和信息化厅财政资金评审专家，深圳市工业和信息化局财政资金评审专家。 主要从事货币政策、资产价格、产业政策等方面的教学和研究工作，先后参', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1017', '吴燚', '大数据与人工智能学院', '副教授/博士', '相依变量的概率极限理论及其在统计模型，动力系统及风险管理中的应用；非参数模型、半参数EV回归模型中各种估计量的统计大样本性质；次线性期望空间、Hilbert空间、Banach空间下的极限理论及应用 主持的教科研项目： 参与导师及导师团队的国家自然科学基金项目多项', '', '吴燚，男，1987年2月生，安徽池州人，副教授。2007年毕业于山东大学数学与应用数学专业，获理学学士学位，2014年9月至2020年6月就读于安徽大学统计学专业，获理学博士学位。 主讲课程： 概率论与数理统计，随机过程，多元统计分析 研究方向： 相依变量的概率极限理论及其在统计模型，动力系统及风险管理中的应用；非参数模型、半参数EV回归模型中各种估计量的统计大样本性质；次线性期望空间、Hilbert空间、Banach空间下的极限理论及应用 主持的教科研项目： 参与导师及导师团队的国家自然科学基金项目多项（11671012，11871072等），安徽省自然科学基金杰出青年项目（1508085J06）和安徽省高校拔尖人才重点项目(gxbjZD2016005)。此外，主持安徽大学研究生创新项目一项(yfc100021)。《Communications in Statistics - Theory and Methods》、《Discrete Dynamics in Nature and Society》等SCI期刊审稿人。 研究成果： 1、 Wu Yi, Wang Xuejun, Narayanaswamy Balakrishnan. On the consistency of the P-C estimator in a nonparametric regression model. Statistical Papers, 2020, 61, 899-915. (SCI 3区) 2、Wang Xuejun, Wu Yi, Yu Wei, Yang Wenzhi, Hu Shuhe. Asymptotics for the linear kenel quantile estimator of Value-at-risk. TEST, 2019, 28(4), 1144-1174. (SCI 2区) 3、Wang Xuejun, Wu Yi, Hu Shuhe. The Berry-Esseen bounds of the weighted estimator in a nonparametric regression model . ANNALS OF THE INSTITUTE OF STATISTICAL MATHEMATICS, 2019, 71(5), 1143-1162. (SCI 3区) 4、 Wu Yi, Wang Xuejun, Li Yongming, Hu Shuhe. Berry-Esseen type bounds of the estimators in a semiparametric model under linear process errors with alpha-mixing dependent innovations . STATISTICS, 2019, 53(5), 943-967. (SCI 3区) 5、 Wu Yi, Wang Xuejun, Sung SooHak. Asymptotic normality and mean consistency for the weighted estimator in nonparametric regression models .JOURNAL OF THE KOREAN STATISTICAL SOCIETY, 2019, 48(3), 463-479.(SCI 4区) 6、 Wu Yi, Wang Xuejun, Hu Tien-Chung, Cabrera Manuel Ordonez, Volodin Andrei. Limiting behaviour for arrays of rowwisewidely orthant dependent random variables under conditions of R -h-integrability and its applications. STOCHASTICS, 2019, 91(6), 916-944.(SCI 4区) 7、 Wu Yi, Zhang Fei, Wang Xuejun. Convergence properties for weighted sums of weakly dependent random vectors in Hilbert spaces. STOCHASTICS, 2019. (SCI 4区) 8、 Wu Yi, Wang Xuejun. On Consistency of the Nearest Neighbor Estimator of the Density Function and Its Applications. ACT', '0', '0', '0', '2026-06-05 20:02:00', '2026-06-05 20:02:00', NULL, '山东大学', NULL, '概率论与数理统计，随机过程，多元统计分析 研究方向： 相依变量的概率极限理论及其在统计模型，动力系统及风险管理中的应用；非参数模型、半参数EV回归模型中各种估计量的统计大样本性质；次线性期望空间、Hilbert空间、Banach空间下的极限理论及应用 主持的教科研项目： 参与导师及导师团队的国家自然科学基金项目多项', NULL, '大学数学与应用数学专业，获理学学士学位，；大学统计学专业，获理学博士学位。 主讲课程： 概率论与数理统计，随机过程，多元统计分析 研究方向： 相依变量的概率极限理论及其在统计模型，动力系统及风险管理中的应用；非参数模型、半参数；大学研究生创新项目一项', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1018', '宫天辰', '商学院', '宫天辰-商学院', NULL, '', '宫天辰，安徽大学经济学博士，长期从事发展经济和数字经济领域的研究工作，在CSSCI和SSCI来源期刊上发表多篇学术论文，参与多项国家级与省部级项目。', '0', '0', '0', '2026-06-05 20:02:02', '2026-06-05 20:02:02', NULL, NULL, NULL, NULL, NULL, '大学经济学博士，长期从事发展经济和数字经济领域的研究工作，在', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1019', '徐国长', '商学院', '徐国长-商学院', '传统文化与行为决策、创新创业管理、数字经济领域的研究', '', '徐国长，安徽舒城人，2015年6月于南京航空航天大学经济与管理学院工商管理专业获管理学学士学位，2025年6月于南京航空航天大学经济与管理学院管理科学与工程专业获管理学博士学位。现为池州学院商学院（法学院）电子商务系教师。主要从事传统文化与行为决策、创新创业管理、数字经济领域的研究。先后参与国家社科基金项目、国家软科学项目、教育部人文社科基金项目、江苏省重大软科学研究项目、江苏省社会科学基金项目、江苏省高校哲学社会科学重大项目等科研项目；主持安徽省教育厅科学研究项目（青年科研项目）、安徽省质量工程项目、池州学院人才科研项目等。近年来在《研究与发展管理》、《商业经济与管理》、《科技进步与对策》、 Chinese Management Studies 、 Sustainability 等CSSCI、SSCI期刊共发表学术论文6篇。', '0', '0', '0', '2026-06-05 20:02:04', '2026-06-05 20:02:04', NULL, NULL, NULL, NULL, NULL, '大学经济与管理学院工商管理专业获管理学学士学位，；大学经济与管理学院管理科学与工程专业获管理学博士学位。现为池州学院商学院', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1020', '史见汝', '商学院', '史见汝-商学院', NULL, '', '史见汝，中国地质大学（武汉）本硕博毕业，管理学博士。现任池州学院商学院（法学院）教师，池州市重大决策社会稳定风险评估专家库专家。一直从事城市韧性、资源环境与公共政策领域的研究工作。 论文： [1] Shi J , Li S*, Liu M, Li X, Yan H, Dong C. Ecological Well—being and its Equity in Various Economic Contexts: Evidence from 130 Cities in the Yangtze River Economic Belt. Ecological Indicators, 2023, 156, 111093.（中科院1区top） [2] Shi J , Li S*, Song Y, Zhou N, Guo K, Bai J. How socioeconomic factors affect ecosystem service value: Evidence from China. Ecological Indicators, 2022, 145, 109589.（中科院1区top） [3] Li S, Shi J *, Wu Q. Environmental Kuznets Curve: Empirical Relationship between Energy Consumption and Economic Growth in Upper—Middle—Income Regions of China. Int. J. Environ. Res. Public Health 2020, 17, 6971.（中科院3区） [4] Liu M, Li S, Li Y, Shi J , Bai J, Evaluating the synergistic effects of digital economy and government governance on urban low—carbon transition, Sustainable Cities and Society, 2024, 105, 105337.（中科院1区top） [5]李先敏,李世祥, 史见汝 ,等.生态足迹的演化规律及人文驱动因素——来自长江重点生态区与黄河重点生态区的异质性分析[J].生态经济,2025,41(10):156—164.（人大复印刊转载） 专著： [1]李世祥，郭海湘，李先敏， 史见汝. 自然灾害应急管理：基于“一案三制”视角，中国社会科学出版社，2024. 决策咨询： [1]湖北构建“共抓长江大保护”体制机制的思考，获湖北省委副书记批示，被水利部长江水利委员会、湖北省发改委等部门采纳应用，2019.（8/12） [2]关于南阳市建设全域农村能源革命示范区的政策建议，获全国政协常委、河南省政协副主席肯定性批示，被中国农工民主党河南省委、南阳市发改委采纳应用，2020.（5/10） 主持项目： [1]长三角地区生态安全屏障韧性能力评估与提升机制研究，安徽省教育厅高等学校科学研究（社会科学类）青年项目，2026.01—2027.12. [2]长江经济带城市生态韧性水平演化及协同治理研究，省社科界青年学人成长计划，2025.11—2026.11. [3]长三角典型生态退化区生态修复对策研究，池州学院高层次人才启动经费项目，2025.12—2028.12.', '0', '0', '0', '2026-06-05 20:02:05', '2026-06-05 20:02:05', NULL, NULL, NULL, NULL, NULL, '大学；博士。现任池州学院商学院', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1021', '刘玮', '商学院', '刘玮-商学院', NULL, '', '刘玮，1996年生，吉林大学经济学博士，现为池州学院商学院老师。长期从事宏观经济计量分析等相关研究，多次参与国家社会科学基金重大项目，已在CSSCI、SSCI发表相关论文3篇。', '0', '0', '0', '2026-06-05 20:02:07', '2026-06-05 20:02:07', NULL, NULL, NULL, NULL, NULL, '大学经济学博士，现为池州学院商学院老师。长期从事宏观经济计量分析等相关研究，多次参与国家社会科学基金重大项目，已在', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1022', '唐鹏', '大数据与人工智能学院', '副教授/博士', NULL, '', '唐鹏，男，1984年10月生，安徽池州人，副教授，博士。2006年6月毕业于长沙理工大学建筑环境与设备工程专业，获工学学士学位；2009年6月毕业于中国科学技术大学工程热物理专业，获工学硕士学位；2021年6月毕业于中国科学技术大学动力工程与工程热物理专业，获工学博士学位。 E-mail: tangpeng2008@163.com 研究领域和方向： 计算燃烧学、天文数据挖掘等 主讲课程： 计算机网络、C程序设计、大学生科学素养等 科研论文： 1、Tang P, Zhang H, Ye T, et al. A novel method for chemistry tabulation of strained premixed/stratified flames based on principal component analysis [J]. Applied Mathematics and Mechanics, 2018, 39(6): 855-866. 2、唐鹏,张宏达,叶桃红, et al.拉伸层流预混火焰化学热力学建表方法研究[J].推进技术, 2017(05):138-144. 教科研项目 ： 1.主持：教育厅重点项目：数据挖掘在拉伸预混燃烧中的应用（KJ2018A0582） 2.主持：校级重点项目：湍流预混燃烧化学热力学建表方法的降维研究（2016ZRZ007） 3.主持：校级质量工程项目：Python编程基础与应用（2019XYZJC11） 获奖情况： 1.2021年指导学生获全国“数学建模大赛”省级一等奖； 2.2021年指导学生数维杯国际大学生数学建挑战赛Honorable Mention，二等奖； 3.2021年指导学生MathorCup高校数学建模挑战赛（大数据竞赛本科组）二等奖； 4.2021年指导学生获中国大学生计算机设计大赛安徽省三等奖； 5.2019年指导学生获安徽省物联网应用创新大赛二等奖； 6.2019年指导学生获“产投杯”池州市 “创青春”青年创业大赛二等奖； 7.2018年指导学生获全国大学生大数据技能竞赛三等奖； 8.2018年指导学生获“创青春 中国联通”安徽省大学生创业大赛铜奖； 9.2018年指导学生获暑期“三下乡”社会实践优秀团队二等奖； 10.2018年指导学生获暑期“三下乡”社会实践优秀成果奖； 11.2018年指导学生获第四届“互联网+”大学生创新创业大赛校赛三等奖； 12.2016-2017、2017-2018两学年优秀教学质量奖。', '0', '0', '0', '2026-06-05 20:02:09', '2026-06-05 20:02:09', NULL, '长沙理工大学', NULL, '计算机网络、C程序设计、大学生科学素养等 科研论文： ', NULL, '博士。；大学建筑环境与设备工程专业，获工学学士学位；；大学工程热物理专业，获工学硕士学位；', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1023', '桂冬冬', '商学院', '桂冬冬-商学院', '运筹优化、低空经济、交通运输规划与管理、电子商务物流等方向的科研与教学工作', '', '桂冬冬，男，中共党员，安徽安庆人，南京航空航天大学工学博士。现为商学院电子商务系教师，主要从事运筹优化、低空经济、交通运输规划与管理、电子商务物流等方向的科研与教学工作。主持及参与多项国家级与省部级教科研项目，以第一作者在SSCI/SCI/EI 期刊发表论文4篇。', '0', '0', '0', '2026-06-05 20:02:10', '2026-06-05 20:02:10', NULL, NULL, NULL, NULL, NULL, '大学工学博士。现为商学院电子商务系教师，主要从事运筹优化、低空经济、交通运输规划与管理、电子商务物流等方向的科研与教学工作。主持及参与多项国家级与省部级教科研项目，以第一作者在', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1024', '方臣', '商学院', '方臣-商学院', '世界经济领域相关研究、围绕知识产权与中国高水平对外开放主题、在CSSCI期刊发表论文2篇', '', '方臣，安徽贵池人，2025年6月于上海社会科学院获经济学博士学位。主要从事世界经济领域相关研究，围绕知识产权与中国高水平对外开放主题，在CSSCI期刊发表论文2篇。', '0', '0', '0', '2026-06-05 20:02:14', '2026-06-05 20:02:14', NULL, NULL, NULL, NULL, NULL, '博士学位。主要从事世界经济领域相关研究，围绕知识产权与中国高水平对外开放主题，在', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1025', '李宏志', '大数据与人工智能学院', '副教授/博士', NULL, '', '李宏志，男，1988.12-，安徽池州人，讲师，博士，2019.09~2022.07在上海海事大学攻读博士学位。 研究领域和方向： 信息安全 主讲课程： 《C语言程序设计》、《数据结构》、《网络攻防原理与实战》 科研论文： 以第一作者身份发表SCI检索论文10余篇，分别在SCI期刊《IEEE Internet of Things Journal》、《IEEE Systems Journal》、《IEEE Sensors Journal》、《Frontiers of Computer Science》、《Journal of Supercomputing》、《Cluster Computing》、《Mobile Information Systems》以及《IEEE Access》发表SCI期刊论文。 教科研项目 ： 1.主持：MOOC学习环境下基于区块链的教育大数据安全存储与共享方法研究（2022AH051836），教育厅自然重点项目，2022.01~2024.12； 2.主持：池州市社科联项目(2023YB01)，池州市智慧社区养老服务问题与发展对策研究，2024.01~2024.12； 3.主持：一流专业建设背景下自主学习能力培养研究-以《大数据分析与应用》课程的SPOC翻转课堂(2022XJYXM32 )，校级教学研究项目，2023.01~2024.12； 4.主持：“数据结构与程序设计”教学团队(2023XJXTD06 )，校级质量工程项目，2024.1 ~2024.12。 获奖情况： 1、2023年指导学生参加中国大学生计算机设计大赛获省级二等奖； 2、2023年指导学生参加安徽省挑战杯获省级三等奖； 3、2023年指导学生参加大数据与人工智能大赛获省级三等奖； 4、2023年指导学生参加安徽省信息安全大赛获省级一等奖。', '0', '0', '0', '2026-06-05 20:02:17', '2026-06-05 20:02:17', NULL, NULL, NULL, '《C语言程序设计》、《数据结构》、《网络攻防原理与实战》 科研论文： 以第一作者身份发表SCI检索论文', NULL, '博士，；大学攻读博士学位。 研究领域和方向： 信息安全 主讲课程： ；大学生计算机设计大赛获省级二等奖； ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1026', '李瑶', '商学院', '李瑶-商学院', NULL, '', '李瑶，北京师范大学管理学博士。 主要从事城乡韧性与可持续发展、绿色营销等方面的教学和研究工作，先后参与联合国开发计划署（UNDP）南南合作项目、国家自然科学基金面上项目、国家社会科学基金重大专项、北京市社会科学基金决策咨询重大项目等课题的研究。近5年，围绕研究主题，在《Journal of Asian Architecture And Building Engineering》、《Ecology and Evolution》、《生态科学》、《城市发展研究》等期刊发表学术文章16篇，其中第一作者发表SCI/SSCI/CSCD等核心期刊论文4篇。', '0', '0', '0', '2026-06-05 20:02:18', '2026-06-05 20:02:18', NULL, NULL, NULL, NULL, NULL, '大学管理学博士。 主要从事城乡韧性与可持续发展、绿色营销等方面的教学和研究工作，先后参与联合国开发计划署', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1027', '钱盈盈', '商学院', '钱盈盈-商学院', NULL, '', '钱盈盈，博士，池州学院商（法）学院教师，讲授《市场营销学》《跨境电商营销》《管理学》等课程。 毕业于英国伯明翰大学，曾参加The European Marketing Academy等国际学术会议并作报告，参与撰写《Research Handbook of Innovation and Creativity for Marketing Management》等学术书籍。', '0', '0', '0', '2026-06-05 20:02:19', '2026-06-05 20:02:19', NULL, '英国伯明翰大学', NULL, NULL, NULL, '博士，池州学院商；大学，曾参加', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1028', '华义平', '大数据与人工智能学院', '华义平-大数据与人工智能学院', NULL, '', '华义平，女，1982年1月，安徽潜山人，讲师，硕士。2004年毕业于安徽师范大学数学与应用数学专业，获理学学士学位，2010年毕业于安徽师范大学数学与计算机学院，获理学硕士学位。 主讲课程： 高等数学，线性代数，概率论与数理统计，解析几何，微分几何 研究领域与方向： 微分几何 主持项目： 1、池州学院引进研究生科研启动项目：“关于非空间形式中子流形的研究”（2010RC019); 2、池州学院校级自然重点项目：“射影平坦的Finsler度量的研究”（2014ZRZ011） 发表论文： 1、一类局部对偶平坦的 度量，中国科学技术大学学报，2018年第11期 2、射影相关于Randers度量的 -度量，湖南师范大学自然科学学报，2018年第3期 3、对偶平坦的Kropina度量的共形性质，杭州师范大学学报，2018年第6期 4、关于一般螺线性质的探讨，池州学院学报，2013年第6期 5、共形平坦黎曼流形上的Schouten张量，纯粹数学与应用数学，2012年第3期 6、局部共形平坦流形上的Schouten张量及其应用，南京大学学报（数学半年刊），2012年第1期', '0', '0', '0', '2026-06-05 20:02:22', '2026-06-05 20:02:22', NULL, '安徽师范大学', NULL, '高等数学，线性代数，概率论与数理统计，解析几何，微分几何 研究领域与方向： 微分几何 主持项目： ', NULL, '硕士。；大学数学与应用数学专业，获理学学士学位，；大学数学与计算机学院，获理学硕士学位。 主讲课程： 高等数学，线性代数，概率论与数理统计，解析几何，微分几何 研究领域与方向： 微分几何 主持项目： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1029', '蒋劭妍', '商学院', '蒋劭妍-商学院', NULL, '', '蒋劭妍，博士，池州学院高层次引进人才。本硕博均就读于南京林业大学，曾就职于三胞集团博后工作站、战略规划部，担任垠坤集团等大型企业产业研究顾问，长期从事生态经济与区域发展规划、企业产业战略发展规划、产业园规划、品牌建设及营销推广等方面工作。对新媒体营销、网店运营、电子商务等课程教学、研究和实践有独特见解，在生态经济、生态发展与文旅产业融合等交叉学科有深入研究，在国内外公开刊物发表研究成果6篇，参与国家、省部级项目3项，授权国家发明专利1项。', '0', '0', '0', '2026-06-05 20:02:23', '2026-06-05 20:02:23', NULL, '南京林业大学', NULL, NULL, NULL, '博士，池州学院高层次引进人才。本硕博均就读于南京林业大学，曾就职于三胞集团博后工作站、战略规划部，担任垠坤集团等大型企业产业研究顾问，长期从事生态经济与区域发展规划、企业产业战略发展规划、产业园规划、品牌', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1030', '计博婧', '大数据与人工智能学院', '计博婧-大数据与人工智能学院', '三支决策、文本情感分析等方面的研究、主持校级科研项目1项、参与省级、校级项目多项', '', '计博婧，女，汉族，1982年1月出生，安徽东至人。2003年毕业于安徽师范大学计算机科学与技术专业，获工学学士学位。2012年7月获南京邮电大学软件工程专业硕士学位。2018年9月至2019年6月在安徽大学进行访学。 主要从事三支决策、文本情感分析等方面的研究，主持校级科研项目1项，参与省级、校级项目多项。 主要承担《微机原理与接口技术》、《物联网导论》、《网页设计》等课程的教学任务。参与主编《计算机组成原理》教材。多次带队参加省级学科与技能竞赛，其中在“安徽省第五届机器人大赛暨全国机器人邀请赛”大赛中，指导学生获得一等奖1次，二等奖1次，三等奖2次。2018年度考核优秀。', '0', '0', '0', '2026-06-05 20:02:24', '2026-06-05 20:02:24', NULL, '安徽师范大学', NULL, NULL, NULL, '大学计算机科学与技术专业，获工学学士学位。；大学软件工程专业硕士学位。；大学进行访学。 主要从事三支决策、文本情感分析等方面的研究，主持校级科研项目', NULL, NULL);
