INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1032', '李年蛟', '大数据与人工智能学院', '李年蛟-大数据与人工智能学院', '图论', '', '李年蛟，讲师，男，1981年3月生，安徽芜湖人。2003年毕业于安徽大学应用数学专业，获理学学士学位，2011年毕业于安徽大学基础数学专业，获理学硕士学位。 主讲课程： 高等数学，线性代数 研究方向： 图论', '0', '0', '0', '2026-06-05 20:02:28', '2026-06-05 20:02:28', NULL, '安徽大学', NULL, '高等数学，线性代数 研究方向： 图论', NULL, '大学应用数学专业，获理学学士学位，；大学基础数学专业，获理学硕士学位。 主讲课程： 高等数学，线性代数 研究方向： 图论', NULL, NULL);
