INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1034', '李世纪', '大数据与人工智能学院', '李世纪-大数据与人工智能学院', NULL, '', '李世纪，讲师，男，1982年3月生，河南南召人。2005年毕业于郑州大学，获理学学士学位，2012年毕业于河南财经政法大学，获经济学硕士学位。 主讲课程： 回归分析、多元统计分析、数据挖掘等', '0', '0', '0', '2026-06-05 20:02:30', '2026-06-05 20:02:30', NULL, '郑州大学', NULL, '回归分析、多元统计分析、数据挖掘等', NULL, '大学，获理学学士学位，；大学，获经济学硕士学位。 主讲课程： 回归分析、多元统计分析、数据挖掘等', NULL, NULL);
