INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1037', '鲁翡翡', '大数据与人工智能学院', '鲁翡翡-大数据与人工智能学院', '组合设计 教学奖励情况： ', '', '鲁翡翡，讲师，女，1986年12月生，安徽安庆人。2008年7月毕业于安庆师范学院数学与应用数学专业，获理学学士学位，2012年6月毕业于南京师范大学运筹学与控制论专业，获理学硕士学位。 主讲课程： 运筹学、线性代数、概率论与数理统计、高等数学 研究方向： 组合设计 教学奖励情况： 1、2016年度池州学院青年教师教学技能大赛获得“三等奖”。 主持的教科研项目： 池州学院自然科研一般项目，带洞圈支架及双重圈支架的存在性（2013ZR018），主持 研究成果： 1、On the existence of holey 4-cycle frames，DiscreteMathematics, 2015,SCI.（第一作者） 2、“互联网+”时代背景下的“运筹学”课程教学的改革探索.明日风尚,2008. （第一作者）', '0', '0', '0', '2026-06-05 20:02:33', '2026-06-05 20:02:33', NULL, '安庆师范学院', NULL, '运筹学、线性代数、概率论与数理统计、高等数学 研究方向： 组合设计 教学奖励情况： ', NULL, '学士学位，；大学运筹学与控制论专业，获理学硕士学位。 主讲课程： 运筹学、线性代数、概率论与数理统计、高等数学 研究方向： 组合设计 教学奖励情况： ', NULL, NULL);
