INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1039', '陆心怡', '大数据与人工智能学院', '陆心怡-大数据与人工智能学院', '微分方程 主持的教科研项目： 池州学院校级科研项目：带有Riemann', '', '陆心怡，讲师，女，1989年11月生，安徽池州人。2011年毕业于阜阳师范学院数学与应用数学专业，获理学学士学位，2014年毕业于聊城大学大学应用数学专业，获理学硕士学位。 主讲课程： 高等数学，微格教学 研究方向： 微分方程 主持的教科研项目： 池州学院校级科研项目：带有Riemann-stieltjes积分条件的分数阶微分方程多点边值问题的解（CZ2018ZR03），主持 获得的主要奖励： 1. 2014年，获“优秀教学新能手”； 2. 2015年，获首届“安徽省高校数学微课程教学设计竞赛”一等奖； 3. 2015年，获“全国高校数学微课程教学竞赛”华东赛区一等奖', '0', '0', '0', '2026-06-05 20:02:36', '2026-06-05 20:02:36', NULL, '阜阳师范学院', NULL, '高等数学，微格教学 研究方向： 微分方程 主持的教科研项目： 池州学院校级科研项目：带有Riemann', NULL, '学士学位，；大学大学应用数学专业，获理学硕士学位。 主讲课程： 高等数学，微格教学 研究方向： 微分方程 主持的教科研项目： 池州学院校级科研项目：带有', NULL, NULL);
