INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1041', '潘韵', '大数据与人工智能学院', '潘  韵-大数据与人工智能学院', '计算机嵌入式、物联网方面的教学与研究工作', '', '潘韵，男，汉族，1980年12月出生，2003年7月毕业于安徽理工大学计算机科学与技术专业，获工学学士学位。2012年7月毕业于南京邮电大学计算机学院，获软件工程硕士学位。主要从事计算机嵌入式、物联网方面的教学与研究工作。 讲授课程： 嵌入式基础、嵌入式体系结构、c语言程序设计、计算机组成原理、毕业论文写作。 累计发表论文6篇，其中独著或第一作者5篇。主持完成池州学院校级项目2项。主持教研3项，其中主持产学研协同育人项目2项。参与省级教研2项。 获池州学院优秀教学质量奖、课内实践优秀奖、多媒体课件奖、年度考核优秀奖。指导学生机器人竞赛获省级一等奖、省三等奖。', '0', '0', '0', '2026-06-05 20:02:38', '2026-06-05 20:02:38', NULL, '安徽理工大学', NULL, NULL, NULL, '大学计算机科学与技术专业，获工学学士学位。；大学计算机学院，获软件工程硕士学位。主要从事计算机嵌入式、物联网方面的教学与研究工作。 讲授课程： 嵌入式基础、嵌入式体系结构、', NULL, NULL);
