INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1045', '任莉莉', '大数据与人工智能学院', '任莉莉-大数据与人工智能学院', '计算机基础方面的教学与研究工作、承担的教学课程有《C程序设计》、《Visual Foxpro 程序设计》、《数据库技术与应用》等', '', '任莉莉，女，山东人，讲师，硕士，2006年毕业于西南财经大学。同年9月进池州学院任教至今。 主要从事计算机基础方面的教学与研究工作，承担的教学课程有《C程序设计》、《Visual Foxpro 程序设计》、《数据库技术与应用》等。主要研究领域为机器学习、分子仿真计算，主持完成了安徽省教育厅自然科研项目《关键词自动标引技术研究》、安徽省教育厅优秀青年人才基金自然项目1项、校级科研项目1项和校级教研项目1项，发表科研及教研论文数篇。参与安徽省科技重大专项1项、安徽大学现代生物制造协同开放课题等项目，合著发表SCI文章3篇，参与编写高等院校规划教材等。曾获池州学院优秀教学质量奖和优秀教案奖。', '0', '0', '0', '2026-06-05 20:02:43', '2026-06-05 20:02:43', NULL, '西南财经大学', NULL, NULL, NULL, '硕士，；大学。同年；大学现代生物制造协同开放课题等项目，合著发表', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1046', '何佳莹', '商学院', '何佳莹-商学院', NULL, '', '何佳莹，池州学院商学院专任教师，澳门城市大学在读博士，讲师，澳门管理科学与工程学会会员，中国电子商务创业导师、阿里巴巴跨境电子商务师，从事跨境电子商务、新媒体技术等领域的教学与研究。曾于澳门大学数据挖掘实验室及SGS瑞士通标标准有限公司电子与电磁实验室任研究助理，并曾在广州尚左网络科技有限公司、深圳尚左体育文化有限公司、韩国优美尚品化妆品有限公司及上海邦秀文化社区从事产品运营相关工作。', '0', '0', '0', '2026-06-05 20:02:43', '2026-06-05 20:02:43', NULL, NULL, NULL, NULL, NULL, '大学在读博士，讲师，澳门管理科学与工程学会会员，中国电子商务创业导师、阿里巴巴跨境电子商务师，从事跨境电子商务、新媒体技术等领域的教学与研究。曾于澳门大学数据挖掘实验室及', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1047', '孙兰娟', '大数据与人工智能学院', '孙兰娟-大数据与人工智能学院', '软件工程 主持的教科研项目： ', '', '孙兰娟，讲师，女，1982年6月生，安徽东至人。2003年毕业于安徽理工大学大学计算机科学与技术专业，获理学学士学位，2008年—2011年在南京邮电大学计算机学院攻读在职研究生，获软件工程硕士学位。 主讲课程： 编译原理，C语言,网页设计（Web前端开发） 研究方向： 软件工程 主持的教科研项目： 1. 池州学院教研项目：本科“操作系统”教学方法的改进(2010jy048)，主持 2. 池州学院教研项目：工程模式下的计算机课内实践的研究与实施（2014jyxm），主持 3. 池州学院自然重点项目：基于Android的校园服务设计与研究（2014ZRZ009）,主持 4. 产学合作协同育人项目:Web前端行业教学课程改革（201702106006）,主持 5. 产学合作协同育人项目:网页设计（Web前端开发技术）实训(201702119106) ,主持 获奖情况： 获池州学院优秀教学质量奖、多媒体课件奖、年度考核优秀奖。指导学生机器人竞赛获省三等奖。', '0', '0', '0', '2026-06-05 20:02:45', '2026-06-05 20:02:45', NULL, '安徽理工大学大学', NULL, '编译原理，C语言,网页设计', NULL, '大学大学计算机科学与技术专业，获理学学士学位，；大学计算机学院攻读在职研究生，获软件工程硕士学位。 主讲课程： 编译原理，；本科', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1048', '毕小燕', '商学院', '毕小燕-商学院', NULL, '', '毕小燕，硕士研究生，主讲《财务管理学》、《会计学原理》等专业课程。主要研究方向包括企业财务管理运用，税务筹划等。', '0', '0', '0', '2026-06-05 20:02:48', '2026-06-05 20:02:48', NULL, NULL, NULL, NULL, NULL, '硕士研究生，主讲', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1049', '操贝蒂', '商学院', '操贝蒂-商学院', NULL, '', '操贝蒂，女，安徽潜山人，硕士，现为池州学院商学院（法学院）讲师。主讲《跨境电子商务》《跨境电商函电》等课程，主持2项安徽省质量工程项目，参与多项国家级、省级课程建设，参编省级规划教材1部。研究方向为农业经济管理与乡村产业振兴，先后主持安徽省教育厅人文社会科学重点项目、池州市社科联重点项目、项池州学院科研重点项目，参与多项省级科研课题，发表教科研论文10余篇。指导学生团队在专业学科和技能竞赛、创新创业训练项目等大学生学科竞赛中获奖10余项。', '0', '0', '0', '2026-06-05 20:02:49', '2026-06-05 20:02:49', NULL, NULL, NULL, NULL, NULL, '硕士，现为池州学院商学院；大学生学科竞赛中获奖', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1050', '高露', '商学院', '高露-商学院', NULL, '', '高露，硕士研究生，主讲《金融企业会计》、《税法》等专业课程。在教学中，注重理论与实践相结合，致力于培养学生的专业应用能力和创新思维。积极指导学生参与学科竞赛，带领学生参加安徽省财税技能大赛、安徽省金融投资分析大赛等多项赛事，并取得了优异成绩。通过竞赛指导，有效提升了学生的专业素养和团队协作能力。未来将继续深耕教学科研，探索更有效的教学方法，为培养高素质财经人才贡献力量。', '0', '0', '0', '2026-06-05 20:02:51', '2026-06-05 20:02:51', NULL, NULL, NULL, NULL, NULL, '硕士研究生，主讲', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1051', '陈国华', '商学院', '陈国华-商学院', NULL, '', '陈国华，男，1978年1月生，江苏南通人，现任池州学院商学院（法学院）讲师、执业律师。四川大学法学学士，后于中国政法大学及安徽大学深造，获诉讼法与法律硕士学位，专注于诉讼法与司法制度研究。自2001年投身法学教育以来，主编《法学导论》教材，并在省级以上刊物发表《再论法的价值》等多篇学术论文，屡获安徽省及池州市法学论文奖项。在实务领域，担任国家税务总局池州市税务局、市财政局、人民医院及多家大型企业的法律顾问，积极参与地方立法咨询，专业意见多被采纳。同时兼任池州市仲裁委员会仲裁员、市政府立法专家咨询员、市税务协会副会长及多家法院特邀专家与调解员，为地方法治建设贡献专业力量。', '0', '0', '0', '2026-06-05 20:02:53', '2026-06-05 20:02:53', NULL, NULL, NULL, NULL, NULL, '大学法学学士，后于中国政法大学及安徽大学深造，获诉讼法与法律硕士学位，专注于诉讼法与司法制度研究。自', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1052', '谢杨梅', '大数据与人工智能学院', '谢杨梅-大数据与人工智能学院', '智能信息处理 主持的科研项目： ', '', '谢杨梅，讲师，女，1979年12月生，安徽池州人。2002年毕业于东北大学秦皇岛分校自动化专业，获工学学士学位，2006年—2008年在安徽大学计算机学院攻读在职研究生，获计算机应用技术硕士学位。。 主讲课程：数据库技术与应用，计算机基础，C语言 研究方向：智能信息处理 主持的科研项目： 1、省级高等学校优秀青年人才基金项目：基于ICA算法的特定源信号提取及其应用（2011SQRL162）,主持 2、池州学院自然项目：基于独立分量分析的生物电信号提取算法研究（2010ZR010）,主持 3、池州学院自然重点项目：基于VPRS决策树算法在高校就业分析中的应用（2017ZRZ010）,主持 获奖情况：获池州学院年度考核优秀奖、优秀共产党员、安徽省普通高校毕业生就业工作先进者。', '0', '0', '0', '2026-06-05 20:02:54', '2026-06-05 20:02:54', NULL, '东北大学', NULL, '数据库技术与应用，计算机基础，C语言 研究方向：智能信息处理 主持的科研项目： ', NULL, '大学秦皇岛分校自动化专业，获工学学士学位，；大学计算机学院攻读在职研究生，获计算机应用技术硕士学位。。 主讲课程：数据库技术与应用，计算机基础，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1053', '许芳芳', '大数据与人工智能学院', '许芳芳-大数据与人工智能学院', '数据挖掘 参与主持的教科研项目： ', '', '许芳芳，讲师，女，1984年2月生，安徽池州人。2004年毕业于淮北师范大学计算机科学与技术专业，获理学学士学位，2011年毕业于华东师范大学计算机应用技术专业，获工学硕士学位。 主讲课程： 数据库原理与应用，数据库技术与应用，数据库技术 研究方向： 数据挖掘 参与主持的教科研项目： 1、池州学院精品线下开放课程：数据库原理与应用(2018xjpkc04)，主持. 2、产学合作协同育人项目：数据库原理与应用课程改革（201702030026），主持. 3、池州学院校级教研重点项目：应用型本科院校计算机专业数据库课程教学改革研究(2015jyxm15)，主持. 4、池州学院校级科研一般项目：Web文本聚类算法的研究与实现（2011ZR003），主持. 5、池州学院校级教研重点项目：以新工科建设为背景、以计算思维为导向的大学计算机基础课程改革与建设研究（2018XJYXM10），参与. 主要获得的奖励： 1、2016年度考核优秀. 2、2015年获优秀试卷奖. 3、2014年获优秀课内实践教学教案奖. 参编教材： 《数据库原理及应用》中国科学技术大学出版社，2016.', '0', '0', '0', '2026-06-05 20:02:56', '2026-06-05 20:02:56', NULL, '淮北师范大学', NULL, '数据库原理与应用，数据库技术与应用，数据库技术 研究方向： 数据挖掘 参与主持的教科研项目： ', NULL, '大学计算机科学与技术专业，获理学学士学位，；大学计算机应用技术专业，获工学硕士学位。 主讲课程： 数据库原理与应用，数据库技术与应用，数据库技术 研究方向： 数据挖掘 参与主持的教科研项目： ；本科院校计算机专业数据库课程教学改革研究', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1054', '胡校敏', '商学院', '胡校敏-商学院', NULL, '', '胡校敏，1995年7月毕业于安徽大学法学专业，2008年7月取得南京师范大学诉讼法专业硕士学位，现在池州学院商学院（法学院）任教。', '0', '0', '0', '2026-06-05 20:02:58', '2026-06-05 20:02:58', NULL, '安徽大学', NULL, NULL, NULL, '大学法学专业，；大学诉讼法专业硕士学位，现在池州学院商学院', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1055', '杨永超', '大数据与人工智能学院', '杨永超-大数据与人工智能学院', '机器学习，计算机视觉，自然语言处理 主持及参与的教科研项目： ', '', NULL, '0', '0', '0', '2026-06-05 20:02:58', '2026-06-05 20:02:58', NULL, NULL, NULL, '计算机网络，数据库技术与应用 研究方向： 机器学习，计算机视觉，自然语言处理 主持及参与的教科研项目： ', NULL, '大学自动化专业，获工学学士学位；；大学模式识别与智能系统专业，获工学硕士学位。 主讲课程： 计算机网络，数据库技术与应用 研究方向： 机器学习，计算机视觉，自然语言处理 主持及参与的教科研项目： ；大学出版社，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1056', '凌小丽', '商学院', '凌小丽-商学院', NULL, '', '凌小丽，女，安徽财经大学社会保障学专业管理学硕士，人力资源管理专业专任教师。主讲社会保障学、人力资源战略与规划等课程。主持池州学院引进研究生科研启动项目《中国特色的全国社会保障基金投资政策研究》，相关成果发表于《池州学院学报》2011年第5期。主持1项省级校验项目，多项校级科研项目。参编《房地产营销》等教材，其中《物业管理》于2012年9月由凤凰出版社出版。2015年参与池州学院‘大学生就业去向的影响因素分析’科研项目，并作为指导教师在第四届全国大学生人力资源管理知识技能竞赛第五大区赛中指导学生获得一等奖。此外，曾获池州学院优秀奖。', '0', '0', '0', '2026-06-05 20:03:01', '2026-06-05 20:03:01', NULL, NULL, NULL, NULL, NULL, '大学社会保障学专业管理学硕士，人力资源管理专业专任教师。主讲社会保障学、人力资源战略与规划等课程。主持池州学院引进研究生科研启动项目；大学生就业去向的影响因素分析；大学生人力资源管理知识技能竞赛第五大区赛中指导学生获得一等奖。此外，曾获池州学院优秀奖。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1057', '章哲庆', '大数据与人工智能学院', '章哲庆-大数据与人工智能学院', '知识工程、知识图谱和人工智能等方面的研究、主持校级科研项目2项、参与省级项目1项', '', '章哲庆，男，汉族，1987年9月出生，安徽池州人。2009年7月毕业于湖南科技大学，获工学学士学位；2012年7月毕业于广东工业大学，获工学硕士学位，2018年9月在南京航空航天大学进行学位进修。 主要从事知识工程、知识图谱和人工智能等方面的研究，主持校级科研项目2项，参与省级项目1项。 主要承担《C语言程序设计》、《移动应用开发》、《嵌入式系统》等课程的教学任务。先后获池州学院“教学成果三等奖”2次；获池州学院“优秀教学试卷”1次；获池州学院“优秀多媒体课件”奖2次。多次带队参加国际级和省级学科与技能竞赛，其中在“安徽省机器人”大赛中，指导学生获得一等奖2次，二等奖4次，三等奖7次；指导学生参加中国大学生服务外包创新创业大赛获得全国二等奖2次，三等奖1次。', '0', '0', '0', '2026-06-05 20:03:04', '2026-06-05 20:03:04', NULL, '湖南科技大学', NULL, NULL, NULL, '大学，获工学学士学位；；大学，获工学硕士学位，；大学进行学位进修。 主要从事知识工程、知识图谱和人工智能等方面的研究，主持校级科研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1058', '赵盼', '大数据与人工智能学院', '赵盼-大数据与人工智能学院', NULL, '', NULL, '0', '0', '0', '2026-06-05 20:03:07', '2026-06-05 20:03:07', NULL, NULL, NULL, '《网络管理》、《Python程序设计》、《人工智能基础》、《C程序设计》等。 教 科研论文： ', NULL, '硕士。；大学通信与信息系统专业，获得工程硕士学位。 ；大学生网络与分布式系统创新设计大赛获二等奖', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1059', '曹雪峰', '商学院', '曹雪峰-商学院', NULL, '', '曹雪峰，国际贸易学讲师，硕士，承担《金融学》、《国际商法》、《国际结算》、《商业银行经营管理学》等课程的教学工作，主持省级质量工程1项，指导学生或B类赛一等奖一次。', '0', '0', '0', '2026-06-05 20:03:07', '2026-06-05 20:03:07', NULL, NULL, NULL, NULL, NULL, '硕士，承担', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1060', '查淑萍', '大数据与人工智能学院', '查淑萍-大数据与人工智能学院', '图论，主持池州学院校级项目一项。', '', '查淑萍，女，1978年3月生，安徽怀宁人，硕士，实验师。 主讲课程： 中学代数研究、中学几何研究、几何画板、高等数学等。 研究方向： 图论，主持池州学院校级项目一项。', '0', '0', '0', '2026-06-05 20:03:09', '2026-06-05 20:03:09', NULL, NULL, NULL, '中学代数研究、中学几何研究、几何画板、高等数学等。 研究方向： 图论，主持池州学院校级项目一项。', NULL, '硕士，实验师。 主讲课程： 中学代数研究、中学几何研究、几何画板、高等数学等。 研究方向： 图论，主持池州学院校级项目一项。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1061', '张璇', '商学院', '张璇-商学院', NULL, '', '张璇，经济学硕士，讲师，主要研究领域为贸易经济、产业经济及农业经济。教学方面成果突出，聚焦课程教学改革与混合式教学模式创新，主持省级教研项目2项、校级教研项目4项，发表教研论文4篇；获省级教学成果奖二等奖1项、校级教学成果奖二等奖2项，省级教师智慧教学大赛一等奖1项，校级教师教学技能大赛一等奖1项、二等奖1项、三等奖2项，获评校级教坛新秀、“双能型”导师称号。科研方面，主持校级科研项目2项，参与省级科研项目5项，发表学术论文7篇。指导学生参加学科竞赛成绩优异，获国家级一等奖1项、省级一等奖4项、二等奖8项、三等奖16项，多次荣获学科竞赛优秀指导教师称号。', '0', '0', '0', '2026-06-05 20:03:10', '2026-06-05 20:03:10', NULL, NULL, NULL, NULL, NULL, '硕士，讲师，主要研究领域为贸易经济、产业经济及农业经济。教学方面成果突出，聚焦课程教学改革与混合式教学模式创新，主持省级教研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1062', '汪颖', '商学院', '汪颖-商学院', NULL, '', '汪颖，中共党员，管理学讲师，财务管理专业硕士，主要负责审计学、财务管理专业课程教学，主要课程包括《审计学》、《大数据审计理论与应用》、《成本会计学》。近年来，积极开展企业绩效和公司治理相关研究，积累了系统的研究成果与教学资源；主持或参与各类教科研项目6项，发表论文2篇；指导学生参加学科竞赛获得省级奖项10余项，以赛促学、以赛促教成效显著。秉持“以爱为基、以学为本”的教学理念，尊重每一位学生的独特性，不仅教知识，更育品格，让教育有温度、有力量、有成长。', '0', '0', '0', '2026-06-05 20:03:13', '2026-06-05 20:03:13', NULL, NULL, NULL, NULL, NULL, '硕士，主要负责审计学、财务管理专业课程教学，主要课程包括', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1063', '王婷', '大数据与人工智能学院', '王婷-大数据与人工智能学院', NULL, '', '王婷，女，1993年5月，安徽枞阳人，讲师，硕士。2015年毕业于阜阳师范学院电子信息科学与技术专业，获工学学士学位，2018年毕业于中国计量大学计算机应用技术专业，获工学硕士学位。 主讲课程： 数据结构 研究领域与方向： 数据挖掘与数据分析 发表论文： 1、Wang T, Piao G, Pan J, Jin Q. Health Concerns: Self-Disclosure and Online Behavior Analysis[C]// International Conference on Information Technology in Medicine and Education.IEEE, 2017:182-186.', '0', '0', '0', '2026-06-05 20:03:13', '2026-06-05 20:03:13', NULL, '阜阳师范学院', NULL, '数据结构 研究领域与方向： 数据挖掘与数据分析 发表论文： ', NULL, '硕士。；学士学位，；大学计算机应用技术专业，获工学硕士学位。 主讲课程： 数据结构 研究领域与方向： 数据挖掘与数据分析 发表论文： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1064', '张鹏程', '商学院', '张鹏程-商学院', NULL, '', '张鹏程，男，出生于1965年7月11日。1990年毕业于中南财经大学贸易专业，大学本科学历，学士学位。主要研究方向包括市场营销战略与策略、企业定价等。1990年至2002年在安徽省经贸学校担任教师；2002年至今在池州学院担任教师，讲师职称。发表论文3篇，编写教材2本。教学经验丰富，主要讲授市场营销学、企业定价、市场营销调研、营销渠道管理等课程。', '0', '0', '0', '2026-06-05 20:03:15', '2026-06-05 20:03:15', NULL, '学贸易专业，大学', NULL, NULL, NULL, '大学贸易专业，大学本科学历，学士学位。主要研究方向包括市场营销战略与策略、企业定价等。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1065', '伍贵宾', '大数据与人工智能学院', '讲师/博士', NULL, '', '伍贵宾，男，安徽池州人。2003年于哈尔滨工业大学获得计算机科学与技术学士学位，2005年于哈尔滨工业大学获得计算机科学与技术硕士学位，2023年于北京邮电大学获得信息与通信工程博士学位。 主讲课程： 《机器学习》 主要研究领域：计算机视觉、自然语言处理 科研论文： [1] CarveNet: a channel-wise attention-based network for irregular scene text recognition [J]. International Journal on Document Analysis and Recognition (IJDAR), 2022: 1-10. [2] TableRobot: an automatic annotation method for heterogeneous tables [J]. Personal And Ubiquitous Computing 26, 2022，933–939. [3]基于生成式对抗门控卷积网络的两阶段式印章消除[J].计算机科学. 发明专利 [1] Method of monocular depth estimation based on joint self-attention mechanism[P].Australia patent: 2020103715, 2021-01-27. [2]一种文档图像的形变度评估、筛选方法和装置[P].发明专利CN112435218A, 2021-03-02. [3]特定领域词汇的发现及分类器训练方法和装置[P].发明专利CN108846033B,2022-04-08 [4]车险欺诈团伙的识别方法及装置[P].发明专利CN110428337B,2023-01-20. [5]表格版式恢复方法，计算机可读介质以及计算机[P].发明专利CN110399878B,2023-05-26.', '0', '0', '0', '2026-06-05 20:03:16', '2026-06-05 20:03:16', NULL, NULL, NULL, '《机器学习》 主要研究领域：计算机视觉、自然语言处理 科研论文： ', NULL, '大学获得计算机科学与技术学士学位，；大学获得计算机科学与技术硕士学位，；大学获得信息与通信工程博士学位。 主讲课程： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1066', '戴鹏', '大数据与人工智能学院', '讲师/博士', NULL, '', '戴鹏，男，1994.09-，安徽池州人，讲师，工学博士，2016年本科毕业于北京邮电大学信息与通信工程学院，2023年博士毕业于北京邮电大学网络与交换技术国家重点实验室。 E-mail:pdai@bupt.edu.cn 研究领域和方向： 主讲课程： 《人工智能程序设计与数据分析》、《Python数据分析》 科研论文： 1. Dai Peng , Wang Y, Jin D, et al. An improving approach to analyzing change impact of C programs[J]. Computer Communications, 2022, 182: 60-71. (SCI，JCR一区) 2. Dai Peng , Zhang Q, Wang Y, et al. Improving Large-Gap Clone Detection Recall Using Multiple Features[J]. International Journal of Software Engineering and K nowledge Engineering, 2022, 32(07): 1071-1099. (SCI，JCR二区). 3. Dai Peng ,Yang L,Wang Y, Jin D, et al. Constructing Traceability between Software Requirements and Source Code Based on Neural Networks,Mathematics, 2023, Volume 11, Issue 2, 315.(SCI，JCR一区) 4.Zhang QJ, Dai Peng , et al,Statement-grained Hierarchy Enhanced Code Summarization, Advanced Intelligent Systems.(under review, SCI, JCR一区) 5.发明专利：软件需求与代码映射方法与系统，发明人：宫云战， 戴鹏 等。（已授权，授权号：ZL202110796925.1） 教科研项目 ： 1.参与：国家自然科学基金联合基金项目“源代码漏洞分析、检测与验证技术研究”(U1736110) 2.参与：广西密码学与信息安全重点实验室研究课题“基于软件动态运行特征的故障检测方法研究”(GCIS202103) 3.主持：“人工智能在新工科建设中支持个性化教育与服务研究”教育部产学研合作项目，2023.11~2024.11。 获奖情况： 2019年校级优秀博士生后备奖学金 校级优秀研究生干部 校一等学业奖学金 2020年院优秀研究生学生干部 校一等学业奖学金 2021年国重实验室优秀研究生，校一等学业奖学金 2022年院优秀研究生学生干部 校一等学业奖学金', '0', '0', '0', '2026-06-05 20:03:18', '2026-06-05 20:03:18', NULL, '北京邮电大学', NULL, '《人工智能程序设计与数据分析》、《Python数据分析》 科研论文： ', NULL, '博士，；本科毕业于北京邮电大学信息与通信工程学院，；博士毕业于北京邮电大学网络与交换技术国家重点实验室。 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1067', '王明', '商学院', '王明-商学院', NULL, '', '王明，知识产权专业教师，讲师，主要承担《知识产权管理》、《专利法》、《知识产权总论》等课程。近年来，积极开展知识产权运营等领域研究，具有一定的理论功底、跨学科背景。目前在公开刊物发表学术论文数篇，主持或参与各类科研项目、质量工程项目多项。', '0', '0', '0', '2026-06-05 20:03:18', '2026-06-05 20:03:18', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1068', '方甜甜', '商学院', '方甜甜-商学院', NULL, '', '方甜甜，审计学教研室讲师，硕士，近年来，积极开展企业可持续发展方面的研究，积累了系统的研究成果与教学资源，在相关领域展现出突出的学术研究与实践融合能力。先后获得2018-2019、2019-2020两学年度优秀教学质量奖、2018年度青年教师技能大赛校赛优秀奖、2019年度青年教师技能大赛校赛三等奖，指导学生立项国家级大学生创新创业项目2项、指导学生获得B类赛事省厅一等奖2次、二等奖5次、三等奖3次，在教学过程中注重将理论与实践相结合，所教授课程《高级财务管理学》线上教学平台课程点击率已达56万人次；主持省级质量工程项目1项、校级质量工程项目3项，主持四类科研项目1项。', '0', '0', '0', '2026-06-05 20:03:20', '2026-06-05 20:03:20', NULL, NULL, NULL, NULL, NULL, '硕士，近年来，积极开展企业可持续发展方面的研究，积累了系统的研究成果与教学资源，在相关领域展现出突出的学术研究与实践融合能力。先后获得；大学生创新创业项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1069', '汪宏', '大数据与人工智能学院', '汪宏-大数据与人工智能学院', '复分析及其应用。 主讲课程：复变函数，高等数学，概率论与数理统计，线性代数，复变函数与积分变换等。', '', '汪宏，男，1990.05-，安徽池州人，讲师，硕士。2017年6月毕业于安徽大学基础数学专业。 E-mail:wanghong_math@163.com. 研究方向：复分析及其应用。 主讲课程：复变函数，高等数学，概率论与数理统计，线性代数，复变函数与积分变换等。', '0', '0', '0', '2026-06-05 20:03:20', '2026-06-05 20:03:20', NULL, '安徽大学', NULL, '复变函数，高等数学，概率论与数理统计，线性代数，复变函数与积分变换等。', NULL, '硕士。；大学基础数学专业。 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1070', '徐家洪', '商学院', '徐家洪-商学院', NULL, '', '徐家洪（1971.10），籍贯安徽青阳县，池州学院商学院（法学院），市场营销系教师，硕士，副教授。长期担任《数据统计与分析》、《数据加工与可视化》、《大数据市场营销》等课程的教学工作。', '0', '0', '0', '2026-06-05 20:03:21', '2026-06-05 20:03:21', NULL, NULL, NULL, NULL, NULL, '硕士，副教授。长期担任', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1071', '俞文昌', '大数据与人工智能学院', '俞文昌-大数据与人工智能学院', '跟大数据、数据挖掘和机器学习相关工作', '', '2013年硕士毕业于北京理工大学计算机技术专业。2013年加入搜狗科技股份有限公司，从事搜狗地图研发工作主要负责实时路况数据的UGC原始数据收集，加工，生成实时路况数据。2014年加入百度地图，先后负责过地图POI(point of interest地图商铺等兴趣点)的Rank，地图POI的推荐，地图POI知识图谱。2018年加入池州学院数学与计算机学院，讲师。 主要从事跟大数据，数据挖掘和机器学习相关工作。比较擅长常见机器学习算法，包括线性回归模型，常见各种聚类算法，主流推荐算法，自然语言处理等。', '0', '0', '0', '2026-06-05 20:03:23', '2026-06-05 20:03:23', NULL, '北京理工大学', NULL, NULL, NULL, '硕士毕业于北京理工大学计算机技术专业。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1072', '洪乐银', '商学院', '洪乐银-商学院', NULL, '', '洪乐银，中共党员，管理学硕士，市场营销系专任教师。主讲《服务营销学》、《营销渠道管理》等多门专业课程。主持或参与多项校级及省部级教科研项目，公开发表学术论文2篇。工作期间，获校级课程思政教学比赛三等奖，指导学生获得安徽省大学生创新大赛、安徽省大学生金融投资创新大赛、安徽省大学生国际贸易综合技能大赛等多项省级奖项。', '0', '0', '0', '2026-06-05 20:03:25', '2026-06-05 20:03:25', NULL, NULL, NULL, NULL, NULL, '硕士，市场营销系专任教师。主讲；大学生创新大赛、安徽省大学生金融投资创新大赛、安徽省大学生国际贸易综合技能大赛等多项省级奖项。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1073', '汪珺', '大数据与人工智能学院', '汪珺-大数据与人工智能学院', '人工智能、硬件加速算法 主讲课程： 计算机组成原理、数字信号、数字图像处理 教科研项目： ', '', '汪珺，女，汉族，1998年5月，籍贯安徽池州，参加工作时间2022年8月，硕士研究生，讲师。 办公地点： 博奕北103 电子邮箱： wangjun@czu.edu.cn 研究方向： 人工智能、硬件加速算法 主讲课程： 计算机组成原理、数字信号、数字图像处理 教科研项目： 2024年度科研项目：基于多模态感知的课堂行为研究（CZ2024ZR02），主持。 获奖情况： （1）2024年获池州学院第二届课程思政教学比赛二等奖（理工组）。 （2）指导学生参加2025年安徽省机器人大赛，获安徽省二等奖一项，三等级2项。 （2）指导学生参加2024年度安徽省大数据与人工智能应用竞赛，获安徽省一等奖1项，二等奖2项。 （3）指导学生参加2024年高校物联网应用创新大赛，获安徽省一等奖1项，三等奖1项。 （4）指导学生参加第十九届和第十八届全国大学生智能汽车竞赛，获安徽省一等奖。 （5）指导学生参加2024年安徽省机器人大赛，获安徽省三等奖2项。', '0', '0', '0', '2026-06-05 20:03:25', '2026-06-05 20:03:25', NULL, NULL, NULL, '计算机组成原理、数字信号、数字图像处理 教科研项目： ', NULL, '硕士研究生，讲师。 办公地点： 博奕北；大学生智能汽车竞赛，获安徽省一等奖。 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1074', '马凌天', '商学院', '马凌天-商学院', NULL, '', NULL, '0', '0', '0', '2026-06-05 20:03:26', '2026-06-05 20:03:26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1075', '胡杰', '大数据与人工智能学院', '胡杰-大数据与人工智能学院', NULL, '', '胡杰，男，1993年2月生，籍贯安徽池州，硕士，实验师。 E-mail： xiaojieCZU@czu.edu.cn 研究领域和方向： 群体智能 主讲课程： 《计算机组成原理》，《C语言程序设计》等课程的教学任务。 科研论文： 1.Reliability Analysis of Swarm Self-Security Intelligence System Based on Fault Tree andMonte Carlo Simulation（2022年） 教科研项目： 1.《计算机组成原理》2022XJYXM3，2022年，主持。 获奖情况： 2022年安徽省大数据与人工智能应用竞赛大数据现场赛赛道本科组二等奖 2022年安徽省高校物联网应用创新大赛三等奖', '0', '0', '0', '2026-06-05 20:03:27', '2026-06-05 20:03:27', NULL, NULL, NULL, '《计算机组成原理》，《C语言程序设计》等课程的教学任务。 科研论文： ', NULL, '硕士，实验师。 ；本科组二等奖 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1076', '胡彬', '商学院', '胡彬-商学院', NULL, '', '胡彬，男，1989年生，中共党员，硕士，讲师。现任池州学院商学院（法学院）党政办副主任、专任教师。 主要讲授课程：《微观经济学》《宏观经济学》《经济学基础》等。 科研与教研项目：主持横向项目“贸易摩擦对中小外贸企业影响及策略研究”（2025年，到账经费2万元），“池出好味公司年货节横向技术服务”（2026年，到账经费2.5万元）；参与多项省市级及校级教科研项目，包括安徽省社会科学创新发展研究课题、安徽省教育教学研究项目、池州市金融支持地方经济发展研究等。 学术成果：在《福建师范大学学报》、《哈尔滨商业大学学报》、《商业经济研究》、《安徽金融》、《池州学院学报》等期刊发表论文多篇，研究方向涵盖企业创新、金融支持区域产业发展、新文科课程改革等。 荣誉与奖励：获池州学院“党的二十大知识竞赛”二等奖、智慧教学比赛校赛二等奖、校级教学成果奖二等奖（排名第4）等；指导学生获得安徽省大学生国际贸易综合技能大赛、全国企业竞争模拟大赛、 安徽省大学生金融投资创新大赛 等多项省级及以上奖项。', '0', '0', '0', '2026-06-05 20:03:28', '2026-06-05 20:03:28', NULL, NULL, NULL, NULL, NULL, '硕士，讲师。现任池州学院商学院；大学学报；大学学报', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1077', '王燕', '大数据与人工智能学院', '讲师/博士', '数理统计 主讲课程： 多元统计分析、实变函数 科研论文： ', '', '王燕，女，汉族，1994年8月生，安徽六安人，2024年6月参加工作，2015年12月加入中国共产党，安徽大学统计学专业毕业，研究生学历，理学博士学位。 办公地点： 博奕北103 电子邮箱： wyahdx@126.com 研究方向： 数理统计 主讲课程： 多元统计分析、实变函数 科研论文： 1、Wang Yan, Wang Xuejun. Complete f-moment convergence for Sung''s type weighted sums and its application to the EV regression models. Statistical Papers, 2021, 62(2), 769-793. (SCI) 2、Wang Yan, Yu Wei, Li Xiaoqin, Wang Xuejun. The Berry-Esseen type bound for the G-M estimator in a nonparametric regression model with alpha-mixing errors. Statistics, 2022, 56(1), 97-120. (SCI) 3、Wang Yan, Wang Xuejun, Shen Aiting. Asymptotic properties for generalized edge frequency polygon of nonparametric density estimation, Journal of Statistical Computation and Simulation, 2024, 94(18), 4210-4233. (SCI) 4、Wang Yan, Li Xiaoqin, Chen ling, Wang Minghui, Wang Xuejun. A note on the asymptotic properties of the estimators in a semiparametric regression model. Communications in Statistics-Simulation and Computation, 2022, 51(2), 358-373. (SCI) 5、Wang Yan, Li Xiaoqin, Chen ling, Wang Xuejun. Asymptotics for the G-M estimator in nonparametric regression models. Communications in Statistics-Simulation and Computation, 2024, 53(7), 3143-3169. (SCI) 科研项目： 主持安徽大学数学科学学院研究生创新研究项目（Z010111023）； 参与国家社会科学基金一般项目（22BTJ059）； 安徽省自然科学基金面上项目（2108085MA06、2308085MA07）； 参与安徽省高校自然科学研究重点项目（2024AH051399）。 获奖情况： 2014-2015年度本科生国家奖学金 2017年“安徽省普通高等学校品学兼优毕业生” 2019年硕士研究生国家奖学金 2022年度“国元”奖学金', '0', '0', '0', '2026-06-05 20:03:29', '2026-06-05 20:03:29', NULL, NULL, NULL, '多元统计分析、实变函数 科研论文： ', NULL, '大学统计学专业毕业，研究生学历，理学博士学位。 办公地点： 博奕北；大学数学科学学院研究生创新研究项目；本科生国家奖学金 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1078', '孙静远', '商学院', '孙静远-商学院', NULL, '', '孙静远，中共党员，讲师，商学院（法学院）电子商务专业专任教师，研究方向为电子商务物流。主持或参与多项校级和省部级教科研项目，指导省级大学生创新创业训练项目3项，参与编写省级规划教材1部，公开发表学术论文5篇，作为主要起草人编写2项团体标准并发布。', '0', '0', '0', '2026-06-05 20:03:29', '2026-06-05 20:03:29', NULL, NULL, NULL, NULL, NULL, '大学生创新创业训练项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1079', '刘根生', '商学院', '刘根生-商学院', NULL, '', '刘根生，清华大学工学硕士，池州学院商学院（法学院）讲师。2006年进入池州学院以来，积极从事物流管理、电子商务以及跨境电商营销相关课程的教学工作。从事物流管理、物流信息技术方面的研究工作，发表物流方面的学术论文4篇。', '0', '0', '0', '2026-06-05 20:03:31', '2026-06-05 20:03:31', NULL, NULL, NULL, NULL, NULL, '大学工学硕士，池州学院商学院', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1080', '冯敏', '大数据与人工智能学院', '讲师/博士', '第一性原理', '', '冯敏，女，汉，1993年6月生，河南平顶山人，2011年10月加入中国共产党，2024年9月任职于池州学院。教育背景，本科毕业于河南科技大学，硕士研究生毕业于昆明理工大学，博士研究生毕业于广东工业大学，在广东工业大学博士后流动工作站2年，并赴香港科技大学访学1年。现任助理研究员（中级），在国际学术期刊上发表SCI一区论文6篇，其中以第一作者发表SCI一区论文3篇，影响因子均大于15，已授权中国发明专利 1 项，主持广东省项目 1项，参与国家自然科学基金面上项目1项。 办公地点： 博奕北101 电子邮箱： mintie_feng@foxmail.com 研究方向： 第一性原理（DFT）模拟计算、电催化热力学与动力学计算 主讲课程： C程序设计、高等数学 科研论文： 1. Min Feng, Jingle Huang, Yang Peng, Churong Huang, Xin Yue; Shaoming Huang. Tuning Electronic Structures of Transition Metal Carbides to Boost Oxygen Evolution Reaction in Acidic Medium[J], ACS Nano, 2022,16: 13834. (一作，SCI 一区，IF= 18) 2. Min Feng, Jingle Huang, Yang Peng, Churong Huang, Xin Yue; Shaoming Huang. Tuning the electronic structures of cobalt-molybdenum bimetallic carbides to boost the hydrogen oxidation reaction in alkaline medium[J]. Chemical Engineering Journal, 2022, 428: 131206. (一作，SCI一区，IF= 16.7) 3. Churong Huang, Min Feng, Yang Peng, Jingle Huang, Xin Yue; Shaoming Huang. In Situ Construction of Ni/Ni0.2Mo0.8N Heterostructure to Enhance the Alkaline Hydrogen Oxidation Reaction by Balancing the Binding of Intermediates. 2023, 10.1002/adfm.202300593. （共同一作，SCI一区，IF= 19.9） 4. Jingle Huang; Min Feng; Yang Peng; Churong Huang; Xin Yue; Shaoming Huang. Encapsulating Ni Nanoparticles into Interlayers of Nitrogen‐Doped Nb2CTx MXene to Boost Hydrogen Evolution Reaction in Acid[J], Small, 2022, 15: 2206098. (SCI 一区，IF= 15.1) 5. Yang Peng, Churong Huang, Jingle Huang, Min Feng, Xinzhuo Qiu, Xin Yue and Shaoming Huang. Filling Octahedral Interstices by Building Geometrical Defects to Construct Active Sites for Boosting the Oxygen Evolution Reaction on NiFe2O4. Advanced Functional Materials, 2022, 32: 2201011. (SCI 一区，IF= 19.9) 6. Xin Yue,* Xueping Qin, Yangdong Chen, Yang Peng, Caihong Liang, Min Feng, Xinzhuo Qiu, Minhua Shao,* and Shaoming Huang*Constructing Active Sites from Atomic-Scale Geometrical Engineering in Spinel Oxide Solid Solutions for Efficient and Robust Oxygen Evolution Reaction Electrocatalysts, 2021, 2101653.', '0', '0', '0', '2026-06-05 20:03:31', '2026-06-05 20:03:31', NULL, '，在广东工业大学', NULL, 'C程序设计、高等数学 科研论文： ', NULL, '本科毕业于河南科技大学，硕士研究生毕业于昆明理工大学，博士研究生毕业于广东工业大学，在广东工业大学博士后流动工作站；大学访学；博士后项目，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1081', '王汇', '商学院', '王汇-商学院', NULL, '', '王汇，法理学硕士，中国法学会会员、安徽省法学会会员。主持并参与多项课题。', '0', '0', '0', '2026-06-05 20:03:33', '2026-06-05 20:03:33', NULL, NULL, NULL, NULL, NULL, '硕士，中国法学会会员、安徽省法学会会员。主持并参与多项课题。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1082', '郭晶晶', '大数据与人工智能学院', '讲师/博士', '图像处理和机器学习 主讲课程： C语言程序设计', '', '郭晶晶，女，汉族，1987年6月生，山东聊城人，2024年11月进入池州学院大数据与人工智能学院工作。博士毕业于中国科学院大学，获得理学博士学位。 办公地点： 博奕北101 电子邮箱： 136720151@qq.com 研究方向： 图像处理和机器学习 主讲课程： C语言程序设计/大数据分析 科研论文： [1] Guo J , Bai X , Deng Y ,et al. A nonlinear solar magnetic field calibration method for the filter-based magnetograph by the residual network[J]. Astronomy & Astrophysics, 2021, 646: A41. [2] Guo J , Bai X , Deng Y ,et al. A non-linear magnetic field calibration method for filter-based magnetographs by multilayer perceptron[J]. Solar Physics, 2020, 295(1): 1-18. [3] Su J T , Bai X Y , Chen J ,et al. Data reduction and calibration of the FMG onboard ASO-S[J]. Research in Astronomy and Astrophysics, 2019, 19(11): 161. [4] Hu, Z Y, Ji, K F, Chen, J ,et al Calibration scheme for space-borne full-disk vector magnetograph under the influence of orbiter velocity, A&A, 2022. [5] 郭晶晶,杨云飞,冯松,等.太阳望远镜高精度导行方法[J].科学通报,2016(10):1112-1120. [6] 陈垂裕, 林佳本, 白先勇, 邓元勇, 黄宇,郭晶晶. FMG 载荷地面试观测导行跟踪系统的设计与实现[J]. 天文学报, 2020, 61(4). 科研项目： 2022年01月——2024年12月，双折射滤光器型成像仪非线性磁场定标方法研究,国家自然科学基金青年科学基金项目(30w) 2022年01月——2023年05月，基于消零干涉技术的系外行星成像反演方法研究，博后基金委2021博士后国际交流计划派出项目(30w) 获奖情况: 2020年博士国家奖学金；2018国科大三好学生称号。', '0', '0', '0', '2026-06-05 20:03:34', '2026-06-05 20:03:34', NULL, '中国科学院大学', NULL, 'C语言程序设计', NULL, '博士毕业于中国科学院大学，获得理学博士学位。 办公地点： 博奕北；博士后国际交流计划派出项目；博士国家奖学金；', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1083', '葛畅', '商学院', '葛畅-商学院', '知识产权法、科技成果转化与知识产权管理等领域的教学与科研工作、主讲专利法、国际知识产权、合同法、商法、电子商务法等多门法学核心课程', '', '葛畅，中共党员，法律硕士，池州学院法学院讲师。主要从事知识产权法、科技成果转化与知识产权管理等领域的教学与科研工作，主讲专利法、国际知识产权、合同法、商法、电子商务法等多门法学核心课程。累计发表学术论文8 篇，其中含北大核心期刊、AMI 核心期刊论文，多篇成果刊发于《人民法院报》《中国知识产权报》等权威法治媒体。主持安徽省社科联、池州市社科联、池州市法学会以及校级人文重点研究项目等多项省、市、校级纵向科研项目。先后在最高人民法院全国法院学术讨论会、安徽省法学会理论征文、首都数字法治论坛等征文活动中获得多项学术奖励。', '0', '0', '0', '2026-06-05 20:03:34', '2026-06-05 20:03:34', NULL, NULL, NULL, NULL, NULL, '硕士，池州学院法学院讲师。主要从事知识产权法、科技成果转化与知识产权管理等领域的教学与科研工作，主讲专利法、国际知识产权、合同法、商法、电子商务法等多门法学核心课程。累计发表学术论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1084', '韩子尧', '大数据与人工智能学院', '讲师/博士', NULL, '', NULL, '0', '0', '0', '2026-06-05 20:03:36', '2026-06-05 20:03:36', NULL, NULL, NULL, NULL, NULL, '博士名录 专任教师 专职辅导员 产业教师 外聘教师 党群工作 党建动态 专题教育 党员发展 理论学习 工会动态 教学管理 教学动态 管理制度 培养方案 质量工程 实践教育基地 实践教学 百校工程 科研工作；博士', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1085', '张汀', '商学院', '张汀-商学院', NULL, '', '张汀，男，讲师，1985年10月生，中共党员。校级“教坛新秀”、池州学院优秀毕业实习指导教师。主讲《市场营销策划》、《销售管理》、《广告学》等专业核心课程。副主编身份编著规划教材《电子商务实用教程（第4版）》、《管理学教程》、《大学生创新创业素养》等。曾担任安徽旭阳铝颜料有限公司特聘讲师、杭州轻创电子商务有限公司大学生赋能培训讲师、安徽徽韵文化传媒有限公司市场营销顾问，指导学生团队参加学科竞赛省级奖项10余项。依托池州本地商旅文产业特色，长期致力于农产品营销传播、市场开发及农村电商等领域的研究工作。', '0', '0', '0', '2026-06-05 20:03:38', '2026-06-05 20:03:38', NULL, NULL, NULL, NULL, NULL, '大学生创新创业素养；大学生赋能培训讲师、安徽徽韵文化传媒有限公司市场营销顾问，指导学生团队参加学科竞赛省级奖项', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1086', '黄翔翔', '大数据与人工智能学院', '讲师/博士', '三维重建与可视化 主讲课程： Linux操作系统与程序设计、面向对象技术 教科研论文： ', '', '黄翔翔，男，汉族，1987/08，安徽巢湖，2013年7月，无，武汉大学，博士，讲师。 办公地点： 博奕北101 电子邮箱： rawmaterial@qq.com 研究方向： 三维重建与可视化 主讲课程： Linux操作系统与程序设计、面向对象技术 教科研论文： [1]黄翔翔，王维，章 平.软件工程专业毕业设计指导实践探究[J],电脑知识与技术, 2024, 20(2):39-42. [2]Huang X, Wang W, Ji Z, et al. Representation Enhancement-Based Proximal Policy Optimization for UAV Path Planning and Obstacle Avoidance[J]. International Journal of Aerospace Engineering, 2023, 2023. [3]Wang W, Huang X*, Cheng B. Deep Q-network Based UAV Autonomous Obstacle Avoidance with Prior Reward Shaping[C]//2023 IEEE 5th International Conference on Power, Intelligent Computing and Systems (ICPICS).IEEE,2023: 147-151. [4]Zhou, H.; Ji, Z.; You, X.; Liu, Y.; Chen, L.; Zhao, K.; Lin, S.; Huang,X. Geometric Primitive-Guided UAV Path Planning for High-Quality Image-Based Reconstruction. Remote Sens. 2023, 15, 2632. [5]黄翔翔;朱全生;江万寿;多视纹理映射中无需设定偏差的快速可见性检测[J],测绘学报,2020,49(01):92-107. [6]HUANG X; ZHU Q;JIANG W ;GPVC:Graphics Pipeline-Based Visibility Classification for Texture Reconstruction[J], Remote Sensing, 2018,10(11): 1725. 教科研项目： [1]2024年池州学院校级质量工程项目《计算机科学导论线上线下混合课程式课程建设，2024XHHKC09》，主持，在研 [2]2024年池州学院高层次人才科研启动基金《多细节表面纹理重建的时空优化，RZ2400001943》，主持，在研 [3]2021年安徽工程大学校级质量工程项目《以解决复杂工程问题为导向的面向对象程序设计教学研究，2021jyxm50》，主持，结题 [4]武汉大学测绘遥感国家重点实验室2023年开放基金《多模态关系引导的多细节纹理重建方法研究，23E04》, 主持，在研 [5] 企业横向项目<<手持激光雷达SLAM的三维可视、交互与量测软件，HX-2021-07-009>>，主持，结题 [6]2021年安徽工程大学高层次人才科研启动基金《多视多细节城市表面模型纹理重建方法研，2021YQQ013》，主持，结题 [7] 2022年安徽省自然科学基金<<基于无人机倾斜影像的城市三维实景模型多细节层次纹理建模方法研究，2208085QD106>>，主持，结题 获奖情况： 2021年全国大学生物联网设计竞赛优秀指导教师奖', '0', '0', '0', '2026-06-05 20:03:38', '2026-06-05 20:03:38', NULL, NULL, NULL, 'Linux操作系统与程序设计、面向对象技术 教科研论文： ', NULL, '大学，博士，讲师。 办公地点： 博奕北；大学校级质量工程项目；大学测绘遥感国家重点实验室', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1087', '唐良尊', '大数据与人工智能学院', '讲师/博士', '微波光子学', '', '唐良尊，男，汉族，1991年2月出生，安徽芜湖人，中共党员。2017年入党，2025年5月参加工作，博士，讲师，本、硕、博均毕业于南京航空航天大学。 办公地点：逸夫楼112 电子邮箱：lztang@czu.edu.cn 研究方向：微波光子学/光电振荡器/光纤传感 主讲课程：高等数学 教科研论文： L. Tang , S. Liu, L. Yang, Z. Tang, S. Li and S. Pan, "Microwave Frequency Divider With Tunable Division Factors Based on an Optoelectronic Oscillator," in IEEE Photonics Technology Letters, vol. 37, no. 19, pp. 1133-1136, 1 Oct.1, 2025, doi: 10.1109/LPT.2025.3585525. L. Tang , S. Liu, C. Du, Z. Tang, S. Li and S. Pan, "Period-Doubling Optoelectronic Parametric Oscillator for Reconfigurable Microwave Waveform Generation," in Journal of Lightwave Technology, vol. 43, no. 7, pp. 3131-3140, 1 April1, 2025, doi: 10.1109/JLT.2024.3517877. L. Tang , S. Liu, Z. Tang, S. Li and S. Pan, "On-Chip Photonic Frequency Divider for Dual-Wavelength Optical Signal," 2023 Conference on Lasers and Electro-Optics (CLEO), San Jose, CA, USA, 2023, pp. 1-2. L. Tang , Z. Tang, S. Li, S. Liu and S. Pan, "Simultaneous Measurement of Microwave Doppler Frequency Shift and Angle of Arrival Based on a Silicon Integrated Chip," in IEEE Transactions on Microwave Theory and Techniques, vol. 70, no. 9, pp. 4243-4251, Sept. 2022, doi: 10.1109 /TMTT.2022.3186384. Z. Xu, L. Tang , H. Zhang and S. Pan, "Simultaneous Real-Time Ranging and Velocimetry via a Dual-Sideband Chirped Lidar," in IEEE Photonics Technology Letters, vol. 29, no. 24, pp. 2254-2257, 15 Dec.15, 2017, doi: 10.1109/LPT.2017.2771415. 教科研项目： 暂无 获奖情况： 暂无', '0', '0', '0', '2026-06-05 20:03:41', '2026-06-05 20:03:41', NULL, '南京航空航天大学', NULL, '高等数学 教科研论文： L. Tang , S. Liu, L. Yang, Z. Tang, S. Li and S. Pan, ', NULL, '博士，讲师，本、硕、博均毕业于南京航空航天大学。 办公地点：逸夫楼', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1088', '张永东', '商学院', '张永东-商学院', NULL, '', '张永东，中共党员，硕士研究生。现任池州学院商学院（法学院）专职辅导员、商学院（法学院）学生第六党支部书记。曾获“池州学院年度考核优秀”“池州学院师德师风考核优秀”“辅导员考核优秀”等荣誉。主持校级科研项目1项、横向课题2项，并围绕学生工作发表多篇学术论文。所带班级多次获评“优秀团支部”，指导学生荣获10余项省级以上学科竞赛奖项。服务学校相关工作方面，先后借调在学生处（就业创业指导中心）负责毕业生就业工作，在校团委参与团组织建设、科技创新、第二课堂、社团管理等工作。', '0', '0', '0', '2026-06-05 20:03:41', '2026-06-05 20:03:41', NULL, NULL, NULL, NULL, NULL, '硕士研究生。现任池州学院商学院', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1089', '潘珺', '大数据与人工智能学院', '潘珺-大数据与人工智能学院', NULL, '', '潘珺，女，1990年10月，安徽池州人，助教，硕士。2013年毕业于华中科技大学经济学专业，获理学学士学位，2017年毕业于厦门大学王亚楠经济研究院，获理学硕士学位。 主讲课程： 宏观经济学，多元统计分析，风险管理 研究领域与方向： 数量经济学', '0', '0', '0', '2026-06-05 20:03:43', '2026-06-05 20:03:43', NULL, '华中科技大学', NULL, '宏观经济学，多元统计分析，风险管理 研究领域与方向： 数量经济学', NULL, '硕士。；大学经济学专业，获理学学士学位，；大学王亚楠经济研究院，获理学硕士学位。 主讲课程： 宏观经济学，多元统计分析，风险管理 研究领域与方向： 数量经济学', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1090', '王琴', '商学院', '王琴-商学院', NULL, '', '王琴，中共党员，经济学硕士，现为商学院（法学院）副科级专职辅导员， 讲师。自2020年入职以来，累计带过6个班级，涵盖审计学、电子商务等专业，并兼任《大学生职业生涯规划与就业指导》《劳动教育》等课程教学。曾获得池州学院2025年辅导员素质能力大赛三等奖，主持校级质量工程项目1项、校级科研项目1项，发表四类以上论文3篇，指导学生参加学科竞赛获得省级以上奖项10余项。', '0', '0', '0', '2026-06-05 20:03:43', '2026-06-05 20:03:43', NULL, NULL, NULL, NULL, NULL, '硕士，现为商学院；大学生职业生涯规划与就业指导', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1091', '章健', '商学院', '章健-商学院', NULL, '', '章健，商学院（法学院）专职辅导员，所带班级多次荣获优秀班集体和优秀团支部。主持省级科研项目一项，校级科研项目一项，参与科研项目、横行项目10余项。指导学生参加学科竞赛，荣获10多项省级以上奖项。', '0', '0', '0', '2026-06-05 20:03:45', '2026-06-05 20:03:45', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1092', '苏华杰', '大数据与人工智能学院', '苏华杰-大数据与人工智能学院', NULL, '', '苏华杰，男，1993年10月，六安霍山，助教，硕士，2019年毕业于北京大学 E-mail:410225640@qq.com 研究领域和方向： 应用数学 主讲课程： 高等数学、概率论与数理统计、解析几何、实变函数 科研论文： 1.Heisenberg supermagnetic hierarchy with the quadratic and cubic constraints,2022.08.sci 教科研项目 ： 1.机器学习在量子态纠缠判别中的应用，校级自然一般. 获奖情况：', '0', '0', '0', '2026-06-05 20:03:45', '2026-06-05 20:03:45', NULL, '北京大学', NULL, '高等数学、概率论与数理统计、解析几何、实变函数 科研论文： ', NULL, '硕士，；大学 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1093', '杨树琛', '商学院', '杨树琛-商学院', NULL, '', '杨树琛，专职辅导员，理学硕士。在职期间发表四类及以上论文两篇。指导管理类学科竞赛，获得省级以上奖项二十余项，其中指导学生获A类比赛省三等奖2次，B类比赛全国三等奖2次，全国二等奖1次，全省一等奖7次。', '0', '0', '0', '2026-06-05 20:03:46', '2026-06-05 20:03:46', NULL, NULL, NULL, NULL, NULL, '硕士。在职期间发表四类及以上论文两篇。指导管理类学科竞赛，获得省级以上奖项二十余项，其中指导学生获', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1094', '章琛', '大数据与人工智能学院', '章琛-大数据与人工智能学院', NULL, '', '章琛，男，1994年5月生，安徽池州人，讲师，硕士。2020年毕业于安徽财经大学统计与应用数学学院，获经济学硕士学位。 Email ：gemchang@126.com 研究领域和方向： 经济统计、资源环境统计。 主讲课程： 企业经营统计学、经济统计分析、概率论与数理统计等。', '0', '0', '0', '2026-06-05 20:03:47', '2026-06-05 20:03:47', NULL, '安徽财经大学', NULL, '企业经营统计学、经济统计分析、概率论与数理统计等。', NULL, '硕士。；大学统计与应用数学学院，获经济学硕士学位。 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1095', '高燕', '商学院', '高燕-商学院', NULL, '', NULL, '0', '0', '0', '2026-06-05 20:03:48', '2026-06-05 20:03:48', NULL, NULL, NULL, NULL, NULL, '博士，高级职业生涯规划师，池州学院；大学生职业生涯规划与就业指导工作室主持人。；大学生电子商务', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1096', '柯万超', '大数据与人工智能学院', '柯万超-大数据与人工智能学院', '深度学习、Web开发 主讲课程： 离散数学、Web服务与开发、移动应用开发等 教科研项目： ', '', '柯万超，男，汉族，1993年6月，籍贯安徽池州，参加工作时间2021年7月，硕士研究生，讲师。 办公地点： 博弈南402 电子邮箱： 2833856463@qq.com 研究方向： 深度学习、Web开发 主讲课程： 离散数学、Web服务与开发、移动应用开发等 教科研项目： 2024年度横向科研项目：智能配电节能供电系统及其软件研发（2024HX0317），主持。 2023年度安徽省质量工程教材建设项目：Java Web程序设计（2023jcjs158），参与。 获奖情况： （1）2025年获第五届全国高校教师教学大赛安徽赛区比赛池州学院三等奖（新工科组）。 （2）指导学生参加2025年第十六届安徽省软件赛C/C++程序设计，获安徽省二等奖。 （3）指导学生参加2024年第三届安徽省乡村振兴创新创业大赛，获安徽省二等奖。 （4）指导学生参加2024年安徽省大学生网络与分布式系统创新设计大赛创意赛、技能赛，获安徽省三等奖两项。 （5）指导学生参加2023年安徽省大学生工程实践与创新能力大赛，获安徽省三等奖。 （6）指导学生参加2023年第二届安徽省乡村振兴创新创业大赛，获安徽省三等奖。', '0', '0', '0', '2026-06-05 20:03:49', '2026-06-05 20:03:49', NULL, NULL, NULL, '离散数学、Web服务与开发、移动应用开发等 教科研项目： ', NULL, '硕士研究生，讲师。 办公地点： 博弈南；大学生网络与分布式系统创新设计大赛创意赛、技能赛，获安徽省三等奖两项。 ；大学生工程实践与创新能力大赛，获安徽省三等奖。 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1097', '汪翠萍', '商学院', '汪翠萍-商学院', NULL, '', '汪翠萍，法学硕士，专职辅导员，负责学院学生心理健康教育工作。扎根学生工作一线，注重将法学专业背景与育人实践深度融合，聚焦学风建设、党团班级管理、职业生涯规划与就业指导等方面落实立德树人，具有较强的心理育人意识与实务能力，以扎实的专业素养和务实的工作作风，持续为学生的健康成长与全面发展保驾护航。近年来，主持或参与各类科研项目4项（其中主持纵向项目1项），发表学术论文3篇，指导学生参与省级大学生创新创业训练计划项目4项，在A类、B类学科与创新创业竞赛中多次获奖。', '0', '0', '0', '2026-06-05 20:03:50', '2026-06-05 20:03:50', NULL, NULL, NULL, NULL, NULL, '硕士，专职辅导员，负责学院学生心理健康教育工作。扎根学生工作一线，注重将法学专业背景与育人实践深度融合，聚焦学风建设、党团班级管理、职业生涯规划与就业指导等方面落实立德树人，具有较强的心理育人意识与实务能；大学生创新创业训练计划项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1098', '钱凯', '大数据与人工智能学院', '钱凯-大数据与人工智能学院', NULL, '', '钱凯，男，1992年1月生，安徽池州人，助教，硕士。2015年毕业于河南农业大学，计算机科学与技术专业，获学士学位。2019年毕业河南理工大学，软件工程专业，获软件工程硕士学位。2022年7月入职池州学院。 办公地点： 博古北一楼102 E-mail: Qkai311@163.com 研究领域和方向： 大数据与知识发现方向 主讲课程： 计算机组成原理、java面向对象程序设计、大数据分析及可视化 科研论文： 1. 《Device-to-Device移动社交网络信息传播模型》，河南理工大学学报(自然科学版)，2019（北大核心）。 2 《Measurement and analysis of content diffusion characteristics in opportunity environments with Spark》，Frontiers of Information Technology & Electronic Engineering，2019（SCI）。 发明专利： 一种适用于面向文件共享的移动社交网络的信息传播预测方法[ZH]公开(公告)号:CN109410078A 一种基于毫米波的空调趣味控制方法、装置及空调器。授权公告号:CN110779148A 一种WIFI模组质量预测方法、装置、设备及存储介质。授权公告:CN111212434A 空调送风方向控制装置和空调器。授权公告CN113294879A (CN113294879B) 一种用户画像生成方法及空调设备的推荐方法公开（公告）号： CN111932297A 获奖情况： 1. 参加“歌尔杯”研究生移动终端应用设计创新大赛，全国二等奖，2017年 2. 指导学生参加中国大学生计算机设计大赛安徽省级赛二等奖，2023年 3. 指导学生参加安徽省大学生网络与分布式系统创新设计大赛省三，2024年 企业项目经历： 2021.4-2022.6：北京中科特瑞科技有限公司（池州分公司）授课，大数据工程师。 2019.7-2021.4：宁波奥克斯电气股份有限公司 智能技术研究院，风控系统开发项目、wifi模组数据品质可视化项目等，开发工程师', '0', '0', '0', '2026-06-05 20:03:51', '2026-06-05 20:03:51', NULL, '河南农业大学', NULL, '计算机组成原理、java面向对象程序设计、大数据分析及可视化 科研论文： ', NULL, '硕士。；大学，计算机科学与技术专业，获学士学位。；大学，软件工程专业，获软件工程硕士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1099', '凌莹', '商学院', '凌莹-商学院', NULL, '', '凌莹，女，汉族，中共党员，硕士研究生。现任池州学院商学院（法学院）专职辅导员、讲师，兼任商学院（法学院）学生第四党支部书记。入职以来，主持校级科研项目1项，参与校级教研项目及科研项目4项，主持横向课题2项，并围绕学生工作发表多篇学术论文。所带班级多次获评校级“先进班集体”“优秀团支部”等荣誉称号，指导学生参加学科竞赛荣获省级以上奖项20余项。', '0', '0', '0', '2026-06-05 20:03:52', '2026-06-05 20:03:52', NULL, NULL, NULL, NULL, NULL, '硕士研究生。现任池州学院商学院', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1100', '王慧', '大数据与人工智能学院', '​王慧-大数据与人工智能学院', '经济统计、概率统计 主讲课程： 概率论与数理统计 教科研论文： ', '', '王慧，女，汉族，1996年8月，安徽六安，2022年7月参加工作，硕士研究生（讲师） 办公地点： 博弈北103 电子邮箱： 2869113105@qq.com 研究方向： 经济统计、概率统计 主讲课程： 概率论与数理统计 教科研论文： 1.王慧,江海峰.基于空间视角的安徽省区域旅游经济影响因素研究[J].铜陵学院学报,2023, 22 (02): 39-44； 2.王慧，吴焱，王巍.次线性期望下m-EMD阵列的完全收敛性[J].廊坊师范学院学报（自然科学版）,2025(01); 3.Wang, Hui, Wang, Wei, & Wu, Yi (2024). Complete convergence for m - widely acceptable random variables under sub - linear expectations. Communications in Statistics - Theory and Methods. DOI: 10.1080/03610926.2024.2437517. 教科研项目： 池州学院自然科研一般项目：相依样本下边缘频率插值密度估计的渐近性质及应用研究，主持。 获奖情况： 1.曾指导学生获得全国大学生统计建模大赛省二等奖2项，省三等奖2项； 2.曾指导学生获得全国市场调查分析大赛省二等奖1项，三等奖5项；', '0', '0', '0', '2026-06-05 20:03:54', '2026-06-05 20:03:54', NULL, NULL, NULL, '概率论与数理统计 教科研论文： ', NULL, '硕士研究生；大学生统计建模大赛省二等奖', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1101', '裴胜', '商学院', '裴胜-商学院', NULL, '', '裴胜，中共党员，硕士研究生学历，现任池州学院商学院（法学院）专职辅导员，兼任学生第八党支部书记。始终牢记立德树人根本任务，坚守育人初心，以责任护航学生成长，用温情深耕学生服务，用心用情助力学生综合素质全面提升与长远发展。', '0', '0', '0', '2026-06-05 20:03:54', '2026-06-05 20:03:54', NULL, NULL, NULL, NULL, NULL, '硕士研究生学历，现任池州学院商学院', NULL, NULL);
