INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1108', '武江龙', '大数据与人工智能学院', '副教授/博士', NULL, '', '武江龙，男，汉族，副教授，硕士研究生导师，理学博士毕业于澳门科技大学，美国数学会《Mathematical Reviews》评论员，河南南阳人，2002年6月加入中国共产党，2007年7月参加工作。 E-mail: jl-wu@163.com 研究领域和方向： （实）调和分析及其应用、（遥感）图像处理、分析Lie群及p-adic分析等 主讲课程： 实变函数、数值分析、高等数学、线性代数、现代实分析基础(研究生)等 教科研论文：取得的一系列成果先后发表在中国数学会《数学学报（中、英文版）》，中科院《数学物理学报》，法国科学院《Comptes Rendus Mathématique》，俄罗斯科学院《Izvestiya Mathematics》，捷克科学院《Czechoslovak Mathematical Journal》和韩国数学会《Bulletin of the Korean Mathematical Society》等国内外重要核心期刊上， 部分成果如下： 2014年的部分成果 [1] Jianglong Wu. Boundedness for fractional Hardy-type operator on Herz-Morrey spaces with variable exponent. Bull. Korean Math. Soc., 51(2): 423–435, 2014. SCI,WOS: 000334569900010 [2] Jianglong Wu. Boundedness of some sublinear operators on Herz-Morrey spaces with variable exponent. Georgian Math. J., 21(1): 101–111, 2014. SCI,WOS: 000335839800013 [3] Jianglong Wu. Boundedness for commutators of fractional integrals on Herz-Morrey spaces with variable exponent. Kyoto J. Math., 54(3): 483–495, 2014. SCI,WOS:000340440200001 [4] Jianglong Wu and Q.Liu. Weighted endpoint estimates for multilinear commutatorsof Marcinkiewicz integrals. Bull. Malays. Math. Sci. Soc., 37(3): 819–831, 2014. SCI,WOS:000339225300018 [5] Jianglong Wu and Q.Liu. λ-central BMO estimates for higher order commutators of Hardy operators. Commun. Math. Res., 30(3): 201–206, 2014. (CSCD) [6] Jianglong Wu and Q.Liu. Weighted estimates for multilinear commutators of Marcinkiewicz integrals with bounded kernel. Ukrainian Math. J., 66(4): 602–616, 2014. SCI,WOS: 000345703400011 [7] P.Zhang and Jianglong Wu. Commutators of the fractional maximal function on variable exponent Lebesgue spaces. Czechoslovak Math. J., 64(1): 183–197, 2014. SCI,WOS:000340548200017 [8] P.Zhang and Jianglong Wu. Commutators for the maximal functions on Lebesgue spaces with variable exponent. Math. Inequal. Appl., 17(4): 1375–1386, 2014. SCI,WOS: 000345462600012, [9] 张璞， 武江龙. 分数次Hardy算子的交换子在变指数Herz-Morrey空间中的有界性. 数学进展, 43(4): 581–589, 2014. (CSCD) 2015年—2019年的部分成果 [10] Jianglong Wu. Bound', '0', '0', '0', '2026-06-05 20:04:08', '2026-06-05 20:04:08', NULL, '澳门科技大学', NULL, '实变函数、数值分析、高等数学、线性代数、现代实分析基础', NULL, '硕士研究生导师，理学博士毕业于澳门科技大学，美国数学会；本科研业务费：与奇异积分算子相关的若干问题；本科研业务费：', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1109', '李刍', '大数据与人工智能学院', '讲师/博士', '时序预测、风与光伏发电预测 主讲课程：程序设计基础 在研项目：基于卫星与天空成像仪的光伏功率预测、基于风电场群的功率预测研究', '', '李刍，男，汉族，1992.7，汉族，中共党员，博士，毕业于中国科学技术大学。 办公地点：博奕北103 电子邮箱：lichuzm@mail.ustc.edu.cn 研究方向：时序预测、风与光伏发电预测 主讲课程：程序设计基础 在研项目：基于卫星与天空成像仪的光伏功率预测、基于风电场群的功率预测研究', '0', '0', '0', '2026-06-05 20:04:11', '2026-06-05 20:04:11', NULL, '中国科学技术大学', NULL, '程序设计基础 在研项目：基于卫星与天空成像仪的光伏功率预测、基于风电场群的功率预测研究', NULL, '博士，毕业于中国科学技术大学。 办公地点：博奕北', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1110', '毛中杰', '大数据与人工智能学院', '讲师/博士', '人工智能 主讲课程：操作系统 科研论文： ', '', '毛中杰，男，汉族，湖北仙桃人，中共党员，博士毕业于武汉大学计算机学院，获工学博士学位。 办公地点：博奕北101 电子邮箱：jankin987@qq.com 研究方向：人工智能 主讲课程：操作系统 科研论文： [1] Mao Z , Wang Y, et al., Textual Tokens Classification for Multi-Modal Alignment in Vision-Language Tracking[C]. IEEE International Conference on Acoustics, Speech, and Signal Processing, 2024, 8025-8029. [2] Mao Z , Wei C, et al., Tiny Object Tracking with Proposal Position Enhancement[J]. IEEE Signal Processing Letters, 2023, 30, 1692-1696. [3] Mao Z , Chen X, et al., Multimodal Object Tracking by Exploiting Appearance and Class Information[J]. Journal of Visual Communication and Image Representation, 2022, 89. [4] Mao Z , Chen X, et al., Robust Tracking for Motion Blur via Context Enhancement[C]. IEEE International Conference on Image Processing, 2021, 659-663. [5] Fan S, Chen X, He C, Yu L, Mao Z , et.al., Multiple frequency-spatial network for RGBT tracking in the presence of motion blur[J]. NEURAL COMPUTING & APPLICATIONS, 2023, 35, 34, 24389-24406.', '0', '0', '0', '2026-06-05 20:04:13', '2026-06-05 20:04:13', NULL, '武汉大学计算机学院', NULL, '操作系统 科研论文： ', NULL, '博士毕业于武汉大学计算机学院，获工学博士学位。 办公地点：博奕北', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1111', '陈家乐', '大数据与人工智能学院', '讲师/博士', '基于深度学习的蛋白质分类和结构预测 主讲课程：大学计算机与信息技术 教科研论文： ', '', '个人简介 姓名：陈家乐 性别：男 民族：汉 出生年月：1996年6月 籍贯：河南周口 参加工作时间：2025年7月 入党时间：2023年12月 毕业学校：本硕博均就读于南京农业大学 学历学位：博士 职称：讲师 荣誉：无 办公地点：池州学院博奕楼北103 电子邮箱：jialechen@czu.edu.cn 研究方向：基于深度学习的蛋白质分类和结构预测 主讲课程：大学计算机与信息技术 教科研论文： [1] Chen J, Yu Q, Zhang T, et al. Quorum sensing luxI/R genes enhances cadmium detoxification in Aeromonas by up-regulating EPS production and cadmium resistance genes[J]. Journal of Hazardous Materials, 2025: 137959. [2] Chen J, Gao X, Zhang C et al.Chen J, Gao X, Zhang C, et al. Rapid Identification of Metal Resistance Genes Using an Enhanced ResNet Deep Learning Model Trained on a largely Expanded BacMet-Based Database[J]. Journal of Hazardous Materials, 2025: 139625. [3] Chen J, Zheng C, Run J, et al. Cadmium bioavailability and accumulation in rice grain are controlled by pH and Ca in paddy soils with high geological background of transportation and deposition[J]. Bulletin of Environmental Contamination and Toxicology, 2021, 106: 92-98. [4]陈家乐,相满城,唐林茜,等.运积型地质高背景稻田土壤重金属污染和人体健康风险评价[J].生态学杂志,2021,40(08):2334-2340. [5]陈家乐,唐林茜,相满城,等.区域土壤-水稻籽粒镉耦合关系模型的构建和验证[J].生态学杂志,2021,40(08):2341-2347. 教科研项目：参与多项国家重点发和国家自然科学基因项目 获奖情况：无', '0', '0', '0', '2026-06-05 20:04:15', '2026-06-05 20:04:15', NULL, '南京农业大学', NULL, '大学计算机与信息技术 教科研论文： ', NULL, '大学 学历学位：博士 职称：讲师 荣誉：无 办公地点：池州学院博奕楼北；大学计算机与信息技术 教科研论文： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1112', '夏玉发', '大数据与人工智能学院', '讲师/博士', NULL, '', '夏玉发，男，汉族，1987年7月生，河南信阳人，中共党员，讲师。2020年9月至2025年6月，在武汉大学读博士，获工学博士学位。 2015年7月至2020年8月，在中科院深圳先进技术研究院工作，职务为助理研究员。 办公地点 ：博奕楼北204 电子邮箱 ：yufa_xia@163.com 研究方向 ：遥感影像处理 主讲课程 ：数字信号处理，大学计算机基础 教科研项目： 1.基于动态纹理表达的SAR影像建模与信息提取，年份：2021.01-2024.12，国家自然科学基金面上项目，54万元，参与，已结题。 2.基于深度学习的冠脉血流动力学指标快速计算方法研究，年份：2018.01-2021.12，国家自然科学基金面上项目，62万元，参与，已结题。 3.面向临床医护场景基于先验机制与深度学习双模型驱动的无创连续血压精准估计方法的研究，年份：2018.01-2020.12，国家自然科学基金青年项目，20万元，参与，已结题。 教科研论文： 1. Yufa Xia and Xin Xu. "Active Learning-Enhanced Pyramidal Convolution Unet for Change Detection in Optical and SAR Remote Sensing Image Pairs." IEEE Journal of Selected Topics in Applied Earth Observations and Remote Sensing, Vol. 17 (2024), pp 17503 - 17521. (SCI, 中科院二区) 2. Yufa Xia, Xin Xu, and Fangling Pu. "PCBA-Net: Pyramidal Convolutional Block Attention Network for Synthetic Aperture Radar Image Change Detection." Remote Sensing 14.22 (2022): 5762. (SCI, 中科院二区) 3. Yufa Xia and Yaoqin Xie. "A novel wearable electrocardiogram classification system using convolutional neural networks and active learning." IEEE Access 7 (2019): 7989-8001. (SCI) (谷歌学术引用量:71) 4. Yufa Xia, Huailing Zhang, Lin Xu, Zhifan Gao, Heye Zhang, Huafeng Liu, and Shuo Li. "An automatic cardiac arrhythmia classification system with wearable electrocardiogram." IEEE Access 6 (2018): 16529-16538. (SCI) (谷歌学术引用量: 149) 5. Yufa Xia, Xin Liu, Dan Wu, Huahua Xiong, Lijie Ren, Lin Xu, Wanqing Wu, Heye Zhang. "Influence of beat-to-beat blood pressure variability on vascular elasticity in hypertensive population." Scientific Reports 7.1 (2017): 8394. (SCI) 6. Yufa Xia, Dan Wu, Zhifan Gao, Xin Liu, Qian Chen, Lijie Ren, Wanqing Wu. "Association between beat-to-beat blood pressure variability and vascular elasticity in normal young adults during the cold pressor test." Medicine 96.8 (2017). (SCI) 7. Yang Yang#, Xin Liu#, Yufa Xia# (共同一作), Xin Liu#, Wanqing Wu#, Huahua Xiong, Heye Zhang, Lin Xu, Kelvin K. L. Wong, Hanbin Ouyang, Wenhua Huang. "Impact of spatial characteristics in the left st', '0', '0', '0', '2026-06-05 20:04:17', '2026-06-05 20:04:17', NULL, NULL, NULL, NULL, NULL, '大学读博士，获工学博士学位。 ；大学计算机基础 教科研项目： ；大学优秀助教； ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1113', '张安骏', '大数据与人工智能学院', '讲师/博士', '基于深度学习的遥感影像智能解译 主讲课程：计算机操作系统 教科研论文： ', '', '张安骏，男，汉，199010出生，籍贯安徽安庆。2006参加工作，毕业于合肥工业大学，博士研究生/工学博士，讲师职称。 办公地点：博奕北楼103 电子邮箱：zajjerry1990@163.com 研究方向：基于深度学习的遥感影像智能解译 主讲课程：计算机操作系统 教科研论文： 1. Zhang Anjun ,YangXuezhi*,AiJiaqiu, FangShuai. RegionlevelSARImage ClassificationusingDeep FeaturesandSpatialConstraints[J].ISPRSJournalofPhotogrammetryandRemoteSensing,2020,163C:36-48.(SCI-IF11.74, 一区，遥感领域顶刊) 2. Zhang A . , YangX*. , JiaL. , AiJ.,andDongZ.(2019)-SARimageclassificationusingadaptive neighborhood-basedconvolutionalneuralnetwork[J].EuropeanJournalofRemoteSensing,2019,52(1):178-193.(SCI-IF3.168，感领域国际主流期刊) 3. Zhang Anjun ,YangXuezhi*,JiaLu,AiJiaqiu,andXiaJingfan.(2019)-SRAD-CNNforadaptivesynthetic apertureradarimageclassification[J].InternationalJournalofRemoteSensing,2019,40(9):3461-3485.(SCI-IF3.531)(SCI-IF3.4，遥感领域国际主流期刊) 4. Zhang A *.,JiaL.,WangJ.,WangC..(2023)-SARImageClassificationUsingGatedChannelAttentionBased ConvolutionalNeuralNetwork[J]. 2023,RemoteSensing,15(2):362. (SCI-IF5.349,二区，遥感权威期刊) 5. Zhang A *,HuangL,JiaL, etal..(2024)-SARimageclassificationusingdeepfeaturesandneighborhood heterogeneityconfidencerefinedspatial constraints[J].2024,InternationalJournalofRemoteSensing,45(5):1419-1449.(SCI-IF3.4，遥感领域国际主流期刊) 6.WangJ,ZengF, Zhang A ,etal.Aglobalpatchsimilarity-basedgraphforunsupervisedSARimagechangedetection[J].RemoteSensingLetters, 2024,15(4):353-362. 7.WangJ, Zhang A .SARImageChangeDetectionBasedonHeterogeneousGraphWithMultiattributesandMultirelationships[J].IEEEAccess, 2022,10: 44347-44361. 教科研项目： (1) 融合超像素区域深度特征提取与相关性描述的SAR图像分类方法研究，KJ2021A0021，省教育厅基金重点项目，6万元，2021-2023年. (2) SAR数据处理前沿技术与应用系统，PA2020GDSK0081，合肥工业大学工业安全与应急技术安徽省重点实验室自主创新课题，5万元，2020-2021年. (3) 基于深度学习的大豆主产区种植区提取与面积测算技术研究，AE202215，农业生态大数据分析与应用技术国家地方联合工程研究中心开放课题，3万元，2022-2023年. 获奖情况：无', '0', '0', '0', '2026-06-05 20:04:19', '2026-06-05 20:04:19', NULL, '合肥工业大学', NULL, '计算机操作系统 教科研论文： ', NULL, '大学，博士研究生；博士，讲师职称。 办公地点：博奕北楼；大学工业安全与应急技术安徽省重点实验室自主创新课题，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1114', '张江悦', '大数据与人工智能学院', '讲师/博士', '图论及其应用 主讲课程：高等数学 教科研论文： ', '', '张江悦，女，汉族，1994年4月生，山西晋城人，2025年6月参加工作，2023年4月29日加入中国共产党，兰州大学应用数学专业毕业，研究生学历，理学博士学位。 办公地点：博奕楼北103 电子邮箱：jiangyuezhang2025@163.com 研究方向：图论及其应用 主讲课程：高等数学 教科研论文： [1] J. Zhang, Y. Wu, H. Zhang, The maximum matching extendability and factor criticality of 1-planar graphs, Discrete Appl. Math. 338 (2023) 247-254. (SCI) [2] J. Zhang, Y. Wu, H. Zhang, On restricted matching extension of 1-embeddable graphs in surfaces with small genus, Discrete Math. 347 (2024) 114172. (SCI)', '0', '0', '0', '2026-06-05 20:04:24', '2026-06-05 20:04:24', NULL, NULL, NULL, '高等数学 教科研论文： ', NULL, '大学应用数学专业毕业，研究生学历，理学博士学位。 办公地点：博奕楼北', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1115', '沈杰', '大数据与人工智能学院', '沈杰-大数据与人工智能学院', NULL, '', '沈杰，男，汉族，1984年8月，安徽长丰人，中共党员，硕士，毕业于合肥工业大学。 电子邮箱： 576239641@qq.com 办公地点： 博采北204 主讲课程： C语言、办公自动化 研究领域与方向： 深度学习图像识别', '0', '0', '0', '2026-06-05 20:04:26', '2026-06-05 20:04:26', NULL, '合肥工业大学', NULL, 'C语言、办公自动化 研究领域与方向： 深度学习图像识别', NULL, '硕士，毕业于合肥工业大学。 电子邮箱： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1116', '孙晓兵', '大数据与人工智能学院', '孙晓兵-大数据与人工智能学院', 'NLP、ASR、信息安全、生态环境等领域方向 主讲课程：', '', '孙晓兵，男，汉族，1994.7，河北邢台人，硕士，毕业于燕山大学。 电子邮箱：sunxiaobing@czu.edu.cn 研究方向：NLP、ASR、信息安全、生态环境等领域方向 主讲课程：《数据结构》 科研论文： HeHaitao, Sun Xiaobing* ,et al. "A novel multimodal-sequential approach based on multi-view features for network intrusion detection." IEEE Access 7 (2019): 183207-183221. 发明专利： 1.孙晓兵，齐路，唐会军，等。一种实时转译文本的纠错方法、系统、存储介质和装置。CN202111037395.9. 2.孙晓兵，齐路，唐会军，等。一种用于监管领域的文本纠错方法、存储介质和装置。CN202111052921.9. 3.孙晓兵。ASR文本纠错训练样本集的构造方法、系统和电子设备。CN202211598033.1.', '0', '0', '0', '2026-06-05 20:04:28', '2026-06-05 20:04:28', NULL, '燕山大学', NULL, '《数据结构》 科研论文： HeHaitao, Sun Xiaobing', NULL, '硕士，毕业于燕山大学。 电子邮箱：', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1117', '陈广士副', '文学与传媒学院', '教授', NULL, '', '基本情况 姓名 陈广士 性别 男 职称 副教授 所属系 中文系 是否硕导 否 最高学历 硕士研究生 Email 8 71763223 @ qq.com 详细情况 所在学科专业 中国现当代文学 研究方向 中国通俗文学、张恨水研究 讲授课程 中国现当代文学 教育经历 1.1992-1996安徽大学中文系本科 2.2006-2008年苏州大学文学院硕士 工作经历 1996年7月至今，池州学院 科研项目 1.池州师专教研项目《现当代文学课程的教学方法如何适应本科层次的教学需要》（2006XJ019） 2.池州学院重点科研项目《张恨水的思想发展及对其创作的影响》（XK0916） 学术论文 1.《关于张恨水早期作品〈真假宝玉〉的几点看法》，《艺术探索》2007（2） 2.《浅谈鸳蝴派小说〈红鸳语〉的现代性特征》，《池州师专学报》2007（2） 3.《虚实相济演人生——试论〈名优之死〉第三幕的双重舞台结构》，《艺术探索》2007（6） 4.《本科专业现当代文学教学若干方法的探讨》，《池州学院学报》2018（4） 5. 《让经典的光辉重新闪耀——关于提高学生对现代文学经典阅读兴趣的几点思考》，《中国成人教育》2008（8） 6.《现代文学教学中经典阅读的引导》，《池州学院学报》2008（12） 7.《试论张恨水对传统才子佳人小说的继承和发展》，《池州学院学报》2009（4） 8.《〈大江东去〉:激变时代的爱情悲歌》，《池州学院学报》2012（10） 9.《国如用我何妨死——张恨水的民族意识》，《池州学院学报》2010（10） 著作教材 参编：《中国现代文学史 1917-2000》、《高等语文》、中国二十世纪文学风貌十二讲 获奖情况 社会兼职 安徽省张恨水学会理事', '0', '0', '0', '2026-06-05 20:25:26', '2026-06-05 20:25:26', NULL, '年苏州大学文学院（硕士）', NULL, NULL, NULL, '硕士研究生 ；大学中文系本科 ；大学文学院硕士 工作经历 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1118', '向叶平副', '文学与传媒学院', '教授', '中国现当代文学、女性文学 讲授课程：中国现当代文学、女性文学研究等 教育经历： ', '', '姓名：向叶平 职称：副教授 最高学位：硕士研究生 Email：591305254@qq.com 详细情况 所在学科专业：中国语言文学 研究方向：中国现当代文学、女性文学 讲授课程：中国现当代文学、女性文学研究等 教育经历： 1999.06湘潭大学汉语言文学本科毕业 2005.12 获安徽师范大学中国现当代文学硕士学位 2008.10 首届安徽省中青年文艺评论家高级研修班 2014.09—2015.06 北京大学中文系访问学者 2019.12 第五届安徽省中青年文艺评论家高级研修班 工作经历： 1999年7月入职池州师专 2004年晋升讲师 2012年10月至今，任池州学院副教授 教科研项目： 主持安徽省青年人才项目1项、安徽省高校人文社科重点研究基地项目1项、校级教科研项目多项，参与国家社科基金项目、教育部人文社科规划项目等多项。 学术论文： 在《学术界》《东吴学术》《嘉应大学学报》《池州学院学报》等刊物发表论文20余篇。 文学创作： 在《清明》《安徽文学》《青年文学》《现代青年》《安徽日报》《池州日报》等刊物发表小说、散文近100万字。 教材、著作： 1.《燕燕于飞》，中国文联出版社，2001年（独著、小说） 2.《20世纪中国文学风貌十二讲》，合肥工业大学出版社，2005年（编委） 3.《中国现代文学史1917-2000（下）》，安徽教育出版社，2010年（参编） 4.《向叶平作品：散文选》，江苏美术出版社，2013年（独著） 5.《向叶平作品：中短篇小说选》，江苏美术出版社，2013年（独著） 6.《九华山志》（光绪版，古籍点校），安徽文艺出版社，2019年（第一作者） 7.《“野地”里的呐喊——梅娘作品研究》，合肥工业大学出版社，2022年（独著） 8.《王阳明与九华山文献汇编》，中国社会科学出版社，2024年（参编） 9.《韦政通学思行年》（全五册），台湾花木兰文化事业有限公司，2025年（合著） 10.国家级一流本科课程《张恨水小说研究》，2023年（参与建设） 获奖情况： 池州师专校级优秀教师（2004） 池州市首届优秀文艺作品新人新作奖（2005） 池州师专先进女教职工（2006） 池州市第二届优秀文艺作品奖文艺评论类三等奖（2007） 池州学院教坛新秀（2008） 安徽省先进班集体（2008） 安徽省小说对抗赛池州赛区中篇小说类一等奖（2008） 池州市第四届优秀文艺作品图书类三等奖（2014） 安徽省工会2016年度“书香三八”征文一等奖（2016） 安徽省教科文卫体工会2017年度第一届“书香天使”读书活动家书类一等奖（2017） 安徽省第一届校园读书创作活动优秀奖（2017） 海南团省委《现代青年》2019年度人物“最佳专栏作家”（2020） 安徽省民俗学会2020年学术年会优秀论文（2020） 安徽省“书香之家”（2020） 池州市第六届社会科学奖优秀奖（2021） 中国（安徽）大学生茶文化创新大赛“优秀指导教师”（2021） 社会兼职： 安徽省作家协会会员、安徽省文艺评论家协会会员、安徽省张恨水研究会常务理事、《现代青年》杂志专栏作家、池州市第二、三届家庭教育讲师团成员、台湾实践大学客座副教授、台湾宜兰大学政通学者', '0', '0', '0', '2026-06-05 20:25:30', '2026-06-05 20:25:30', NULL, '获安徽师范大学（硕士）', NULL, NULL, NULL, '硕士研究生 ；大学汉语言文学本科毕业 ；大学中国现当代文学硕士学位 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1119', '李华维副', '文学与传媒学院', '教授', NULL, '', '基本情况 姓名 李华维 性别 女 职称 副教授 所属系 中文系 是否硕导 否 最高学历 博士研究生 Email 97078703@qq.com 详细情况 所在学科专业 亚 非语言文 学 研究方向 泰语、中 泰语言比较、对外汉语 讲授课程 现代汉语、现代 汉语词汇研究、对外汉语教学概论、对外汉语教学法、对外汉语词汇教学、大学生文学素养 教育经历 1.2004年9月至2008年6月就读于 广西民族大学 ，获文学学士学位； 2.2006年6月至2007年3月就读于泰国清迈皇家大学； 3.2008年9月至2011年6月就读于云南民族大学，获文学硕士学位； 4.2009年9至2010年9月就读于泰国清迈大学。 工作经历 1.2009年3月至2009年7月任云南民族大学东语学院兼职教师； 2.2009年9月至2010年9月任泰国清迈大学人文学院中文系兼职教师； 3.2011年7月至今任教于池州学院文学与传媒学院； 4.2016年8月至2017年5月任泰国清迈大学人文学院访问学者。 科研项目 1.主持2011年校级人文社科项目“汉泰语动词的使动用法对比研究”（2011RC011）； 2.主持2017年校级人文社科重点项目“汉泰语亲属称谓对比及其文化内涵研究”（2017RWZ017）； 3.参与2008年国家级社科基金项目“印度阿萨姆邦阿洪傣族编年史《阿洪姆兰基》的翻译及诠释”（ A080014）； 4.参与2014年安徽省人文社科重点项目”皖南方言俗语的整理与研究—以贵池方言为研究对象”（SK2014A058）； 5. 参与2014年校级质量工程项目“应用型本科院校应用语言学课程群建设研究”（2014jyxm401）。 学术论文 1.《汉泰语显性使动句的对比》，池州学院学报，2015年第2期； 2.《泰语语流音变探析》，池州学院学报，2016年第4期； 3.《汉泰语亲属称谓异同及其文化内涵探究》，红河学院学报，2020年第2期； 4.《汉语副词“再” 与泰语副词“อีก”“ค่อย”对比研究》，青年与社会，2014年第23期。 著作教材 获奖情况 2012年3月，获池州学院庆“三八”教师演讲比赛二等奖； 2013年5月，获池州学院第一届辅导员技能大赛二等奖； 2013年6月，获池州学院青年教师技能大赛优秀奖； 2014年6月，获池州学院青年教师技能大赛优秀奖。 社会兼职 安徽省汉语国际教育研究会会员 安徽省语言学会会员', '0', '0', '0', '2026-06-05 20:26:10', '2026-06-05 20:26:10', NULL, '博士研究生', NULL, NULL, NULL, '博士研究生 ；大学生文学素养 教育经历 ；大学 ，获文学学士学位； ', NULL, NULL);
