INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1123', '李二龙', '外国语学院', '李二龙-外国语学院', NULL, '', '基本情况 姓 名 李二龙 性 别 男 职 称 讲师 所属 系 大学英语教研部 最高学历 硕士研究生 Email 详细情况 学科专业 语言学及应用语言学 研究方向 英语教学 讲授课程 英语阅读、英语教学法、大学英语 教育经历 江西师范大学本科、硕士 工作经历 科研项目 1.2007 年度校级科研项目 - 不同语言水平的学生歧义容忍度的差异研究（ XYK200711 ） 2. 2020 年池州学院校级一般教学研究项目：英语阅读课程思政建设的探索与实践 （ 2020XKSXM03 ） 3. 2023 年池州学院校级教育教学改革研究重点项目：习近平文化思想融入英语阅读课程的探索与实践（ 2023XJYXM16 ） 学术论文 1. 论大学英语课堂中的德育渗透 [J]. 湖北经济学院学报 ( 人文社会科学版 ) 2015 (04) pp.202-203 2. 论基础教育英语课程标准的统一性和多样性 [J]. 基础教育研究 2014 (04) pp.19-20 3. 阅读领先 , 说写跟上 , 有效整合语言输入与输出 [J]. 鸡西大学学报 2013 (01) pp.106-108 4. 口头交际的特点及其对英语口语教学的启示 [J]. 池州学院学报 2013 (01) pp.148-151 5. 师生风格冲突对外语教学的影响及应对举措 [J]. 西南农业大学学报 ( 社会科学版 ) 2013 (05) pp.150-153 6. 外语课堂师生风格冲突的成因、影响及对策 [J]. 新余学院学报 2013 (03) pp.96-98 7. 论翻译中的文化负迁移及相关影响因素 [J]. 牡丹江师范学院学报 ( 哲学社会科学版 ) 2013 (04) pp.104-106 8. 语音、语法和词汇的文化内涵及其对外语教学的启示 [J]. 太原师范学院学报 ( 社会科学版 ) 2012 (02) pp.124-127 9. 微格教学与新手教师培训 [J]. 佳木斯教育学院学报 2012 (03) pp.255 10. 高师外语教育性别失衡的成因、影响及对策 [J]. 长春大学学报 2012 (10) pp.126-129 11. 歧义容忍度对英语阅读理解的影响和启示 [J]. 长春理工大学学报 ( 社会科学版 ) 2011 (03) pp.159-161 12. 论大学英语教学目标的多元化 [J]. 牡丹江大学学报 2011 (07) pp.133-135 13. 话语标记的特点、功能及其认知阐释 [J]. 黑龙江教育学院学报 2011 (08) pp.150-151+162 14. 英语阅读中的批判性思维及其培养策略—以英语专业学生为例 [J]. 池州学院学报 2022 （ 08 ） pp.120-122 著作教材 参编《新英汉双解词典》，北京大学出版社， 1999 获奖情况 1.2008 年 12 月获池州学院 2007-2008 年度优秀辅导员； 2.2018 年指导 2016 级学生田敏参加第九届安徽省高等学校师范生教学技能竞赛获二等奖； 3. 2019 年指导 2017 级学生杨思铭参加安徽省高等学校师范生教学技能竞赛暨首届长三角师范生教学基本功大赛选拔赛获一等奖，本人获优秀指导教师奖； 4.2020 年指导 2018 级学生潘彦伊参加第 11 届“外教社杯”全国高校外语教学大赛安徽赛区本科师范技能组获二等奖，本人被评为指导教师二等奖。 5. 2022 年指导学生张瑞参加第 12 届“外教社杯”全国高校外语教学大赛安徽赛区本科师范技能组获一等奖，本人被评为指导教师一等奖。 6.2022 年获 2022 届“优秀毕业实习指导教师”。 7. 2023 年获全国高校外语课程思政教学案例大赛三等奖。 社会兼职', '0', '0', '0', '2026-06-05 20:36:33', '2026-06-05 20:36:33', NULL, '江西师范大学', NULL, NULL, NULL, '大学英语教研部 最高学历 硕士研究生 ；大学英语 教育经历 江西师范大学本科、硕士 工作经历 科研项目 ；大学英语课堂中的德育渗透 ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1124', '陈灵子', '外国语学院', '博士', NULL, '', '基本情况 姓 名 陈灵子 性 别 女 职 称 所属 系 大学外语部 最高学历 博士研究生 Email 详细情况 学科专业 英美文学 研究方向 英美文学 讲授课程 大学英语 教育经历 2016年硕士毕业于南昌大学，2025年博士毕业于中国人民大学 工作经历 2025年9月至今 池州学院 科研项目 曾经参与国社科项目福特 ·马多克斯·福特研究，长期致力于弗雷德里克·詹姆逊的后现代西方马克思主义理论研究 学术论文 著作教材 获奖情况 社会兼职', '0', '0', '0', '2026-06-05 20:36:35', '2026-06-05 20:36:35', NULL, '南昌大学', NULL, NULL, NULL, '大学外语部 最高学历 博士研究生 ；大学英语 教育经历 ；硕士毕业于南昌大学，', NULL, NULL);
