INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1139', '宛颂', '地理与规划学院', '宛颂-地理与规划学院', '土壤微生物生态 联系方式： wansong2020@126.com', '', '宛颂， 男，讲师，生态学理学博士，近年来，在国内外期刊发表论文20余篇。 教授课程： 区域分析与规划、毕业论文写作指导等 研究领域： 土壤微生物生态 联系方式： wansong2020@126.com', '0', '0', '0', '2026-06-06 12:31:51', '2026-06-06 12:31:51', NULL, NULL, NULL, '区域分析与规划、毕业论文写作指导等 研究领域： 土壤微生物生态 联系方式： wansong2020@126.com', NULL, '博士，近年来，在国内外期刊发表论文', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1140', '曹靖', '地理与规划学院', '曹靖-地理与规划学院', '产业与区域发展；国土空间规划；城市人居环境评价；数字化与人工智能技术应用', 't_1140_avatar.jpg', '曹靖，陕西宝鸡人。2010年于中山大学获得学士学位，2022年于中国科学院大学、中科院地理所获得博士学位。主要从事城乡规划与区域发展、人居环境、智慧城市相关研究，发表各类学术论文十余篇，参加各类科研项目数十项。', '1', '0', '0', '2026-06-06 12:31:53', '2026-06-08 14:43:18', NULL, NULL, '发表学术论文十余篇；参加各类科研项目数十项', 'GIS设计与开发；3S技术集成与应用', NULL, '中山大学理学学士（2010）；中国科学院大学/中科院地理所博士（2022）', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1141', '朱方华', '地理与规划学院', '朱方华-地理与规划学院', '环境岩土工程 联系方式： zhufanghua2016@mail.hfut.edu.cn', '', '朱方华， 男，讲师，高级工程师，地质学理学博士，池州学院青年教师教学型、科研型导师。近年来，主持省级教科研项目1项，承担横向项目3余项，在国内外期刊发表论文10余篇，授权发明专利9项、实用新型专利2项，获中国交通运输协会科技奖二等奖1项，安徽省交通科技进步奖一等奖2项。 教授课程： 地质学、土壤地理学 研究领域： 环境岩土工程 联系方式： zhufanghua2016@mail.hfut.edu.cn', '0', '0', '0', '2026-06-06 12:31:55', '2026-06-06 12:31:55', NULL, NULL, NULL, '地质学、土壤地理学 研究领域： 环境岩土工程 联系方式： zhufanghua2016@mail.hfut.edu.cn', NULL, '博士，池州学院青年教师教学型、科研型导师。近年来，主持省级教科研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1142', '谢红', '地理与规划学院', '谢红-地理与规划学院', '城市与区域可持续发展、城市治理与风险管理 联系方式： 875262198@qq.com', '', '谢红， 女，东南大学管理学博士。近年来，主持省级教科研项目1项，承担横向项目1项，在国内外期刊发表论文10余篇，参编国家级规划教材1部，获教学成果省级三等奖1项。 教授课程： 国土空间规划原理、国土空间规划管理与法规、大学生职业生涯规划与就业素养 研究领域： 城市与区域可持续发展、城市治理与风险管理 联系方式： 875262198@qq.com', '0', '0', '0', '2026-06-06 12:31:58', '2026-06-06 12:31:58', NULL, '东南大学（博士）', NULL, '国土空间规划原理、国土空间规划管理与法规、大学生职业生涯规划与就业素养 研究领域： 城市与区域可持续发展、城市治理与风险管理 联系方式： 875262198@qq.com', NULL, '大学管理学博士。近年来，主持省级教科研项目；大学生职业生涯规划与就业素养 研究领域： 城市与区域可持续发展、城市治理与风险管理 联系方式： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1143', '侯建峰', '地理与规划学院', '侯建峰-地理与规划学院', '土壤生态学 全球变化生态学 森林生态学 联系方式： mehoujianfeng@163.com', '', '侯建峰， 男，讲师，土壤学博士。近年来，主持省级教科研项目1项，承担横向项目3项，在国内外期刊发表论文6篇。 教授课程： 土地资源学、村庄规划 研究领域： 土壤生态学 全球变化生态学 森林生态学 联系方式： mehoujianfeng@163.com', '0', '0', '0', '2026-06-06 12:32:00', '2026-06-06 12:32:00', NULL, NULL, NULL, '土地资源学、村庄规划 研究领域： 土壤生态学 全球变化生态学 森林生态学 联系方式： mehoujianfeng@163.com', NULL, '博士。近年来，主持省级教科研项目', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1144', '樊伟', '地理与规划学院', '樊伟-地理与规划学院', '森林土壤养分循环、土壤微生物生态等 联系方式： 1352367224@qq.com', '', '樊伟 ，女，安徽农业大学农学博士。近年来，在国内外期刊发表论文十余篇。 教授课程： 《自然地理学》、《区域分析与规划》、《大学生职业生涯与规划》... 研究领域： 森林土壤养分循环、土壤微生物生态等 联系方式： 1352367224@qq.com', '0', '0', '0', '2026-06-06 12:32:02', '2026-06-06 12:32:02', NULL, '安徽农业大学（博士）', NULL, '《自然地理学》、《区域分析与规划》、《大学生职业生涯与规划》... 研究领域： 森林土壤养分循环、土壤微生物生态等 联系方式： 1352367224@qq.com', NULL, '大学农学博士。近年来，在国内外期刊发表论文十余篇。 教授课程： ；大学生职业生涯与规划', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1145', '王滕', '地理与规划学院', '王滕-地理与规划学院', '土木工程、建筑结构工程设计与安全性评价 联系方式： 254592570@qq.com', '', '王滕 ，男，讲师，工学博士。近年来，主持省级教科研项目1项，承担横向项目1项，在国内外期刊发表论文6篇，授权发明专利6项、实用新型专利3项。 教授课程： 园林工程、风景园林设计、大学生职业规划 研究领域： 土木工程、建筑结构工程设计与安全性评价 联系方式： 254592570@qq.com', '0', '0', '0', '2026-06-06 12:32:04', '2026-06-06 12:32:04', NULL, NULL, NULL, '园林工程、风景园林设计、大学生职业规划 研究领域： 土木工程、建筑结构工程设计与安全性评价 联系方式： 254592570@qq.com', NULL, '博士。近年来，主持省级教科研项目；大学生职业规划 研究领域： 土木工程、建筑结构工程设计与安全性评价 联系方式： ', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1146', '宗师', '地理与规划学院', '宗师-地理与规划学院', '基础地质；矿产资源调查；三维地质建模；碳中和；南极地质', 't_1146_avatar.jpg', '宗师，男，1989年生，江苏泰州人。毕业于中国地质大学（北京）和中国地质科学院，矿物学、岩石学、矿床学专业。2025年3月起任职池州学院地理与规划学院副教授。曾参与中国第34次、第40次南极科考，第40次队任内陆队科研班班长，主导地质调查等工作。曾在东南极拉斯曼丘陵、苏北盆地等地开展地质与CO2封存研究。', '0', '0', '0', '2026-06-06 12:32:06', '2026-06-06 12:32:06', NULL, '中国地质大学', '发表SCI论文6篇（中科院二区4篇、三区1篇、EI封面文章1篇），代表性成果发表于Marine Geology、Minerals、International Geology Review、岩石学报等期刊。参与中国第34次、第40次南极科学考察。', '地球概论；区域地理野外实习；全球变化导论', NULL, '中国地质大学（北京）/中国地质科学院 博士；中国极地研究中心 博士后（2022-2025）', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1147', '方新焰', '地理与规划学院', '方新焰-地理与规划学院', '深层油气地球化学、地球早期环境-生物演化与深层油气资源效应 联系方式： fangxinyan@czu.edu.cn', '', '方新焰 ，男，讲师，地球化学专业理学博士，池州学院青年教师，《地质资源勘查与灾害防治团队》负责人，《矿物岩石》期刊青年编委。近年来，主持国家级科研项目2项，在国内外期刊发表论文20余篇，获教学成果校级二等奖1项。 教授课程： 地理科学导论、自然资源学原理、区域地理野外实习、中学地理课例分析 研究领域： 深层油气地球化学、地球早期环境-生物演化与深层油气资源效应 联系方式： fangxinyan@czu.edu.cn', '0', '0', '0', '2026-06-06 12:32:08', '2026-06-06 12:32:08', NULL, NULL, NULL, '地理科学导论、自然资源学原理、区域地理野外实习、中学地理课例分析 研究领域： 深层油气地球化学、地球早期环境-生物演化与深层油气资源效应 联系方式： fangxinyan@czu.edu.cn', NULL, '博士，池州学院青年教师，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1148', '张家慧', '地理与规划学院', '张家慧-地理与规划学院', NULL, '', '张家慧 ，女，1992年生，江苏宜兴人。2014年获兰州大学大气科学专业理学学士学位，2022年获北京师范大学地理科学学部全球环境变化专业理学博士学位，2018-2019年获国家留学基金委资助赴美国联合培养。2025年6月进入池州学院工作，现为地理与规划学院专业教师。 主要研究方向 ：气候系统诊断分析、灾害风险评估、地理大数据分析 教授课程 ：空间信息可视化、数字高程模型 代表性论文 ： [1]. Zhang, Jiahui et al., (2025). Exploring the effects of different population projection datasets on global compound drought and heatwave exposure estimates under shared socioeconomic pathways. Environmental Research Letters 20(5), 054024. [2]. Zhang, Jiahui et al., (2025). Evaluating the impact of gridded population datasets variability on flood exposure estimates across South Asia. Geomatics, Natural Hazards and Risk 26(1), 2481996. [3].Zhang, Jiahui et al., (2018). Anomalous holiday precipitation over southern China. Atmospheric Chemistry and Physics 18, 16775-16791.', '0', '0', '0', '2026-06-06 12:32:10', '2026-06-06 12:32:10', NULL, NULL, NULL, NULL, NULL, '大学大气科学专业理学学士学位，；大学地理科学学部全球环境变化专业理学博士学位，', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1149', '董琳慧', '地理与规划学院', '董琳慧-地理与规划学院', NULL, '', '董琳慧 ，女，1997年9月生，安徽安庆人。 2019年6月于中国石油大学（北京）获得资源勘查工程学士学位。 2025年6月于中国科学技术大学获得地质学博士学位（博士期间赴瑞士苏黎世联邦理工学院进行为期1年联合培养）。 2025年6月进入池州学院工作，现任地理与规划学院专业教师。 主讲课程 ：遥感概论 研究方向 ：古海洋地球化学、同位素地球化学 联系方式 ：linhuidong927@163.com 论文发表情况 ： 1. Lin-Hui Dong, Wei Wei, Lingang Xu, Yi-Bo Lin, Ze-Rui Liu, Songqi Pan, Zhenhua Jing, and Fang Huang, Vanadium isotope evidence for seawater contribution to V enrichment/mineralization in early Cambrian metalliferous black shales, Science Bulletin, 69, 1006-1010, 2024.（中科院一区TOP期刊，IF= 18.8） 2. Wei Wei # , Lin-Hui Dong # , Shuhai Xiao, Yi-Bo Lin, Lingang Xu, Guang-Yi Wei, Wenzhong Wang, Lan-Lan Tian, Hai-Zhen Wei, and Fang Huang, Seawater barium and sulfide removal improved marine habitability for the Cambrian Explosion of early animals, National Science Review, 11, nwae237, 2024.（中科院一区TOP期刊，IF= 16.3） 3. Lin-Hui Dong , Wei Wei, Cheng-Long Yu, Zhen-Hui Hou, Zhen Zeng, Tianyu Chen , and Fang Huang, Determination of Vanadium isotope compositions in carbonates using an Fe coprecipitation method and MC-ICP-MS, Analytical Chemistry, 93, 7172-7179, 2021.（中科院一区TOP期刊，Nature Index期刊，IF= 6.7） 4. Wei Wei, Huajian Wang, Shuichang Zhang, Lin-Hui Dong , Dongdong Li, and Fang Huang, Dynamic redox evolution in the middle-late Mesoproterozoic oceans, Chemical Geology, 679, 122685, 2025.（中科院二区TOP期刊） 5. Lan-Lan Tian, Wei Wei, Lin-Hui Dong , Songqi Pan, Zhenhua Jing, and Fang Huang, Diagenetic effect on barium isotope compositions of barites in the lower Cambrian successions, Chemical Geology, 635, 121631, 2023.（中科院二区TOP期刊） 6. Wei Wei, Xi Chen, Hong-Fei Ling, Fei Wu, Lin-Hui Dong , Songqi Pan, Zhenhua Jing, and Fang Huang, Vanadium isotope evidence for widespread marine oxygenation from the late Ediacaran to early Cambrian, Earth and Planetary Science Letters, 602, 117942, 2023.（中科院一区TOP期刊，Nature Index期刊） 7. Nian-Qin Zhang, Kun Zhou, Yi-Xiang Chen, Fang Huang, Xiao-Feng Gu, Lin-Hui Dong , Gengxin Deng, Peng Gao. Barium isotope variation during granitic magma differentiation: impli', '0', '0', '0', '2026-06-06 12:32:12', '2026-06-06 12:32:12', NULL, '中国科学技术大学（博士）', NULL, '遥感概论', NULL, '大学；学士学位。 ；大学获得地质学博士学位', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1150', '陈松', '地理与规划学院', '陈松-地理与规划学院', '林业遥感、激光雷达遥感、森林碳汇监测 教授课程 ：无人机生态环境监管应用、无人机航测图像处理 代表性论文： ', '', '陈松 ，男，1996年8月生，安徽淮南人。2018年获中南林业科技大学林学专业农学学士学位，2021年获中南林业科技大学林学专业农学硕士学位，2025年获中南林业科技大学林学专业农学博士学位。2025年6月进入池州学院工作，现为地理与规划学院专业教师。 主要研究方向： 林业遥感、激光雷达遥感、森林碳汇监测 教授课程 ：无人机生态环境监管应用、无人机航测图像处理 代表性论文： [1] Chen S. , Gong M., Sun H., Chen M., Wang B. Estimation of Forest Canopy Height from Spaceborne Full-Waveform LiDAR Data Using a Bisection Approximation Decomposition Method[J]. FORESTS, 2025, 16(1). [2] Ma K., Xiong Y., Jiang F., Chen S. , Sun H. A Novel Vegetation Point Cloud Density Tree-Segmentation Model for Overlapping Crowns Using UAV LiDAR[J]. Remote Sensing, 2021, 13(8):20. [3] Jiang F., Kutia K. Ma K., Chen S. , Jlab C., Sun H. Estimating the aboveground biomass of coniferous Forest in Northeast China using spectral variables, land surface temperature and soil moisture[J]. Science of The Total Environment, 2021, 785. [4] 陈松 ,孙华,吴童,蒋馥根.基于Sentinel-2与机载激光雷达数据的误差变量联立方程组森林蓄积量反演研究[J].中南林业科技大学学报, 2020, 40(12):44-53. 发明专利、软件著作权与标准 : [1]孙华，贡鸣， 陈松 ，马开森.一种结合树顶树干检测与林木模型的机载点云分割方法（ZL 202311475702.0）国家知识产权局，2024.04.30 [2] Sun Hua, Ma Kaisen, Jiang Fugen, Chen Song . Airborne and Ground Laser Scanning Registration Target Combination,国际专利（2022/05559），Republic of South Africa.，2022.09.28 [3]马开森，孙华，蒋馥根， 陈松 ，杜志.一种机载和地面激光扫描配准标靶组合装置（ZL 202121019073.7）国家知识产权局，2021.10.22 [4]蒋馥根,孙华, 陈松 ,林辉. KNN叶面积指数模拟系统V1.0（2020SR0244786', '0', '0', '0', '2026-06-06 12:32:14', '2026-06-06 12:32:14', NULL, NULL, NULL, NULL, NULL, '大学林学专业农学学士学位，；大学林学专业农学硕士学位，；大学林学专业农学博士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1151', '周朋', '地理与规划学院', '周朋-地理与规划学院', NULL, '', '周朋 ，女，1996年生，江苏徐州人。2025年1月毕业于北京师范大学地理科学学部全球环境变化专业，获理学博士学位。2023-2024年获国家留学基金委资助赴瑞典斯德哥尔摩大学联合培养。2025年6月进入池州学院工作，现为地理与规划学院专业教师。 主要研究方向 ：全新世气候变化、西风和亚洲季风、千年变率 教授课程 ：国土空间规划 代表性论文 ： (1) Zhou, P. , Li, X., Shi, Z., Sha, Y., Lei, J., & An, Z. (2023). Strengthened East Asian winter monsoon regulated by insolation and Arctic sea ice since the middle Holocene. Geophysical Research Letters , 50, e2023GL105440. (中科院一区TOP，NI期刊) (2) Zhou, P. , Shi, Z., Li, X. and Zhou, W., 2020. Response of Westerly Jet Over the Northern Hemisphere to Astronomical Insolation During the Holocene. Frontiers in Earth Science , 8(282). (中科院三区) (3) Shi, Z., Zhou, P. , Li, X., Cheng, H., Sha, Y., Xie, X., Liu, H., Wu, J. and Liu, X., 2021. Distinct Holocene precipitation trends over arid Central Asia and linkages to westerlies and Asian monsoon. Quaternary Science Reviews , 266: 107055. (中科院一区TOP) (4) Sha, Y., Shi, Z., Zhou, P. , Lei, J. and Mao, X. (2023). Differentiation of Asian summer precipitation induced by the mountain building of the Tibetan Plateau and Central Asian Orogenic Belt. Palaeogeography, Palaeoclimatology, Palaeoecology , 619, 111547. (中科院二区TOP) (5) Sha, Y., Ren, X., Shi, Z., Zhou, P. , Li, X. and Liu, X., 2020. Influence of the Tibetan Plateau and its northern margins on the mid-latitude Westerly Jet over Central Asia in summer. Palaeogeography, palaeoclimatology, palaeoecology ,2020 v.544: pp. 109611-. (中科院二区TOP) (6) 石正国，雷婧， 周朋 ，等．轨道尺度亚洲气候演化机理的数值模拟：历史与展望[J]． 第四纪研究 , 2020, 40 (1) : 8-17．', '0', '0', '0', '2026-06-06 12:32:17', '2026-06-06 12:32:17', NULL, '博士', NULL, NULL, NULL, '大学地理科学学部全球环境变化专业，获理学博士学位。；大学联合培养。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1152', '张丽敏', '地理与规划学院', '张丽敏-地理与规划学院', '克隆植物生态学，湿地植物生态学 教授课程： 土地资源学 代表性论文： ', '', '张丽敏 ，女，1990年12月生，河南永城人。2013年获九江学院生物技术（生物制药）专业理学学士学位，2015年获北京林业大学林业专业农学硕士学位，2019年获北京林业大学湿地生态学专业理学博士学位。2025年6月至今在池州学院工作，现为池州学院地理与规划学院专业教师。 研究方向： 克隆植物生态学，湿地植物生态学 教授课程： 土地资源学 代表性论文： 1. Zhang Li-Min , Zheng Li-Li, Yu Fei-Hai*. 2025. Parental effects of physiological integration on growth of a clonal herb. Frontiers in Plant Science. 15, 1518400. (SCI二区). 2. Zhang Li-Min , Alpert Peter, Yu Fei-Hai*. 2022. Nutrient foraging ability promotes intraspecific competitiveness in the clonal plant Hydrocotyle vulgaris . Ecological Indicators. 138, 108862.(SCI二区Top). 3. Zhang Li-Min , Roiloa R. Sergio, Zhang Jia-Fan, Yu Wen-Han, Qiu Chen-Yan, Wang Dan-Hao, Yu Fei-Hai*. 2022. Clonal parental effects on offspring growth of different vegetative generations in the aquatic plant Pistia stratiotes . Frontiers in Plant Science.13, 890309. (SCI二区Top). 4. Zhang Li-Min , Roiloa R. Sergio, Xue Wei, Yu Fei-Hai*. 2022. Effects of temporal heterogeneity in nutrient supply on intra- and inter-genet competition of a clonal herb. Global Ecology and Conservation , 35, e02076. (SCI二区). 5. Zhang Li-Min , Jin Yu, Yao Si-Mei, Lei Ning-Fei, Chen Jin-Song, Zhang Qian, Yu Fei-Hai*. 2020.Growth and morphological responses of duckweed to clonal fragmentation, nutrientavailability and population density. Frontiers in Plant Science. 11, 618. (SCI二区Top). 6. Zhang Li-Min , Yao Si-Mei, Jin Yu, Song Ming-Hua, Lei Ning-Fei, Chen Jin-Song, Yu Fei-Hai*. 2020. Effects of clonal fragmentation and nutrient availability on the competitive ability of the floating plant Salvinia natans . Folia Geobotanica. 55, 63-71. (SCI四区). 7. Zhang Li-Min , Alpert Peter, Si Chao, Yu Fei-Hai*. 2019. Interactive effects of fragment size, nutrients, and interspecific competition on growth of the floating, clonal plant Salvinia natans . Aquatic Botany. 153, 81-87. (SCI四区). 8. Zhang Li-Min # , Lu Hua-Zheng # , Alpert Peter, Song Liang, Liu Wen-Yao, Yu Fei-Hai*. 2019. Higher benefits of clonal integration in rhizome-derived than in frond-deri', '0', '0', '0', '2026-06-06 12:32:19', '2026-06-06 12:32:19', NULL, '年获北京林业大学（硕士）', NULL, NULL, NULL, '学士学位，；大学林业专业农学硕士学位，；大学湿地生态学专业理学博士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1153', '方梦超', '地理与规划学院', '方梦超-地理与规划学院', NULL, '', '方梦超 ，男，1991年生，安徽广德人。2016年获盐城师范学院生物科学专业理学学士学位，2019年获杭州师范大学生态学专业理学硕士学位，2025年获中央民族大学民族生态学专业法学博士学位。2025年6月进入池州学院工作，现为地理与规划学院专业教师。 未来主要研究方向 ：生物多样性、土壤生态学，分子与生理生态学 代表性论文 ： （1） Fang M C , Lu G, Zhang S P, Liang W. Urbanized lands degrade surrounding grasslands by deteriorating the interactions between plants and soil microbiome. Front Microbiol. 2024, 15: 1505916. (二区top) （3） Fang M C , Lu G, Zhang S P, Liang W. Overgrazing on unmanaged grassland interfered with the restoration of adjacent grazing-banned grassland by affecting soil properties and microbial community. Front Microbiol. 2024, 14: 1327056. (二区top) （3） Fang M C , Zhu X M, Du Y, Zhang L, Lin L H. Macroecological patterns of climatic niche breadth variation in Lacertid lizards. Asian Herpetol Res, 2019, 1: 41-47. (三区) （4）Zhu XM, Hua L, Fang M C , Du Y, Lin CX, Lin LH, Ji X. Lineage diversification and niche evolution in the Reeves’ Butterfly Lizard Leiolepis reevesii (Agamidae). Integrative Zoology, 2021, 16: 404-419.（二区） （5）Lu G, Fang M C , Zhang S P. Spatial Variation in Responses of Plant Spring Phenology to Climate Warming in Grasslands of Inner Mongolia: Drivers and Application. Plants, 2024, 13: 520.（二区） 科研项目 ： 2020‒2024：少数民族地区生态环境重点实验室项目（KLEEMA202207,国家民委）参与。 2018‒2019：巨蜥科气候生态位宽度的变异格局（LY17C030003,浙江省自然科学基金）参与。 2016‒2017：圆鼻巨蜥的空间需求、热需求和能量分配策略（31270571,国家自然科学基金）参与。 联系方式 ：fangmch@outlook.com', '0', '0', '0', '2026-06-06 12:32:21', '2026-06-06 12:32:21', NULL, '年获杭州师范大学（硕士）', NULL, NULL, NULL, '学士学位，；大学生态学专业理学硕士学位，；大学民族生态学专业法学博士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1154', '陈文艳', '地理与规划学院', '陈文艳-地理与规划学院', '森林病害与区域生态安全、生态保护与修复 代表性论文： ', '', '陈文艳 ，女，1996年生，安徽池州人。2018年获安徽农业大学林学专业农学学士学位，2025年获北京林业大学森林保护学专业农学博士学位。2025年6月进入池州学院工作，现为地理与规划学院专业教师。 未来主要研究方向： 森林病害与区域生态安全、生态保护与修复 代表性论文： 1. Chen WY , Meng FL, Li FH, Tian CM. Septins are involved in infection structure formation, stress responses and pathogenicity in Colletotrichum gloeosporioides . Int J Biol Macromol. 2024;283(Pt 3):137759.（SCI一区TOP，IF=7.7） 2. Chen WY , Fan XL, Tian CM, Li F, Chou GF. Identification and Characterization of Neocosmospora silvicola Causing Canker Disease on Pinus armandii in China. Plant disease, 2023; 07(10): 3026-3036.（SCI二区，IF=4.50） 3. 陈文艳 ,姜宁,范鑫磊,郭怀林,田呈明.甘肃华山松溃疡病病原真菌类群的初步鉴定.西北林学院学报, 2020, 05-08.（CSCD收录） 4. 陈文艳 ,姜宁,范鑫磊,田呈明.林木病原真菌——赤黏壳科(Erythrogloeaceae)的识别与鉴定.中国森林病虫, 2020, 39(02): 20-27. 5.Yang Q, Chen WY , Jiang N, Tian CM. Nectria-related fungi causing dieback and canker diseases in China, with Neothyronectriacitri sp. nov. described. MycoKeys. 2019; 56:49-66.（SCI二区，IF=3.30）。 科研项目： 国家自然科学基金面上项目（31670647），中国间座壳目病原真菌的分类和系统学研究，2016.01-2020.12，参与； 国家自然科学基金面上项目（32071767），杨树炭疽病菌附着胞形成相关识别受体蛋白功能及信号传导机制研究，2021.01-2024.12，参与。 联系方式： 15705666768@163.com', '0', '0', '0', '2026-06-06 12:32:23', '2026-06-06 12:32:23', NULL, NULL, NULL, NULL, NULL, '大学林学专业农学学士学位，；大学森林保护学专业农学博士学位。', NULL, NULL);
INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1155', '朱福斌', '地理与规划学院', '', '土壤遥感；土壤地理', 't_1155_avatar.jpg', '朱福斌，男，1995年4月生，浙江永嘉人。讲师。南京农业大学农业资源与环境专业农学博士学位（2024）。主要研究方向为土壤遥感。', '0', '0', '0', '2026-06-06 12:32:25', '2026-06-06 12:32:25', NULL, '南京农业大学（博士）', '以第一作者发表论文3篇', '', NULL, '安徽农业大学 地理信息科学 理学学士（2017）；安徽农业大学 资源环境信息技术 农学硕士（2020）；南京农业大学 农业资源与环境 农学博士（2024）', NULL, NULL);
