INSERT INTO teachers (id, name, college, title, research, avatar, bio, like_count, review_count, avg_rating, created_at, updated_at, undergraduate, graduate, achievements, courses, papers, education, projects, social_roles) VALUES ('1191', '汪恭敬', '地理与规划学院', '', '大学生就业与生涯教育；辅导员专业化发展；学生思想政治教育；乡村振兴与返乡创业', 't_new_wanggj_avatar.jpg', '博士，池州学院地理与规划学院专职辅导员，教工第四党支部书记，" 职场问道大学生就业与创业指导辅导员工作室主持人。长期负责毕业生就业、学生思政、生涯教育工作。2023年校级辅导员沙龙特邀主讲人。', '0', '0', '0', '2026-06-16 18:21:02', '2026-06-16 18:21:02', '', '', '论文《高校辅导员精神性指导行为对大学生就业焦虑的影响：心理韧性和职业召唤的链式中介作用》获校级心理健康论文一等奖；主持校级辅导员工作室专项项目XZ2022075；发表论文《大学生返乡创业赋能乡村振兴的理论逻辑与实践路向》（万方期刊）；2021年带队2019级地理科学专业赴黄山开展人文地理野外实习', '生涯混沌理论与高校辅导员的专业发展；就业指导相关课程', '', '博士（2023年辅导员沙龙官方报道标注）', '', '');
